_V1090_BUILD_MANIFEST_FILE = APP_DIR / "FANTASY_EDGE_BUILD_MANIFEST.json"
_V1090_SELF_HASH_PLACEHOLDER = "__FANTASY_EDGE_V1090_SELF_HASH__"
_V1090_EXPECTED_CANONICAL_SHA256 = "2615834b0562b9ae881d00d4ca378718609ee667addb01e506f897cef7568d70"

def _v1090_canonical_source_bytes(raw: bytes) -> bytes:
    try:
        txt=raw.decode("utf-8")
        pat=r'(_V1090_EXPECTED_CANONICAL_SHA256\s*=\s*")[^"]*(")'
        txt=re.sub(pat, lambda m: m.group(1)+_V1090_SELF_HASH_PLACEHOLDER+m.group(2), txt, count=1)
        return txt.encode("utf-8")
    except Exception:
        return raw

def _v1090_runtime_build_integrity():
    out={
        "version":APP_VERSION,
        "source_path":str(Path(__file__).resolve()),
        "source_dir":str(APP_DIR),
        "source_sha256":"",
        "source_fingerprint":"",
        "canonical_sha256":"",
        "self_expected_sha256":_V1090_EXPECTED_CANONICAL_SHA256,
        "self_ok":False,
        "manifest_version":"",
        "manifest_sha256":"",
        "manifest_present":False,
        "manifest_ok":False,
        "manifest_status":"missing (optional)",
        "build_ok":False,
        "build_status":"unverified",
    }
    try:
        raw=Path(__file__).read_bytes()
        sha=hashlib.sha256(raw).hexdigest()
        can=hashlib.sha256(_v1090_canonical_source_bytes(raw)).hexdigest()
        out["source_sha256"]=sha
        out["source_fingerprint"]=sha[:12]
        out["canonical_sha256"]=can
        out["self_ok"]=bool(_V1090_EXPECTED_CANONICAL_SHA256 and _V1090_EXPECTED_CANONICAL_SHA256!="__TO_BE_FILLED__" and hmac.compare_digest(can.lower(),_V1090_EXPECTED_CANONICAL_SHA256.lower()))
    except Exception as e:
        out["build_status"]=f"source verification error: {e}"
        return out
    try:
        m=json.loads(_V1090_BUILD_MANIFEST_FILE.read_text(encoding="utf-8"))
        out["manifest_present"]=True
        mv=str(m.get("app_version","") or "")
        mh=str(m.get("app_sha256","") or "").lower()
        out["manifest_version"]=mv
        out["manifest_sha256"]=mh
        version_ok=(mv==APP_VERSION)
        hash_ok=bool(mh) and hmac.compare_digest(mh,out["source_sha256"].lower())
        out["manifest_ok"]=bool(version_ok and hash_ok)
        if out["manifest_ok"]:
            out["manifest_status"]="verified"
        elif not version_ok:
            out["manifest_status"]=f"version mismatch: manifest V{mv or '?'} / runtime V{APP_VERSION}"
        else:
            out["manifest_status"]="app.py hash mismatch"
    except FileNotFoundError:
        out["manifest_status"]="missing (optional for hosted deployment)"
    except Exception as e:
        out["manifest_present"]=True
        out["manifest_status"]=f"manifest unreadable: {e}"
    manifest_gate=(not out["manifest_present"]) or out["manifest_ok"]
    out["build_ok"]=bool(out["self_ok"] and manifest_gate)
    if out["build_ok"] and out["manifest_ok"]:
        out["build_status"]="self-verified + manifest verified"
    elif out["build_ok"]:
        out["build_status"]="self-verified; manifest not deployed (allowed)"
    elif not out["self_ok"]:
        out["build_status"]="embedded source signature mismatch"
    else:
        out["build_status"]=out["manifest_status"]
    return out

_V1090_BUILD_INTEGRITY=_v1090_runtime_build_integrity()
