def _v1060_nearby_files(filename, nested_glob=None, limit=40):
    """Newest current/shared/sibling persistence candidates without a full disk walk."""
    candidates=[]; seen=set()
    for q in (APP_DIR/filename,_V1060_SHARED_DIR/filename):
        try: rq=str(q.resolve())
        except Exception: rq=str(q)
        if rq not in seen: seen.add(rq); candidates.append(q)
    roots=[]
    try: roots=[APP_DIR.parent,APP_DIR.parent.parent]
    except Exception: roots=[]
    patterns=[f"*/{filename}",f"*/*/{filename}"] if not nested_glob else [f"*/{nested_glob}",f"*/*/{nested_glob}"]
    for root in roots:
        for pat in patterns:
            try:
                for q in root.glob(pat):
                    try: rq=str(q.resolve())
                    except Exception: rq=str(q)
                    if rq in seen: continue
                    seen.add(rq); candidates.append(q)
                    if len(candidates)>=int(limit): break
            except Exception: pass
            if len(candidates)>=int(limit): break
        if len(candidates)>=int(limit): break
    def stamp(q):
        try: return float(q.stat().st_mtime) if q.exists() else -1.0
        except Exception: return -1.0
    return sorted(candidates,key=stamp,reverse=True)

def _v1060_atomic_bytes(path,payload):
    try:
        path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)
        tmp=path.with_suffix(path.suffix+".tmp")
        tmp.write_bytes(payload); tmp.replace(path); return True
    except Exception: return False

def _v1060_atomic_text(path,text):
    try:
        path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)
        tmp=path.with_suffix(path.suffix+".tmp")
        tmp.write_text(text,encoding="utf-8"); tmp.replace(path); return True
    except Exception: return False
