def _v966_merge_state(default, saved):
    if not isinstance(saved,dict):
        return default
    out=dict(default)
    out.update({k:v for k,v in saved.items() if k not in ["idp","kicker","roster_slots","mock"]})
    saved_idp=dict(saved.get("idp",{}) or {})
    if float(saved_idp.get("solo",1.5))==1.5 and float(saved_idp.get("assist",0.75))==0.75:
        saved_idp["solo"]=1.0; saved_idp["assist"]=0.5
    out["idp"]=dict(default["idp"]); out["idp"].update(saved_idp)
    out["kicker"]=dict(default["kicker"]); out["kicker"].update(saved.get("kicker",{}))
    out["roster_slots"]=dict(default["roster_slots"]); out["roster_slots"].update(saved.get("roster_slots",{}))
    out["mock"]=dict(default["mock"]); out["mock"].update(saved.get("mock",{}))
    return out


def _v967_named_team_count(s):
    """Count non-generic fantasy team labels without treating Team 2, etc. as recovered names."""
    if not isinstance(s,dict):
        return 0
    names=s.get("team_names",{}) or {}
    if not isinstance(names,dict):
        return 0
    n=0
    for k,v in names.items():
        text=str(v or "").strip()
        if not text:
            continue
        generic=(text.lower()=="my team" or bool(re.fullmatch(r"team\s+\d+",text.lower())))
        if not generic:
            n+=1
    return n


def _v967_state_score(s):
    """Prefer real league completeness over file recency during migration/recovery."""
    if not isinstance(s,dict):
        return (-1,-1,-1,-1)
    return (
        int(_v966_rostered_count(s)),
        int(_v967_named_team_count(s)),
        len(s.get("draft_log",[]) or []) if isinstance(s.get("draft_log",[]),list) else 0,
        len(s.get("my_team",[]) or []) if isinstance(s.get("my_team",[]),list) else 0,
    )


def _v967_historical_local_states():
    """Find state files left behind by pre-V9.64 folder layouts.

    V9.64 changed ZIP nesting, so APP_DIR-relative persistence could silently point
    at a new JSON file. Search only nearby project folders and return parseable
    alternatives; cap discovery so a deployment cannot walk the whole filesystem.
    """
    found=[]; seen=set()
    roots=[]
    cur=APP_DIR
    for _ in range(3):
        if cur and str(cur) not in seen and str(cur) not in ("/",""):
            roots.append(cur); seen.add(str(cur))
        cur=cur.parent
    candidates=[]
    for root in roots:
        for pat in ("fantasy_edge_state.json","*/fantasy_edge_state.json","*/*/fantasy_edge_state.json"):
            try:
                candidates.extend(list(root.glob(pat)))
            except Exception:
                pass
    uniq=[]; seen_paths=set()
    for path in candidates:
        try:
            rp=str(path.resolve())
        except Exception:
            rp=str(path)
        if rp in seen_paths or path==STATE:
            continue
        seen_paths.add(rp); uniq.append(path)
        if len(uniq)>=30:
            break
    for path in uniq:
        try:
            x=json.loads(path.read_text())
            if isinstance(x,dict):
                found.append((path,x,_v967_state_score(x)))
        except Exception:
            continue
    return found


def _v967_recover_team_names_from_draft(s):
    """Recover the real league labels preserved in draft history.

    Team IDs were not historically stored in draft_log, so opponent IDs are assigned
    deterministically by first appearance. Team 1 remains the user's team.
    """
    if not isinstance(s,dict):
        return s
    current=s.get("team_names",{}) or {}
    if not isinstance(current,dict):
        current={}
    # Do not replace an already recovered/custom registry.
    if _v967_named_team_count({"team_names":current}) >= max(2,int(s.get("teams",12))-2):
        return s
    ordered=[]
    my_label=None
    for e in s.get("draft_log",[]) or []:
        if not isinstance(e,dict):
            continue
        label=str(e.get("team","") or "").strip()
        if not label:
            continue
        owner_kind=str(e.get("owner","") or "").strip().lower()
        if owner_kind=="mine" or label.lower() in ("my team","griffin"):
            my_label="Griffin"
            continue
        if label not in ordered:
            ordered.append(label)
    if len(ordered)<5:
        return s
    total=max(int(s.get("teams",12) or 12),len(ordered)+1)
    recovered={"1": my_label or "Griffin"}
    for i,label in enumerate(ordered[:total-1],start=2):
        recovered[str(i)]=label
    for i in range(1,total+1):
        recovered.setdefault(str(i), current.get(str(i),"Griffin" if i==1 else f"Team {i}"))
    s["teams"]=total
    s["team_names"]=recovered
    s["_v967_team_registry_recovered_from_draft"]=True
    return s


def _v968_apply_packaged_draft_recovery(s):
    """Rebuild team ownership from the surviving cleaned 177-pick live draft log.

    This is only used when the active ownership map is materially less complete.
    Existing non-draft ownership records are preserved.
    """
    if not isinstance(s,dict):
        return s
    path=APP_DIR/"fantasy_edge_live_draft_log_recovery_177.csv"
    if not path.exists():
        return s
    try:
        import csv as _csv
        with path.open("r",encoding="utf-8-sig",newline="") as _fh:
            rows=list(_csv.DictReader(_fh))
    except Exception:
        return s
    if len(rows)<150:
        return s
    names={"1":"Griffin","2":"Scott","3":"Tia/katie","4":"Matt","5":"Brock","6":"Shane","7":"Connor","8":"Grace","9":"Denny","10":"Owen","11":"Sarah","12":"Randy"}
    def _n(v): return re.sub(r"[^a-z0-9]","",str(v or "").lower())
    aliases={_n(v):k for k,v in names.items()}
    aliases.update({"myteam":"1","griffin":"1","tiakatie":"3","satah":"11"})
    recovered={}
    cleanlog=[]
    for row in rows:
        p=str(row.get("player","") or "").strip()
        if not p: continue
        team=str(row.get("team","") or "").strip()
        owner_kind=str(row.get("owner","") or "").strip()
        tid="1" if owner_kind.lower()=="mine" or _n(team) in ("myteam","griffin") else aliases.get(_n(team),"ROSTERED_UNKNOWN")
        recovered[_owner_key(p)]={"player":p,"owner":tid}
        e={"owner":owner_kind,"team":team,"player":p,"position":str(row.get("position","") or "").strip()}
        for field in ("overall_pick","round"):
            val=str(row.get(field,"") or "").strip()
            e[field]=int(val) if val.isdigit() else val
        cleanlog.append(e)
    current=s.get("ownership",{}) or {}
    current_count=_v966_rostered_count(s)
    known_count=sum(1 for r in recovered.values() if str(r.get("owner"))!="ROSTERED_UNKNOWN")
    if current_count>=known_count:
        return s
    merged=dict(recovered)
    if isinstance(current,dict):
        for k,rec in current.items():
            if k not in merged and isinstance(rec,dict): merged[k]=rec
    s["teams"]=12; s["team_names"]=names; s["draft_log"]=cleanlog; s["ownership"]=merged
    s["my_team"]=[r.get("player") for r in merged.values() if isinstance(r,dict) and str(r.get("owner"))=="1"]
    s["taken"]=[r.get("player") for r in merged.values() if isinstance(r,dict) and str(r.get("owner"))!="FA"]
    s["_v968_full_draft_recovery"]=True
    s["_v968_recovered_assignments"]=known_count
    s["_v968_unknown_assignments"]=sum(1 for r in merged.values() if isinstance(r,dict) and str(r.get("owner"))=="ROSTERED_UNKNOWN")
    return s

def _v973_snapshot_identity(x):
    if not isinstance(x,dict): return ""
    key=str(x.get("key","") or "").strip()
    if key: return "key:"+key
    base=str(x.get("base_key","") or "").strip()
    rev=str(x.get("revision","") or "")
    if base: return f"base:{base}|r:{rev}"
    return "|".join([
        str(x.get("season","") or ""),str(x.get("week","") or ""),
        str(x.get("frozen_at",x.get("saved_at","")) or ""),str(x.get("checkpoint","") or "")
    ])

def _v973_merge_list_records(*lists):
    out={}
    loose=[]
    for seq in lists:
        if not isinstance(seq,list): continue
        for row in seq:
            if not isinstance(row,dict): continue
            ident=_v973_snapshot_identity(row)
            if not ident.strip("|"):
                loose.append(row); continue
            prev=out.get(ident)
            # Keep the richer copy if the same snapshot exists in several stores.
            richness=lambda r:(len(r.get("start_sit",[]) or []),len(r.get("waivers",[]) or []),len(r),len(str(r)))
            if prev is None or richness(row)>richness(prev): out[ident]=row
    vals=list(out.values())+loose
    try: vals=sorted(vals,key=lambda x:(int(x.get("season",0) or 0),int(x.get("week",0) or 0),str(x.get("frozen_at",x.get("saved_at","")) or ""),str(x.get("key","") or "")))
    except Exception: pass
    return vals

def _v973_read_history_vault():
    try:
        if _V973_HISTORY_VAULT_FILE.exists():
            x=json.loads(_V973_HISTORY_VAULT_FILE.read_text())
            return x if isinstance(x,dict) else {}
    except Exception: pass
    return {}

def _v973_write_history_vault(s):
    try:
        payload={
            "recommendation_history":list((s or {}).get("recommendation_history",[]) or []),
            "unified_decision_ledger":list((s or {}).get("unified_decision_ledger",[]) or []),
            "learning_receipts":list((s or {}).get("learning_receipts",[]) or []),
            "saved_at":datetime.now(timezone.utc).isoformat(),
            "app_version":APP_VERSION,
        }
        tmp=_V973_HISTORY_VAULT_FILE.with_suffix('.tmp')
        tmp.write_text(json.dumps(payload,indent=2,default=str)); tmp.replace(_V973_HISTORY_VAULT_FILE)
        return True
    except Exception as e:
        st.session_state["_v973_history_vault_error"]=repr(e); return False

def _v973_merge_calibration_layers(target,*sources):
    if not isinstance(target,dict): return target
    vault=_v973_read_history_vault()
    allsrc=[vault]+[x for x in sources if isinstance(x,dict)]
    target["recommendation_history"]=_v973_merge_list_records(target.get("recommendation_history",[]),*[x.get("recommendation_history",[]) for x in allsrc])
    # These ledgers are append-only evidence too. Use stable JSON identity so roster recovery can never erase them.
    for k in ("unified_decision_ledger","learning_receipts"):
        merged=[]; seen=set()
        for seq in [target.get(k,[])]+[x.get(k,[]) for x in allsrc]:
            if not isinstance(seq,list): continue
            for row in seq:
                try: ident=json.dumps(row,sort_keys=True,default=str)
                except Exception: ident=str(row)
                if ident in seen: continue
                seen.add(ident); merged.append(row)
        target[k]=merged
    return target

def _v1004_merge_free_agent_overrides(base, *sources):
    """Union explicit FA corrections across every discovered persistence layer."""
    vals=[]; seen=set()
    for src in (base,)+tuple(sources):
        if not isinstance(src,dict):
            continue
        for n in src.get("free_agent_overrides",[]) or []:
            k=_owner_key(n)
            if k and k not in seen:
                seen.add(k); vals.append(str(n))
    if isinstance(base,dict):
        base["free_agent_overrides"]=vals
    return base

def _v1039_parse_saved_at(value):
    try:
        dt=datetime.fromisoformat(str(value or "").replace("Z","+00:00"))
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=timezone.utc)
        return float(dt.timestamp())
    except Exception:
        return 0.0

def _v1039_state_recency(s):
    """Explicit user saves outrank legacy 'most complete' recovery snapshots.

    Before V10.39 the bootstrap preferred whichever file had the most rostered
    players.  That is useful for disaster recovery, but it can undo an intentional
    add/remove/move because a stale historical copy may have one extra player.
    """
    if not isinstance(s,dict):
        return (0.0,0)
    return (_v1039_parse_saved_at(s.get("_state_saved_at")), int(s.get("_state_revision",0) or 0))

def _v1039_mark_state_saved(s, reason="State save"):
    if not isinstance(s,dict):
        return s
    try: prev=int(s.get("_state_revision",0) or 0)
    except Exception: prev=0
    s["_state_revision"]=max(prev,0)+1
    s["_state_saved_at"]=datetime.now(timezone.utc).isoformat()
    s["_state_save_reason"]=str(reason or "State save")[:160]
    s["_state_save_app_version"]=str(APP_VERSION)
    return s

def _v1039_ownership_fingerprint(s):
    """Identity-level save verification; counts alone can hide a reverted move."""
    own=(s or {}).get("ownership",{}) or {}
    rows=[]
    if isinstance(own,dict):
        for rec in own.values():
            if not isinstance(rec,dict): continue
            p=str(rec.get("player","") or "").strip(); o=str(rec.get("owner","FA") or "FA")
            if p:
                rows.append((_owner_key(p),o))
    payload={
        "ownership":sorted(set(rows)),
        "team_names":sorted((str(k),str(v)) for k,v in ((s or {}).get("team_names",{}) or {}).items()),
        "free_agents":sorted(_owner_key(x) for x in ((s or {}).get("free_agent_overrides",[]) or []) if str(x).strip()),
    }
    return hashlib.sha256(json.dumps(payload,sort_keys=True,separators=(",",":"),default=str).encode("utf-8")).hexdigest()

def _v1039_write_local_state(s):
    """Atomic local commit so a cloud problem can never erase an editor action."""
    tmp=STATE.with_name(STATE.name+".tmp")
    tmp.write_text(json.dumps(s,indent=2))
    tmp.replace(STATE)
    chk=json.loads(STATE.read_text())
    if _v1039_ownership_fingerprint(chk)!=_v1039_ownership_fingerprint(s):
        raise RuntimeError("Local ownership verification mismatch after save.")
    return True


# ---------------- V10.43 strict Yahoo-slot IDP eligibility ----------------
# This league has one DL and one DB slot, but Yahoo's DL pool is not "all linebackers".
# Edge/outside linebackers can carry DL/DE eligibility while off-ball LB/ILB/MLB players
# are not valid substitutes for the DL slot.  Keep that distinction canonical across
# League Setup, the IDP model, Waivers, Start/Sit and Trade Finder.
_V1042_DL_RAW = {"DL","DE","DT","NT","EDGE","ED"}
_V1042_DB_RAW = {"DB","CB","S","FS","SS","SAF"}
_V1042_EDGE_LB_RAW = {"OLB","LOLB","ROLB"}
_V1042_OFFBALL_LB_RAW = {"LB","ILB","MLB","WLB","SLB"}
# V10.43: only verified dual-eligible edge players may use a curated fallback when a
# provider collapses their raw position to generic LB. Statistical pass-rush production
# is NEVER enough to manufacture Yahoo DL eligibility.
_V1043_YAHOO_DL_OVERRIDES = {
    norm(x) for x in [
        "Brian Burns","Trey Hendrickson","Donovan Ezeiruaku","Boye Mafe",
        "Josh Hines-Allen","Jonathan Greenard","Nick Herbig","Lukas Van Ness","Abdul Carter",
    ]
}

# V10.44: league/Yahoo truth beats provider heuristics and old cached classifications.
# Devin Lloyd was verified in the user's Yahoo league as NOT eligible for the DL slot.
# Keep this as a narrow current-season safety override until direct Yahoo eligibility
# metadata is available to the app.
_V1044_YAHOO_DL_DENY = {norm("Devin Lloyd")}

def _v1042_parse_fantasy_positions(value):
    if value is None:
        return set()
    if isinstance(value,(list,tuple,set)):
        vals=value
    else:
        txt=str(value).strip()
        if not txt:
            return set()
        try:
            parsed=json.loads(txt)
            vals=parsed if isinstance(parsed,(list,tuple,set)) else re.split(r"[,/| ]+",txt)
        except Exception:
            vals=re.split(r"[,/| ]+",txt.strip("[](){}'\""))
    return {str(v).upper().strip() for v in vals if str(v).strip()}

def _v1042_edge_role_from_stats(g):
    """Return (is_edge, score) for a generic LB using pass-rush vs tackle profile.

    It is intentionally conservative: an off-ball linebacker with one opportunistic sack
    should not suddenly become Yahoo-DL eligible.  Strong QB-hit/sack volume with a lower
    tackle-heavy profile can promote a generic LB into the edge lane.
    """
    if g is None or not isinstance(g,pd.DataFrame) or g.empty:
        return False,0.0
    def _sum(c):
        return float(pd.to_numeric(g.get(c,0.0),errors="coerce").fillna(0.0).sum()) if c in g.columns else 0.0
    games=max(int(pd.to_numeric(g.get("week",pd.Series(dtype=float)),errors="coerce").nunique()),1)
    solo=_sum("solo"); ast=_sum("assist"); sacks=_sum("sack"); qbh=_sum("qb_hit"); tfl=_sum("tfl")
    tackle_pg=(solo+ast)/games
    sack_pg=sacks/games; qbh_pg=qbh/games; tfl_pg=tfl/games
    pressure_pg=1.55*sack_pg+0.45*qbh_pg+0.18*tfl_pg
    pressure_share=(1.7*sacks+0.55*qbh+0.20*tfl)/max(solo+ast,1.0)
    edge=(
        sack_pg>=0.45
        or qbh_pg>=1.20
        or (sack_pg>=0.25 and qbh_pg>=0.50 and tackle_pg<=6.5)
        or (pressure_pg>=0.85 and pressure_share>=0.20 and tackle_pg<=6.0)
    )
    score=float(pressure_pg + 0.45*pressure_share - 0.035*max(tackle_pg-5.0,0.0))
    return bool(edge),round(score,4)

def _v1042_yahoo_idp_slot(raw_pos, fantasy_positions=None, player_name="", role_group=None):
    """Return (slot, source) using roster legality, never statistical inference.

    V10.43 intentionally ignores ``role_group`` for eligibility. A generic LB can rush
    the passer well and still be LB-only in Yahoo. Stats may shape a projection only
    after the player has independent DL/DB slot eligibility.
    """
    raw=str(raw_pos or "").upper().strip()
    fps=_v1042_parse_fantasy_positions(fantasy_positions)
    # Explicit Yahoo-league denial wins over stale provider/cache metadata.
    if norm(player_name) in _V1044_YAHOO_DL_DENY:
        return "","verified Yahoo league: not DL-eligible"
    if fps & _V1042_DB_RAW:
        return "DB","provider fantasy eligibility"
    if fps & _V1042_DL_RAW:
        return "DL","provider fantasy eligibility"
    if raw in _V1042_DB_RAW:
        return "DB","explicit defensive-back position"
    if raw in _V1042_DL_RAW:
        return "DL","explicit defensive-line/edge position"
    if norm(player_name) in _V1043_YAHOO_DL_OVERRIDES:
        return "DL","verified Yahoo dual-position override"
    if raw in (_V1042_OFFBALL_LB_RAW | _V1042_EDGE_LB_RAW):
        return "","LB-only/uncertified for this Yahoo DL slot"
    return "","unsupported defensive position"

def _v1039_directory_rows_from_sleeper(players):
    """League-editor identities using Yahoo-compatible DL/DB eligibility.

    Sleeper is still only an identity directory.  Its multi-position fantasy eligibility
    is useful for separating edge LBs from true off-ball linebackers; pure LB-only players
    are not exposed as DL in this Yahoo league.
    """
    if not isinstance(players,dict):
        return []
    offense={"QB":"QB","RB":"RB","HB":"RB","FB":"RB","WR":"WR","TE":"TE","K":"K"}
    rows=[]
    for pid,pl in players.items():
        if not isinstance(pl,dict) or pl.get("active") is False:
            continue
        raw=str(pl.get("position") or "").upper().strip()
        name=str(pl.get("full_name") or " ".join([pl.get("first_name") or "",pl.get("last_name") or ""]).strip()).strip()
        if not name:
            continue
        fantasy_positions=pl.get("fantasy_positions") or []
        pos=offense.get(raw)
        elig_source="offense"
        if not pos:
            pos,elig_source=_v1042_yahoo_idp_slot(raw,fantasy_positions,name)
        if not pos:
            continue
        team=str(pl.get("team") or "").upper().strip()
        rows.append({
            "player_id":str(pid),"player":name,"position":pos,"raw_position":raw,"team":team,"active":True,
            "fantasy_positions":fantasy_positions,"depth_chart_position":pl.get("depth_chart_position"),
            "depth_chart_order":pl.get("depth_chart_order"),"weight":pl.get("weight"),"yahoo_id":pl.get("yahoo_id"),
            "idp_eligibility_source":elig_source,
        })
    return rows

def _v1039_load_league_directory_snapshot():
    rows=[]
    chosen=None
    for _path in _v1060_nearby_files("fantasy_edge_league_directory_v1039.json"):
        try:
            if not _path.exists() or _path.stat().st_size<8: continue
            x=json.loads(_path.read_text(encoding="utf-8"))
            if isinstance(x,list) and any(isinstance(r,dict) and r.get("player") for r in x):
                chosen=x; break
        except Exception:
            continue
    if isinstance(chosen,list):
        rows.extend(r for r in chosen if isinstance(r,dict) and r.get("player"))
        try:
            payload=json.dumps(chosen,indent=2)
            _v1060_atomic_text(_V1039_LEAGUE_DIRECTORY_FILE,payload)
            _v1060_atomic_text(_V1060_SHARED_DIRECTORY,payload)
        except Exception: pass
    rows.extend(dict(r) for r in _V1039_LEAGUE_DIRECTORY_SEED)
    dedup={}
    for r in rows:
        k=_owner_key(r.get("player",""))
        if k: dedup[k]=r
    return list(dedup.values())

def _v1039_league_player_directory(refresh_live=False):
    """Complete identity universe for League Setup, independent of fantasy rank.

    A successful live call is persisted for future navigation.  If the provider is
    unavailable, the last snapshot plus packaged critical identities remain usable.
    """
    rows=_v1039_load_league_directory_snapshot()
    try:
        active=globals().get("_active_roster_export")
        if isinstance(active,pd.DataFrame) and not active.empty:
            rows.extend(active[[c for c in ["player_id","player","position","raw_position","team","active"] if c in active.columns]].to_dict("records"))
    except Exception:
        pass
    if refresh_live:
        try:
            live_rows=_v1039_directory_rows_from_sleeper(sleeper_players())
            if live_rows:
                rows.extend(live_rows)
                try:
                    _payload=json.dumps(live_rows,indent=2)
                    _v1060_atomic_text(_V1039_LEAGUE_DIRECTORY_FILE,_payload)
                    _v1060_atomic_text(_V1060_SHARED_DIRECTORY,_payload)
                except Exception: pass
        except Exception as e:
            st.session_state["_v1039_league_directory_error"]=repr(e)
    dedup={}
    for r in rows:
        if not isinstance(r,dict): continue
        k=_owner_key(r.get("player",""))
        if not k: continue
        # Prefer rows with a real position/team over seed/minimal rows.
        prev=dedup.get(k,{})
        score=lambda z: int(bool(z.get("position")))+int(bool(z.get("team")))+int(bool(z.get("player_id")))
        if not prev or score(r)>=score(prev): dedup[k]=dict(r)
    return pd.DataFrame(list(dedup.values())) if dedup else pd.DataFrame(columns=["player","position","raw_position","team"])


# ---------------- V10.41 league edit authority ----------------
# Weekly refresh runtime state is intentionally broad, but roster/team edits are
# user-authored league truth.  A stale runtime snapshot must never overwrite them
# after an add/remove/move from the isolated League Setup fragment.
_V1041_LEAGUE_AUTH_KEYS = (
    "ownership","my_team","taken","team_names","free_agent_overrides",
    "teams","roster_slots","ppr","pass_td","faab","idp","kicker","mock",
)

def _v1041_merge_runtime_state(local_state, runtime_state):
    base=dict(local_state or {})
    runtime=dict(runtime_state or {}) if isinstance(runtime_state,dict) else {}
    out=dict(base)
    out.update(runtime)
    for key in _V1041_LEAGUE_AUTH_KEYS:
        if key in base:
            out[key]=base[key]
        else:
            out.pop(key,None)
    # Save receipts are part of the same authority contract.  They let recency
    # recovery choose the explicit user edit rather than an older runtime copy.
    for key in ("_state_revision","_state_saved_at_utc","_state_save_reason"):
        if key in base:
            out[key]=base[key]
    return out

def _v1041_sync_runtime_league_state(s):
    """Update the in-session refresh handoff with the newest league edit."""
    try:
        runtime=dict(st.session_state.get("_v794_runtime_state",{}) or {})
        for key in _V1041_LEAGUE_AUTH_KEYS:
            if key in s:
                runtime[key]=s[key]
            else:
                runtime.pop(key,None)
        for key in ("_state_revision","_state_saved_at_utc","_state_save_reason"):
            if key in s: runtime[key]=s[key]
        st.session_state["_v794_runtime_state"]=runtime
    except Exception:
        pass

def _v1041_reset_roster_editor_cache():
    """Discard per-team editor drafts after an authoritative roster commit."""
    try:
        for key in list(st.session_state.keys()):
            sk=str(key)
            if sk.startswith("v926_roster_draft_") or sk.startswith("v926_roster_base_") or sk.startswith("v926_dirty_"):
                st.session_state.pop(key,None)
    except Exception:
        pass


def _v1041_invalidate_league_derivatives(s):
    """Roster edits invalidate roster-dependent recommendations, not NFL data."""
    if isinstance(s,dict):
        s["_v779_trade_ideas"]=[]
        s["_v935_trade_scan_meta"]={}
        s.pop("_v850_trade_scan_diagnostics",None)
    try:
        st.session_state["_v742_waiver_transactions"]=[]
        for key in list(st.session_state.keys()):
            sk=str(key)
            if sk.startswith("_v935_trade") or sk.startswith("_v933_scarcity") or sk.startswith("_v728_command"):
                st.session_state.pop(key,None)
    except Exception:
        pass

def _v1041_full_app_rerun():
    """League edits must rebuild the whole app, not only the navigation fragment."""
    try:
        st.rerun(scope="app")
    except TypeError:
        st.rerun()


def load_state():
    """V9.67 local/history/cloud bootstrap with safe league recovery.

    A fresh web container can have an empty local JSON even while the cloud sync
    receipt says CONNECTED_VERIFIED. Prefer the most complete real league state,
    and use the embedded last-known-good snapshot only when both real sources are
    empty. This prevents the UI from showing Rostered 0 after redeploy/restart.
    """
    default={
        "teams":12,"ppr":1.0,"pass_td":4,"faab":100,
        "my_team":[],"taken":[],"ownership":{},"team_names":{},"injury_overrides":{},"free_agent_overrides":[],
        "roster_slots":{"QB":1,"RB":2,"WR":2,"TE":1,"FLEX":2,"K":1,"DL":1,"DB":1,"BENCH":6},
        "mock":{"draft_slot":1,"rounds":17,"randomness":12},
        "idp":{"solo":1.0,"assist":0.5,"sack":4.0,"tfl":2.0,"qb_hit":0.0,
               "int":7.0,"pd":2.0,"ff":4.0,"fr":4.0,"def_td":12.0,"safety":8.0},
        "kicker":{"pat":1.0,"fg_0_19":3.0,"fg_20_29":3.0,"fg_30_39":3.0,
                  "fg_40_49":4.0,"fg_50_59":4.5,"fg_60_plus":5.5,
                  "missed_fg":0.0,"missed_pat":0.0}
    }
    local=None
    if STATE.exists():
        try:
            x=json.loads(STATE.read_text())
            if isinstance(x,dict): local=x
        except Exception:
            local=None

    cloud=None; cloud_updated=""
    try:
        row=_cloud_probe()
        if isinstance(row,dict) and isinstance(row.get("state"),dict):
            cloud=row["state"]; cloud_updated=str(row.get("updated_at","") or "")
    except Exception:
        cloud=None

    # V9.67: also inspect nearby pre-V9.64 state paths. A folder-layout change can
    # make the current APP_DIR look empty while the real league survives next door.
    historical=_v967_historical_local_states()
    hist_path=None; hist=None
    if historical:
        hist_path,hist,_=max(historical,key=lambda row: row[2])

    lc=_v966_rostered_count(local); cc=_v966_rostered_count(cloud); hc=_v966_rostered_count(hist)
    chosen=None; source="DEFAULT"
    # Compare full league quality, not roster count alone. Custom team names and
    # draft history break ties so a generic packaged shell cannot beat a real league.
    candidates=[]
    if isinstance(local,dict): candidates.append(("LOCAL",local,_v967_state_score(local)))
    if isinstance(cloud,dict): candidates.append(("CLOUD_RECOVERED",cloud,_v967_state_score(cloud)))
    if isinstance(hist,dict): candidates.append(("HISTORICAL_PATH_RECOVERED",hist,_v967_state_score(hist)))
    # V10.39: once any source contains an explicit user-save receipt, recency is
    # authoritative.  Do not resurrect a stale copy merely because it has more
    # rostered players; that behavior made deliberate removals/moves look unsaved.
    _explicit=[row for row in candidates if _v1039_state_recency(row[1])>(0.0,0)]
    if _explicit:
        _pref={"LOCAL":2,"CLOUD_RECOVERED":1,"HISTORICAL_PATH_RECOVERED":0}
        source,chosen,_=max(_explicit,key=lambda row: (_v1039_state_recency(row[1]),_pref.get(row[0],-1)))
    elif candidates and max(x[2][0] for x in candidates)>0:
        source,chosen,_=max(candidates,key=lambda row: row[2])
    if chosen is None:
        # Preserve non-ownership custom settings if either source has them, but if
        # all discovered sources lack a league roster, recover the packaged last-known-good league.
        meaningful_local=isinstance(local,dict) and bool(local.get("my_team") or local.get("draft_log") or local.get("taken"))
        meaningful_cloud=isinstance(cloud,dict) and bool(cloud.get("my_team") or cloud.get("draft_log") or cloud.get("taken"))
        if meaningful_cloud:
            chosen=cloud; source="CLOUD_METADATA_RECOVERED"
        elif meaningful_local:
            chosen=local; source="LOCAL_METADATA"
        else:
            seed=_v966_recovery_seed()
            if _v966_rostered_count(seed)>0 or seed.get("my_team"):
                chosen=seed; source="EMBEDDED_RECOVERY"

    out=_v966_merge_state(default,chosen or {})
    out=_v968_apply_packaged_draft_recovery(out)
    out=_v967_recover_team_names_from_draft(out)
    # V9.73: calibration evidence is independent of roster completeness. Merge it
    # from every discovered store so a roster-recovery winner can never erase weeks.
    out=_v973_merge_calibration_layers(out,local,cloud,hist)
    out=_v1004_merge_free_agent_overrides(out,local,cloud,hist)
    # V10.04: explicit free-agent corrections are authoritative over every legacy
    # ownership/recovery layer. Apply before rebuilding my_team.
    out=_apply_free_agent_overrides(out)

    # Repair the legacy my_team list from authoritative ownership whenever possible.
    own=out.get("ownership",{}) or {}
    owned_team1=[]
    if isinstance(own,dict):
        owned_team1=[str(v.get("player")) for v in own.values()
                     if isinstance(v,dict) and str(v.get("owner"))=="1" and str(v.get("player","")).strip()]
    if owned_team1 and not out.get("my_team"):
        out["my_team"]=list(dict.fromkeys(owned_team1))

    st.session_state["_v966_boot_source"]=source
    st.session_state["_v966_boot_local_rostered"]=int(lc)
    st.session_state["_v966_boot_cloud_rostered"]=int(cc)
    st.session_state["_v966_boot_cloud_updated_at"]=cloud_updated
    st.session_state["_v967_boot_historical_rostered"]=int(hc)
    st.session_state["_v967_boot_historical_path"]=str(hist_path or "")
    st.session_state["_v967_team_names_recovered"]=bool(out.get("_v967_team_registry_recovered_from_draft"))

    # If recovery found a populated state, persist it locally so the next rerun is
    # stable even when the cloud becomes temporarily unavailable.
    if _v966_rostered_count(out)>0:
        try: STATE.write_text(json.dumps(out,indent=2))
        except Exception: pass
    return out

def exact_roster_rounds(slots):
    """Total draft rounds implied by the exact roster template."""
    return int(sum(max(int(slots.get(p,0)),0) for p in ["QB","RB","WR","TE","FLEX","K","DL","DB","BENCH"]))

def _cloud_config():
    # Streamlit secrets can override these packaged publishable settings.
    try:
        url=str(st.secrets.get("SUPABASE_URL",_CLOUD_DEFAULT_URL)).rstrip("/")
        key=str(st.secrets.get("SUPABASE_PUBLISHABLE_KEY",_CLOUD_DEFAULT_KEY))
    except Exception:
        url=_CLOUD_DEFAULT_URL; key=_CLOUD_DEFAULT_KEY
    return url,key

def _cloud_headers():
    _,key=_cloud_config()
    h={"apikey":key,"Content-Type":"application/json"}
    # Legacy anon keys are JWTs and may be used as Bearer tokens.
    # Modern sb_publishable_* keys should be sent as apikey only.
    if key.startswith("eyJ"):
        h["Authorization"]=f"Bearer {key}"
    return h

def _cloud_probe():
    """Read the cloud row without mutating local or remote state."""
    url,_=_cloud_config()
    endpoint=f"{url}/rest/v1/fantasy_edge_state?league_key=eq.{CLOUD_LEAGUE_KEY}&select=state,updated_at"
    req=urllib.request.Request(endpoint,headers=_cloud_headers(),method="GET")
    with urllib.request.urlopen(req,timeout=5) as r:
        rows=json.loads(r.read().decode("utf-8"))
    if rows and isinstance(rows[0].get("state"),dict):
        return {"state":rows[0]["state"],"updated_at":rows[0].get("updated_at","")}
    return None

def _cloud_load():
    row=_cloud_probe()
    return row.get("state") if isinstance(row,dict) else None

def _v705_ownership_stats(s):
    own=(s or {}).get("ownership",{}) or {}
    if not isinstance(own,dict): own={}
    rostered=0; unknown=0; fa=0
    for entry in own.values():
        if not isinstance(entry,dict): continue
        owner=str(entry.get("owner","FA"))
        if owner=="FA": fa+=1
        elif owner=="ROSTERED_UNKNOWN":
            rostered+=1; unknown+=1
        else:
            rostered+=1
    return {"rostered":rostered,"unknown":unknown,"free_agents":fa,"ownership_entries":len(own)}

def _v705_state_is_suspicious(candidate,baseline):
    """Protect a complete local league from obviously incomplete/stale cloud payloads."""
    c=_v705_ownership_stats(candidate); b=_v705_ownership_stats(baseline)
    if b["rostered"]>=50 and c["rostered"]==0:
        return True,"Cloud ownership map is empty while the local league is populated."
    if b["rostered"]>=100 and c["rostered"] < b["rostered"]-12:
        return True,f"Cloud has {c['rostered']} rostered players vs {b['rostered']} locally."
    if c["unknown"] > b["unknown"]+10 and b["unknown"]<=5:
        return True,f"Cloud contains {c['unknown']} unknown-team assignments vs {b['unknown']} locally."
    return False,""

def _v705_write_sync_status(ok,mode,error="",cloud_updated_at=""):
    payload={
        "ok":bool(ok),"mode":str(mode),"error":str(error or ""),
        "cloud_updated_at":str(cloud_updated_at or ""),
        "checked_at":datetime.now(timezone.utc).isoformat()
    }
    try: _SYNC_STATUS_FILE.write_text(json.dumps(payload,indent=2))
    except Exception: pass
    st.session_state["_v657_cloud_ok"]=bool(ok)
    st.session_state["_v657_cloud_error"]=str(error or "")
    st.session_state["_v705_cloud_mode"]=str(mode)
    st.session_state["_v705_cloud_updated_at"]=str(cloud_updated_at or "")
    st.session_state["_v705_cloud_checked_at"]=payload["checked_at"]

def _v705_read_sync_status():
    try:
        if _SYNC_STATUS_FILE.exists():
            x=json.loads(_SYNC_STATUS_FILE.read_text())
            return x if isinstance(x,dict) else {}
    except Exception: pass
    return {}

def _v924_authoritative_sync_status():
    """Return one canonical league-sync status for every League Setup surface.

    V9.24 fixes the split-brain state where the persisted sync receipt could say
    CONNECTED_VERIFIED while a fresh Streamlit session defaulted _cloud_ok=False.
    The most recently checked status wins, then all legacy session keys are
    synchronized from that single object so compact and recovery UIs cannot
    contradict each other.
    """
    persisted=_v705_read_sync_status()
    session_status={
        "ok": bool(st.session_state.get("_v657_cloud_ok", False)),
        "mode": str(st.session_state.get("_v705_cloud_mode", "UNKNOWN") or "UNKNOWN"),
        "error": str(st.session_state.get("_v657_cloud_error", "") or ""),
        "cloud_updated_at": str(st.session_state.get("_v705_cloud_updated_at", "") or ""),
        "checked_at": str(st.session_state.get("_v705_cloud_checked_at", "") or ""),
    }

    def _ts(v):
        try:
            return datetime.fromisoformat(str(v or "").replace("Z","+00:00")).timestamp()
        except Exception:
            return 0.0

    # A persisted receipt is authoritative on new sessions. If this browser has
    # performed a newer test/save, its newer checked_at wins instead.
    if isinstance(persisted,dict) and persisted:
        chosen = session_status if _ts(session_status.get("checked_at")) > _ts(persisted.get("checked_at")) else persisted
    else:
        chosen = session_status

    out={
        "ok": bool(chosen.get("ok",False)),
        "mode": str(chosen.get("mode","UNKNOWN") or "UNKNOWN"),
        "error": str(chosen.get("error","") or ""),
        "cloud_updated_at": str(chosen.get("cloud_updated_at","") or ""),
        "checked_at": str(chosen.get("checked_at","") or ""),
    }
    st.session_state["_v657_cloud_ok"]=out["ok"]
    st.session_state["_v657_cloud_error"]=out["error"]
    st.session_state["_v705_cloud_mode"]=out["mode"]
    st.session_state["_v705_cloud_updated_at"]=out["cloud_updated_at"]
    st.session_state["_v705_cloud_checked_at"]=out["checked_at"]
    st.session_state["_v924_sync_status"]=dict(out)
    return out

def _cloud_save(s):
    """Write the current state to the shared league row.
    Update-first avoids ambiguous upsert behavior with RLS/PostgREST.
    """
    url,_=_cloud_config()
    headers=_cloud_headers()
    headers["Prefer"]="return=representation"

    # 1) Update the known row directly.
    patch_endpoint=f"{url}/rest/v1/fantasy_edge_state?league_key=eq.{CLOUD_LEAGUE_KEY}"
    patch_payload=json.dumps({"state":s,"updated_at":datetime.now(timezone.utc).isoformat()}).encode("utf-8")
    patch_req=urllib.request.Request(patch_endpoint,data=patch_payload,headers=headers,method="PATCH")
    with urllib.request.urlopen(patch_req,timeout=6) as r:
        body=r.read().decode("utf-8")
        if not (200 <= int(r.status) < 300):
            raise RuntimeError(f"Cloud PATCH failed HTTP {r.status}")
        rows=json.loads(body) if body.strip() else []
        if isinstance(rows,list) and len(rows)>0:
            return True

    # 2) If the row somehow does not exist, insert it.
    post_endpoint=f"{url}/rest/v1/fantasy_edge_state"
    post_payload=json.dumps({
        "league_key":CLOUD_LEAGUE_KEY,
        "state":s,
        "updated_at":datetime.now(timezone.utc).isoformat()
    }).encode("utf-8")
    post_req=urllib.request.Request(post_endpoint,data=post_payload,headers=headers,method="POST")
    with urllib.request.urlopen(post_req,timeout=6) as r:
        if not (200 <= int(r.status) < 300):
            raise RuntimeError(f"Cloud POST failed HTTP {r.status}")
    return True

def save_state(s, reason="State save"):
    """V10.39 local-first, identity-verified save.

    Local persistence is committed atomically before any network operation. Cloud
    verification compares the exact ownership fingerprint and save revision, not
    only roster counts, so a move/remove cannot be falsely reported as saved.
    """
    _v1039_mark_state_saved(s,reason)
    # Preserve the local append-only evidence vault without waiting on the network.
    _v973_merge_calibration_layers(s)
    _v973_write_history_vault(s)
    _v1039_write_local_state(s)
    _v1041_sync_runtime_league_state(s)
    result={"local":True,"cloud":False,"revision":int(s.get("_state_revision",0) or 0),"error":""}
    try:
        # Preserve calibration evidence that may exist only in the connected copy.
        # The ownership edit is already durable locally, so a failed probe cannot
        # undo the user's roster action.
        _pre_row=_cloud_probe()
        _pre_state=_pre_row.get("state") if isinstance(_pre_row,dict) else None
        if isinstance(_pre_state,dict):
            _v973_merge_calibration_layers(s,_pre_state)
            _v973_write_history_vault(s)
            _v1039_write_local_state(s)
        _cloud_save(s)
        row=_cloud_probe()
        chk=row.get("state") if isinstance(row,dict) else None
        if not isinstance(chk,dict):
            raise RuntimeError("Cloud verification returned no state.")
        if _v1039_ownership_fingerprint(chk)!=_v1039_ownership_fingerprint(s):
            raise RuntimeError("Cloud ownership verification mismatch after save.")
        if int(chk.get("_state_revision",0) or 0)!=int(s.get("_state_revision",0) or 0):
            raise RuntimeError("Cloud save revision did not round-trip.")
        # Merge any cloud-only calibration evidence after ownership is verified,
        # then keep the merged copy locally for the next startup.
        _v973_merge_calibration_layers(s,chk)
        _v973_write_history_vault(s)
        _v1039_write_local_state(s)
        _v705_write_sync_status(True,"CONNECTED_VERIFIED","",row.get("updated_at","") if isinstance(row,dict) else "")
        result["cloud"]=True
    except Exception as e:
        result["error"]=repr(e)
        _v705_write_sync_status(False,"LOCAL_ONLY",repr(e),"")
    st.session_state["_v1039_last_save_receipt"]=dict(result)
    return result

def _owner_key(name):
    """Canonical ownership/player identity key; Unicode accents and suffix aliases collapse.

    V11.08: ownership previously removed non-ASCII letters *before* Unicode
    decomposition.  That made e.g. ``Jevón Holland`` -> ``jevnholland`` while
    ``Jevon Holland`` -> ``jevonholland`` and allowed one NFL player to appear
    twice in League Setup.  Normalize to ASCII first, then apply the existing
    punctuation/suffix rules so every surface shares one stable identity key.
    """
    s=unicodedata.normalize("NFKD",str(name or "")).encode("ascii","ignore").decode("ascii")
    s=s.strip().lower().replace("’","'").replace("`","'")
    s=re.sub(r"\b(jr|sr|ii|iii|iv|v)\.?\s*$","",s,flags=re.I).strip()
    s=re.sub(r"[^a-z0-9]","",s)
    aliases={
        "kenwalker":"kennethwalker",
        "kennethwalkeriii":"kennethwalker",
        "kennygainwell":"kennethgainwell",
        "kennethgainwell":"kennethgainwell",
        # V11.08 one-time migration for the malformed key produced by the old
        # accent-dropping ownership normalizer.  New Unicode names are handled
        # generically by NFKD above; this alias only recovers legacy saved state.
        "jevnholland":"jevonholland",
    }
    return aliases.get(s,s)

def _v1108_unique_display_names(names):
    """Return one display label per canonical player, preserving first-source preference."""
    out=[]; seen=set()
    for value in (names or []):
        name=str(value or "").strip()
        key=_owner_key(name)
        if not name or not key or key in seen:
            continue
        seen.add(key); out.append(name)
    return out

def _ensure_ownership_state(s, names=None):
    # V6.75 collapse legacy suffix-specific ownership keys on every load.
    _legacy_own=s.get("ownership",{}) or {}
    if isinstance(_legacy_own,dict) and _legacy_own:
        _canon={}
        for _legacy_key,_entry in _legacy_own.items():
            if not isinstance(_entry,dict):
                continue
            _display=str(_entry.get("player","") or _legacy_key).strip()
            _key=_owner_key(_display)
            if not _key:
                continue
            _owner=str(_entry.get("owner","FREE AGENT"))
            _prev=_canon.get(_key)
            if _prev is None or (_prev.get("owner")=="FREE AGENT" and _owner!="FREE AGENT"):
                _canon[_key]={"player":_display,"owner":_owner}
        s["ownership"]=_canon

    if not isinstance(s.get("ownership"),dict): s["ownership"]={}
    if not isinstance(s.get("team_names"),dict): s["team_names"]={}
    for i in range(1,int(s.get("teams",12))+1):
        s["team_names"].setdefault(str(i),"My Team" if i==1 else f"Team {i}")
    own=s["ownership"]
    _override_keys={_owner_key(x) for x in (s.get("free_agent_overrides",[]) or []) if str(x).strip()}
    # Canonicalize any pre-V6.59 ownership keys and resolve collisions. An
    # explicit numbered team always wins over ROSTERED_UNKNOWN.
    reconciled={}
    for oldk,rec in list(own.items()):
        if not isinstance(rec,dict): continue
        player=str(rec.get("player",oldk)).strip()
        if not player: continue
        k=_owner_key(player)
        incoming={"player":player,"owner":str(rec.get("owner","ROSTERED_UNKNOWN"))}
        existing=reconciled.get(k)
        if existing is None or (existing.get("owner")=="ROSTERED_UNKNOWN" and incoming.get("owner")!="ROSTERED_UNKNOWN"):
            reconciled[k]=incoming
    own.clear(); own.update(reconciled)
    # Recover ownership from the persistent draft log too. This protects against
    # older versions that wrote a draft_log entry but did not immediately update
    # the ownership map.
    for entry in s.get("draft_log",[]) or []:
        if not isinstance(entry,dict):
            continue
        p=str(entry.get("player","")).strip()
        if not p:
            continue
        owner_kind=str(entry.get("owner","")).strip().lower()
        team_text=str(entry.get("team","")).strip()
        if owner_kind=="mine" or team_text.lower() in ("my team","griffin"):
            recovered_owner="1"
        else:
            # Prefer a recovered custom team-name registry when available.
            recovered_owner="ROSTERED_UNKNOWN"
            for _tid,_nm in (s.get("team_names",{}) or {}).items():
                if str(_nm).strip().lower()==team_text.lower() and str(_tid)!="1":
                    recovered_owner=str(_tid); break
            if recovered_owner=="ROSTERED_UNKNOWN":
                m=re.search(r"(?:team\s*)?(\d+)$",team_text.lower())
                if m and 1 <= int(m.group(1)) <= int(s.get("teams",12)):
                    recovered_owner=str(int(m.group(1)))
        k=_owner_key(p)
        if k in _override_keys:
            continue
        existing=own.get(k)
        if existing is None or (existing.get("owner")=="ROSTERED_UNKNOWN" and recovered_owner!="ROSTERED_UNKNOWN"):
            own[k]={"player":p,"owner":recovered_owner}

    for n in s.get("taken",[]) or []:
        if str(n).strip() and _owner_key(n) not in _override_keys:
            own.setdefault(_owner_key(n),{"player":str(n).strip(),"owner":"ROSTERED_UNKNOWN"})
    for n in s.get("my_team",[]) or []:
        if str(n).strip() and _owner_key(n) not in _override_keys:
            own[_owner_key(n)]={"player":str(n).strip(),"owner":"1"}
    if names:
        bykey={_owner_key(n):str(n) for n in names if str(n).strip()}
        for k,rec in own.items():
            if k in bykey and isinstance(rec,dict): rec["player"]=bykey[k]
    return s

def _free_agent_override_keys(s):
    """Canonical players explicitly confirmed as free agents by the league owner.

    These overrides are authoritative over legacy taken/my_team/draft recovery data.
    They exist because compatibility layers can otherwise resurrect a manually freed
    player after cloud recovery or deployment.
    """
    vals=(s.get("free_agent_overrides",[]) or []) if isinstance(s,dict) else []
    return {_owner_key(x) for x in vals if str(x).strip()}

def _apply_free_agent_overrides(s):
    if not isinstance(s,dict):
        return s
    keys=_free_agent_override_keys(s)
    if not keys:
        return s
    own=s.get("ownership",{}) or {}
    if isinstance(own,dict):
        for k in list(own.keys()):
            rec=own.get(k)
            disp=(rec.get("player",k) if isinstance(rec,dict) else k)
            if _owner_key(disp) in keys or _owner_key(k) in keys:
                own.pop(k,None)
    s["ownership"]=own
    s["my_team"]=[x for x in (s.get("my_team",[]) or []) if _owner_key(x) not in keys]
    s["taken"]=[x for x in (s.get("taken",[]) or []) if _owner_key(x) not in keys]
    return s

def _player_owner(s,name):
    if _owner_key(name) in _free_agent_override_keys(s):
        return "FA"
    rec=(s.get("ownership") or {}).get(_owner_key(name))
    return rec.get("owner","FA") if isinstance(rec,dict) else "FA"

def _is_free_agent(s,name):
    """Return True only when all persisted ownership sources say free agent."""
    key=_owner_key(name)
    if key in _free_agent_override_keys(s):
        return True
    if _player_owner(s,name)!="FA":
        return False
    legacy_names=list(s.get("taken",[]) or [])+list(s.get("my_team",[]) or [])
    if key in {_owner_key(n) for n in legacy_names if str(n).strip()}:
        return False
    for entry in s.get("draft_log",[]) or []:
        if isinstance(entry,dict) and _owner_key(entry.get("player",""))==key:
            return False
    return True

def _sync_legacy_from_ownership(s):
    s=_apply_free_agent_overrides(s)
    _fa_overrides=_free_agent_override_keys(s)
    my=[]; taken=[]
    for rec in (s.get("ownership") or {}).values():
        if not isinstance(rec,dict): continue
        p=str(rec.get("player","")).strip(); o=str(rec.get("owner","FA"))
        if not p or o=="FA" or _owner_key(p) in _fa_overrides: continue
        taken.append(p)
        if o=="1": my.append(p)
    s["my_team"]=list(dict.fromkeys(my)); s["taken"]=list(dict.fromkeys(taken))
    return s

@st.cache_data(ttl=1800)
def sleeper_players():
    # Used only as a live NFL player directory, not as the fantasy-league source.
    r=requests.get("https://api.sleeper.app/v1/players/nfl",timeout=6)
    r.raise_for_status()
    return r.json()

def _v806_csv_release(url, max_bytes=32*1024*1024):
    """Bound downloads that pandas otherwise reads with no usable time limit."""
    payload=io.BytesIO()
    started=time.monotonic()
    with requests.get(url,stream=True,timeout=(4,12),headers={"User-Agent":"FantasyEdge/8.06"}) as response:
        response.raise_for_status()
        for chunk in response.iter_content(chunk_size=262144):
            if time.monotonic()-started>25:
                raise TimeoutError("NFL CSV download exceeded 25 seconds")
            payload.write(chunk)
            if payload.tell()>max_bytes:
                raise RuntimeError("NFL CSV exceeds download limit")
    payload.seek(0)
    return pd.read_csv(payload,low_memory=False)

def _v1059_weekly_stats_cache_path(year):
    try:
        _V1059_NATIVE_CACHE_DIR.mkdir(parents=True,exist_ok=True)
    except Exception:
        pass
    return _V1059_NATIVE_CACHE_DIR / f"weekly_stats_{int(year)}.csv.gz"

def _v1059_load_weekly_stats_disk(year):
    """Last-known-good completed-game stats across app versions."""
    name=f"weekly_stats_{int(year)}.csv.gz"
    candidates=[_v1059_weekly_stats_cache_path(year),_V1060_SHARED_NATIVE_DIR/name]
    try: candidates += _v1060_nearby_files(name,nested_glob=f"fantasy_edge_native_cache_v1059/{name}")
    except Exception: pass
    seen=set()
    for path in candidates:
        try:
            path=Path(path); rp=str(path.resolve())
            if rp in seen: continue
            seen.add(rp)
            if not path.exists() or path.stat().st_size<=256: continue
            x=pd.read_csv(path,compression="gzip",low_memory=False)
            if isinstance(x,pd.DataFrame) and not x.empty:
                # Promote a recovered sibling cache into the new stable locations.
                if path not in {_v1059_weekly_stats_cache_path(year),_V1060_SHARED_NATIVE_DIR/name}:
                    try: _v1059_save_weekly_stats_disk(year,x)
                    except Exception: pass
                return x
        except Exception: continue
    return pd.DataFrame()

def _v1059_save_weekly_stats_disk(year,df):
    if not isinstance(df,pd.DataFrame) or df.empty: return False
    ok=False
    for path in [_v1059_weekly_stats_cache_path(year),_V1060_SHARED_NATIVE_DIR/f"weekly_stats_{int(year)}.csv.gz"]:
        try:
            path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)
            tmp=path.with_suffix(path.suffix+".tmp")
            df.to_csv(tmp,index=False,compression="gzip")
            tmp.replace(path); ok=True
        except Exception: pass
    return ok

@st.cache_data(ttl=3600,show_spinner=False)
def _v1059_weekly_stats_live(year):
    """Successful live nflverse downloads are cached; failures raise and are NOT cached."""
    url=f"https://github.com/nflverse/nflverse-data/releases/download/stats_player/stats_player_week_{int(year)}.csv"
    x=_v806_csv_release(url)
    if not isinstance(x,pd.DataFrame) or x.empty:
        raise RuntimeError("nflverse weekly stats returned no rows")
    _v1059_save_weekly_stats_disk(year,x)
    return x

def _v806_weekly_stats(year):
    """Navigation-safe stats: persistent actuals first; live only on a true cold start."""
    cached=_v1059_load_weekly_stats_disk(int(year))
    if isinstance(cached,pd.DataFrame) and not cached.empty:
        return cached
    try:
        return _v1059_weekly_stats_live(int(year))
    except Exception:
        return pd.DataFrame()

# Preserve the legacy cache-clear contract used by grading/manual-refresh code.
_v806_weekly_stats.clear=_v1059_weekly_stats_live.clear

@st.cache_data(ttl=900,show_spinner=False)
def _v1059_sleeper_completed_stats_frame(season,target_week):
    """Secondary completed-game stat bridge for native offense/K/IDP models.

    This is actual box-score production, not a projection feed.  It normalizes the
    Sleeper weekly stats schema into the small nflverse-compatible subset consumed by
    Fantasy Edge's native models.  It is used only when the primary weekly-stats table
    is unavailable inside the bounded refresh window.
    """
    try:
        season=int(season); target_week=max(1,int(target_week))
    except Exception:
        return pd.DataFrame()
    if target_week<=1:
        return pd.DataFrame()
    try:
        directory=sleeper_players() or {}
    except Exception:
        directory={}
    if not isinstance(directory,dict) or not directory:
        return pd.DataFrame()

    def num(d,*keys):
        for k in keys:
            try:
                if isinstance(d,dict) and k in d and d.get(k) is not None:
                    v=float(d.get(k))
                    if np.isfinite(v): return v
            except Exception:
                pass
        return 0.0
    rows=[]
    for week in range(1,target_week):
        payload=None
        for url in [
            f"https://api.sleeper.app/v1/stats/nfl/regular/{season}/{week}",
            f"https://api.sleeper.com/stats/nfl/regular/{season}/{week}",
        ]:
            try:
                r=requests.get(url,timeout=4,headers={"User-Agent":f"FantasyEdge/{APP_VERSION}"})
                r.raise_for_status(); data=r.json()
                if isinstance(data,(dict,list)):
                    payload=data; break
            except Exception:
                continue
        if payload is None: continue
        if isinstance(payload,dict):
            items=[(str(pid),item) for pid,item in payload.items() if isinstance(item,dict)]
        else:
            items=[]
            for item in payload:
                if not isinstance(item,dict): continue
                pid=str(item.get("player_id") or item.get("playerId") or item.get("id") or ((item.get("player") or {}).get("player_id") if isinstance(item.get("player"),dict) else "") or "")
                if pid: items.append((pid,item))
        for pid,item in items:
            pl=directory.get(pid,{}) if isinstance(directory.get(pid,{}),dict) else {}
            stx=item.get("stats") if isinstance(item.get("stats"),dict) else item
            if not isinstance(stx,dict): continue
            name=str(pl.get("full_name") or pl.get("search_full_name") or (str(pl.get("first_name") or "")+" "+str(pl.get("last_name") or "")).strip()).strip()
            raw_pos=str(pl.get("position") or stx.get("position") or "").upper().strip()
            if not name or not raw_pos: continue
            team=str(stx.get("team") or pl.get("team") or "").upper().strip()
            opp=str(stx.get("opp") or stx.get("opponent") or stx.get("opponent_team") or "").upper().strip()
            # Require evidence of an actual weekly stat row rather than a zero shell.
            gp=num(stx,"gp","games_played","gms_active")
            activity=sum(abs(num(stx,k)) for k in [
                "pass_att","pass_yd","rush_att","rush_yd","rec_tgt","rec","rec_yd",
                "xpa","xpm","fga","fgm","idp_tkl_solo","idp_tkl_ast","idp_sack","idp_int","idp_pass_def"
            ])
            if gp<=0 and activity<=0: continue

            fgm=num(stx,"fgm","fg_made")
            fga=num(stx,"fga","fg_att")
            fg019=num(stx,"fgm_0_19","fg_made_0_19")
            fg2029=num(stx,"fgm_20_29","fg_made_20_29")
            fg3039=num(stx,"fgm_30_39","fg_made_30_39")
            fg4049=num(stx,"fgm_40_49","fg_made_40_49")
            fg5059=num(stx,"fgm_50_59","fg_made_50_59")
            fg60=num(stx,"fgm_60p","fgm_60_plus","fg_made_60_","fg_made_60_plus")
            classified=fg019+fg2029+fg3039+fg4049+fg5059+fg60
            # If the provider exposes only total makes, put unclassified makes in the
            # neutral 30-39 bucket rather than inventing bonus long-FG points.
            fg3039 += max(0.0,fgm-classified)
            fgmiss=max(num(stx,"fgmiss","fg_missed"),max(0.0,fga-fgm))
            xpm=num(stx,"xpm","pat_made")
            xpa=num(stx,"xpa","pat_att")
            xpmiss=max(num(stx,"xpmiss","pat_missed"),max(0.0,xpa-xpm))

            rows.append({
                "season":season,"season_type":"REG","week":week,
                "player_id":pid,"player_display_name":name,"position":raw_pos,
                "recent_team":team,"team":team,"opponent_team":opp,
                "attempts":num(stx,"pass_att","passing_attempts"),
                "passing_yards":num(stx,"pass_yd","passing_yards"),
                "passing_tds":num(stx,"pass_td","passing_tds"),
                "interceptions":num(stx,"pass_int","passing_interceptions"),
                "carries":num(stx,"rush_att","rushing_attempts"),
                "rushing_yards":num(stx,"rush_yd","rushing_yards"),
                "rushing_tds":num(stx,"rush_td","rushing_tds"),
                "targets":num(stx,"rec_tgt","targets"),
                "receptions":num(stx,"rec","receptions"),
                "receiving_yards":num(stx,"rec_yd","receiving_yards"),
                "receiving_tds":num(stx,"rec_td","receiving_tds"),
                "fumbles_lost":num(stx,"fum_lost","fumbles_lost"),
                "passing_2pt_conversions":num(stx,"pass_2pt","passing_2pt_conversions"),
                "rushing_2pt_conversions":num(stx,"rush_2pt","rushing_2pt_conversions"),
                "receiving_2pt_conversions":num(stx,"rec_2pt","receiving_2pt_conversions"),
                "pat_made":xpm,"pat_missed":xpmiss,
                "fg_made_0_19":fg019,"fg_made_20_29":fg2029,"fg_made_30_39":fg3039,
                "fg_made_40_49":fg4049,"fg_made_50_59":fg5059,"fg_made_60_plus":fg60,
                "fg_missed":fgmiss,
                "def_tackles_solo":num(stx,"idp_tkl_solo","tkl_solo","def_tackles_solo"),
                "def_tackle_assists":num(stx,"idp_tkl_ast","tkl_ast","def_tackle_assists"),
                "def_sacks":num(stx,"idp_sack","sack","def_sacks"),
                "def_tackles_for_loss":num(stx,"idp_tkl_loss","tkl_loss","def_tackles_for_loss"),
                "def_qb_hits":num(stx,"idp_qb_hit","qb_hit","def_qb_hits"),
                "def_interceptions":num(stx,"idp_int","def_interceptions"),
                "def_pass_defended":num(stx,"idp_pass_def","pass_def","def_pass_defended"),
                "def_fumbles_forced":num(stx,"idp_ff","ff","def_fumbles_forced"),
                "fumble_recovery_opp":num(stx,"idp_fum_rec","fum_rec","def_fumbles_recovered"),
                "def_tds":num(stx,"idp_def_td","def_td","def_tds"),
                "def_safeties":num(stx,"idp_safe","safe","safety","def_safeties"),
                "_v1059_stats_source":"Sleeper completed stats bridge",
            })
    return pd.DataFrame(rows)


@st.cache_data(ttl=1800, show_spinner=False)
def _v1060_espn_completed_stats_frame(season,target_week):
    """Provider-independent completed-game bridge for all native FE models.

    ESPN's public scoreboard/summary payloads are already used by Fantasy Edge for
    the IDP pair-history bridge.  V10.60 extends that proven path to a normalized
    player-week table so a slow nflverse release can no longer leave offense, kicker,
    and IDP simultaneously MODEL PENDING.  Only games explicitly marked final/post
    are accepted; this function never fabricates an in-progress stat line.
    """
    try:
        season=int(season); target_week=max(1,int(target_week))
    except Exception:
        return pd.DataFrame()
    if target_week<=1:
        return pd.DataFrame()

    def _num(v):
        try:
            if v is None: return 0.0
            if isinstance(v,(int,float,np.integer,np.floating)):
                x=float(v); return x if np.isfinite(x) else 0.0
            txt=str(v).strip().replace(',','')
            if not txt or txt.lower() in {'nan','none','--','-','—'}: return 0.0
            m=re.search(r'[-+]?\d+(?:\.\d+)?',txt)
            return float(m.group(0)) if m else 0.0
        except Exception:
            return 0.0

    def _pair(v):
        txt=str(v or '').strip()
        m=re.match(r'^\s*(\d+(?:\.\d+)?)\s*[/\-]\s*(\d+(?:\.\d+)?)\s*$',txt)
        if not m: return (0.0,0.0)
        try: return (float(m.group(1)),float(m.group(2)))
        except Exception: return (0.0,0.0)

    def _label_map(cat):
        labels=list(cat.get('labels') or [])
        keys=list(cat.get('keys') or [])
        desc=list(cat.get('descriptions') or [])
        n=max(len(labels),len(keys),len(desc))
        out=[]
        for i in range(n):
            vals=[]
            for arr in (labels,keys,desc):
                if i<len(arr): vals.append(str(arr[i] or ''))
            out.append(' '.join(vals).upper())
        return out

    # Fetch scoreboards first; then summaries concurrently so the fallback stays bounded.
    event_rows=[]
    for week in range(1,target_week):
        try:
            url=("https://site.api.espn.com/apis/site/v2/sports/football/nfl/scoreboard"
                 f"?dates={season}&seasontype=2&week={week}")
            r=requests.get(url,timeout=6,headers={'User-Agent':f'Mozilla/5.0 FantasyEdge/{APP_VERSION}'})
            r.raise_for_status(); data=r.json() or {}
            for ev in data.get('events',[]) or []:
                status=((ev.get('status') or {}).get('type') or {})
                completed=bool(status.get('completed')) or str(status.get('state','')).lower()=='post'
                event_id=str(ev.get('id') or '').strip()
                if completed and event_id:
                    event_rows.append((week,event_id))
        except Exception:
            continue
    if not event_rows:
        return pd.DataFrame()

    def _fetch(item):
        week,event_id=item
        try:
            url=f"https://site.api.espn.com/apis/site/v2/sports/football/nfl/summary?event={event_id}"
            rr=requests.get(url,timeout=6,headers={'User-Agent':f'Mozilla/5.0 FantasyEdge/{APP_VERSION}'})
            rr.raise_for_status(); return week,rr.json() or {}
        except Exception:
            return week,{}

    summaries=[]
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=8,thread_name_prefix='fedge-espn-box') as ex:
            futs=[ex.submit(_fetch,x) for x in event_rows]
            for f in concurrent.futures.as_completed(futs,timeout=min(32,max(10,len(futs)*1.25))):
                try:
                    week,data=f.result()
                    if data: summaries.append((week,data))
                except Exception: pass
    except Exception:
        pass
    if not summaries:
        return pd.DataFrame()

    # nflverse-compatible subset consumed by FE offense, kicker and IDP models.
    zero_fields=[
        'attempts','passing_yards','passing_tds','interceptions','carries','rushing_yards','rushing_tds',
        'targets','receptions','receiving_yards','receiving_tds','fumbles_lost',
        'passing_2pt_conversions','rushing_2pt_conversions','receiving_2pt_conversions',
        'pat_made','pat_missed','fg_made_0_19','fg_made_20_29','fg_made_30_39','fg_made_40_49',
        'fg_made_50_59','fg_made_60_plus','fg_missed','def_tackles_solo','def_tackle_assists',
        'def_sacks','def_tackles_for_loss','def_qb_hits','def_interceptions','def_pass_defended',
        'def_fumbles_forced','fumble_recovery_opp','def_tds','def_safeties'
    ]
    rows={}
    for week,data in summaries:
        sides=((data.get('boxscore') or {}).get('players') or [])
        for side in sides:
            team=str(((side.get('team') or {}).get('abbreviation')) or side.get('teamAbbreviation') or '').upper().strip()
            for cat in side.get('statistics',[]) or []:
                cname=re.sub(r'[^a-z0-9]','',str(cat.get('name') or cat.get('displayName') or '').lower())
                lm=_label_map(cat)
                for ar in cat.get('athletes',[]) or []:
                    ath=ar.get('athlete') or {}
                    name=str(ath.get('displayName') or ath.get('fullName') or ath.get('shortName') or '').strip()
                    if not name: continue
                    pos=str(((ath.get('position') or {}).get('abbreviation')) or '').upper().strip()
                    aid=str(ath.get('id') or '')
                    rk=(int(week),_owner_key(name),team)
                    if rk not in rows:
                        base={'season':season,'season_type':'REG','week':int(week),'player_id':aid,
                              'player_display_name':name,'position':pos,'recent_team':team,'team':team,
                              '_v1059_stats_source':'ESPN completed boxscore bridge'}
                        base.update({k:0.0 for k in zero_fields}); base['_def_total']=0.0
                        rows[rk]=base
                    rec=rows[rk]
                    if pos and not rec.get('position'): rec['position']=pos
                    stats=list(ar.get('stats') or [])
                    for i,val in enumerate(stats):
                        lab=lm[i] if i<len(lm) else ''
                        # Passing
                        if 'passing' in cname:
                            if ('C/ATT' in lab or ('COMPLET' in lab and 'ATT' in lab)):
                                _,att=_pair(val); rec['attempts']=max(rec['attempts'],att)
                            elif 'YDS' in lab or 'YARD' in lab: rec['passing_yards']=max(rec['passing_yards'],_num(val))
                            elif lab.strip().startswith('TD') or 'PASSING TOUCHDOWN' in lab: rec['passing_tds']=max(rec['passing_tds'],_num(val))
                            elif 'INT' in lab: rec['interceptions']=max(rec['interceptions'],_num(val))
                        # Rushing
                        elif 'rushing' in cname:
                            if 'CAR' in lab or 'ATT' in lab: rec['carries']=max(rec['carries'],_num(val))
                            elif 'YDS' in lab or 'YARD' in lab: rec['rushing_yards']=max(rec['rushing_yards'],_num(val))
                            elif lab.strip().startswith('TD') or 'TOUCHDOWN' in lab: rec['rushing_tds']=max(rec['rushing_tds'],_num(val))
                        # Receiving
                        elif 'receiving' in cname:
                            if 'TGTS' in lab or 'TARGET' in lab: rec['targets']=max(rec['targets'],_num(val))
                            elif 'REC' in lab and 'YDS' not in lab and 'YARD' not in lab: rec['receptions']=max(rec['receptions'],_num(val))
                            elif 'YDS' in lab or 'YARD' in lab: rec['receiving_yards']=max(rec['receiving_yards'],_num(val))
                            elif lab.strip().startswith('TD') or 'TOUCHDOWN' in lab: rec['receiving_tds']=max(rec['receiving_tds'],_num(val))
                        # Kicking. Distance detail is not always present in ESPN summaries.
                        elif 'kicking' in cname:
                            if lab.strip().startswith('FG') or 'FIELD GOAL' in lab:
                                made,att=_pair(val)
                                if att>0:
                                    rec['_fg_total_made']=max(float(rec.get('_fg_total_made',0)),made)
                                    rec['_fg_total_att']=max(float(rec.get('_fg_total_att',0)),att)
                            elif lab.strip().startswith('XP') or 'EXTRA POINT' in lab:
                                made,att=_pair(val)
                                if att>0:
                                    rec['pat_made']=max(rec['pat_made'],made); rec['_pat_att']=max(float(rec.get('_pat_att',0)),att)
                            elif 'LONG' in lab:
                                rec['_fg_long']=max(float(rec.get('_fg_long',0)),_num(val))
                        # Fumbles can be present for offense and defense.
                        elif 'fumble' in cname:
                            if 'LOST' in lab: rec['fumbles_lost']=max(rec['fumbles_lost'],_num(val))
                            elif 'FORCED' in lab or lab.strip()=='FF': rec['def_fumbles_forced']=max(rec['def_fumbles_forced'],_num(val))
                            elif 'REC' in lab or lab.strip()=='FR': rec['fumble_recovery_opp']=max(rec['fumble_recovery_opp'],_num(val))
                        # Defensive box categories.
                        if any(tok in cname for tok in ('defens','interception')):
                            if 'SOLO' in lab: rec['def_tackles_solo']=max(rec['def_tackles_solo'],_num(val))
                            elif 'TOT' in lab or 'TOTAL TACK' in lab: rec['_def_total']=max(float(rec.get('_def_total',0)),_num(val))
                            elif 'AST' in lab or 'ASSIST' in lab: rec['def_tackle_assists']=max(rec['def_tackle_assists'],_num(val))
                            elif 'SACK' in lab: rec['def_sacks']=max(rec['def_sacks'],_num(val))
                            elif 'TFL' in lab or 'TACKLE FOR LOSS' in lab: rec['def_tackles_for_loss']=max(rec['def_tackles_for_loss'],_num(val))
                            elif 'QB' in lab and ('HIT' in lab or 'HT' in lab): rec['def_qb_hits']=max(rec['def_qb_hits'],_num(val))
                            elif 'INT' in lab: rec['def_interceptions']=max(rec['def_interceptions'],_num(val))
                            elif 'PD' in lab or 'PASS DEF' in lab: rec['def_pass_defended']=max(rec['def_pass_defended'],_num(val))
                            elif 'FF' in lab or 'FORCED FUM' in lab: rec['def_fumbles_forced']=max(rec['def_fumbles_forced'],_num(val))
                            elif 'FR' in lab or 'FUMBLE REC' in lab: rec['fumble_recovery_opp']=max(rec['fumble_recovery_opp'],_num(val))
                            elif lab.strip()=='TD' or 'TOUCHDOWN' in lab: rec['def_tds']=max(rec['def_tds'],_num(val))
                            elif 'SAF' in lab: rec['def_safeties']=max(rec['def_safeties'],_num(val))

    out=[]
    for rec in rows.values():
        total=float(rec.pop('_def_total',0.0) or 0.0)
        if total>0 and float(rec.get('def_tackle_assists',0) or 0)<=0:
            rec['def_tackle_assists']=max(0.0,total-float(rec.get('def_tackles_solo',0) or 0))
        # Neutral kicker distance reconstruction: only the longest made FG receives a
        # distance bonus; remaining makes use the 30-39 bucket rather than inventing bonuses.
        made=float(rec.pop('_fg_total_made',0.0) or 0.0); att=float(rec.pop('_fg_total_att',0.0) or 0.0)
        long=float(rec.pop('_fg_long',0.0) or 0.0); pat_att=float(rec.pop('_pat_att',0.0) or 0.0)
        if made>0:
            bonus=min(1.0,made)
            if long>=60: rec['fg_made_60_plus']+=bonus
            elif long>=50: rec['fg_made_50_59']+=bonus
            elif long>=40: rec['fg_made_40_49']+=bonus
            else: bonus=0.0
            rec['fg_made_30_39']+=max(0.0,made-bonus)
        rec['fg_missed']=max(rec.get('fg_missed',0.0),max(0.0,att-made))
        rec['pat_missed']=max(rec.get('pat_missed',0.0),max(0.0,pat_att-float(rec.get('pat_made',0) or 0)))
        # Keep only rows with real production/opportunity evidence.
        activity=sum(abs(float(rec.get(k,0) or 0)) for k in zero_fields)
        if activity>0: out.append(rec)
    return pd.DataFrame(out)


def _v1060_merge_completed_stats(base,bridge):
    """Append only newer completed weeks from a fallback bridge to a richer base table."""
    b=base.copy() if isinstance(base,pd.DataFrame) else pd.DataFrame()
    x=bridge.copy() if isinstance(bridge,pd.DataFrame) else pd.DataFrame()
    if x.empty: return b
    try:
        bw=int(pd.to_numeric(b.get('week',pd.Series(dtype=float)),errors='coerce').dropna().max()) if not b.empty else 0
    except Exception: bw=0
    if 'week' in x.columns and bw>0:
        newer=x[pd.to_numeric(x['week'],errors='coerce').fillna(0).gt(bw)].copy()
        if newer.empty: return b
        x=newer
    out=pd.concat([b,x],ignore_index=True,sort=False) if not b.empty else x.reset_index(drop=True)
    return out


# ---------------- V10.64 roster historical-sample repair ----------------
def _v1064_merge_missing_player_weeks(base, bridge, target_week=None):
    """Fill missing historical player-weeks even when the cache's max week is current.

    V10.60 only invoked completed-box bridges when the *maximum* cached week lagged.
    That misses a different failure mode: a cache can contain Week 2 overall while a
    specific player is missing a valid Week 1 row.  Native offense then reports zero
    model games for that player even though a completed sample exists.

    Primary/nflverse rows remain authoritative.  A bridge row is appended only when
    the canonical (player, week) identity is absent from the base table.
    """
    b=base.copy() if isinstance(base,pd.DataFrame) else pd.DataFrame()
    x=bridge.copy() if isinstance(bridge,pd.DataFrame) else pd.DataFrame()
    if x.empty:
        return b,0
    name_candidates=["player_display_name","player_name","display_name","full_name","player"]
    xn=next((c for c in name_candidates if c in x.columns),None)
    if not xn or "week" not in x.columns:
        return b,0
    x["__v1064_key"]=x[xn].astype(str).map(norm)
    x["__v1064_week"]=pd.to_numeric(x["week"],errors="coerce")
    x=x[x["__v1064_key"].ne("") & x["__v1064_week"].notna()].copy()
    if target_week is not None:
        try: x=x[x["__v1064_week"].lt(int(target_week))].copy()
        except Exception: pass
    if x.empty:
        return b,0

    existing=set()
    if not b.empty and "week" in b.columns:
        bn=next((c for c in name_candidates if c in b.columns),None)
        if bn:
            bk=b[bn].astype(str).map(norm)
            bw=pd.to_numeric(b["week"],errors="coerce")
            existing=set(zip(bk[bw.notna()].astype(str),bw[bw.notna()].astype(int)))
    x["__v1064_pair"]=list(zip(x["__v1064_key"].astype(str),x["__v1064_week"].astype(int)))
    add=x[~x["__v1064_pair"].isin(existing)].copy()
    if add.empty:
        return b,0
    add=add.drop(columns=["__v1064_key","__v1064_week","__v1064_pair"],errors="ignore")
    out=pd.concat([b,add],ignore_index=True,sort=False) if not b.empty else add.reset_index(drop=True)
    return out,int(len(add))


def _v1064_rostered_offense_sample_gaps(board_df, model_df, state_snapshot):
    """Return rostered QB/RB/WR/TE keys with no native completed-game model row."""
    if not isinstance(board_df,pd.DataFrame) or board_df.empty:
        return set()
    b=board_df.copy()
    pos=b.get("position",pd.Series("",index=b.index)).fillna("").astype(str).str.upper()
    mine=b["player"].map(lambda n:_player_owner(state_snapshot,n)=="1")
    wanted=set(b.loc[mine & pos.isin(["QB","RB","WR","TE"]),"player"].astype(str).map(norm))
    have=set()
    if isinstance(model_df,pd.DataFrame) and not model_df.empty:
        if "key" in model_df.columns: have=set(model_df["key"].fillna("").astype(str))
        elif "player" in model_df.columns: have=set(model_df["player"].astype(str).map(norm))
    return {k for k in wanted if k and k not in have}


# ---------------- V10.40 free IDP projection engine ----------------
@st.cache_data(ttl=21600, show_spinner=False)
def _v1040_snap_counts(year):
    """Current-season defensive snap counts from nflverse/PFR.

    This is a free role source, not a fantasy-projection vendor.  The model still
    works when snap counts are temporarily unavailable; snap share only improves
    role confidence and catches under-the-radar defenders before box-score volume
    fully arrives.
    """
    try:
        url=f"https://github.com/nflverse/nflverse-data/releases/download/snap_counts/snap_counts_{int(year)}.csv"
        x=_v806_csv_release(url,max_bytes=16*1024*1024)
        return x if isinstance(x,pd.DataFrame) else pd.DataFrame()
    except Exception:
        return pd.DataFrame()


def _v1040_idp_pos(raw):
    """Yahoo-compatible two-slot IDP grouping. Generic/off-ball LB is not DL."""
    slot,_=_v1042_yahoo_idp_slot(raw)
    return slot or str(raw or "").upper().strip()


# ---------------- V10.45 current defensive-participation authority ----------------
def _v1045_idp_participation_status(row):
    """Return (ready, lane, reason) for a DL/DB's *current defensive role*.

    Yahoo slot legality answers *where* a defender may be used.  It does not prove the
    player is actually part of a current defensive rotation.  V10.45 therefore requires
    recent defensive snaps or sufficiently strong recent defensive box-score activity
    before an IDP projection is allowed to become actionable.

    The box-score fallback matters when the public snap feed is temporarily missing or
    a player's name does not join cleanly.  Thresholds are deliberately above a single
    stray tackle/one-off special-teams event so depth-only identities do not become
    waiver or trade candidates.
    """
    try:
        pos=str(row.get("position",row.get("Position","")) or "").upper().strip()
    except Exception:
        pos=""
    if pos not in {"DL","DB"}:
        return True,"NOT_IDP","Not an IDP row"

    def _num(key, default=0.0):
        try:
            v=pd.to_numeric(pd.Series([row.get(key,default)]),errors="coerce").iloc[0]
            return float(v) if pd.notna(v) else float(default)
        except Exception:
            return float(default)
    def _truth(key, default=False):
        try:
            v=row.get(key,default)
        except Exception:
            return bool(default)
        if isinstance(v,(bool,np.bool_)):
            return bool(v)
        return str(v).strip().lower() in {"1","true","yes","y"}

    snap_pct=max(0.0,_num("fe_idp_snap_pct",0.0))
    snaps_recent=max(0.0,_num("fe_idp_snaps_recent",0.0))
    snap_games=max(0.0,_num("fe_idp_snap_games",0.0))
    snap_observed=_truth("fe_idp_snap_observed",False) or snap_games>0 or snap_pct>0 or snaps_recent>0
    model_games=max(0.0,_num("fe_idp_model_games",0.0))
    recent_active=max(0.0,_num("fe_idp_recent_active_games",0.0))
    recent_tackles=max(0.0,_num("fe_idp_recent_tackles",0.0))
    recent_pressure=max(0.0,_num("fe_idp_recent_pressure_events",0.0))
    recent_coverage=max(0.0,_num("fe_idp_recent_coverage_events",0.0))
    recent_events=max(0.0,_num("fe_idp_recent_def_events",0.0))

    # Snap-share is the strongest participation evidence.  DL rotations naturally
    # operate at lower shares than full-time safeties/corners, so thresholds differ.
    pct_floor=0.18 if pos=="DL" else 0.22
    snap_floor=10.0 if pos=="DL" else 14.0
    if snap_pct>=pct_floor or snaps_recent>=snap_floor:
        return True,"ACTIVE_SNAP_ROLE",f"Recent defensive role: {snap_pct*100:.0f}% snaps / {snaps_recent:.0f} defensive snaps"

    # Public snap data can miss a player.  Require repeated/meaningful defensive
    # production before using box scores as the fallback proof of a real role.
    early=model_games<=1.0
    if recent_active>=2:
        return True,"ACTIVE_BOX_ROLE",f"Defensive production recorded in {int(recent_active)} recent games"
    if pos=="DL":
        tackle_floor=2.0 if early else 3.0
        pressure_floor=1.0 if early else 2.0
        event_floor=3.0 if early else 4.0
        if recent_tackles>=tackle_floor or recent_pressure>=pressure_floor or recent_events>=event_floor:
            return True,"ACTIVE_BOX_ROLE",f"Recent DL activity: {recent_tackles:.0f} tackles / {recent_pressure:.0f} pressure events"
    else:
        tackle_floor=3.0 if early else 4.0
        coverage_floor=1.0 if early else 2.0
        event_floor=4.0 if early else 5.0
        if recent_tackles>=tackle_floor or recent_coverage>=coverage_floor or recent_events>=event_floor:
            return True,"ACTIVE_BOX_ROLE",f"Recent DB activity: {recent_tackles:.0f} tackles / {recent_coverage:.0f} coverage plays"

    new_evidence=any(k in row for k in [
        "fe_idp_recent_def_events","fe_idp_recent_active_games","fe_idp_snap_observed","fe_idp_snap_games"
    ]) if hasattr(row,"__contains__") else False
    if not new_evidence and not snap_observed:
        return False,"REFRESH_REQUIRED","No V10.45 participation evidence in this saved snapshot — refresh weekly data"
    if snap_observed:
        return False,"DEPTH_NOT_ACTIONABLE",f"Defensive usage below actionable floor: {snap_pct*100:.0f}% snaps / {snaps_recent:.0f} defensive snaps"
    return False,"NO_CURRENT_DEFENSIVE_ROLE","No meaningful recent defensive snap or box-score role"



# ---------------- V10.51 defensive role/usage bridge ----------------
def _v1051_apply_idp_role_bridge(board_df):
    """Promote observed IDP snap/box evidence into the shared role-confidence layer.

    V10.40+ already records defender-specific snap share and recent defensive events,
    but the older generic role engine was built around offensive carries/targets/routes.
    As a result, a DL/DB could be correctly projection-ready while Waivers still showed
    weak global role confidence.  This bridge keeps the raw IDP evidence authoritative
    and makes every downstream tab see the same current defensive role.

    No projection/VORP is changed here.  This is evidence plumbing only.
    """
    if board_df is None or not isinstance(board_df,pd.DataFrame) or board_df.empty:
        return board_df
    out=board_df.copy(); idx=out.index
    pos=out.get("position",pd.Series("",index=idx)).fillna("").astype(str).str.upper()
    idp=pos.isin(["DL","DB"])
    if not bool(idp.any()):
        return out

    def num(name,default=0.0):
        return pd.to_numeric(out.get(name,pd.Series(default,index=idx)),errors="coerce").fillna(default)
    def truth(name,default=False):
        raw=out.get(name,pd.Series(default,index=idx))
        return raw.fillna(default).map(lambda v: bool(v) if isinstance(v,(bool,np.bool_)) else str(v).strip().lower() in {"1","true","yes","y"})

    slot_ok=truth("fe_idp_slot_eligible",False)
    ready=truth("fe_idp_participation_ready",False)
    fresh=truth("fe_idp_model_fresh",False)
    snap_observed=truth("fe_idp_snap_observed",False)
    snap_pct=num("fe_idp_snap_pct",0.0).clip(lower=0.0,upper=1.0)
    snaps=num("fe_idp_snaps_recent",0.0).clip(lower=0.0)
    snap_games=num("fe_idp_snap_games",0.0).clip(lower=0.0)
    games=num("fe_idp_model_games",0.0).clip(lower=0.0)
    active_games=num("fe_idp_recent_active_games",0.0).clip(lower=0.0)
    events=num("fe_idp_recent_def_events",0.0).clip(lower=0.0)
    tackles=num("fe_idp_recent_tackles",0.0).clip(lower=0.0)
    pressures=num("fe_idp_recent_pressure_events",0.0).clip(lower=0.0)
    coverage=num("fe_idp_recent_coverage_events",0.0).clip(lower=0.0)
    model_conf=num("fe_idp_model_confidence",0.0).clip(lower=0.0,upper=1.0)
    lane=out.get("fe_idp_participation_lane",pd.Series("",index=idx)).fillna("").astype(str)

    observed_box=(active_games.gt(0) | events.gt(0) | tackles.gt(0) | pressures.gt(0) | coverage.gt(0))
    current=idp & slot_ok & fresh & games.gt(0) & (snap_observed | observed_box)
    actionable=current & ready
    depth_current=current & ~ready

    for c,d in [
        ("_usage_recency","UNAVAILABLE"),("_usage_games",0.0),("_usage_source","Unavailable"),
        ("_role_confidence",0.0),("_role_confidence_source","directory/default"),
        ("_role_trend","NO LIVE ROLE DATA"),("_role_provenance",""),
        ("fe_role_confidence",0.0),("fe_idp_role_confidence",0.0),
        ("fe_idp_role_evidence_current",False),("fe_idp_role_source",""),
        ("fe_idp_role_contract",""), ("fe_idp_role_score",0.0),
    ]:
        if c not in out.columns: out[c]=d
    for c in ["_usage_games","_role_confidence","fe_role_confidence","fe_idp_role_confidence","fe_idp_role_score"]:
        out[c]=pd.to_numeric(out[c],errors="coerce").fillna(0.0).astype(float)

    # Snap-backed confidence is strongest.  DL rotations legitimately peak at lower
    # shares than full-time DBs, so normalize against position-specific strong-role marks.
    strong_mark=pos.map({"DL":0.65,"DB":0.85}).fillna(0.75).astype(float)
    snap_strength=(snap_pct/strong_mark).clip(lower=0.0,upper=1.0)
    snap_conf=(74.0 + 20.0*snap_strength + 4.0*model_conf).clip(74.0,98.0)

    # When PFR/nflverse snap counts lag, repeated defensive box-score activity is still
    # direct current-game evidence.  Keep this confidence usable but below true snap proof.
    box_strength=(active_games*4.5 + events*1.25 + model_conf*6.0).clip(lower=0.0,upper=24.0)
    box_conf=(64.0 + box_strength).clip(64.0,90.0)
    role_conf=pd.Series(0.0,index=idx)
    use_snap=actionable & snap_observed
    use_box=actionable & ~snap_observed & observed_box
    role_conf.loc[use_snap]=snap_conf.loc[use_snap]
    role_conf.loc[use_box]=box_conf.loc[use_box]

    # A current but below-threshold defender must not inherit an 80-90% inferred role
    # confidence merely from market rank/projection.  Cap those depth identities.
    old_conf=num("_role_confidence",0.0)
    low_conf=(34.0 + 10.0*(snap_pct/0.18).clip(0,1)).clip(34,44)
    out.loc[out.index[depth_current],"_role_confidence"]=np.minimum(old_conf.loc[depth_current],low_conf.loc[depth_current]).values
    out.loc[out.index[depth_current],"fe_role_confidence"]=out.loc[out.index[depth_current],"_role_confidence"].values
    out.loc[out.index[depth_current],"_role_confidence_source"]="CURRENT DEFENSIVE EVIDENCE — BELOW ACTIONABLE ROLE FLOOR"
    out.loc[out.index[depth_current],"_role_trend"]="DEPTH / LOW DEFENSIVE ROLE"
    out.loc[out.index[depth_current],"_role_provenance"]="V10.51 IDP snap/box role bridge"

    if bool(actionable.any()):
        aidx=out.index[actionable]
        out.loc[aidx,"_usage_recency"]="CURRENT"
        existing_games=num("_usage_games",0.0)
        out.loc[aidx,"_usage_games"]=np.maximum(existing_games.loc[actionable],games.loc[actionable]).values
        src=np.where(use_snap.loc[actionable],
                     "nflverse/PFR defensive snaps + weekly defensive stats",
                     "nflverse weekly defensive box-score role")
        out.loc[aidx,"_usage_source"]=src
        out.loc[aidx,"_role_confidence"]=role_conf.loc[actionable].round(1).values
        out.loc[aidx,"fe_role_confidence"]=role_conf.loc[actionable].round(1).values
        out.loc[aidx,"fe_idp_role_confidence"]=role_conf.loc[actionable].round(1).values
        out.loc[aidx,"fe_idp_role_evidence_current"]=True
        out.loc[aidx,"fe_idp_role_source"]=src
        out.loc[aidx,"fe_idp_role_contract"]="V10.51"
        out.loc[aidx,"_role_confidence_source"]=np.where(use_snap.loc[actionable],"OBSERVED DEFENSIVE SNAP ROLE","OBSERVED DEFENSIVE BOX ROLE")
        out.loc[aidx,"_role_trend"]=np.where(use_snap.loc[actionable],"CURRENT DEFENSIVE SNAP ROLE","CURRENT DEFENSIVE BOX ROLE")
        out.loc[aidx,"_role_provenance"]="V10.51 IDP snap/box role bridge"
        # Separate defender-only role score; do not overload offensive carries/routes.
        def_score=(snap_pct*70.0 + np.minimum(20.0,events*2.0) + np.minimum(10.0,active_games*3.0)).clip(0,100)
        out.loc[aidx,"fe_idp_role_score"]=def_score.loc[actionable].round(1).values

    # Current-evidence flag is explicit on all IDP rows so snapshots can be audited.
    out.loc[out.index[idp & ~actionable],"fe_idp_role_evidence_current"]=False
    out.loc[out.index[idp],"fe_idp_role_contract"]="V10.51"
    return out

def _v1040_idp_project_from_weekly(stats_df, snap_df, season, target_week, idp_cfg, eligibility_df=None):
    """Build a Yahoo-slot-aware, early-season-regressed weekly DL/DB projection.

    V10.42 fixes two V10.41 failure modes:
      1) pure LB/ILB/MLB tackle machines no longer get mislabeled as DL;
      2) two-game sack/tackle spikes are empirically shrunk toward eligible-position
         baselines before they become fantasy projections.

    The model still discovers unranked defenders from nflverse. Generic LB/OLB rows may
    enter the DL lane only when provider fantasy eligibility (or a verified Yahoo dual-position
    override) independently certifies DL/DE eligibility; pass-rush stats never create legality.
    """
    if not isinstance(stats_df,pd.DataFrame) or stats_df.empty:
        return pd.DataFrame()
    try:
        yr=int(season); wk=int(target_week)
    except Exception:
        return pd.DataFrame()
    x=stats_df.copy()
    if "season_type" in x.columns:
        x=x[x["season_type"].astype(str).str.upper().eq("REG")].copy()
    if "week" not in x.columns or "position" not in x.columns:
        return pd.DataFrame()
    x["week"]=pd.to_numeric(x["week"],errors="coerce")
    x=x[x["week"].notna() & (x["week"] < wk)].copy()
    if x.empty:
        return pd.DataFrame()
    name_col=next((c for c in ["player_display_name","player_name","display_name","full_name","player"] if c in x.columns),None)
    if not name_col:
        return pd.DataFrame()
    team_col=next((c for c in ["team","recent_team"] if c in x.columns),None)

    defensive_raw=_V1042_DL_RAW|_V1042_DB_RAW|_V1042_EDGE_LB_RAW|_V1042_OFFBALL_LB_RAW
    x=x[x["position"].fillna("").astype(str).str.upper().isin(defensive_raw)].copy()
    if x.empty:
        return pd.DataFrame()

    def ncol(frame,*names):
        for c in names:
            if c in frame.columns:
                return pd.to_numeric(frame[c],errors="coerce").fillna(0.0)
        return pd.Series(0.0,index=frame.index,dtype=float)

    x["solo"]=ncol(x,"def_tackles_solo","tackles_solo")
    x["assist"]=ncol(x,"def_tackle_assists","tackles_assists","assists","def_tackles_with_assist")
    x["sack"]=ncol(x,"def_sacks","sacks")
    x["tfl"]=ncol(x,"def_tackles_for_loss","tackles_for_loss")
    x["qb_hit"]=ncol(x,"def_qb_hits","qb_hits")
    x["int"]=ncol(x,"def_interceptions","interceptions")
    x["pd"]=ncol(x,"def_pass_defended","passes_defended","pass_deflections")
    x["ff"]=ncol(x,"def_fumbles_forced","fumbles_forced")
    x["fr"]=ncol(x,"fumble_recovery_opp","def_fumble_recovery_opp","def_fumbles","fumbles_recovered")
    x["def_td"]=ncol(x,"def_tds","defensive_tds")
    x["safety"]=ncol(x,"def_safeties","def_safety","safeties")
    stat_cols=["solo","assist","sack","tfl","qb_hit","int","pd","ff","fr","def_td","safety"]

    # Optional cached identity metadata from League Setup/Sleeper. It is never required
    # for a projection, but multi-position fantasy eligibility is the strongest clue for
    # Yahoo-like edge classification when an NFL feed calls the player simply LB.
    meta={}
    if isinstance(eligibility_df,pd.DataFrame) and not eligibility_df.empty and "player" in eligibility_df.columns:
        for _,r in eligibility_df.iterrows():
            k=norm(r.get("player",""))
            if k: meta[k]=r.to_dict()

    player_slot={}; player_source={}; player_raw={}; player_edge_score={}
    for name,g in x.groupby(name_col,dropna=True):
        gg=g.sort_values("week")
        raw=str(gg["position"].dropna().astype(str).iloc[-1]).upper().strip() if gg["position"].notna().any() else ""
        m=meta.get(norm(name),{})
        # Provider metadata may be more specific than nflverse's generic LB label.
        mraw=str(m.get("raw_position") or raw).upper().strip()
        fps=m.get("fantasy_positions")
        slot,source=_v1042_yahoo_idp_slot(mraw,fps,str(name),gg)
        if not slot and mraw!=raw:
            slot,source=_v1042_yahoo_idp_slot(raw,None,str(name),gg)
        edge_score=_v1042_edge_role_from_stats(gg)[1] if raw in _V1042_OFFBALL_LB_RAW or mraw in _V1042_OFFBALL_LB_RAW else 0.0
        player_slot[norm(name)]=slot
        player_source[norm(name)]=source
        player_raw[norm(name)]=mraw or raw
        player_edge_score[norm(name)]=edge_score

    x["_k"]=x[name_col].astype(str).map(norm)
    x["_idp_pos"]=x["_k"].map(player_slot)
    x=x[x["_idp_pos"].isin(["DL","DB"])].copy()
    if x.empty:
        return pd.DataFrame()

    cfg=dict(idp_cfg or {})
    weights={
        "solo":float(cfg.get("solo",1.0)),"assist":float(cfg.get("assist",0.5)),
        "sack":float(cfg.get("sack",4.0)),"tfl":float(cfg.get("tfl",2.0)),
        "qb_hit":float(cfg.get("qb_hit",0.0)),"int":float(cfg.get("int",7.0)),
        "pd":float(cfg.get("pd",2.0)),"ff":float(cfg.get("ff",4.0)),
        "fr":float(cfg.get("fr",4.0)),"def_td":float(cfg.get("def_td",12.0)),
        "safety":float(cfg.get("safety",8.0)),
    }
    x["_fantasy_points"]=sum(x[c]*weights[c] for c in stat_cols)

    snap_lookup={}
    if isinstance(snap_df,pd.DataFrame) and not snap_df.empty and "week" in snap_df.columns:
        sd=snap_df.copy()
        if "game_type" in sd.columns:
            sd=sd[sd["game_type"].astype(str).str.upper().eq("REG")].copy()
        sd["week"]=pd.to_numeric(sd["week"],errors="coerce")
        sd=sd[sd["week"].notna() & (sd["week"]<wk)].copy()
        sn_name=next((c for c in ["player","player_name","full_name"] if c in sd.columns),None)
        if sn_name:
            sd["_k"]=sd[sn_name].astype(str).map(norm)
            sd["_def_snaps"]=pd.to_numeric(sd.get("defense_snaps",0),errors="coerce").fillna(0.0)
            sd["_def_pct"]=pd.to_numeric(sd.get("defense_pct",0),errors="coerce").fillna(0.0)
            sd.loc[sd["_def_pct"]>1.5,"_def_pct"]=sd.loc[sd["_def_pct"]>1.5,"_def_pct"]/100.0
            for k,g in sd.groupby("_k"):
                g=g.sort_values("week")
                snap_lookup[k]={
                    "snap_pct_recent":float(g.tail(2)["_def_pct"].mean()) if len(g) else 0.0,
                    "snaps_recent":float(g.tail(2)["_def_snaps"].mean()) if len(g) else 0.0,
                    "snap_games":int(len(g)),
                    "snap_last_week":int(pd.to_numeric(g["week"],errors="coerce").max()) if len(g) else 0,
                }

    # Baselines use only players actually eligible for this league's DL/DB slots.
    pos_baseline={}
    for pos,g in x.groupby("_idp_pos"):
        pos_baseline[pos]={c:float(pd.to_numeric(g[c],errors="coerce").fillna(0).mean()) for c in stat_cols}
        _fp=pd.to_numeric(g["_fantasy_points"],errors="coerce").fillna(0.0)
        pos_baseline[pos]["fp_std"]=float(_fp.std(ddof=0) or 0.0)
        pos_baseline[pos]["fp_mean"]=float(_fp.mean() or 0.0)
        # Robust early-season anchor: a single pick-six / multi-sack game must not
        # raise the ceiling for the very player we are trying to regress.
        pos_baseline[pos]["fp_anchor"]=float(_fp.quantile(0.65) if len(_fp) else 0.0)

    # Empirical-Bayes pseudo-games.  Splash plays need much more evidence than tackles.
    pseudo_games={"solo":3.0,"assist":3.0,"tfl":4.5,"qb_hit":4.5,"pd":5.0,
                  "sack":7.0,"int":10.0,"ff":10.0,"fr":10.0,"def_td":14.0,"safety":14.0}
    trend_weight={"solo":0.16,"assist":0.16,"tfl":0.12,"qb_hit":0.12,"pd":0.10,
                  "sack":0.08,"int":0.04,"ff":0.04,"fr":0.04,"def_td":0.02,"safety":0.02}

    rows=[]
    for name,g in x.groupby(name_col,dropna=True):
        g=g.sort_values("week").copy()
        if g.empty: continue
        key=norm(str(name)); pos=str(g["_idp_pos"].iloc[-1])
        if pos not in {"DL","DB"}: continue
        latest_week=int(pd.to_numeric(g["week"],errors="coerce").max())
        games=int(pd.to_numeric(g["week"],errors="coerce").nunique())
        games=max(games,1)
        base=pos_baseline.get(pos,{})
        projected={}
        for c in stat_cols:
            vals=pd.to_numeric(g[c],errors="coerce").fillna(0.0).to_numpy(dtype=float)
            season_avg=float(np.mean(vals)) if len(vals) else 0.0
            last2=float(np.mean(vals[-2:])) if len(vals) else 0.0
            pb=float(base.get(c,0.0) or 0.0)
            pg=float(pseudo_games.get(c,5.0))
            posterior=(games*season_avg + pg*pb)/max(games+pg,1e-9)
            # Trend only earns weight after multiple games; Week 1-2 cannot dominate.
            tw=float(trend_weight.get(c,0.08))*min(1.0,max(games-1,0)/4.0)
            val=posterior + tw*(last2-season_avg)
            projected[c]=max(0.0,float(val))

        snap=snap_lookup.get(key,{})
        snap_pct=float(snap.get("snap_pct_recent",0.0) or 0.0)
        snaps_recent=float(snap.get("snaps_recent",0.0) or 0.0)
        snap_games=int(snap.get("snap_games",0) or 0)
        snap_last_week=int(snap.get("snap_last_week",0) or 0)
        snap_observed=bool(key in snap_lookup and snap_games>0)

        _recent=g.tail(2).copy()
        _recent_tackles=float(pd.to_numeric(_recent["solo"],errors="coerce").fillna(0).sum()+pd.to_numeric(_recent["assist"],errors="coerce").fillna(0).sum())
        _recent_pressure=float(pd.to_numeric(_recent["sack"],errors="coerce").fillna(0).sum()+pd.to_numeric(_recent["tfl"],errors="coerce").fillna(0).sum()+pd.to_numeric(_recent["qb_hit"],errors="coerce").fillna(0).sum())
        _recent_coverage=float(pd.to_numeric(_recent["int"],errors="coerce").fillna(0).sum()+pd.to_numeric(_recent["pd"],errors="coerce").fillna(0).sum())
        _recent_turnovers=float(pd.to_numeric(_recent["ff"],errors="coerce").fillna(0).sum()+pd.to_numeric(_recent["fr"],errors="coerce").fillna(0).sum())
        _recent_events=float(_recent_tackles+_recent_pressure+_recent_coverage+_recent_turnovers)
        _event_per_game=(
            pd.to_numeric(_recent["solo"],errors="coerce").fillna(0)+
            pd.to_numeric(_recent["assist"],errors="coerce").fillna(0)+
            pd.to_numeric(_recent["sack"],errors="coerce").fillna(0)+
            pd.to_numeric(_recent["tfl"],errors="coerce").fillna(0)+
            pd.to_numeric(_recent["qb_hit"],errors="coerce").fillna(0)+
            pd.to_numeric(_recent["int"],errors="coerce").fillna(0)+
            pd.to_numeric(_recent["pd"],errors="coerce").fillna(0)+
            pd.to_numeric(_recent["ff"],errors="coerce").fillna(0)+
            pd.to_numeric(_recent["fr"],errors="coerce").fillna(0)
        )
        _recent_active_games=int((_event_per_game>0).sum())
        _participation_probe={
            "position":pos,"fe_idp_model_games":games,"fe_idp_snap_pct":snap_pct,
            "fe_idp_snaps_recent":snaps_recent,"fe_idp_snap_games":snap_games,
            "fe_idp_snap_observed":snap_observed,"fe_idp_recent_active_games":_recent_active_games,
            "fe_idp_recent_tackles":_recent_tackles,"fe_idp_recent_pressure_events":_recent_pressure,
            "fe_idp_recent_coverage_events":_recent_coverage,"fe_idp_recent_def_events":_recent_events,
        }
        participation_ready,participation_lane,participation_reason=_v1045_idp_participation_status(_participation_probe)
        role_mult=1.0
        if snap_pct>0:
            role_mult=float(np.clip(0.90+0.15*snap_pct,0.90,1.05))
        elif snaps_recent>0:
            role_mult=float(np.clip(0.92+0.0025*snaps_recent,0.92,1.05))
        for c in projected:
            projected[c]*=role_mult

        stat_proj=float(sum(projected[c]*weights[c] for c in stat_cols))
        actual=pd.to_numeric(g["_fantasy_points"],errors="coerce").fillna(0.0).to_numpy(dtype=float)
        recent_actual=float(np.mean(actual[-2:])) if len(actual) else 0.0
        proj=0.90*stat_proj+0.10*recent_actual

        # V10.42 early-season ceiling: protect against a two-game sack/turnover heater.
        # The ceiling relaxes rapidly as evidence accumulates and does not apply from Week 5 on.
        base_fp=float(base.get("fp_anchor",base.get("fp_mean",0.0)) or 0.0)
        cap_applied=False
        if games<=3 and base_fp>0:
            mult={1:1.38,2:1.58,3:1.78}.get(games,1.90)
            role_bonus=0.75 if snap_pct>=0.72 else 0.25 if snap_pct>=0.55 else 0.0
            early_cap=base_fp*mult + role_bonus
            if proj>early_cap:
                factor=max(0.0,early_cap/max(proj,1e-9))
                for c in projected: projected[c]*=factor
                proj=float(early_cap); cap_applied=True

        # V10.43 robust uncertainty: shrink tiny-sample player volatility toward the
        # eligible-position distribution. This avoids 7 PPG projections displaying
        # nonsensical 0-19 point intervals after one splash game.
        pos_std=float(base.get("fp_std",0.0) or 0.0)
        player_std=float(np.std(actual,ddof=0)) if len(actual)>=2 else pos_std
        if pos_std<=0:
            pos_std=max(1.5,0.32*max(proj,1.0))
        volatility=float(np.sqrt((games*(player_std**2)+4.0*(pos_std**2))/max(games+4.0,1.0)))
        spread=max(1.10,min(0.72*volatility,0.52*max(proj,1.0)+1.25))
        floor=max(0.0,proj-spread)
        ceiling=max(proj,proj+1.12*spread)
        if games<=3:
            floor=max(floor,0.35*proj)
            ceiling=min(ceiling,1.72*proj+1.0)
        current_completed=max(0,wk-1)
        fresh=bool(latest_week>=current_completed) if current_completed else True
        tackle_pg=float(pd.to_numeric(g["solo"],errors="coerce").fillna(0).mean()+pd.to_numeric(g["assist"],errors="coerce").fillna(0).mean())
        conf=0.33+0.10*min(games,4)+0.08*int(fresh)+0.05*min(1.0,tackle_pg/4.0)
        if snap_pct>0 or snaps_recent>0: conf+=0.07
        if player_source.get(key,"").startswith("pressure-role"): conf-=0.04
        conf=float(np.clip(conf,0.35,0.86))
        team=str(g[team_col].dropna().astype(str).iloc[-1]).upper() if team_col and g[team_col].notna().any() else ""
        rows.append({
            "player":str(name).strip(),"key":key,"position":pos,"team":team,
            "fe_idp_raw_position":player_raw.get(key,str(g["position"].iloc[-1])),
            "fe_idp_eligibility_source":player_source.get(key,""),
            "fe_idp_edge_role_score":float(player_edge_score.get(key,0.0) or 0.0),
            "fe_idp_slot_eligible":True,
            "fe_idp_model_ppg":round(proj,3),"fe_idp_model_floor":round(floor,3),
            "fe_idp_model_ceiling":round(ceiling,3),"fe_idp_model_confidence":round(conf,3),
            "fe_idp_model_games":games,"fe_idp_model_last_week":latest_week,
            "fe_idp_model_fresh":fresh,"fe_idp_snap_pct":round(snap_pct,3),
            "fe_idp_snaps_recent":round(snaps_recent,1),"fe_idp_snap_games":snap_games,
            "fe_idp_snap_last_week":snap_last_week,"fe_idp_snap_observed":bool(snap_observed),
            "fe_idp_recent_active_games":_recent_active_games,"fe_idp_recent_tackles":round(_recent_tackles,2),
            "fe_idp_recent_pressure_events":round(_recent_pressure,2),"fe_idp_recent_coverage_events":round(_recent_coverage,2),
            "fe_idp_recent_def_events":round(_recent_events,2),
            "fe_idp_participation_ready":bool(participation_ready),
            "fe_idp_participation_lane":str(participation_lane),
            "fe_idp_participation_reason":str(participation_reason),
            "fe_idp_participation_contract":"V10.45",
            "fe_idp_early_cap_applied":bool(cap_applied),
            "fe_idp_projected_solo":round(projected["solo"],3),
            "fe_idp_projected_assist":round(projected["assist"],3),
            "fe_idp_projected_sack":round(projected["sack"],3),
            "fe_idp_projected_tfl":round(projected["tfl"],3),
            "fe_idp_projected_qb_hit":round(projected["qb_hit"],3),
            "fe_idp_projected_int":round(projected["int"],3),
            "fe_idp_projected_pd":round(projected["pd"],3),
            "fe_idp_projected_ff":round(projected["ff"],3),
            "fe_idp_projected_fr":round(projected["fr"],3),
            "fe_idp_projected_td":round(projected["def_td"],3),
            "fe_idp_projected_safety":round(projected["safety"],3),
            "fe_idp_model_source":"Fantasy Edge IDP model • Yahoo-slot eligibility • completed weekly stats" + (" + snap share" if (snap_pct>0 or snaps_recent>0) else ""),
        })
    return pd.DataFrame(rows)


# ---------------- V10.44 saved-IDP legality migration ----------------
def _v1044_revalidate_saved_idp_legality(board_df):
    """Re-check cached/saved IDP rows against the current strict Yahoo contract.

    V10.42 could persist generic linebackers as DL with an inferred pressure-role
    eligibility source.  Loading that saved board in a newer build previously trusted
    the old ``fe_idp_slot_eligible=True`` flag, so the bad row survived even though the
    live V10.43 classifier had been fixed.  This migration makes current league legality
    authoritative on every render, including snapshot-only/cloud-restored navigation.
    """
    if board_df is None or not isinstance(board_df,pd.DataFrame) or board_df.empty:
        return board_df
    out=board_df.copy()
    idx=out.index
    pos=out.get("position",pd.Series("",index=idx)).fillna("").astype(str).str.upper()
    is_idp=pos.isin(["DL","DB"])
    if not bool(is_idp.any()):
        return out
    if "fe_idp_slot_eligible" not in out.columns:
        out["fe_idp_slot_eligible"]=False
    if "fe_idp_eligibility_source" not in out.columns:
        out["fe_idp_eligibility_source"]=""

    raw_series=out.get("fe_idp_raw_position",out.get("raw_position",pos)).fillna("").astype(str).str.upper()
    src_series=out.get("fe_idp_eligibility_source",pd.Series("",index=idx)).fillna("").astype(str)
    names=out.get("player",pd.Series("",index=idx)).fillna("").astype(str)
    fantasy_series=out.get("fantasy_positions",pd.Series([None]*len(out),index=idx))

    for i in out.index[is_idp]:
        name=str(names.loc[i])
        raw=str(raw_series.loc[i] or "").upper().strip()
        src=str(src_series.loc[i] or "").strip()
        src_l=src.lower()
        fps=fantasy_series.loc[i] if i in fantasy_series.index else None

        # Old V10.42 statistical inference is never legal evidence.
        legacy_inferred=("pressure-role" in src_l) or ("inferred edge" in src_l)
        generic_lb=raw in (_V1042_OFFBALL_LB_RAW | _V1042_EDGE_LB_RAW)
        trusted_generic_source=(
            "provider fantasy eligibility" in src_l or
            "verified yahoo dual-position override" in src_l
        )

        slot,new_src=_v1042_yahoo_idp_slot(raw,fps,name)
        if legacy_inferred:
            slot=""; new_src="legacy inferred LB eligibility rejected"
        elif generic_lb and not trusted_generic_source:
            # Recalculate generic LBs from current provider metadata / curated Yahoo
            # override only.  A saved True flag is not evidence.
            slot,new_src=_v1042_yahoo_idp_slot(raw,fps,name)
        elif generic_lb and trusted_generic_source and not slot:
            # Some saved rows do not retain fantasy_positions. Preserve only a trusted
            # prior source, except for explicit current Yahoo denials above.
            if norm(name) not in _V1044_YAHOO_DL_DENY:
                slot="DL"
                new_src=src

        legal=slot in {"DL","DB"} and slot==str(pos.loc[i])
        out.at[i,"fe_idp_slot_eligible"]=bool(legal)
        if legal:
            out.at[i,"fe_idp_eligibility_source"]=str(new_src or src)
        else:
            out.at[i,"fe_idp_eligibility_source"]=str(new_src or "not certified for Yahoo DL/DB slot")
    return out


# ---------------- V10.55 native offensive projection engine ----------------
def _v1055_offense_project_from_weekly(stats_df, season, target_week, ppr, pass_td):
    """Build QB/RB/WR/TE weekly projections from observed NFL statistics.

    This mirrors the philosophy of the Fantasy Edge IDP model: observed volume and
    production are the primary evidence, volatile touchdown/efficiency statistics are
    regressed harder than opportunity, and external projection sites are *not* required
    for a player to receive a usable offensive projection.

    The output is intentionally matchup-neutral.  Fantasy Edge's existing matchup,
    role and injury layers are applied later so the same effect is never counted twice.
    """
    if not isinstance(stats_df,pd.DataFrame) or stats_df.empty:
        return pd.DataFrame()
    try:
        yr=int(season); wk=int(target_week); ppr=float(ppr); pass_td=float(pass_td)
    except Exception:
        return pd.DataFrame()
    x=stats_df.copy()
    if "season_type" in x.columns:
        x=x[x["season_type"].astype(str).str.upper().eq("REG")].copy()
    if "week" not in x.columns or "position" not in x.columns:
        return pd.DataFrame()
    x["week"]=pd.to_numeric(x["week"],errors="coerce")
    x=x[x["week"].notna() & (x["week"]<wk)].copy()
    if x.empty:
        return pd.DataFrame()
    name_col=next((c for c in ["player_display_name","player_name","display_name","full_name","player"] if c in x.columns),None)
    if not name_col:
        return pd.DataFrame()
    team_col=next((c for c in ["recent_team","team"] if c in x.columns),None)
    x["position"]=x["position"].fillna("").astype(str).str.upper()
    x=x[x["position"].isin(["QB","RB","WR","TE"])].copy()
    if x.empty:
        return pd.DataFrame()

    def ncol(*names):
        for c in names:
            if c in x.columns:
                return pd.to_numeric(x[c],errors="coerce").fillna(0.0)
        return pd.Series(0.0,index=x.index,dtype=float)

    # Canonical component names. nflverse has kept these stable, but aliases make
    # saved/test fixtures and schema transitions harmless.
    x["pass_att"]=ncol("attempts","passing_attempts")
    x["pass_yd"]=ncol("passing_yards")
    x["pass_td"]=ncol("passing_tds")
    x["pass_int"]=ncol("interceptions","passing_interceptions")
    x["rush_att"]=ncol("carries","rushing_attempts")
    x["rush_yd"]=ncol("rushing_yards")
    x["rush_td"]=ncol("rushing_tds")
    x["targets"]=ncol("targets")
    x["receptions"]=ncol("receptions")
    x["rec_yd"]=ncol("receiving_yards")
    x["rec_td"]=ncol("receiving_tds")
    # nflverse splits lost fumbles by play type. Prefer an explicit total when a
    # schema provides one; otherwise sum the mutually exclusive sack/rush/receive
    # event buckets so QB strip-sacks are not missed.
    if "fumbles_lost" in x.columns:
        x["fumbles_lost"]=pd.to_numeric(x["fumbles_lost"],errors="coerce").fillna(0.0)
    else:
        x["fumbles_lost"]=(
            ncol("sack_fumbles_lost") + ncol("rushing_fumbles_lost") + ncol("receiving_fumbles_lost")
        )
    x["two_pt"]=ncol("passing_2pt_conversions")+ncol("rushing_2pt_conversions")+ncol("receiving_2pt_conversions")
    stat_cols=["pass_att","pass_yd","pass_td","pass_int","rush_att","rush_yd","rush_td","targets","receptions","rec_yd","rec_td","fumbles_lost","two_pt"]

    x["_fantasy_points"]=(
        x["pass_yd"]/25.0 + x["pass_td"]*pass_td - x["pass_int"]*2.0
        + x["rush_yd"]/10.0 + x["rush_td"]*6.0
        + x["receptions"]*ppr + x["rec_yd"]/10.0 + x["rec_td"]*6.0
        - x["fumbles_lost"]*2.0 + x["two_pt"]*2.0
    )
    x["_opportunities"]=np.where(
        x["position"].eq("QB"),
        x["pass_att"]+x["rush_att"],
        x["targets"]+x["rush_att"],
    )

    # Build priors only from players who actually had a fantasy-relevant weekly role.
    # This prevents backup/zero rows from dragging the league baseline toward zero.
    meaningful=(
        (x["position"].eq("QB") & ((x["pass_att"]>=10)|(x["rush_att"]>=4))) |
        (x["position"].eq("RB") & (x["_opportunities"]>=5)) |
        (x["position"].isin(["WR","TE"]) & (x["_opportunities"]>=3))
    )
    baselines={}
    for pos,g_all in x.groupby("position"):
        g=g_all[meaningful.loc[g_all.index]].copy()
        if g.empty: g=g_all.copy()
        d={}
        for c in stat_cols:
            vals=pd.to_numeric(g[c],errors="coerce").fillna(0.0)
            med=float(vals.median()) if len(vals) else 0.0
            mean=float(vals.mean()) if len(vals) else 0.0
            # A median/mean blend is robust to spike games but does not flatten stars.
            d[c]=0.65*med+0.35*mean
        fp=pd.to_numeric(g["_fantasy_points"],errors="coerce").fillna(0.0)
        d["fp_std"]=float(fp.std(ddof=0) or 0.0)
        d["fp_anchor"]=float(fp.quantile(0.65) if len(fp) else 0.0)
        baselines[pos]=d

    # Opportunity is relatively sticky; touchdowns/turnovers are not.  More pseudo
    # games means stronger regression toward the position prior.
    pseudo={
        "pass_att":2.2,"rush_att":2.4,"targets":2.6,"receptions":3.2,
        "pass_yd":3.2,"rush_yd":3.5,"rec_yd":3.5,
        "pass_td":6.5,"rush_td":8.0,"rec_td":8.0,"pass_int":6.0,
        "fumbles_lost":10.0,"two_pt":10.0,
    }
    trend={
        "pass_att":0.20,"rush_att":0.24,"targets":0.24,"receptions":0.18,
        "pass_yd":0.14,"rush_yd":0.14,"rec_yd":0.14,
        "pass_td":0.05,"rush_td":0.04,"rec_td":0.04,"pass_int":0.04,
        "fumbles_lost":0.02,"two_pt":0.02,
    }

    rows=[]
    for name,g in x.groupby(name_col,dropna=True):
        g=g.sort_values("week").copy()
        if g.empty: continue
        pos=str(g["position"].iloc[-1]).upper()
        if pos not in {"QB","RB","WR","TE"}: continue
        games=max(1,int(pd.to_numeric(g["week"],errors="coerce").nunique()))
        latest_week=int(pd.to_numeric(g["week"],errors="coerce").max())
        b=baselines.get(pos,{})
        projected={}
        for c in stat_cols:
            vals=pd.to_numeric(g[c],errors="coerce").fillna(0.0).to_numpy(dtype=float)
            season_avg=float(np.mean(vals)) if len(vals) else 0.0
            last2=float(np.mean(vals[-2:])) if len(vals) else season_avg
            prior=float(b.get(c,0.0) or 0.0)
            pg=float(pseudo.get(c,4.0))
            posterior=(games*season_avg + pg*prior)/max(games+pg,1e-9)
            tw=float(trend.get(c,0.08))*min(1.0,max(games-1,0)/3.0)
            projected[c]=max(0.0,float(posterior + tw*(last2-season_avg)))

        # Physical/statistical sanity constraints.
        projected["receptions"]=min(projected["receptions"],projected["targets"])
        projected["pass_int"]=min(projected["pass_int"],projected["pass_att"])
        projected["pass_td"]=min(projected["pass_td"],projected["pass_att"])

        component_ppg=(
            projected["pass_yd"]/25.0 + projected["pass_td"]*pass_td - projected["pass_int"]*2.0
            + projected["rush_yd"]/10.0 + projected["rush_td"]*6.0
            + projected["receptions"]*ppr + projected["rec_yd"]/10.0 + projected["rec_td"]*6.0
            - projected["fumbles_lost"]*2.0 + projected["two_pt"]*2.0
        )
        actual=pd.to_numeric(g["_fantasy_points"],errors="coerce").fillna(0.0).to_numpy(dtype=float)
        recent_actual=float(np.mean(actual[-2:])) if len(actual) else 0.0
        # Stats-converted expectation remains the authority; recent result is only a
        # small role/trend stabilizer because its underlying stats are already modeled.
        proj=max(0.0,0.92*component_ppg+0.08*recent_actual)

        opps=pd.to_numeric(g["_opportunities"],errors="coerce").fillna(0.0).to_numpy(dtype=float)
        recent_opps=float(np.mean(opps[-2:])) if len(opps) else 0.0
        season_opps=float(np.mean(opps)) if len(opps) else 0.0
        projected_opps=(projected["pass_att"]+projected["rush_att"]) if pos=="QB" else (projected["targets"]+projected["rush_att"])
        if pos=="QB":
            ready=bool(recent_opps>=10.0 or season_opps>=12.0 or recent_actual>=8.0)
        elif pos=="RB":
            ready=bool(recent_opps>=4.0 or season_opps>=4.0 or recent_actual>=4.0)
        else:
            ready=bool(recent_opps>=2.0 or season_opps>=2.0 or recent_actual>=4.0)

        current_completed=max(0,wk-1)
        # V10.64: a missed game/bye is an availability event, not deletion of the
        # underlying skill/usage sample. Keep current-season completed-game evidence
        # native-authoritative and track its age separately; downstream injury/role
        # layers handle whether the player is actually safe to start.
        sample_age=max(0,int(current_completed)-int(latest_week)) if current_completed else 0
        fresh=bool(games>=1 and latest_week>=1)
        pos_std=float(b.get("fp_std",0.0) or 0.0)
        player_std=float(np.std(actual,ddof=0)) if len(actual)>=2 else pos_std
        if pos_std<=0: pos_std=max(2.0,0.28*max(proj,1.0))
        volatility=float(np.sqrt((games*(player_std**2)+4.0*(pos_std**2))/max(games+4.0,1.0)))
        spread=max(1.25,min(0.78*volatility,0.46*max(proj,1.0)+2.0))
        floor=max(0.0,proj-spread)
        ceiling=max(proj,proj+1.10*spread)
        if games<=2:
            floor=max(0.0,min(floor,0.55*proj))
            ceiling=min(ceiling,1.75*proj+2.0)
        conf=0.34+0.11*min(games,4)+0.10*int(fresh)+0.08*min(1.0,recent_opps/max({"QB":30,"RB":14,"WR":9,"TE":7}.get(pos,10),1))
        # Evidence gets less certain while a player is not generating new game samples,
        # but it does not disappear. Availability/return-ramp logic remains separate.
        conf-=min(0.20,0.05*max(0,sample_age))
        if not ready: conf-=0.12
        conf=float(np.clip(conf,0.30,0.90))
        team=str(g[team_col].dropna().astype(str).iloc[-1]).upper() if team_col and g[team_col].notna().any() else ""

        rows.append({
            "player":str(name).strip(),"key":norm(name),"position":pos,"team":team,
            "fe_off_model_ppg":round(proj,3),"fe_off_model_floor":round(floor,3),
            "fe_off_model_ceiling":round(ceiling,3),"fe_off_model_confidence":round(conf,3),
            "fe_off_model_games":games,"fe_off_model_last_week":latest_week,
            "fe_off_model_target_week":wk,"fe_off_model_sample_age_weeks":int(sample_age),
            "fe_off_model_fresh":bool(fresh),"fe_off_model_ready":bool(ready),
            "fe_off_availability_independent":True,
            "fe_off_recent_ppg":round(recent_actual,3),
            "fe_off_recent_opportunities":round(recent_opps,2),"fe_off_season_opportunities":round(season_opps,2),
            "fe_off_projected_opportunities":round(float(projected_opps),2),
            "fe_off_projected_pass_yd":round(projected["pass_yd"],2),
            "fe_off_projected_pass_td":round(projected["pass_td"],3),
            "fe_off_projected_pass_int":round(projected["pass_int"],3),
            "fe_off_projected_rush_att":round(projected["rush_att"],2),
            "fe_off_projected_rush_yd":round(projected["rush_yd"],2),
            "fe_off_projected_rush_td":round(projected["rush_td"],3),
            "fe_off_projected_targets":round(projected["targets"],2),
            "fe_off_projected_receptions":round(projected["receptions"],2),
            "fe_off_projected_rec_yd":round(projected["rec_yd"],2),
            "fe_off_projected_rec_td":round(projected["rec_td"],3),
            "fe_off_model_source":"Fantasy Edge offense model • completed weekly stats • league scoring",
        })
    return pd.DataFrame(rows)


def _v1055_apply_offense_projection_contract(board_df, model_df, teams, slots):
    """Make the native offense model the canonical QB/RB/WR/TE projection.

    Existing Razzball/FantasyPros season projections are retained only as audit/fallback
    evidence.  Sleeper/ESPN weekly projections remain a secondary calibration layer in
    ``_v755_player_state_row``.  Kicker is handled separately by the V10.58 native model.
    """
    if board_df is None or not isinstance(board_df,pd.DataFrame) or board_df.empty:
        return board_df,0
    if model_df is None or not isinstance(model_df,pd.DataFrame) or model_df.empty:
        return board_df,0
    out=board_df.copy()
    if "key" not in out.columns:
        out["key"]=out["player"].astype(str).map(norm)
    idx=out.index
    pos=out.get("position",pd.Series("",index=idx)).fillna("").astype(str).str.upper()
    offense=pos.isin(["QB","RB","WR","TE"])

    # Preserve the old published-season number as comparison/fallback evidence before
    # replacing the canonical projection with Fantasy Edge's own model.
    if "fe_external_season_ppg" not in out.columns: out["fe_external_season_ppg"]=np.nan
    if "fe_external_season_source" not in out.columns: out["fe_external_season_source"]=""
    src=out.get("projection_source",pd.Series("",index=idx)).fillna("").astype(str)
    ext_mask=offense & src.str.contains("Razzball|FantasyPros|published season projection",case=False,regex=True)
    cur_proj=pd.to_numeric(out.get("projection",pd.Series(np.nan,index=idx)),errors="coerce")
    out.loc[ext_mask,"fe_external_season_ppg"]=cur_proj.loc[ext_mask]
    out.loc[ext_mask,"fe_external_season_source"]=src.loc[ext_mask]

    model=model_df.copy()
    if "key" not in model.columns: model["key"]=model["player"].astype(str).map(norm)
    model=model[model["key"].astype(str).ne("")].sort_values(["fe_off_model_ready","fe_off_model_confidence"],ascending=False).drop_duplicates("key")
    model["_v1060_native_team"]=model.get("team",pd.Series("",index=model.index)).fillna("").astype(str).str.upper().str.strip()
    model_cols=[c for c in model.columns if c.startswith("fe_off_")]

    # V10.63: completed-game native evidence is durable and availability-independent.
    # A partial refresh can omit a QUESTIONABLE/GTD player; the old merge erased every
    # saved fe_off_* sample in that case. New rows now overwrite matching evidence only,
    # while unmatched players retain their last certified completed-game native sample.
    existing_model_cols=[c for c in out.columns if c.startswith("fe_off_")]
    payload=model[["key","_v1060_native_team"]+model_cols].copy()
    payload=payload.rename(columns={c:f"__v1063_new_{c}" for c in model_cols})
    out=out.merge(payload,on="key",how="left")
    for c in sorted(set(existing_model_cols)|set(model_cols)):
        nc=f"__v1063_new_{c}"
        if nc in out.columns:
            if c in out.columns:
                out[c]=out[nc].combine_first(out[c])
            else:
                out[c]=out[nc]
            out=out.drop(columns=[nc],errors="ignore")

    _cur_team=out.get("team",pd.Series("",index=out.index)).fillna("").astype(str).str.upper().str.strip()
    _model_team=out.get("_v1060_native_team",pd.Series("",index=out.index)).fillna("").astype(str).str.upper().str.strip()
    _fill_team=_cur_team.isin(["","NFL","FA","NONE","N/A","NAN"]) & ~_model_team.isin(["","NFL","FA","NONE","N/A","NAN"])
    if bool(_fill_team.any()):
        out.loc[_fill_team,"team"]=_model_team.loc[_fill_team].values
        if "_live_team_verified" not in out.columns: out["_live_team_verified"]=0
        out.loc[_fill_team,"_live_team_verified"]=1
    out=out.drop(columns=["_v1060_native_team"],errors="ignore")

    # V10.64: projection evidence and availability are fully separated. A player who
    # misses a completed week (injury/GTD/bye) keeps the current-season native sample.
    # Track sample age for confidence/return-ramp logic instead of revoking the model
    # merely because the player did not create a box score in the immediately prior week.
    try:
        _v1063_target=int(pd.to_numeric(model.get("fe_off_model_target_week",pd.Series(dtype=float)),errors="coerce").dropna().max())
    except Exception:
        _v1063_target=0
    if _v1063_target>0 and "fe_off_model_last_week" in out.columns:
        _v1063_last=pd.to_numeric(out["fe_off_model_last_week"],errors="coerce")
        _v1063_has=pd.to_numeric(out.get("fe_off_model_ppg",pd.Series(np.nan,index=out.index)),errors="coerce").notna()
        _v1064_age=(_v1063_target-1-_v1063_last).clip(lower=0)
        if "fe_off_model_sample_age_weeks" not in out.columns: out["fe_off_model_sample_age_weeks"]=np.nan
        _v1064_prev_age=pd.to_numeric(out["fe_off_model_sample_age_weeks"],errors="coerce").fillna(_v1064_age)
        _v1064_age_delta=(_v1064_age-_v1064_prev_age).clip(lower=0)
        if "fe_off_model_confidence" in out.columns:
            _v1064_conf=pd.to_numeric(out["fe_off_model_confidence"],errors="coerce")
            _v1064_decay=(0.05*_v1064_age_delta).clip(lower=0,upper=0.20)
            out.loc[_v1063_has,"fe_off_model_confidence"]=(
                _v1064_conf.loc[_v1063_has]-_v1064_decay.loc[_v1063_has]
            ).clip(lower=0.30,upper=0.90).values
        out.loc[_v1063_has,"fe_off_model_sample_age_weeks"]=_v1064_age.loc[_v1063_has].values
        out.loc[_v1063_has,"fe_off_model_fresh"]=_v1063_last.loc[_v1063_has].ge(1).values

    idx=out.index
    pos=out.get("position",pd.Series("",index=idx)).fillna("").astype(str).str.upper()
    offense=pos.isin(["QB","RB","WR","TE"])
    # Weekly medical status is intentionally NOT part of native-model readiness.
    # QUESTIONABLE/GTD/DOUBTFUL changes confidence/actionability downstream but never
    # deletes completed-game history or converts a valid same-week model to pending.
    ready=offense & out.get("fe_off_model_ready",pd.Series(False,index=idx)).fillna(False).astype(bool) & out.get("fe_off_model_fresh",pd.Series(False,index=idx)).fillna(False).astype(bool)
    native=pd.to_numeric(out.get("fe_off_model_ppg",pd.Series(np.nan,index=idx)),errors="coerce")

    # Revoke only samples that no longer satisfy the current-season native contract.
    # Missing the immediately prior game is no longer grounds for revocation; injury,
    # bye and return risk are handled separately from projection evidence.
    _v1063_prev_engine=out.get("fe_projection_engine",pd.Series("",index=idx)).fillna("").astype(str).str.upper()
    _v1063_prev_contract=out.get("fe_off_projection_contract_ready",pd.Series(False,index=idx)).fillna(False).astype(bool)
    _v1063_stale_native=offense & (~ready) & (_v1063_prev_engine.eq("FE_OFFENSE_STAT_MODEL") | _v1063_prev_contract)
    if bool(_v1063_stale_native.any()):
        out.loc[_v1063_stale_native,"fe_projection_engine"]=""
        out.loc[_v1063_stale_native,"fe_projection_contract_ready"]=False
        out.loc[_v1063_stale_native,"fe_off_projection_contract_ready"]=False
        _v1063_ps=out.get("projection_source",pd.Series("",index=idx)).fillna("").astype(str)
        _v1063_oldsrc=_v1063_ps.str.contains("Fantasy Edge offense model",case=False,regex=False)
        out.loc[_v1063_stale_native & _v1063_oldsrc,"projection_source"]="Stale FE native fallback • refresh required"
        out.loc[_v1063_stale_native,"fe_projection_source"]="Stale FE native fallback • refresh required"

    # Current observed role can move opportunity modestly, but never replace the
    # stat model or create a projection from nothing.
    rc=pd.to_numeric(out.get("_role_confidence",pd.Series(0,index=idx)),errors="coerce").fillna(0.0)
    role_current=out.get("_usage_recency",pd.Series("",index=idx)).fillna("").astype(str).str.upper().eq("CURRENT")
    obs_opps=pd.to_numeric(out.get("_opps_last",pd.Series(0,index=idx)),errors="coerce").fillna(0.0)
    model_opps=pd.to_numeric(out.get("fe_off_projected_opportunities",pd.Series(0,index=idx)),errors="coerce").fillna(0.0)
    role_scale=pd.Series(1.0,index=idx,dtype=float)
    role_mask=ready & pos.isin(["RB","WR","TE"]) & role_current & rc.ge(55) & obs_opps.gt(0) & model_opps.gt(0)
    if bool(role_mask.any()):
        ratio=(obs_opps/model_opps.replace(0,np.nan)).clip(0.75,1.30).fillna(1.0)
        w=(0.08+0.12*(rc/100.0)).clip(0.08,0.20)
        role_scale.loc[role_mask]=(1.0+w.loc[role_mask]*(ratio.loc[role_mask]-1.0)).clip(0.88,1.12)
    final_native=(native*role_scale).clip(lower=0.0)

    for c,d in [
        ("display_projection",np.nan),("projection_available",False),("projection_source",""),
        ("fe_projection_source",""),("fe_projection_engine",""),("fe_projection_contract_ready",False),
        ("fe_off_projection_contract_ready",False),("fe_off_role_scale",1.0),
        ("fe_week_low",np.nan),("fe_week_high",np.nan),("fe_uncertainty",np.nan),
        ("vorp",np.nan),("display_vorp",np.nan),("replacement_ppg",np.nan),
    ]:
        if c not in out.columns: out[c]=d

    ridx=out.index[ready & final_native.notna() & final_native.gt(0)]
    if len(ridx):
        out.loc[ridx,"projection"]=final_native.loc[ridx].round(3).values
        out.loc[ridx,"display_projection"]=out.loc[ridx,"projection"]
        out.loc[ridx,"projection_available"]=True
        out.loc[ridx,"projection_source"]="Fantasy Edge offense model • observed weekly stats"
        out.loc[ridx,"fe_projection_source"]="Fantasy Edge offense model • observed weekly stats"
        out.loc[ridx,"fe_projection_engine"]="FE_OFFENSE_STAT_MODEL"
        out.loc[ridx,"fe_projection_contract_ready"]=True
        out.loc[ridx,"fe_off_projection_contract_ready"]=True
        out.loc[ridx,"fe_off_role_scale"]=role_scale.loc[ridx].round(3).values
        lo=pd.to_numeric(out.loc[ridx,"fe_off_model_floor"],errors="coerce")*role_scale.loc[ridx]
        hi=pd.to_numeric(out.loc[ridx,"fe_off_model_ceiling"],errors="coerce")*role_scale.loc[ridx]
        out.loc[ridx,"fe_week_low"]=lo.round(3).values
        out.loc[ridx,"fe_week_high"]=hi.round(3).values
        out.loc[ridx,"fe_uncertainty"]=((hi-lo).clip(lower=0)/2.0).round(3).values

        # V10.59: native completed-game evidence is also valid role/usage evidence.
        # Preserve stronger live usage when present; otherwise bridge the model sample
        # into the shared Start/Sit role fields instead of displaying blank usage.
        for c,d in [("_usage_recency","UNAVAILABLE"),("_usage_games",0),("_opps_last",0.0),("_recent_ppg3",0.0),("_role_confidence",0.0),("_role_confidence_source",""),("_role_trend","NO LIVE ROLE DATA"),("_usage_source","")]:
            if c not in out.columns: out[c]=d
        _cur_rec=out.loc[ridx,"_usage_recency"].fillna("").astype(str).str.upper()
        _cur_games=pd.to_numeric(out.loc[ridx,"_usage_games"],errors="coerce").fillna(0)
        _bridge_idx=ridx[~_cur_rec.eq("CURRENT") | _cur_games.le(0)]
        if len(_bridge_idx):
            out.loc[_bridge_idx,"_usage_recency"]="CURRENT"
            out.loc[_bridge_idx,"_usage_games"]=pd.to_numeric(out.loc[_bridge_idx,"fe_off_model_games"],errors="coerce").fillna(0).values
            out.loc[_bridge_idx,"_opps_last"]=pd.to_numeric(out.loc[_bridge_idx,"fe_off_recent_opportunities"],errors="coerce").fillna(0).values
            if "fe_off_recent_ppg" in out.columns:
                out.loc[_bridge_idx,"_recent_ppg3"]=pd.to_numeric(out.loc[_bridge_idx,"fe_off_recent_ppg"],errors="coerce").fillna(0).values
            _mc=(pd.to_numeric(out.loc[_bridge_idx,"fe_off_model_confidence"],errors="coerce").fillna(0)*100.0).clip(45,90)
            _oldc=pd.to_numeric(out.loc[_bridge_idx,"_role_confidence"],errors="coerce").fillna(0)
            out.loc[_bridge_idx,"_role_confidence"]=np.maximum(_oldc.to_numpy(dtype=float),_mc.to_numpy(dtype=float))
            out.loc[_bridge_idx,"_role_confidence_source"]="FE native completed-game usage"
            out.loc[_bridge_idx,"_role_trend"]="STABLE"
            out.loc[_bridge_idx,"_usage_source"]="Fantasy Edge native offense model"

    # Rebuild offensive VORP from the now-native weekly projection.  Fallback
    # externally projected players may still help define a replacement line, but native
    # rows are the only rows whose canonical projection is overwritten here.
    t=max(int(teams),1); flex=float((slots or {}).get("FLEX",0))
    replacement_slots={
        "QB":max(t*int((slots or {}).get("QB",1)),t),
        "RB":max(int(round(t*(float((slots or {}).get("RB",2))+flex*.38))),t),
        "WR":max(int(round(t*(float((slots or {}).get("WR",2))+flex*.55))),t),
        "TE":max(int(round(t*(float((slots or {}).get("TE",1))+flex*.07))),t),
    }
    repl={}
    avail=out.get("projection_available",pd.Series(False,index=out.index)).fillna(False).astype(bool)
    for p,n in replacement_slots.items():
        vals=pd.to_numeric(out.loc[pos.eq(p)&avail,"projection"],errors="coerce").dropna().sort_values(ascending=False).reset_index(drop=True)
        repl[p]=float(vals.iloc[min(max(int(n)-1,0),len(vals)-1)]) if len(vals) else np.nan
    if len(ridx):
        out.loc[ridx,"replacement_ppg"]=pos.loc[ridx].map(repl).values
        out.loc[ridx,"vorp"]=pd.to_numeric(out.loc[ridx,"projection"],errors="coerce")-pd.to_numeric(out.loc[ridx,"replacement_ppg"],errors="coerce")
        out.loc[ridx,"display_vorp"]=out.loc[ridx,"vorp"]

        prog=pd.to_numeric(out.get("progression",pd.Series(0,index=out.index)),errors="coerce").fillna(0)
        reg=pd.to_numeric(out.get("regression",pd.Series(0,index=out.index)),errors="coerce").fillna(0)
        cs=pd.to_numeric(out.get("consensus_strength",pd.Series(45,index=out.index)),errors="coerce").fillna(45)
        scarcity=pos.map({"QB":0.0,"RB":0.9,"WR":1.35,"TE":0.35}).fillna(0.0)
        pure=pd.to_numeric(out.get("vorp",pd.Series(0,index=out.index)),errors="coerce").fillna(0)*9.0 + pd.to_numeric(out.get("projection",pd.Series(0,index=out.index)),errors="coerce").fillna(0)*1.6 + prog*.12-reg*.10+scarcity
        out.loc[ridx,"pure_model_score"]=pure.loc[ridx]
        out.loc[ridx,"draft_score"]=pure.loc[ridx]+cs.loc[ridx]*.10
        out.loc[ridx,"waiver_score"]=pd.to_numeric(out.loc[ridx,"projection"],errors="coerce")*4.0+prog.loc[ridx]*.23-reg.loc[ridx]*.10
        out["model_rank"]=pd.to_numeric(out.get("draft_score",pd.Series(np.nan,index=out.index)),errors="coerce").rank(method="min",ascending=False)
        out["display_model_rank"]=out["model_rank"]
    return out,int(len(ridx))


# ---------------- V10.58 native kicker projection engine ----------------
def _v1058_kicker_project_from_weekly(stats_df, season, target_week, kicker_cfg):
    """Build K weekly projections from observed kicking statistics.

    The kicker model mirrors Fantasy Edge's offense/IDP philosophy: opportunity is
    trusted more than volatile scoring outcomes, rare long-field-goal production is
    regressed aggressively, and the league's editable Yahoo kicker scoring is applied
    directly to the projected stat line.  External weekly projections are not required.
    """
    if not isinstance(stats_df,pd.DataFrame) or stats_df.empty:
        return pd.DataFrame()
    try:
        yr=int(season); wk=int(target_week)
        cfg=dict(kicker_cfg or {})
    except Exception:
        return pd.DataFrame()
    x=stats_df.copy()
    if "season_type" in x.columns:
        x=x[x["season_type"].astype(str).str.upper().eq("REG")].copy()
    if "week" not in x.columns or "position" not in x.columns:
        return pd.DataFrame()
    x["week"]=pd.to_numeric(x["week"],errors="coerce")
    x=x[x["week"].notna() & (x["week"]<wk)].copy()
    if x.empty:
        return pd.DataFrame()
    name_col=next((c for c in ["player_display_name","player_name","display_name","full_name","player"] if c in x.columns),None)
    if not name_col:
        return pd.DataFrame()
    team_col=next((c for c in ["recent_team","team"] if c in x.columns),None)
    x["position"]=x["position"].fillna("").astype(str).str.upper()
    x=x[x["position"].eq("K")].copy()
    if x.empty:
        return pd.DataFrame()

    def ncol(*names):
        for c in names:
            if c in x.columns:
                return pd.to_numeric(x[c],errors="coerce").fillna(0.0)
        return pd.Series(0.0,index=x.index,dtype=float)

    x["pat_made"]=ncol("pat_made")
    x["pat_missed"]=ncol("pat_missed")
    x["fg_0_19"]=ncol("fg_made_0_19")
    x["fg_20_29"]=ncol("fg_made_20_29")
    x["fg_30_39"]=ncol("fg_made_30_39")
    x["fg_40_49"]=ncol("fg_made_40_49")
    x["fg_50_59"]=ncol("fg_made_50_59")
    x["fg_60_plus"]=ncol("fg_made_60_","fg_made_60_plus")
    x["fg_missed"]=ncol("fg_missed")
    stat_cols=["pat_made","pat_missed","fg_0_19","fg_20_29","fg_30_39","fg_40_49","fg_50_59","fg_60_plus","fg_missed"]

    x["_pat_att"]=x["pat_made"]+x["pat_missed"]
    x["_fg_made"]=x[["fg_0_19","fg_20_29","fg_30_39","fg_40_49","fg_50_59","fg_60_plus"]].sum(axis=1)
    x["_fg_att"]=x["_fg_made"]+x["fg_missed"]
    x["_opportunities"]=x["_pat_att"]+x["_fg_att"]
    x["_fantasy_points"]=(
        x["pat_made"]*float(cfg.get("pat",1.0))
        + x["fg_0_19"]*float(cfg.get("fg_0_19",3.0))
        + x["fg_20_29"]*float(cfg.get("fg_20_29",3.0))
        + x["fg_30_39"]*float(cfg.get("fg_30_39",3.0))
        + x["fg_40_49"]*float(cfg.get("fg_40_49",4.0))
        + x["fg_50_59"]*float(cfg.get("fg_50_59",4.5))
        + x["fg_60_plus"]*float(cfg.get("fg_60_plus",5.5))
        + x["fg_missed"]*float(cfg.get("missed_fg",0.0))
        + x["pat_missed"]*float(cfg.get("missed_pat",0.0))
    )

    meaningful=x[x["_opportunities"].ge(1)].copy()
    if meaningful.empty: meaningful=x.copy()
    prior={}
    for c in stat_cols:
        vals=pd.to_numeric(meaningful[c],errors="coerce").fillna(0.0)
        prior[c]=0.65*float(vals.median() if len(vals) else 0.0)+0.35*float(vals.mean() if len(vals) else 0.0)
    fp_all=pd.to_numeric(meaningful["_fantasy_points"],errors="coerce").fillna(0.0)
    league_std=float(fp_all.std(ddof=0) or 0.0)

    # Common attempts stabilize quickly; long-distance makes and misses are much noisier.
    pseudo={
        "pat_made":2.5,"pat_missed":8.0,
        "fg_0_19":5.0,"fg_20_29":4.5,"fg_30_39":4.0,
        "fg_40_49":5.0,"fg_50_59":6.5,"fg_60_plus":10.0,"fg_missed":7.0,
    }
    trend={
        "pat_made":0.18,"pat_missed":0.02,
        "fg_0_19":0.08,"fg_20_29":0.10,"fg_30_39":0.12,
        "fg_40_49":0.10,"fg_50_59":0.07,"fg_60_plus":0.03,"fg_missed":0.03,
    }

    rows=[]
    for name,g in x.groupby(name_col,dropna=True):
        g=g.sort_values("week").copy()
        if g.empty: continue
        games=max(1,int(pd.to_numeric(g["week"],errors="coerce").nunique()))
        latest_week=int(pd.to_numeric(g["week"],errors="coerce").max())
        projected={}
        for c in stat_cols:
            vals=pd.to_numeric(g[c],errors="coerce").fillna(0.0).to_numpy(dtype=float)
            season_avg=float(np.mean(vals)) if len(vals) else 0.0
            last2=float(np.mean(vals[-2:])) if len(vals) else season_avg
            pg=float(pseudo.get(c,5.0)); pv=float(prior.get(c,0.0) or 0.0)
            posterior=(games*season_avg+pg*pv)/max(games+pg,1e-9)
            tw=float(trend.get(c,0.05))*min(1.0,max(games-1,0)/3.0)
            projected[c]=max(0.0,float(posterior+tw*(last2-season_avg)))

        component=(
            projected["pat_made"]*float(cfg.get("pat",1.0))
            + projected["fg_0_19"]*float(cfg.get("fg_0_19",3.0))
            + projected["fg_20_29"]*float(cfg.get("fg_20_29",3.0))
            + projected["fg_30_39"]*float(cfg.get("fg_30_39",3.0))
            + projected["fg_40_49"]*float(cfg.get("fg_40_49",4.0))
            + projected["fg_50_59"]*float(cfg.get("fg_50_59",4.5))
            + projected["fg_60_plus"]*float(cfg.get("fg_60_plus",5.5))
            + projected["fg_missed"]*float(cfg.get("missed_fg",0.0))
            + projected["pat_missed"]*float(cfg.get("missed_pat",0.0))
        )
        actual=pd.to_numeric(g["_fantasy_points"],errors="coerce").fillna(0.0).to_numpy(dtype=float)
        recent_actual=float(np.mean(actual[-2:])) if len(actual) else 0.0
        proj=max(0.0,0.95*component+0.05*recent_actual)
        opps=pd.to_numeric(g["_opportunities"],errors="coerce").fillna(0.0).to_numpy(dtype=float)
        recent_opps=float(np.mean(opps[-2:])) if len(opps) else 0.0
        season_opps=float(np.mean(opps)) if len(opps) else 0.0
        projected_fg_att=sum(projected[c] for c in ["fg_0_19","fg_20_29","fg_30_39","fg_40_49","fg_50_59","fg_60_plus","fg_missed"])
        projected_pat_att=projected["pat_made"]+projected["pat_missed"]
        projected_opps=projected_fg_att+projected_pat_att
        ready=bool(recent_opps>=1.5 or season_opps>=1.5 or recent_actual>=3.0)
        current_completed=max(0,wk-1)
        fresh=bool(latest_week>=current_completed) if current_completed else True
        player_std=float(np.std(actual,ddof=0)) if len(actual)>=2 else league_std
        if league_std<=0: league_std=max(2.5,0.40*max(proj,1.0))
        volatility=float(np.sqrt((games*(player_std**2)+5.0*(league_std**2))/max(games+5.0,1.0)))
        spread=max(2.0,min(0.85*volatility,0.62*max(proj,1.0)+2.4))
        floor=max(0.0,proj-spread)
        ceiling=max(proj,proj+1.15*spread)
        conf=0.30+0.10*min(games,4)+0.10*int(fresh)+0.10*min(1.0,recent_opps/5.0)
        if not ready: conf-=0.12
        conf=float(np.clip(conf,0.28,0.84))
        team=str(g[team_col].dropna().astype(str).iloc[-1]).upper() if team_col and g[team_col].notna().any() else ""
        rows.append({
            "player":str(name).strip(),"key":norm(name),"position":"K","team":team,
            "fe_k_model_ppg":round(proj,3),"fe_k_model_floor":round(floor,3),
            "fe_k_model_ceiling":round(ceiling,3),"fe_k_model_confidence":round(conf,3),
            "fe_k_model_games":games,"fe_k_model_last_week":latest_week,
            "fe_k_model_fresh":bool(fresh),"fe_k_model_ready":bool(ready),
            "fe_k_recent_opportunities":round(recent_opps,2),"fe_k_season_opportunities":round(season_opps,2),
            "fe_k_projected_opportunities":round(float(projected_opps),2),
            "fe_k_projected_fg_attempts":round(float(projected_fg_att),2),
            "fe_k_projected_pat_attempts":round(float(projected_pat_att),2),
            "fe_k_projected_fg_40_plus":round(float(projected["fg_40_49"]+projected["fg_50_59"]+projected["fg_60_plus"]),2),
            "fe_k_model_source":"Fantasy Edge kicker model • completed weekly kicking stats • league scoring",
        })
    return pd.DataFrame(rows)


def _v1058_apply_kicker_projection_contract(board_df, model_df, teams, slots):
    """Make the native kicker model canonical and add newly active kickers when needed."""
    if board_df is None or not isinstance(board_df,pd.DataFrame) or board_df.empty:
        return board_df,0,0
    if model_df is None or not isinstance(model_df,pd.DataFrame) or model_df.empty:
        return board_df,0,0
    out=board_df.copy()
    if "key" not in out.columns: out["key"]=out["player"].astype(str).map(norm)
    model=model_df.copy()
    if "key" not in model.columns: model["key"]=model["player"].astype(str).map(norm)
    model=model[model["key"].astype(str).ne("")].sort_values(["fe_k_model_ready","fe_k_model_confidence"],ascending=False).drop_duplicates("key")
    _v1060_k_team=dict(zip(model["key"].astype(str),model.get("team",pd.Series("",index=model.index)).fillna("").astype(str).str.upper().str.strip()))

    # Weekly stats are also the discovery source.  This avoids a stale hard-coded K list
    # preventing a newly signed/replacement kicker from reaching Waivers or Start/Sit.
    existing=set(out["key"].astype(str))
    add_rows=[]
    for _,r in model.iterrows():
        k=str(r.get("key","") or "")
        if not k or k in existing: continue
        add_rows.append({
            "player":str(r.get("player","") or ""),"key":k,"position":"K","raw_position":"K",
            "team":str(r.get("team","") or "").upper(),"projection":0.0,"display_projection":0.0,
            "projection_available":False,"projection_source":"","confidence":0.50,
            "consensus_rank":np.nan,"market_pick":np.nan,"progression":0.0,"regression":0.0,
            "consensus_strength":45.0,"injury":"","injury_effective":"","profile":"Current kicker • native model",
            "id":"native-k:"+k,"identity_key":"native-k:"+k+"|K",
        })
        existing.add(k)
    if add_rows:
        out=pd.concat([out,pd.DataFrame(add_rows)],ignore_index=True,sort=False)

    idx=out.index
    pos=out.get("position",pd.Series("",index=idx)).fillna("").astype(str).str.upper()
    kmask=pos.eq("K")
    if "fe_k_pre_native_ppg" not in out.columns: out["fe_k_pre_native_ppg"]=np.nan
    if "fe_k_pre_native_source" not in out.columns: out["fe_k_pre_native_source"]=""
    old_proj=pd.to_numeric(out.get("projection",pd.Series(np.nan,index=idx)),errors="coerce")
    out.loc[kmask,"fe_k_pre_native_ppg"]=old_proj.loc[kmask]
    out.loc[kmask,"fe_k_pre_native_source"]=out.get("projection_source",pd.Series("",index=idx)).fillna("").astype(str).loc[kmask]

    mcols=[c for c in model.columns if c.startswith("fe_k_")]
    out=out.drop(columns=[c for c in mcols if c in out.columns],errors="ignore")
    out=out.merge(model[["key"]+mcols],on="key",how="left")
    _cur_team=out.get("team",pd.Series("",index=out.index)).fillna("").astype(str).str.upper().str.strip()
    _model_team=out["key"].astype(str).map(_v1060_k_team).fillna("").astype(str).str.upper().str.strip()
    _fill_team=_cur_team.isin(["","NFL","FA","NONE","N/A","NAN"]) & ~_model_team.isin(["","NFL","FA","NONE","N/A","NAN"])
    if bool(_fill_team.any()):
        out.loc[_fill_team,"team"]=_model_team.loc[_fill_team].values
        if "_live_team_verified" not in out.columns: out["_live_team_verified"]=0
        out.loc[_fill_team,"_live_team_verified"]=1
    idx=out.index
    pos=out.get("position",pd.Series("",index=idx)).fillna("").astype(str).str.upper()
    ready=pos.eq("K") & out.get("fe_k_model_ready",pd.Series(False,index=idx)).fillna(False).astype(bool) & out.get("fe_k_model_fresh",pd.Series(False,index=idx)).fillna(False).astype(bool)
    native=pd.to_numeric(out.get("fe_k_model_ppg",pd.Series(np.nan,index=idx)),errors="coerce")
    for c,d in [
        ("display_projection",np.nan),("projection_available",False),("projection_source",""),
        ("fe_projection_source",""),("fe_projection_engine",""),("fe_projection_contract_ready",False),
        ("fe_k_projection_contract_ready",False),("fe_week_low",np.nan),("fe_week_high",np.nan),("fe_uncertainty",np.nan),
        ("vorp",np.nan),("display_vorp",np.nan),("replacement_ppg",np.nan),("draft_score",np.nan),("waiver_score",np.nan),
    ]:
        if c not in out.columns: out[c]=d
    ridx=out.index[ready & native.notna() & native.gt(0)]
    if len(ridx):
        out.loc[ridx,"projection"]=native.loc[ridx].round(3).values
        out.loc[ridx,"display_projection"]=out.loc[ridx,"projection"]
        out.loc[ridx,"projection_available"]=True
        out.loc[ridx,"projection_source"]="Fantasy Edge kicker model • observed weekly kicking stats"
        out.loc[ridx,"fe_projection_source"]="Fantasy Edge kicker model • observed weekly kicking stats"
        out.loc[ridx,"fe_projection_engine"]="FE_KICKER_STAT_MODEL"
        out.loc[ridx,"fe_projection_contract_ready"]=True
        out.loc[ridx,"fe_k_projection_contract_ready"]=True
        lo=pd.to_numeric(out.loc[ridx,"fe_k_model_floor"],errors="coerce")
        hi=pd.to_numeric(out.loc[ridx,"fe_k_model_ceiling"],errors="coerce")
        out.loc[ridx,"fe_week_low"]=lo.round(3).values
        out.loc[ridx,"fe_week_high"]=hi.round(3).values
        out.loc[ridx,"fe_uncertainty"]=((hi-lo).clip(lower=0)/2.0).round(3).values

    # Kicker VORP is position-relative and now uses native expected points.
    t=max(int(teams),1); required=max(t*int((slots or {}).get("K",1)),t)
    avail=out.get("projection_available",pd.Series(False,index=out.index)).fillna(False).astype(bool)
    vals=pd.to_numeric(out.loc[pos.eq("K")&avail,"projection"],errors="coerce").dropna().sort_values(ascending=False).reset_index(drop=True)
    repl=float(vals.iloc[min(max(required-1,0),len(vals)-1)]) if len(vals) else np.nan
    if len(ridx):
        out.loc[ridx,"replacement_ppg"]=repl
        out.loc[ridx,"vorp"]=pd.to_numeric(out.loc[ridx,"projection"],errors="coerce")-repl
        out.loc[ridx,"display_vorp"]=out.loc[ridx,"vorp"]
        prog=pd.to_numeric(out.get("progression",pd.Series(0,index=out.index)),errors="coerce").fillna(0)
        reg=pd.to_numeric(out.get("regression",pd.Series(0,index=out.index)),errors="coerce").fillna(0)
        pure=pd.to_numeric(out.get("vorp",pd.Series(0,index=out.index)),errors="coerce").fillna(0)*9.0 + pd.to_numeric(out.get("projection",pd.Series(0,index=out.index)),errors="coerce").fillna(0)*1.6 - 1.25
        out.loc[ridx,"pure_model_score"]=pure.loc[ridx]
        out.loc[ridx,"draft_score"]=pure.loc[ridx]
        out.loc[ridx,"waiver_score"]=pd.to_numeric(out.loc[ridx,"projection"],errors="coerce")*4.0+prog.loc[ridx]*.08-reg.loc[ridx]*.05
        out["model_rank"]=pd.to_numeric(out.get("draft_score",pd.Series(np.nan,index=out.index)),errors="coerce").rank(method="min",ascending=False)
        out["display_model_rank"]=out["model_rank"]
    return out,int(len(ridx)),int(len(add_rows))


# ---------------- V10.59 native-model continuity ----------------
def _v1059_rehydrate_native_projection_contracts(board_df,teams,slots):
    """Reapply saved native offense/K model rows on every render.

    Snapshot navigation may preserve model component columns while legacy canonical
    fields/flags are absent or were overwritten by an older schema migration. Rehydrating
    from those saved model components keeps Start/Sit, Waivers and Trades on the same
    native projection without a network request.
    """
    out=board_df.copy() if isinstance(board_df,pd.DataFrame) else pd.DataFrame()
    if out.empty: return out,{"offense":0,"kicker":0}
    if "key" not in out.columns: out["key"]=out["player"].astype(str).map(norm)
    counts={"offense":0,"kicker":0}
    try:
        off_cols=[c for c in out.columns if c.startswith("fe_off_model_") or c.startswith("fe_off_recent_") or c.startswith("fe_off_season_") or c.startswith("fe_off_projected_")]
        if "fe_off_model_ppg" in out.columns and off_cols:
            om=out[[c for c in ["player","key","position","team"]+off_cols if c in out.columns]].copy()
            om=om[pd.to_numeric(om.get("fe_off_model_ppg"),errors="coerce").notna()]
            if len(om): out,counts["offense"]=_v1055_apply_offense_projection_contract(out,om,teams,slots)
    except Exception:
        pass
    try:
        k_cols=[c for c in out.columns if c.startswith("fe_k_model_") or c.startswith("fe_k_recent_") or c.startswith("fe_k_season_") or c.startswith("fe_k_projected_")]
        if "fe_k_model_ppg" in out.columns and k_cols:
            km=out[[c for c in ["player","key","position","team"]+k_cols if c in out.columns]].copy()
            km=km[pd.to_numeric(km.get("fe_k_model_ppg"),errors="coerce").notna()]
            if len(km): out,counts["kicker"],_=_v1058_apply_kicker_projection_contract(out,km,teams,slots)
    except Exception:
        pass
    return out,counts

def _v1060_native_contract_coverage(board_df):
    b=board_df if isinstance(board_df,pd.DataFrame) else pd.DataFrame()
    if b.empty: return {"offense":0,"kicker":0,"idp":0}
    pos=b.get("position",pd.Series("",index=b.index)).fillna("").astype(str).str.upper()
    eng=b.get("fe_projection_engine",pd.Series("",index=b.index)).fillna("").astype(str).str.upper()
    return {
        "offense":int((pos.isin(["QB","RB","WR","TE"]) & eng.eq("FE_OFFENSE_STAT_MODEL")).sum()),
        "kicker":int((pos.eq("K") & eng.eq("FE_KICKER_STAT_MODEL")).sum()),
        "idp":int((pos.isin(["DL","DB"]) & eng.eq("FE_IDP_STAT_MODEL")).sum()),
    }

def _v1060_rebuild_native_from_persistent_stats(board_df,season,week,teams,slots,ppr,pass_td,idp_cfg,kicker_cfg):
    """Rebuild canonical FE models from persistent actuals before page-specific decisions."""
    out=board_df.copy() if isinstance(board_df,pd.DataFrame) else pd.DataFrame()
    diag={"source":"none","offense":0,"kicker":0,"idp":0,"stats_rows":0,"latest_week":0}
    if out.empty: return out,diag
    stats=_v1059_load_weekly_stats_disk(int(season))
    if not isinstance(stats,pd.DataFrame) or stats.empty: return out,diag
    try: latest=int(pd.to_numeric(stats.get("week",pd.Series(dtype=float)),errors="coerce").dropna().max())
    except Exception: latest=0
    diag.update({"source":"persistent completed-game stats","stats_rows":int(len(stats)),"latest_week":latest})
    cache_key=json.dumps({"season":int(season),"week":int(week),"rows":int(len(stats)),"latest":latest,"ppr":float(ppr),"pass_td":float(pass_td),"idp":idp_cfg or {},"kicker":kicker_cfg or {}},sort_keys=True,default=str)
    bundle=None
    try:
        c=st.session_state.get("_v1060_native_bundle",{}) or {}
        if c.get("key")==cache_key: bundle=c
    except Exception: pass
    if not bundle:
        try: off=_v1055_offense_project_from_weekly(stats,int(season),int(week),float(ppr),float(pass_td))
        except Exception: off=pd.DataFrame()
        try: km=_v1058_kicker_project_from_weekly(stats,int(season),int(week),kicker_cfg or {})
        except Exception: km=pd.DataFrame()
        try:
            elig=_v1039_league_player_directory(refresh_live=False)
            im=_v1040_idp_project_from_weekly(stats,pd.DataFrame(),int(season),int(week),idp_cfg or {},elig)
        except Exception: im=pd.DataFrame()
        bundle={"key":cache_key,"off":off,"k":km,"idp":im}
        try: st.session_state["_v1060_native_bundle"]=bundle
        except Exception: pass
    try:
        im=bundle.get("idp",pd.DataFrame())
        if isinstance(im,pd.DataFrame) and not im.empty: out,diag["idp"],_=_v1040_attach_idp_model(out,im)
    except Exception: pass
    try:
        off=bundle.get("off",pd.DataFrame())
        if isinstance(off,pd.DataFrame) and not off.empty: out,diag["offense"]=_v1055_apply_offense_projection_contract(out,off,teams,slots)
    except Exception: pass
    try:
        km=bundle.get("k",pd.DataFrame())
        if isinstance(km,pd.DataFrame) and not km.empty: out,diag["kicker"],_=_v1058_apply_kicker_projection_contract(out,km,teams,slots)
    except Exception: pass
    return out,diag

def _v1059_fill_identity_from_saved_directory(board_df):
    """Backfill only missing/NFL placeholder team identity from the persisted directory."""
    out=board_df.copy() if isinstance(board_df,pd.DataFrame) else pd.DataFrame()
    if out.empty or "player" not in out.columns: return out,0
    try:
        directory=_v1039_league_player_directory(refresh_live=False)
    except Exception:
        directory=pd.DataFrame()
    if not isinstance(directory,pd.DataFrame) or directory.empty: return out,0
    if "key" not in out.columns: out["key"]=out["player"].astype(str).map(norm)
    directory=directory.copy(); directory["key"]=directory["player"].astype(str).map(norm)
    directory=directory[directory["key"].astype(str).ne("")].drop_duplicates("key").set_index("key")
    team=out.get("team",pd.Series("",index=out.index)).fillna("").astype(str).str.upper().str.strip()
    bad=team.isin(["","NFL","FA","NONE","N/A","NAN"])
    mapped=out["key"].map(directory.get("team",pd.Series(dtype=object))) if "team" in directory.columns else pd.Series("",index=out.index)
    fill=bad & mapped.fillna("").astype(str).str.strip().ne("")
    if fill.any(): out.loc[fill,"team"]=mapped.loc[fill].astype(str).str.upper().values
    return out,int(fill.sum())

# ---------------- V10.41 canonical IDP projection contract ----------------
def _v1041_apply_idp_projection_contract(board_df):
    """Make the V10.40 stat model the same IDP projection used by every tab.

    The weekly snapshot can be rendered without re-running live providers.  This
    deterministic contract rehydrates saved FE IDP model fields into the canonical
    projection/fe_week columns that Start/Sit, Waivers, Trade Finder, Scarcity,
    Player Lab, Action Queue and IDP pages already consume.
    """
    if board_df is None or not isinstance(board_df,pd.DataFrame) or board_df.empty:
        return board_df
    board_df=_v1044_revalidate_saved_idp_legality(board_df)
    out=board_df.copy()
    idx=out.index
    pos=out.get("position",pd.Series("",index=idx)).fillna("").astype(str).str.upper()
    is_idp=pos.isin(["DL","DB"])
    if not bool(is_idp.any()):
        return out

    def numcol(name, default=np.nan):
        return pd.to_numeric(out.get(name,pd.Series(default,index=idx)),errors="coerce")

    model=numcol("fe_idp_model_ppg")
    ext=numcol("_external_week_projection")
    conf=numcol("fe_idp_model_confidence",0.0).fillna(0.0)
    games=numcol("fe_idp_model_games",0.0).fillna(0.0)
    fresh_raw=out.get("fe_idp_model_fresh",pd.Series(False,index=idx))
    fresh=fresh_raw.fillna(False).map(lambda v: str(v).strip().lower() in {"1","true","yes","y"} if not isinstance(v,(bool,np.bool_)) else bool(v))
    slot_ok=out.get("fe_idp_slot_eligible",pd.Series(False,index=idx)).fillna(False).astype(bool)

    # V10.45: recompute participation on every load.  Do not trust a previously saved
    # boolean because V10.44 snapshots predate this role contract.
    for c,default in [("fe_idp_participation_ready",False),("fe_idp_participation_lane",""),("fe_idp_participation_reason",""),("fe_idp_participation_contract","")]:
        if c not in out.columns: out[c]=default
    for i in out.index[is_idp]:
        ok,lane,reason=_v1045_idp_participation_status(out.loc[i])
        out.at[i,"fe_idp_participation_ready"]=bool(ok)
        out.at[i,"fe_idp_participation_lane"]=str(lane)
        out.at[i,"fe_idp_participation_reason"]=str(reason)
        out.at[i,"fe_idp_participation_contract"]="V10.45"
    # V10.51: bridge the same snap/box evidence into the shared role-confidence layer
    # before any tab consumes this saved/current board.
    out=_v1051_apply_idp_role_bridge(out)
    participation_ok=out.get("fe_idp_participation_ready",pd.Series(False,index=idx)).fillna(False).astype(bool)
    ready=is_idp & slot_ok & participation_ok & model.gt(0) & games.ge(1) & fresh & conf.ge(0.35)

    # V10.45: no other tab may rank a defender on an old base-board projection when
    # the canonical IDP model is absent or the player is not legal for DL/DB. Keep the
    # identity, but quarantine the stale fantasy value until a current model attaches.
    stale_idp=is_idp & ~ready
    for c,default in [
        ("projection",0.0),("display_projection",0.0),("fe_week",0.0),("fe_week_low",0.0),
        ("fe_week_high",0.0),("fe_uncertainty",0.0),("fe_ros",0.0),("vorp",0.0),
        ("display_vorp",0.0),("projection_available",False),("fe_projection_contract_ready",False)
    ]:
        if c not in out.columns: out[c]=default
    if bool(stale_idp.any()):
        out.loc[out.index[stale_idp],["projection","display_projection","fe_week","fe_week_low","fe_week_high","fe_uncertainty","fe_ros","vorp","display_vorp"]]=0.0
        out.loc[out.index[stale_idp],"projection_available"]=False
        out.loc[out.index[stale_idp],"fe_projection_contract_ready"]=False
        if "fe_projection_source" not in out.columns: out["fe_projection_source"]=""
        out.loc[out.index[stale_idp],"fe_projection_source"]="IDP projection pending / ineligible / non-actionable role"
    if not bool(ready.any()):
        return out

    # The FE stat model is the anchor. A positive external weekly value can be a
    # secondary ensemble input, but the app never depends on it for IDP coverage.
    final=model.copy()
    has_ext=ready & ext.gt(0)
    final.loc[has_ext]=0.55*model.loc[has_ext] + 0.45*ext.loc[has_ext]

    old_proj=numcol("projection",0.0).fillna(0.0)
    repl=numcol("replacement_ppg")
    repl_default=pos.map({"DL":6.2,"DB":5.9}).astype(float)
    repl=repl.where(repl.gt(0),repl_default)
    vorp=final-repl

    floor=numcol("fe_idp_model_floor")
    ceil=numcol("fe_idp_model_ceiling")
    shift=final-model
    low=(floor+shift).where(floor.notna(),final-1.5).clip(lower=0.0)
    high=(ceil+shift).where(ceil.notna(),final+1.5)
    high=np.maximum(high,final)
    low=np.minimum(low,final)
    unc=((high-low)/2.0).clip(lower=0.6)

    source=pd.Series("Fantasy Edge IDP model • nflverse weekly stats",index=idx,dtype=object)
    source.loc[has_ext]="Fantasy Edge IDP model + Sleeper weekly projection"
    model_src=out.get("fe_idp_model_source",pd.Series("",index=idx)).fillna("").astype(str)
    source=source.where(model_src.eq(""),model_src)
    source.loc[has_ext]="Fantasy Edge IDP model + Sleeper weekly projection"

    for c,default in [
        ("projection",0.0),("display_projection",0.0),("vorp",0.0),("display_vorp",0.0),
        ("fe_week",0.0),("fe_week_low",0.0),("fe_week_high",0.0),("fe_uncertainty",0.0),
        ("fe_ros",0.0),("projection_source",""),("projection_available",False),
        ("fe_projection_source",""),("fe_projection_engine",""),("fe_projection_contract_ready",False),
    ]:
        if c not in out.columns: out[c]=default

    rdx=out.index[ready]
    out.loc[rdx,"projection"]=final.loc[ready].round(3).values
    out.loc[rdx,"display_projection"]=final.loc[ready].round(3).values
    out.loc[rdx,"vorp"]=vorp.loc[ready].round(3).values
    out.loc[rdx,"display_vorp"]=vorp.loc[ready].round(3).values
    out.loc[rdx,"fe_week"]=final.loc[ready].round(3).values
    out.loc[rdx,"fe_week_low"]=low.loc[ready].round(3).values
    out.loc[rdx,"fe_week_high"]=pd.Series(high,index=idx).loc[ready].round(3).values
    out.loc[rdx,"fe_uncertainty"]=unc.loc[ready].round(3).values
    out.loc[rdx,"projection_source"]=source.loc[ready].values
    out.loc[rdx,"fe_projection_source"]=source.loc[ready].values
    out.loc[rdx,"projection_available"]=True
    out.loc[rdx,"fe_projection_engine"]="FE_IDP_STAT_MODEL"
    out.loc[rdx,"fe_projection_contract_ready"]=True

    # Keep ROS/value layers aligned with the same weekly model on snapshot-only
    # navigation. This mirrors the app's fast canonical ROS formula and is idempotent.
    br=numcol("breakout",0.0).fillna(0.0).clip(0,1)
    dc=numcol("decline",0.0).fillna(0.0).clip(0,1)
    base_conf=numcol("confidence",0.5).fillna(0.5).clip(0,1)
    merged_conf=np.maximum(base_conf,conf.clip(0,1))
    ros=(final + vorp.clip(-3,5)*0.22 + (br-dc)*1.10 + (merged_conf-0.5)*0.40).clip(lower=0.0)
    out.loc[rdx,"fe_ros"]=ros.loc[ready].round(3).values
    out.loc[rdx,"confidence"]=merged_conf.loc[ready].round(3).values
    return out

def _v1040_attach_idp_model(board_df, model_df):
    """Attach the free stat model and promote newly discovered defenders into the board."""
    if board_df is None or not isinstance(board_df,pd.DataFrame) or board_df.empty:
        return board_df,0,0
    if model_df is None or not isinstance(model_df,pd.DataFrame) or model_df.empty:
        return board_df,0,0
    b=board_df.copy()
    if "key" not in b.columns: b["key"]=b["player"].astype(str).map(norm)
    m=model_df.copy().drop_duplicates("key",keep="last")
    # Remove stale V10.40/10.41 model-created IDPs that no longer pass Yahoo slot
    # eligibility. Without this, a pure LB from an older snapshot can survive forever.
    _model_keys=set(m["key"].astype(str))
    _pool=b.get("pool_status",pd.Series("",index=b.index)).fillna("").astype(str)
    _ids=b.get("id",pd.Series("",index=b.index)).fillna("").astype(str)
    _stale_model=(_pool.eq("IDP_STAT_MODEL")|_ids.str.startswith("idp-model:")) & b["position"].astype(str).isin(["DL","DB"]) & ~b["key"].astype(str).isin(_model_keys)
    if bool(_stale_model.any()):
        b=b.loc[~_stale_model].copy()
    existing=set(b["key"].astype(str))
    added=[]
    repl={"DL":6.2,"DB":5.9}
    for _,r in m[~m["key"].astype(str).isin(existing)].iterrows():
        pos=str(r.get("position","")); proj=float(r.get("fe_idp_model_ppg",0) or 0)
        role_ready=bool(r.get("fe_idp_participation_ready",False))
        if pos not in {"DL","DB"} or proj<=0 or not role_ready: continue
        d={c:np.nan for c in b.columns}
        rp=float(repl.get(pos,6.0))
        d.update({
            "id":"idp-model:"+str(r.get("key")),"player":str(r.get("player")),"key":str(r.get("key")),
            "position":pos,"raw_position":str(r.get("fe_idp_raw_position") or pos),"team":str(r.get("team") or "NFL"),
            "projection":proj,"display_projection":proj,"last_ppg":proj,"prior_ppg":proj,
            "opp_pg":proj,"replacement_ppg":rp,"vorp":proj-rp,"display_vorp":proj-rp,
            "draft_score":proj*5.0,"waiver_score":proj*4.0,"model_rank":999.0,
            "consensus_rank":np.nan,"market_pick":np.nan,"confidence":float(r.get("fe_idp_model_confidence",0.5) or 0.5),
            "projection_available":True,"projection_source":str(r.get("fe_idp_model_source")),
            "profile":"Stat-model IDP • current role","pool_status":"IDP_STAT_MODEL",
            "roster_sync_source":"nflverse weekly defensive stats",
        })
        for c in [c for c in m.columns if c.startswith("fe_idp_")]: d[c]=r.get(c)
        added.append(d); existing.add(str(r.get("key")))
    if added:
        add=pd.DataFrame(added)
        for c in add.columns:
            if c not in b.columns: b[c]=np.nan
        for c in b.columns:
            if c not in add.columns: add[c]=np.nan
        b=pd.concat([b,add[b.columns]],ignore_index=True,sort=False)

    # Attach/refresh model values for every modeled IDP. A verified external weekly
    # projection is still useful, but the free Fantasy Edge model is always retained
    # as an independent source and can stand alone when vendor projections are absent.
    mm=m.set_index("key")
    keys=b["key"].astype(str)
    matched=keys.isin(mm.index) & b["position"].astype(str).isin(["DL","DB"])
    match_idx=b.index[matched]
    model_matches=0
    if len(match_idx):
        for c in [c for c in m.columns if c.startswith("fe_idp_")]:
            if c not in b.columns: b[c]=np.nan
            b.loc[match_idx,c]=keys.loc[match_idx].map(mm[c]).values
        if "projection_source" not in b.columns: b["projection_source"]=""
        if "projection_available" not in b.columns: b["projection_available"]=False
        for i in match_idx:
            k=str(b.at[i,"key"]); rec=mm.loc[k]
            try: b.at[i,"position"]=str(rec.get("position") or b.at[i,"position"])
            except Exception: pass
            try: b.at[i,"raw_position"]=str(rec.get("fe_idp_raw_position") or b.at[i,"raw_position"])
            except Exception: pass
            try:
                _tm=str(rec.get("team") or "").upper().strip()
                _cur=str(b.at[i,"team"] if "team" in b.columns else "").upper().strip()
                if _tm not in {"","NFL","FA","NONE","N/A","NAN"} and _cur in {"","NFL","FA","NONE","N/A","NAN"}:
                    b.at[i,"team"]=_tm
                    if "_live_team_verified" not in b.columns: b["_live_team_verified"]=0
                    b.at[i,"_live_team_verified"]=1
            except Exception: pass
            mp=float(rec.get("fe_idp_model_ppg",0) or 0)
            if mp<=0: continue
            ext=pd.to_numeric(pd.Series([b.at[i,"_external_week_projection"] if "_external_week_projection" in b.columns else np.nan]),errors="coerce").iloc[0]
            # External weekly projection gets a modest ensemble weight only when it
            # is a plausible positive value. The stat model remains the backbone so
            # IDP coverage never depends on buying a projection feed.
            if pd.notna(ext) and float(ext)>0:
                final=0.55*mp+0.45*float(ext)
                src="Fantasy Edge IDP model + Sleeper weekly projection"
            else:
                final=mp; src=str(rec.get("fe_idp_model_source") or "Fantasy Edge IDP model")
            rp=float(b.at[i,"replacement_ppg"] if "replacement_ppg" in b.columns and pd.notna(b.at[i,"replacement_ppg"]) else (6.2 if str(b.at[i,"position"])=="DL" else 5.9))
            for c in ["projection","display_projection"]:
                if c not in b.columns: b[c]=np.nan
                b.at[i,c]=float(final)
            for c in ["vorp","display_vorp"]:
                if c not in b.columns: b[c]=np.nan
                b.at[i,c]=float(final-rp)
            b.at[i,"projection_available"]=True
            b.at[i,"projection_source"]=src
            if "confidence" in b.columns:
                b.at[i,"confidence"]=max(float(pd.to_numeric(pd.Series([b.at[i,"confidence"]]),errors="coerce").fillna(0).iloc[0]),float(rec.get("fe_idp_model_confidence",0.5) or 0.5))
            model_matches+=1
    b=b.drop_duplicates("key",keep="first").reset_index(drop=True)
    b=_v1041_apply_idp_projection_contract(b)
    return b,model_matches,len(added)

@st.cache_data(ttl=86400, show_spinner="Updating NFL statistics...")
def nfl_history():
    try:
        # Use the same public nflverse CSV family as the current-role loader.
        # Fork deployments that update app.py alone do not install nflreadpy.
        years=[2023,2024,2025]
        frames=[]; failures=[]
        for year in years:
            try:
                part=_v806_weekly_stats(year)
                if part.empty: raise ValueError("empty stats file")
                if "season" not in part.columns: part["season"]=year
                frames.append(part)
            except Exception as exc:
                failures.append(f"{year}: {type(exc).__name__}: {exc}")
        if not frames:
            raise RuntimeError("Historical NFL CSV downloads failed: "+"; ".join(failures))
        raw=pd.concat(frames,ignore_index=True)
        if "season_type" in raw:
            raw=raw[raw.season_type.astype(str).str.upper().eq("REG")]

        name="player_display_name" if "player_display_name" in raw else "player_name"
        if "position" not in raw:
            return pd.DataFrame()

        # Keep offensive + defensive positions.
        allowed=["QB","RB","WR","TE","DL","DE","DT","NT","EDGE","LB","OLB","ILB","MLB","DB","CB","S","FS","SS","SAF"]
        raw=raw[raw.position.isin(allowed)].copy()
        raw["_g"]=1

        # Ensure all needed columns exist.
        offensive_cols=["passing_yards","passing_tds","interceptions","rushing_yards","rushing_tds",
                        "receptions","receiving_yards","receiving_tds","targets","carries"]
        # nflverse's current calculate_stats schema uses fumble_recovery_opp and
        # def_safeties. Keep the app's long-lived internal column names so older
        # scoring/feature code and current releases agree.
        if "def_fumble_recovery_opp" not in raw.columns and "fumble_recovery_opp" in raw.columns:
            raw["def_fumble_recovery_opp"]=raw["fumble_recovery_opp"]
        if "def_safety" not in raw.columns and "def_safeties" in raw.columns:
            raw["def_safety"]=raw["def_safeties"]
        defensive_cols=["def_tackles_solo","def_tackles_with_assist","def_tackle_assists","def_sacks","def_tackles_for_loss",
                        "def_qb_hits","def_interceptions","def_pass_defended","def_fumbles_forced",
                        "def_fumble_recovery_opp","def_tds","def_safety"]
        for c in offensive_cols+defensive_cols:
            if c not in raw: raw[c]=0

        raw["fantasy_points_ppr"]=(
            raw.passing_yards.fillna(0)/25 + raw.passing_tds.fillna(0)*4
            - raw.interceptions.fillna(0)*2 + raw.rushing_yards.fillna(0)/10
            + raw.rushing_tds.fillna(0)*6 + raw.receptions.fillna(0)
            + raw.receiving_yards.fillna(0)/10 + raw.receiving_tds.fillna(0)*6
        )

        agg={"fantasy_points_ppr":"sum","_g":"sum"}
        for c in offensive_cols+defensive_cols:
            agg[c]="sum"

        x=raw.groupby(["season",name,"position"],dropna=False).agg(agg).reset_index().rename(columns={name:"player"})
        x["games"]=x["_g"].clip(lower=1)
        if x.games.median()<=2: x["games"]=17
        x["ppr_ppg"]=x.fantasy_points_ppr/x.games
        x["key"]=x.player.map(norm)
        x["position_group"]=x["position"].map(position_group)
        return x
    except Exception as e:
        raise RuntimeError(f"NFL data provider failed: {type(e).__name__}: {e}") from e

@st.cache_data(ttl=21600, show_spinner="Updating 2026 consensus rankings...")
def market_rankings(ppr):
    """Latest FantasyPros expert-consensus rankings from DynastyProcess CSV."""
    try:
        # DynastyProcess publishes the CSV version of the same FantasyPros
        # rankings feed. Read it directly without a separately installed module.
        # Publisher recommends Parquet for Python. Column selection avoids
        # materializing the enormous historical CSV archive on a small host.
        url="https://github.com/dynastyprocess/data/raw/master/files/db_fpecr.parquet"
        payload=io.BytesIO()
        started=time.monotonic()
        with requests.get(url,stream=True,timeout=(6,12),headers={"User-Agent":"FantasyEdge/8.03"}) as response:
            response.raise_for_status()
            for chunk in response.iter_content(chunk_size=262144):
                if time.monotonic()-started>35:
                    raise TimeoutError("Consensus Parquet download exceeded 35 seconds")
                payload.write(chunk)
                if payload.tell()>64*1024*1024:
                    raise RuntimeError("Consensus Parquet exceeds 64 MB download limit")
        payload.seek(0)
        fields=["scrape_date","player","pos","ecr","page_type","fp_page","ecr_type"]
        raw=pd.read_parquet(payload,columns=fields)
        if "scrape_date" not in raw.columns:
            raise RuntimeError("Consensus archive has no scrape_date; refusing undated rankings")
        date=pd.to_datetime(raw["scrape_date"],errors="coerce",utc=True)
        if not date.notna().any():
            raise RuntimeError("Consensus archive has no valid update dates")
        raw["_scrape_dt"]=date
        raw=raw.loc[date.ge(date.max()-pd.Timedelta(days=14))].copy()
        if "page_type" in raw.columns and raw["page_type"].astype(str).str.contains("redraft",case=False).any():
            raw=raw[raw["page_type"].astype(str).str.contains("redraft",case=False)].copy()
        if raw.empty or "player" not in raw.columns or "ecr" not in raw.columns:
            return pd.DataFrame()
        raw = raw.copy()
        raw["ecr"] = pd.to_numeric(raw["ecr"], errors="coerce")
        raw = raw[raw.ecr.notna()]
        raw["key"] = raw.player.map(norm)
        raw["page"] = (raw.get("page_type", pd.Series("", index=raw.index)).fillna("").astype(str) + " " + raw.get("fp_page", pd.Series("", index=raw.index)).fillna("").astype(str)).str.lower()
        raw["etype"] = raw.get("ecr_type", pd.Series("", index=raw.index)).fillna("").astype(str).str.lower()
        raw["pos_raw"] = raw.get("pos", pd.Series("", index=raw.index)).fillna("").astype(str)

        # Prefer overall redraft pages matching league reception scoring.
        score = pd.Series(0.0, index=raw.index)
        score += raw.page.str.contains("overall", regex=False).astype(float) * 5
        score += (~raw.page.str.contains("dynasty", regex=False)).astype(float) * 2
        score += (~raw.page.str.contains("week", regex=False)).astype(float) * 2
        if ppr == 1.0:
            score += (raw.page.str.contains("ppr", regex=False) & ~raw.page.str.contains("half", regex=False)).astype(float) * 5
        elif ppr == 0.5:
            score += (raw.page.str.contains("half", regex=False)).astype(float) * 5
        else:
            score += (~raw.page.str.contains("ppr", regex=False)).astype(float) * 3
        # IDP pages are useful for defenders, but not for offensive overall rank.
        is_idp_page = raw.page.str.contains("idp", regex=False)
        raw["page_score"] = score

        raw["consensus_pos"]=raw["pos_raw"].map(position_group)
        out=[]
        for (key,cpos),g in raw.groupby(["key","consensus_pos"], dropna=False):
            defender = cpos in ["DL","DB"]
            gg = g.copy()
            if defender and is_idp_page.loc[gg.index].any():
                gg = gg[is_idp_page.loc[gg.index]]
            elif not defender:
                non_idp = ~is_idp_page.loc[gg.index]
                if non_idp.any(): gg = gg[non_idp]
            mx = gg.page_score.max()
            gg = gg[gg.page_score.eq(mx)].copy()
            # V9.82: use the newest observation for the live rank and preserve
            # same-source 24h/72h history so the decision engine can measure ECR momentum.
            gg=gg.sort_values("_scrape_dt")
            latest_dt=gg["_scrape_dt"].max()
            latest_rows=gg[gg["_scrape_dt"].eq(latest_dt)]
            row=latest_rows.sort_values("ecr").iloc[0]
            def _hist_rank(hours):
                target=latest_dt-pd.Timedelta(hours=hours)
                prior=gg[gg["_scrape_dt"].le(target)]
                if prior.empty:
                    return float("nan")
                prior_dt=prior["_scrape_dt"].max()
                return float(prior[prior["_scrape_dt"].eq(prior_dt)]["ecr"].median())
            out.append({
                "key":key,"consensus_pos":cpos,"consensus_rank":float(row.ecr),
                "consensus_rank_24h":_hist_rank(24),"consensus_rank_72h":_hist_rank(72),
                "consensus_page":row.page,"consensus_updated_at":str(latest_dt)
            })
        return pd.DataFrame(out)
    except Exception as e:
        raise RuntimeError(f"NFL data provider failed: {type(e).__name__}: {e}") from e

def position_group(pos):
    p=str(pos or "").upper().strip()
    if p in ["DE","DT","NT","EDGE","ED","DL"]: return "DL"
    if p in ["CB","S","FS","SS","SAF","DB"]: return "DB"
    if p in ["LB","ILB","MLB","WLB","SLB","OLB","LOLB","ROLB"]: return "LB"
    return p

def canonical_position(raw_pos):
    p=str(raw_pos or "").upper().strip()
    # V10.43: generic linebacker labels stay LB. A dual-eligible edge is promoted
    # only by the player-aware Yahoo slot contract, never by raw-position aliasing.
    aliases={"HB":"RB","FB":"RB","NT":"DL","DT":"DL","DE":"DL","EDGE":"DL","ED":"DL","CB":"DB","S":"DB","FS":"DB","SS":"DB","SAF":"DB"}
    return aliases.get(p,p)

def validate_position(player, pos):
    """Canonicalize the source position only; never infer position from a player's name."""
    return canonical_position(pos)


# --- Fantasy Edge v9.1 production layer (v9.08 certified) ---
V9_BOARD = APP_DIR / "production_board.csv"
V9_CONFIG = APP_DIR / "engine_config.csv"

@st.cache_data
def load_v9_production():
    """Load the certified v9.1 production board and round-specific engine weights."""
    # V6.51: the authoritative production board is embedded directly in app.py.
    # This prevents Streamlit/Fork working-directory or stale-repository CSVs from
    # silently loading an older player pool. File fallback exists only if decode fails.
    try:
        _embedded_bytes = gzip.decompress(base64.b64decode(_V651_BOARD_GZ_B64.encode("ascii")))
        pb = pd.read_csv(io.BytesIO(_embedded_bytes))
    except Exception:
        if not V9_BOARD.exists():
            return pd.DataFrame(), {"default":(16.0,2.0,.2,.5), "rounds":{}}
        pb=pd.read_csv(V9_BOARD)
    # V6.19 cornerstone pool certification: never silently ship without current
    # first/second-round anchors. This protects dropdown + recommendation pool.
    _cornerstones=["CeeDee Lamb","Kenneth Walker III","Justin Jefferson","Saquon Barkley",
                   "Brock Bowers","Ashton Jeanty","Drake London","A.J. Brown","Nico Collins",
                   "DeVonta Smith","Bo Nix","Colston Loveland","Ladd McConkey","David Montgomery","Bhayshul Tuten","Jeremiyah Love","Jadarian Price","Carnell Tate","George Kittle","Harold Fannin Jr.","Dalton Kincaid","Isaiah Likely","KC Concepcion","Jayden Reed","Matthew Golden","Jayden Higgins","Kenyon Sadiq","DJ Moore","Luther Burden III"]
    _missing_cornerstones=[_p for _p in _cornerstones if _p not in set(pb["Player"].astype(str))]
    if _missing_cornerstones:
        raise RuntimeError("Production player pool missing cornerstone players: "+", ".join(_missing_cornerstones))

    # V6.23 broader top-100 offensive universe smoke test.
    _top100_smoke=[
        "DeVonta Smith","CeeDee Lamb","Kenneth Walker III","Justin Jefferson","Saquon Barkley",
        "Brock Bowers","Drake London","A.J. Brown","Nico Collins","Rashee Rice","Malik Nabers",
        "Chris Olave","Garrett Wilson","Tee Higgins","Jaylen Waddle","Terry McLaurin",
        "Bo Nix","Colston Loveland","Ladd McConkey","David Montgomery","Bhayshul Tuten","Jeremiyah Love","Jadarian Price","Carnell Tate","George Kittle","Harold Fannin Jr.","Dalton Kincaid","Isaiah Likely","KC Concepcion","Jayden Reed","Matthew Golden","Jayden Higgins","Kenyon Sadiq","DJ Moore","Luther Burden III"
    ]
    _missing_top100=[_p for _p in _top100_smoke if _p not in set(pb["Player"].astype(str))]
    if _missing_top100:
        raise RuntimeError("Top-100 offensive player pool incomplete: "+", ".join(_missing_top100))
    pb["key"]=pb["Player"].map(norm)
    # Backward-compatible v9.1 hotfix: derive Base_live_score from certified board fields if absent.
    if "Base_live_score" not in pb.columns:
        def _z9(s):
            s=pd.to_numeric(s,errors="coerce")
            sd=s.std(ddof=0)
            return (s-s.mean())/(sd if pd.notna(sd) and sd!=0 else 1.0)
        pb["Base_live_score"]=(0.55*_z9(pb["Draft_score"])
                               +0.30*_z9(pb["VORP"])
                               +0.15*_z9(-pd.to_numeric(pb["Market_pick"],errors="coerce")))
    cfg={"default":(16.0,2.0,.2,.5), "rounds":{}}
    if V9_CONFIG.exists():
        ec=pd.read_csv(V9_CONFIG)
        vals=dict(zip(ec["Field"].astype(str),ec["Value"].astype(str)))
        def _weights(v):
            try: return tuple(float(x.strip()) for x in str(v).strip("()").split(","))
            except: return None
        d=_weights(vals.get("Default_weights"))
        if d and len(d)==4: cfg["default"]=d
        for k,v in vals.items():
            m=re.fullmatch(r"Round_(\d+)_weights",k)
            w=_weights(v)
            if m and w and len(w)==4: cfg["rounds"][int(m.group(1))]=w
    return pb,cfg

def attach_v9_production(board):
    """Attach certified player signals without disturbing the rest of the dashboard."""
    pb,_=load_v9_production()
    if pb.empty: return board
    keep=pb[["key","Market_pick","VORP","Draft_score","Model_rank","Base_live_score"]].drop_duplicates("key")
    keep=keep.rename(columns={
        "Market_pick":"v9_market_pick","VORP":"v9_vorp","Draft_score":"v9_draft_score",
        "Model_rank":"v9_model_rank","Base_live_score":"v9_base_live_score"})
    return board.merge(keep,on="key",how="left")

def v9_live_rank(avail, round_no, current_pick, roster_counts):
    """Certified v9.08 translation used by the v9.1 live draft assistant."""
    pb,cfg=load_v9_production()
    x=avail.copy()
    if pb.empty or "v9_base_live_score" not in x:
        x["v9_live_score"]=_safe_num_series(x,"draft_score",0.0)
        return x
    # Frozen champion round/player and position priors reconstructed from production board rank/timing.
    # Player identity prior is represented by the certified static base score; round overrides control
    # the dynamic translation exactly as certified in v9.08.
    pw,posw,tw,nw=cfg["rounds"].get(int(round_no),cfg["default"])
    mp=pd.to_numeric(x["v9_market_pick"],errors="coerce").fillna(pd.to_numeric(x["market_pick"],errors="coerce"))
    delta=float(current_pick)-mp
    timing=np.where(delta>=0,np.minimum(delta/18.0,1.5),np.maximum(delta/24.0,-1.5))
    base=pd.to_numeric(x["v9_base_live_score"],errors="coerce")
    fallback=(pd.to_numeric(x["draft_score"],errors="coerce").rank(pct=True)-.5)*2
    base=base.fillna(fallback)
    # Use model-rank percentile as a stable player-prior proxy for players on the certified board.
    mr=pd.to_numeric(x["v9_model_rank"],errors="coerce")
    player_prior=(1-(mr-1)/max(len(pb)-1,1)).clip(0,1).fillna(0)
    # Position prior from the currently available certified board at this round.
    pos_counts=pb["Position"].value_counts(normalize=True).to_dict()
    position_prior=x["position"].map(pos_counts).fillna(0)
    need=[]
    caps={"QB":(1,2),"RB":(2,99),"WR":(2,99),"TE":(1,2),"K":(1,1),"DL":(1,1),"DB":(1,1)}
    for p in x["position"]:
        lo,hi=caps.get(p,(0,99)); cnt=int(roster_counts.get(p,0))
        need.append(1.0 if cnt<lo else 0.0)
    x["v9_live_score"]=base+pw*player_prior+posw*position_prior+tw*timing+nw*np.asarray(need)
    x["v9_market_pick_effective"]=mp
    return x


def _v944_add_idp_display_metrics(x):
    """Add position-relative IDP metrics without overwriting raw projection/VORP/model_rank."""
    y=x.copy()
    if "idp_impact_score" not in y.columns:
        y["idp_impact_score"]=np.nan
    if "idp_external_rank" not in y.columns:
        y["idp_external_rank"]=np.nan

    y["display_projection"]=pd.to_numeric(y.get("projection",np.nan),errors="coerce")
    y["display_vorp"]=pd.to_numeric(y.get("vorp",np.nan),errors="coerce")
    y["display_model_rank"]=pd.to_numeric(y.get("model_rank",np.nan),errors="coerce")

    mask=y["position"].astype(str).str.upper().isin(["DL","DB"])
    # For IDP, show the score/rank actually used by the IDP mechanism.
    y.loc[mask,"display_projection"]=pd.to_numeric(y.loc[mask,"idp_impact_score"],errors="coerce")
    y.loc[mask,"display_vorp"]=pd.to_numeric(y.loc[mask,"roster_opportunity_adj"],errors="coerce")
    y.loc[mask,"display_model_rank"]=pd.to_numeric(y.loc[mask,"idp_external_rank"],errors="coerce")
    return y

def _marginal_roster_multiplier(pos, counts, slots):
    """How much of a player's raw value is realistically usable on this roster."""
    pos=str(pos)
    have=int(counts.get(pos,0))

    if pos=="RB":
        # RB1/RB2 starters, RB3/RB4 useful FLEX/depth, RB5+ sharply diminished.
        return [1.00,1.00,0.88,0.72,0.48,0.28,0.16][min(have,6)]
    if pos=="WR":
        # WR1/WR2 starters; WR3-WR5 remain useful in 2-FLEX; WR6+ diminished.
        return [1.00,1.00,0.92,0.82,0.68,0.46,0.28][min(have,6)]
    if pos=="TE":
        return 1.00 if have<1 else 0.38 if have==1 else 0.15
    if pos=="QB":
        return 1.00 if have<1 else 0.34 if have==1 else 0.10
    if pos=="K":
        return 1.00 if have<1 else 0.0
    if pos in ("DL","DB"):
        # Required starter is full value. First/second impact backup still useful.
        return 1.00 if have<1 else 0.78 if have==1 else 0.55 if have==2 else 0.30
    return 1.0


def _add_marginal_roster_value(x, roster, slots):
    """Add usable VORP / marginal roster value without overwriting raw VORP."""
    y=x.copy()
    counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}

    raw_vorp=_safe_num_series(y,"vorp",0.0)
    raw_proj=_safe_num_series(y,"projection",0.0)

    mult=y["position"].map(lambda p:_marginal_roster_multiplier(p,counts,slots)).astype(float)
    y["roster_value_multiplier"]=mult
    y["usable_vorp"]=raw_vorp*mult

    # Projection contributes only modestly to marginal value; VORP is primary.
    y["marginal_roster_value"]=(
        y["usable_vorp"]*2.4 +
        np.maximum(raw_proj,0.0)*0.12*mult
    )

    # Late-bench startability/upside proxy: reward candidates with enough projection
    # and usable VORP to plausibly enter the lineup; discount pure roster-cloggers.
    proj_rank=y.groupby("position")["projection"].rank(pct=True,ascending=True).fillna(0.5)
    vorp_rank=y.groupby("position")["vorp"].rank(pct=True,ascending=True).fillna(0.5)
    y["bench_startability"]=np.clip(0.55*proj_rank+0.45*vorp_rank,0.0,1.0)
    y["marginal_roster_value"]*=np.where(
        y["position"].isin(["RB","WR"]) & (mult<0.60),
        0.65+0.35*y["bench_startability"],
        1.0
    )
    return y

def _portfolio_depth_penalty(pos, counts):
    """Penalty for redundant bench concentration; starters/FLEX remain largely untouched."""
    pos=str(pos); have=int(counts.get(pos,0))
    if pos=="RB":
        return 0.0 if have<=3 else 2.0 if have==4 else 8.0 if have==5 else 14.0
    if pos=="WR":
        return 0.0 if have<=4 else 5.0 if have==5 else 10.0
    if pos=="QB":
        return 0.0 if have==0 else 7.0
    if pos=="TE":
        return 0.0 if have==0 else 6.0
    if pos=="K":
        return 0.0 if have==0 else 1000.0
    return 0.0


def _add_cross_position_bench_value(x, roster, slots):
    """Compare each deep-bench candidate to the best other-position use of that bench slot."""
    y=x.copy()
    counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    if "marginal_roster_value" not in y.columns:
        y=_add_marginal_roster_value(y,roster,slots)

    y["portfolio_depth_penalty"]=y["position"].map(lambda p:_portfolio_depth_penalty(p,counts)).astype(float)
    y["portfolio_value"]=pd.to_numeric(y["marginal_roster_value"],errors="coerce").fillna(0.0)-y["portfolio_depth_penalty"]

    # Best alternative at another position = opportunity cost of this bench slot.
    best_by_pos=y.groupby("position")["portfolio_value"].max().to_dict()
    alt=[]
    for _,row in y.iterrows():
        others=[v for p,v in best_by_pos.items() if p!=row.position and pd.notna(v)]
        alt.append(max(others) if others else 0.0)
    y["best_other_position_value"]=alt
    y["value_over_next_roster_slot"]=y["portfolio_value"]-y["best_other_position_value"]
    return y


def _benchmark_candidate_prefilter(avail, current_pick, per_position=12, overall_market=55):
    """
    Lossless-for-practical-draft benchmark prefilter:
    retain the market front plus leaders at every position by projection, VORP,
    draft score, and IDP quality. The exact production scorer chooses from this set.
    """
    if avail is None or len(avail)==0:
        return avail
    x=avail.copy()
    keep=set()

    market=_safe_num_series(x,"market_pick",999.0)
    if "consensus_rank" in x.columns:
        market=pd.to_numeric(x["consensus_rank"],errors="coerce").fillna(market)
    keep.update(market.nsmallest(min(int(overall_market),len(x))).index)

    for p in x["position"].astype(str).unique():
        pm=x["position"].astype(str).eq(p)
        xp=x.loc[pm]
        if xp.empty:
            continue
        for col,ascending in [("projection",False),("vorp",False),("draft_score",False),
                              ("idp_impact_score",False),("idp_external_rank",True)]:
            if col not in xp.columns:
                continue
            vals=pd.to_numeric(xp[col],errors="coerce")
            vals=vals.sort_values(ascending=ascending,na_position="last")
            keep.update(vals.head(min(int(per_position),len(vals))).index)

    return x.loc[x.index.isin(keep)].copy()


def prepare_user_draft_candidates(avail, roster, round_no, current_pick, slot, teams, slots, randomness):
    """Single pre-ranking pipeline used by both Live Draft Mode and Mock Draft Lab."""
    x=avail.copy()

    # Same injury/availability policy in both modes.
    if "injury_severity" in x.columns:
        x=x[pd.to_numeric(x["injury_severity"],errors="coerce").fillna(0)<3].copy()

    # V6.55: never recommend an offensive player whose displayed projection is
    # only a missing/fallback bucket. They remain searchable in the full board.
    if "projection_available" in x.columns:
        _off=x["position"].astype(str).isin(["QB","RB","WR","TE","K"])
        _has=x["projection_available"].fillna(False).astype(bool)
        x=x[(~_off)|_has].copy()

    total_rounds=exact_roster_rounds(slots)
    x=draft_eligibility(x,roster,int(round_no),int(total_rounds),slots)
    if x.empty:
        return x, None

    # V10.65 adaptive roster construction. There is no prescribed RB/WR opening.
    # The only hard requirements are the league's real starter/roster constraints;
    # everything else is a continuous marginal-value adjustment.
    counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    x["_construction_bonus"]=0.0
    _rnd=int(round_no)
    _total=max(int(total_rounds),1)
    _remaining=max(_total-_rnd+1,1)

    # Mandatory starter openings. Skill positions matter immediately; QB is allowed
    # to wait; K/IDP receive urgency only as roster-completion pressure grows.
    for _p in ["QB","RB","WR","TE","K","DL","DB"]:
        _req=int(slots.get(_p,0) or 0); _have=int(counts.get(_p,0) or 0)
        _missing=max(_req-_have,0)
        if not _missing:
            continue
        if _p in ("RB","WR","TE"):
            _b=4.0+1.0*min(_missing,2)
        elif _p=="QB":
            _b=1.5 + (2.5 if _remaining<=7 else 0.0)
        else:
            _b=0.0 if _remaining>5 else 3.5
        x.loc[x.position.eq(_p),"_construction_bonus"]+=_b

    # Two FLEX slots are real starters in this league. Until the complete RB/WR/TE
    # starter+FLEX shell exists, all three skill positions receive a modest bonus.
    _skill_have=sum(int(counts.get(_p,0) or 0) for _p in ("RB","WR","TE"))
    _skill_need=sum(int(slots.get(_p,0) or 0) for _p in ("RB","WR","TE"))+int(slots.get("FLEX",0) or 0)
    if _skill_have < _skill_need:
        x.loc[x.position.isin(["RB","WR","TE"]),"_construction_bonus"]+=2.5

    # Continuous saturation: redundant depth must beat cross-position alternatives,
    # but there is no fixed 'RB4 is bad' or 'must have 3 WR by Round 6' rule.
    for _p,_soft,_hard in [("RB",4,7),("WR",4,7),("TE",1,3),("QB",1,3)]:
        _have=int(counts.get(_p,0) or 0)
        if _have>=_soft:
            x.loc[x.position.eq(_p),"_construction_bonus"]-=2.2*(_have-_soft+1)
        if _have>=_hard:
            x.loc[x.position.eq(_p),"_construction_bonus"]-=5000.0
            x.loc[x.position.eq(_p),"deep_skill_hard_cap"]=True

    if "early_rb_surplus_blocked" not in x.columns: x["early_rb_surplus_blocked"]=False
    if "impact_idp_depth_bonus" not in x.columns: x["impact_idp_depth_bonus"]=0.0
    if "rb6_depth_penalty" not in x.columns: x["rb6_depth_penalty"]=0.0
    if "wr6_depth_penalty" not in x.columns: x["wr6_depth_penalty"]=0.0
    if "deep_skill_hard_cap" not in x.columns: x["deep_skill_hard_cap"]=False
    if "second_backup_penalty" not in x.columns: x["second_backup_penalty"]=0.0
    x["early_rb_surplus_blocked"]=False

    # Surplus-depth discipline while required slots are still open.
    _min_req,_fixed_def,_flex_extra=_minimum_required_picks_remaining(counts,slots)
    if _min_req>0:
        if int(counts.get("QB",0))>=int(slots.get("QB",1)):
            x.loc[x.position.eq("QB"),"_construction_bonus"]-=22.0
        if int(counts.get("TE",0))>=int(slots.get("TE",1)):
            x.loc[x.position.eq("TE"),"_construction_bonus"]-=18.0

        # If one required IDP position is missing, a backup at the other IDP
        # position cannot crowd it out.
        if int(counts.get("DB",0))<int(slots.get("DB",1)) and int(counts.get("DL",0))>=int(slots.get("DL",1)):
            x.loc[x.position.eq("DL"),"_construction_bonus"]-=30.0
            x.loc[x.position.eq("DB"),"_construction_bonus"]+=12.0
        if int(counts.get("DL",0))<int(slots.get("DL",1)) and int(counts.get("DB",0))>=int(slots.get("DB",1)):
            x.loc[x.position.eq("DB"),"_construction_bonus"]-=30.0
            x.loc[x.position.eq("DL"),"_construction_bonus"]+=12.0

    x["roster_need"]=x.position.map(lambda p: roster_need_for_mock(roster,p,slots))
    _sim_mode=("_sim_precomputed_idp" in x.columns and x["_sim_precomputed_idp"].fillna(False).astype(bool).all())
    _delta_cap=18 if _sim_mode else 64
    if _sim_mode and "_sim_delta_cap" in x.columns:
        _dc=pd.to_numeric(x["_sim_delta_cap"],errors="coerce").dropna()
        if len(_dc): _delta_cap=max(int(_dc.iloc[0]),6)
    x["roster_delta"]=_candidate_roster_delta_df(roster,x,slots,exact_cap=_delta_cap)

    # Fantasy Edge marginal roster value: raw VORP is not equally usable at RB6/WR6/QB2/etc.
    x=_add_marginal_roster_value(x,roster,slots)
    x=_add_cross_position_bench_value(x,roster,slots)

    next_pick=next_user_pick(int(current_pick),int(slot),int(teams),int(total_rounds))
    x,_local=v939_shared_candidate_rank(
        x,roster,int(round_no),int(current_pick),next_pick,slots,int(randomness)
    )
    return x,next_pick


def _safe_num_series(df, name, default=0.0):
    if name in df.columns:
        return pd.to_numeric(df[name], errors="coerce").fillna(float(default))
    return pd.Series(float(default), index=df.index, dtype=float)


def _position_depth_after_pick(roster, pos):
    counts = roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    counts = dict(counts)
    p = str(pos)
    counts[p] = int(counts.get(p, 0)) + 1
    return counts


def _starter_flex_improvement(pos, counts, slots):
    """Continuous lineup value; no preferred 4-RB/5-WR template."""
    p = str(pos)
    have = int(counts.get(p, 0))
    need = int(slots.get(p, 0))

    if have < need:
        return 8.0

    if p in ("RB", "WR", "TE"):
        skill_have = int(counts.get("RB", 0)) + int(counts.get("WR", 0)) + int(counts.get("TE", 0))
        skill_need = (
            int(slots.get("RB", 0)) + int(slots.get("WR", 0)) +
            int(slots.get("TE", 0)) + int(slots.get("FLEX", 0))
        )
        if skill_have < skill_need:
            return 5.0

    # Smooth marginal decline after starter/FLEX usefulness is satisfied.
    depth = max(have - need, 0)
    curves = {
        "RB": [2.8, 2.0, 1.2, 0.3, -1.5, -3.5, -5.5],
        "WR": [3.0, 2.3, 1.6, 0.8, -0.8, -2.6, -4.5],
        "TE": [1.2, -1.5, -3.5],
        "QB": [0.8, -2.0, -4.0],
        "DL": [0.8, -1.2, -4.0],
        "DB": [0.8, -1.2, -4.0],
        "K": [-100.0, -100.0],
    }
    vals = curves.get(p, [0.0])
    return float(vals[min(depth, len(vals)-1)])


def _market_survival_probability(market_pick, current_pick, next_pick):
    """
    Smooth probability that a player survives until next turn.
    < 0.2 = strong urgency, > 0.7 = likely wait.
    """
    span = max(float(next_pick) - float(current_pick), 1.0)
    margin = float(market_pick) - float(next_pick)
    # logistic centered around next_pick; 6-pick temperature keeps this smooth
    return float(1.0 / (1.0 + np.exp(-margin / 6.0)))


def _same_position_next_turn_value(x, idx, current_pick, next_pick):
    """Expected best same-position value at next turn."""
    pos = str(x.at[idx, "position"])
    pool = x[x["position"].astype(str).eq(pos)].drop(index=idx, errors="ignore").copy()
    if pool.empty:
        return 0.0, 12.0, 0.0

    evals = _safe_num_series(pool, "evaluation_score", 0.0)
    unified = _safe_num_series(pool, "unified_pick_score", 0.0)
    base = np.maximum(evals, unified)

    market = _safe_num_series(pool, "market_pick", np.nan)
    if "market_pick" not in pool.columns and "consensus_rank" in pool.columns:
        market = _safe_num_series(pool, "consensus_rank", float(next_pick)+20)
    market = market.fillna(float(next_pick)+20)

    surv = market.map(lambda mp: _market_survival_probability(mp, current_pick, next_pick))
    expected = base * surv

    if len(expected):
        j = expected.idxmax()
        next_val = float(expected.loc[j])
        raw_next = float(base.loc[j])
        best_surv = float(surv.loc[j])
    else:
        next_val = raw_next = best_surv = 0.0

    current_val = float(max(
        pd.to_numeric(pd.Series([x.at[idx, "evaluation_score"]]), errors="coerce").fillna(0).iloc[0],
        pd.to_numeric(pd.Series([x.at[idx, "unified_pick_score"]]), errors="coerce").fillna(0).iloc[0],
    ))
    loss = float(np.clip(current_val - next_val, 0.0, 14.0))
    return next_val, loss, best_surv


def _cross_position_opportunity_cost(x, idx):
    """
    Best competing use of the same roster slot across other positions.
    This is the key anti-template mechanism.
    """
    pos = str(x.at[idx, "position"])
    score = _safe_num_series(x, "unified_pick_score", 0.0)
    other = x["position"].astype(str).ne(pos)
    if not other.any():
        return 0.0
    best_other = float(score[other].max())
    mine = float(score.loc[idx])
    return float(np.clip(best_other - mine, -10.0, 14.0))


def _tier_cliff_value(x, candidate_idx):
    pos = str(x.at[candidate_idx, "position"])
    pool = x[x["position"].astype(str).eq(pos)].copy()
    if len(pool) < 2:
        return 0.0

    score = _safe_num_series(pool, "unified_pick_score", 0.0)
    pool = pool.assign(_tier_score=score).sort_values("_tier_score", ascending=False)
    loc = np.where(pool.index.to_numpy() == candidate_idx)[0]
    if len(loc) == 0:
        return 0.0
    i = int(loc[0])
    if i >= len(pool)-1:
        return 0.0
    cliff = float(pool.iloc[i]["_tier_score"] - pool.iloc[i+1]["_tier_score"])
    return float(np.clip(cliff, 0.0, 10.0))


def _future_roster_portfolio_value(pos, counts, slots):
    """
    Score the roster after the candidate is added.
    No fixed roster target; only saturation and flexibility.
    """
    after = dict(counts)
    p = str(pos)
    after[p] = int(after.get(p, 0)) + 1

    rb, wr = int(after.get("RB", 0)), int(after.get("WR", 0))
    qb, te = int(after.get("QB", 0)), int(after.get("TE", 0))
    dl, db = int(after.get("DL", 0)), int(after.get("DB", 0))
    idp = dl + db

    value = 0.0
    # Flexibility reward while still filling usable offensive depth.
    skill = rb + wr + te
    skill_required = int(slots.get("RB",0))+int(slots.get("WR",0))+int(slots.get("TE",0))+int(slots.get("FLEX",0))
    if skill <= skill_required + 2:
        value += 1.0

    # Smooth saturation penalties.
    if rb >= 5: value -= 1.3 * (rb - 4)
    if wr >= 6: value -= 1.1 * (wr - 5)
    if qb >= 2: value -= 1.8 * (qb - 1)
    if te >= 2: value -= 1.4 * (te - 1)

    # IDP: 2 is normal, 3 can be good, 4+ is poor for this 17-player format.
    if idp == 3: value += 0.4
    if idp >= 4: value -= 6.0 + 3.0 * (idp - 4)

    return float(value)


def _live_opportunity_optimizer(x, roster, slots, current_pick, next_pick, top_n=20):
    """
    Final Live/Mock optimizer:
      current player value
      + lineup improvement
      + tier cliff
      + next-turn replacement loss
      + future roster portfolio value
      - cross-position opportunity cost
      - reach risk
    """
    y = x.copy()
    if y.empty:
        return y

    counts = roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    base = _safe_num_series(y, "unified_pick_score", 0.0)

    y["opportunity_score"] = base.astype(float)
    for col in [
        "lineup_improvement_component","tier_cliff_component","replacement_loss_component",
        "next_turn_survival_component","cross_position_cost_component","future_roster_component",
        "reach_risk_component"
    ]:
        y[col] = 0.0

    market = _safe_num_series(y, "market_pick", float(next_pick)+20)
    if "market_pick" not in y.columns and "consensus_rank" in y.columns:
        market = _safe_num_series(y, "consensus_rank", float(next_pick)+20)

    serious = y.nlargest(min(int(top_n), len(y)), "opportunity_score").index

    for idx in serious:
        p = str(y.at[idx, "position"])

        lineup = _starter_flex_improvement(p, counts, slots)
        cliff = _tier_cliff_value(y, idx)
        _, replacement_loss, replacement_survival = _same_position_next_turn_value(
            y, idx, current_pick, next_pick
        )
        cross_cost = _cross_position_opportunity_cost(y, idx)
        future = _future_roster_portfolio_value(p, counts, slots)

        surv = _market_survival_probability(float(market.loc[idx]), current_pick, next_pick)
        urgency = (1.0 - surv) * 5.5

        reach = max(float(market.loc[idx]) - float(current_pick), 0.0)
        reach_risk = min(reach, 48.0) * 0.10

        y.at[idx, "lineup_improvement_component"] = lineup
        y.at[idx, "tier_cliff_component"] = cliff
        y.at[idx, "replacement_loss_component"] = replacement_loss
        y.at[idx, "next_turn_survival_component"] = surv
        y.at[idx, "cross_position_cost_component"] = cross_cost
        y.at[idx, "future_roster_component"] = future
        y.at[idx, "reach_risk_component"] = reach_risk

        y.at[idx, "opportunity_score"] += (
            lineup +
            0.85 * cliff +
            1.20 * replacement_loss +
            urgency +
            future -
            0.85 * max(cross_cost, 0.0) -
            reach_risk
        )

    # Recommendation confidence and challenger gap.
    ranked = y["opportunity_score"].sort_values(ascending=False)
    gap = float(ranked.iloc[0] - ranked.iloc[1]) if len(ranked) >= 2 else 8.0
    y["recommendation_confidence"] = np.clip(50.0 + gap * 6.5, 50.0, 99.0)
    y["challenger_gap"] = gap

    return y



def _objective_player_shortlist(x, top_n=15):
    """
    Stage 1: player-only shortlist.
    Uses projection, VORP, market value, model quality, injury/role and IDP talent.
    No roster need, saturation or bench-shape logic is allowed here.
    """
    y=x.copy()
    if y.empty:
        return y

    proj=_safe_num_series(y,"projection",0.0)
    vorp=_safe_num_series(y,"vorp",0.0)
    market=_safe_num_series(y,"market_pick",999.0)
    if "market_pick" not in y.columns and "consensus_rank" in y.columns:
        market=_safe_num_series(y,"consensus_rank",999.0)

    raw_model=_safe_num_series(y,"draft_score",0.0)
    injury=_safe_num_series(y,"injury_penalty",0.0)
    role=_safe_num_series(y,"role_score",0.0)

    pos=y["position"].astype(str)
    proj_pct=proj.groupby(pos).rank(pct=True,method="average")
    vorp_pct=vorp.groupby(pos).rank(pct=True,method="average")
    market_pct=1.0-market.rank(pct=True,method="average")
    model_pct=raw_model.rank(pct=True,method="average")
    role_pct=role.groupby(pos).rank(pct=True,method="average") if "role_score" in y.columns else pd.Series(0.5,index=y.index)

    y["player_shortlist_score"]=100.0*(
        0.34*proj_pct.fillna(0.5) +
        0.32*vorp_pct.fillna(0.5) +
        0.15*market_pct.fillna(0.5) +
        0.12*model_pct.fillna(0.5) +
        0.07*role_pct.fillna(0.5)
    ) - np.clip(injury,0,30)*1.2

    idp=pos.isin(["DL","DB"])
    if idp.any():
        impact=_safe_num_series(y,"idp_impact_score",0.0)
        tier=_safe_num_series(y,"idp_quality_tier",5.0)
        ext=_safe_num_series(y,"idp_external_rank",50.0)
        impact_pct=impact.groupby(pos).rank(pct=True,method="average")
        ext_pct=1.0-ext.groupby(pos).rank(pct=True,method="average")
        tier_support=np.clip(1.0-(tier-1.0)/4.0,0,1)
        idp_quality=100.0*(0.52*impact_pct.fillna(0.5)+0.28*tier_support+0.20*ext_pct.fillna(0.5))
        y.loc[idp,"player_shortlist_score"]=0.62*y.loc[idp,"player_shortlist_score"]+0.38*idp_quality[idp]

    keep=set(y.nlargest(min(int(top_n),len(y)),"player_shortlist_score").index.tolist())
    for p in pos.dropna().unique():
        pm=pos.eq(p)
        keep.update(y.loc[pm].nlargest(min(3,int(pm.sum())),"player_shortlist_score").index.tolist())

    y["stage1_shortlisted"]=y.index.isin(keep)
    return y


def _future_pick_value(pool, counts, slots, future_pick, prior_pick, excluded=None):
    """Expected best usable roster value at a future turn."""
    q=pool.drop(index=list(excluded or []),errors="ignore").copy()
    if q.empty:
        return 0.0, None

    market=_safe_num_series(q,"market_pick",float(future_pick)+20)
    if "market_pick" not in q.columns and "consensus_rank" in q.columns:
        market=_safe_num_series(q,"consensus_rank",float(future_pick)+20)

    base=_safe_num_series(q,"player_shortlist_score",50.0)
    survival=market.map(lambda mp:_market_survival_probability(mp,prior_pick,future_pick))

    lineup=np.asarray([
        _starter_flex_improvement(p,counts,slots)
        for p in q["position"].astype(str)
    ],dtype=float)
    future=np.asarray([
        _future_roster_portfolio_value(p,counts,slots)
        for p in q["position"].astype(str)
    ],dtype=float)

    expected=0.74*base + 2.2*lineup + 1.2*future
    expected=expected*survival.to_numpy(dtype=float)

    if not np.isfinite(expected).any():
        return 0.0,None
    i=int(np.nanargmax(expected))
    return float(expected[i]),q.index[i]


def _two_pick_rollout_value(x, idx, roster, slots, current_pick, next_pick):
    """
    Stage 2 rollout: estimate the portfolio after this pick plus the next two user turns.
    Lightweight enough for live use; only top contenders receive a rollout.
    """
    counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    p=str(x.at[idx,"position"])
    after=dict(counts)
    after[p]=int(after.get(p,0))+1

    gap=max(int(next_pick)-int(current_pick),1)
    next2=int(next_pick)+gap

    first,first_idx=_future_pick_value(
        x,after,slots,int(next_pick),int(current_pick),excluded=[idx]
    )
    after2=dict(after)
    excluded=[idx]
    if first_idx is not None:
        p2=str(x.at[first_idx,"position"])
        after2[p2]=int(after2.get(p2,0))+1
        excluded.append(first_idx)

    second,_=_future_pick_value(
        x,after2,slots,int(next2),int(next_pick),excluded=excluded
    )

    # Future picks are discounted; current selection remains authoritative.
    return float(0.34*first + 0.20*second)


def _room_run_pressure(x, current_pick, next_pick):
    """
    Adaptive draft-room pressure by position.
    If the available board is being depleted ahead of market expectation, urgency rises.
    """
    y=x.copy()
    pos=y["position"].astype(str)
    market=_safe_num_series(y,"market_pick",999.0)
    if "market_pick" not in y.columns and "consensus_rank" in y.columns:
        market=_safe_num_series(y,"consensus_rank",999.0)

    pressure=pd.Series(0.0,index=y.index,dtype=float)
    span=max(int(next_pick)-int(current_pick),1)

    for p in pos.dropna().unique():
        pm=pos.eq(p)
        if not pm.any():
            continue
        likely_before_next=((market[pm]>=float(current_pick)) & (market[pm]<float(next_pick))).sum()
        available_now=int(pm.sum())
        # More players likely to disappear before next turn => more urgency.
        pr=float(np.clip(likely_before_next/max(min(available_now,8),1),0,1))*4.5
        pressure.loc[pm]=pr
    return pressure


def _candidate_stability(y, finalists, trials=24):
    """
    Perturb projection/VORP/market slightly. Stability is how often the same candidate wins.
    Deterministic seed from candidate count keeps rerenders stable.
    """
    if len(finalists)==0:
        return pd.Series(0.0,index=y.index)
    rng=np.random.default_rng(7000+len(y))
    base=_safe_num_series(y,"final_pick_value",-1e9)
    proj=_safe_num_series(y,"projection",0.0)
    vorp=_safe_num_series(y,"vorp",0.0)
    market=_safe_num_series(y,"market_pick",999.0)
    wins={idx:0 for idx in finalists}

    for _ in range(int(trials)):
        perturb=(
            rng.normal(0,0.55,len(y)) +
            rng.normal(0,0.10,len(y))*proj.to_numpy(float) +
            rng.normal(0,0.18,len(y))*vorp.to_numpy(float) -
            rng.normal(0,0.015,len(y))*market.to_numpy(float)
        )
        vals=base.to_numpy(float)+perturb
        mask=np.array([idx in finalists for idx in y.index],dtype=bool)
        vals=np.where(mask,vals,-1e12)
        win_idx=y.index[int(np.nanargmax(vals))]
        if win_idx in wins:
            wins[win_idx]+=1

    out=pd.Series(0.0,index=y.index,dtype=float)
    for idx,n in wins.items():
        out.loc[idx]=n/max(int(trials),1)
    return out


def _two_stage_live_optimizer(x, roster, slots, current_pick, next_pick):
    """
    Player Value -> Candidate Shortlist -> Strategic Opportunity -> 2-pick Rollout
    -> Challenger Check -> FINAL PICK.
    """
    y=_objective_player_shortlist(x,top_n=15)
    if y.empty:
        return y

    # Stage 2 opportunity logic is only run on shortlisted players.
    strategic=_live_opportunity_optimizer(
        y[y["stage1_shortlisted"]].copy(),
        roster,slots,current_pick,next_pick,top_n=20
    )

    y["opportunity_score"]=-1e9
    y["rollout_value"]=0.0
    y["final_pick_value"]=-1e9
    y["recommendation_confidence"]=50.0
    y["challenger_gap"]=0.0

    for c in [
        "lineup_improvement_component","tier_cliff_component","replacement_loss_component",
        "next_turn_survival_component","cross_position_cost_component","future_roster_component",
        "reach_risk_component"
    ]:
        if c not in y.columns:
            y[c]=0.0
        if c in strategic.columns:
            y.loc[strategic.index,c]=strategic[c]

    y.loc[strategic.index,"opportunity_score"]=strategic["opportunity_score"]

    # Draft-room adaptation enters only at Stage 2.
    room_pressure=_room_run_pressure(y,current_pick,next_pick)
    y["room_run_pressure_component"]=room_pressure

    # Only the top five strategy candidates need the expensive rollout.
    finalists=strategic.nlargest(min(5,len(strategic)),"opportunity_score").index
    for idx in finalists:
        rv=_two_pick_rollout_value(y,idx,roster,slots,current_pick,next_pick)
        y.at[idx,"rollout_value"]=rv
        y.at[idx,"final_pick_value"]=(
            float(y.at[idx,"opportunity_score"])+rv+
            float(room_pressure.loc[idx])
        )

    # Non-finalists retain opportunity score but cannot beat finalists by missing rollout.
    other=strategic.index.difference(finalists)
    y.loc[other,"final_pick_value"]=y.loc[other,"opportunity_score"]

    ranked=y.loc[strategic.index,"final_pick_value"].sort_values(ascending=False)
    if len(ranked)>=2:
        gap=float(ranked.iloc[0]-ranked.iloc[1])
    else:
        gap=8.0
    # Candidate stability test: recommendations that flip under small data perturbations
    # should display lower confidence.
    stability=_candidate_stability(y,list(finalists),trials=24)
    y["candidate_stability"]=stability
    leader_stability=float(stability.loc[ranked.index[0]]) if len(ranked) else 0.0

    conf=float(np.clip(42.0+gap*4.8+leader_stability*35.0,45.0,99.0))
    y.loc[strategic.index,"recommendation_confidence"]=conf
    y.loc[strategic.index,"challenger_gap"]=gap

    # Best same-position and cross-position challenger values for auditability.
    leader=ranked.index[0] if len(ranked) else None
    y["best_same_position_challenger"]=np.nan
    y["best_cross_position_challenger"]=np.nan
    if leader is not None:
        lp=str(y.at[leader,"position"])
        same=strategic[strategic["position"].astype(str).eq(lp)].drop(index=leader,errors="ignore")
        cross=strategic[strategic["position"].astype(str).ne(lp)]
        same_v=float(y.loc[same.index,"final_pick_value"].max()) if len(same) else np.nan
        cross_v=float(y.loc[cross.index,"final_pick_value"].max()) if len(cross) else np.nan
        y.loc[strategic.index,"best_same_position_challenger"]=same_v
        y.loc[strategic.index,"best_cross_position_challenger"]=cross_v

    return y



def _base_player_value_engine(x):
    """One normalized player-value authority, independent of roster shape."""
    y=x.copy()
    pos=y["position"].astype(str)
    proj=_safe_num_series(y,"projection",0.0)
    vorp=_safe_num_series(y,"vorp",0.0)
    market=_safe_num_series(y,"market_pick",999.0)
    if "market_pick" not in y.columns and "consensus_rank" in y.columns:
        market=_safe_num_series(y,"consensus_rank",999.0)
    model=_safe_num_series(y,"draft_score",0.0)
    injury=_safe_num_series(y,"injury_penalty",0.0)

    proj_pct=proj.groupby(pos).rank(pct=True,method="average")
    vorp_pct=vorp.groupby(pos).rank(pct=True,method="average")
    market_pct=1.0-market.rank(pct=True,method="average")
    model_pct=model.rank(pct=True,method="average")

    # Projection/VORP are the primary player-quality authority.
    base=100.0*(0.40*proj_pct.fillna(.5)+0.42*vorp_pct.fillna(.5)+
                0.10*market_pct.fillna(.5)+0.08*model_pct.fillna(.5))

    # Absolute VORP anchor prevents a mediocre player from becoming a top choice
    # solely because he ranks well inside a weak positional pool.
    _abs_vorp=np.clip((vorp+2.0)/14.0,0.0,1.0)
    y["absolute_vorp_anchor"]=(_abs_vorp-0.50)*10.0
    base+=y["absolute_vorp_anchor"]
    base-=np.clip(injury,0,30)*1.25

    # IDP is position-relative: impact/tier/external rank supplement projection/VORP.
    idp=pos.isin(["DL","DB"])
    if idp.any():
        impact=_safe_num_series(y,"idp_impact_score",0.0)
        tier=_safe_num_series(y,"idp_quality_tier",5.0)
        ext=_safe_num_series(y,"idp_external_rank",50.0)
        impact_pct=impact.groupby(pos).rank(pct=True,method="average")
        ext_pct=1.0-ext.groupby(pos).rank(pct=True,method="average")
        tier_pct=np.clip(1.0-(tier-1.0)/4.0,0,1)
        idp_rel=100.0*(.48*impact_pct.fillna(.5)+.30*tier_pct+.22*ext_pct.fillna(.5))
        base.loc[idp]=.58*base.loc[idp]+.42*idp_rel.loc[idp]

    y["base_player_value"]=base
    return y


def _marginal_slot_value(pos, counts, slots):
    """Value of consuming the next roster slot; no target roster counts."""
    p=str(pos); have=int(counts.get(p,0)); req=int(slots.get(p,0))
    if have < req:
        return 9.0
    if p in ("RB","WR","TE"):
        skill=sum(int(counts.get(q,0)) for q in ("RB","WR","TE"))
        starter_skill=int(slots.get("RB",0))+int(slots.get("WR",0))+int(slots.get("TE",0))+int(slots.get("FLEX",0))
        if skill < starter_skill:
            return 5.5

    # Smooth diminishing utility only; not a prescribed roster template.
    depth=max(have-req,0)
    curve={
        # V6.8: RB5/WR5 remain legal, but their marginal utility must beat
        # genuine cross-position alternatives instead of receiving an automatic
        # positive depth bump. This is a soft value curve, not a roster target.
        "RB":[3.0,2.1,0.25,-1.4,-3.0,-4.8,-6.5],
        "WR":[3.2,2.4,0.45,-1.2,-2.8,-4.5,-6.2],
        "TE":[1.4,-1.2,-3.2],
        "QB":[1.0,-1.8,-3.8],
        "DL":[1.0,-1.0,-3.8],
        "DB":[1.0,-1.0,-3.8],
        "K":[-100.0,-100.0],
    }.get(p,[0.0])
    return float(curve[min(depth,len(curve)-1)])


def _survival_wait_cost(y, idx, current_pick, next_pick):
    """(1-P(survive)) × positional replacement drop."""
    p=str(y.at[idx,"position"])
    market=_safe_num_series(y,"market_pick",float(next_pick)+20)
    if "market_pick" not in y.columns and "consensus_rank" in y.columns:
        market=_safe_num_series(y,"consensus_rank",float(next_pick)+20)

    survive=_market_survival_probability(float(market.loc[idx]),current_pick,next_pick)
    pool=y[y["position"].astype(str).eq(p)].drop(index=idx,errors="ignore")
    mine=float(y.at[idx,"base_player_value"])
    repl=float(pool["base_player_value"].max()) if len(pool) else max(mine-12.0,0.0)
    drop=max(mine-repl,0.0)
    return float((1.0-survive)*drop), float(survive)


def _room_position_pressure(y,current_pick,next_pick):
    """Live board depletion proxy, calculated only from the current available board."""
    pos=y["position"].astype(str)
    market=_safe_num_series(y,"market_pick",float(next_pick)+20)
    if "market_pick" not in y.columns and "consensus_rank" in y.columns:
        market=_safe_num_series(y,"consensus_rank",float(next_pick)+20)
    out=pd.Series(0.0,index=y.index,dtype=float)
    for p in pos.unique():
        pm=pos.eq(p)
        soon=((market[pm]>=float(current_pick)) & (market[pm]<float(next_pick))).sum()
        depth=min(int(pm.sum()),10)
        out.loc[pm]=float(np.clip(soon/max(depth,1),0,1))*4.0
    return out


# ---------------- V10.65 championship draft intelligence ----------------
def _v1065_draft_phase(round_no, slots):
    total=max(exact_roster_rounds(slots),1)
    frac=float(round_no)/float(total)
    if frac<=0.35: return "FOUNDATION"
    if frac<=0.70: return "STARTER/FLEX BUILD"
    return "UPSIDE BENCH"


def _v1065_roster_state(roster, slots):
    counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    missing={p:max(int(slots.get(p,0) or 0)-int(counts.get(p,0) or 0),0) for p in ["QB","RB","WR","TE","K","DL","DB"]}
    skill_have=sum(int(counts.get(p,0) or 0) for p in ("RB","WR","TE"))
    skill_need=sum(int(slots.get(p,0) or 0) for p in ("RB","WR","TE"))+int(slots.get("FLEX",0) or 0)
    flex_open=max(skill_need-skill_have,0)
    labels=[]
    if missing.get("TE",0): labels.append("TE UNRESOLVED")
    if missing.get("QB",0): labels.append("QB UNRESOLVED")
    if int(counts.get("RB",0))<int(slots.get("RB",0)): labels.append("RB FRAGILE")
    if int(counts.get("WR",0))<int(slots.get("WR",0)): labels.append("WR FRAGILE")
    if flex_open>0: labels.append(f"{flex_open} FLEX/skill starter{'s' if flex_open!=1 else ''} open")
    if not labels:
        if skill_have<=skill_need+1: labels.append("BALANCED CORE")
        else: labels.append("BENCH / UPSIDE BUILD")
    return {"counts":counts,"missing":missing,"skill_have":skill_have,"skill_need":skill_need,"flex_open":flex_open,"label":" • ".join(labels)}


def _v1065_model_confidence_series(df):
    out=pd.Series(np.nan,index=df.index,dtype=float)
    for col in ["fe_off_model_confidence","fe_k_model_confidence","fe_idp_model_confidence","confidence"]:
        if col not in df.columns: continue
        v=pd.to_numeric(df[col],errors="coerce")
        v=np.where(v>1.0,v/100.0,v)
        v=pd.Series(v,index=df.index,dtype=float).clip(0,1)
        out=out.where(out.notna(),v)
    return out.fillna(0.55)


def _v1065_upside_risk(df, round_no, slots):
    proj=_safe_num_series(df,"projection",0.0).clip(lower=0.0)
    high=pd.to_numeric(df.get("fe_week_high",pd.Series(np.nan,index=df.index)),errors="coerce")
    low=pd.to_numeric(df.get("fe_week_low",pd.Series(np.nan,index=df.index)),errors="coerce")
    unc=pd.to_numeric(df.get("fe_uncertainty",pd.Series(np.nan,index=df.index)),errors="coerce")
    high=high.where(high.notna(),proj+unc.fillna(0.18*proj))
    low=low.where(low.notna(),(proj-unc.fillna(0.18*proj)).clip(lower=0.0))
    gap=(high-proj).clip(lower=0.0)
    pos=df["position"].astype(str)
    upside_pct=gap.groupby(pos).rank(pct=True,method="average").fillna(0.5)
    conf=_v1065_model_confidence_series(df)
    rel_unc=((high-low)/(2.0*proj.replace(0,np.nan))).replace([np.inf,-np.inf],np.nan).fillna(0.35).clip(0,1.5)
    risk=(0.65*rel_unc+0.35*(1.0-conf)).clip(0,1.5)
    phase=_v1065_draft_phase(round_no,slots)
    up_w={"FOUNDATION":4.0,"STARTER/FLEX BUILD":5.5,"UPSIDE BENCH":10.0}[phase]
    risk_w={"FOUNDATION":7.0,"STARTER/FLEX BUILD":5.0,"UPSIDE BENCH":2.5}[phase]
    return (upside_pct-0.5)*up_w, risk*risk_w


def _v1065_te_scarcity_component(df, idx, counts, slots, current_pick, next_pick):
    if str(df.at[idx,"position"])!="TE" or int(counts.get("TE",0))>=int(slots.get("TE",1)):
        return 0.0
    pool=df[df["position"].astype(str).eq("TE")].copy()
    if pool.empty: return 0.0
    mine=float(df.at[idx,"base_player_value"])
    others=pool.drop(index=idx,errors="ignore")
    next_best=float(others["base_player_value"].max()) if len(others) else max(mine-12.0,0.0)
    tier_gap=max(mine-next_best,0.0)
    market=float(pd.to_numeric(pd.Series([df.at[idx,"market_pick"] if "market_pick" in df.columns else np.nan]),errors="coerce").fillna(float(next_pick)+20).iloc[0])
    survive=_market_survival_probability(market,current_pick,next_pick)
    return float(np.clip(2.0+0.75*tier_gap+5.0*(1.0-survive),0.0,12.0))


def _v1065_counts_portfolio_utility(counts, slots):
    # Terminal roster-shape utility for Monte Carlo continuation. It rewards real
    # starters/FLEX completion and penalizes redundant slots without prescribing a strategy.
    val=0.0
    for p in ["QB","RB","WR","TE","K","DL","DB"]:
        have=int(counts.get(p,0)); req=int(slots.get(p,0))
        val-=5.0*max(req-have,0)
    skill=sum(int(counts.get(p,0)) for p in ("RB","WR","TE"))
    skill_need=sum(int(slots.get(p,0)) for p in ("RB","WR","TE"))+int(slots.get("FLEX",0))
    val-=3.5*max(skill_need-skill,0)
    val-=1.2*max(int(counts.get("QB",0))-1,0)
    val-=1.0*max(int(counts.get("TE",0))-1,0)
    val-=0.7*max(int(counts.get("RB",0))-5,0)
    val-=0.7*max(int(counts.get("WR",0))-5,0)
    val-=2.0*max(int(counts.get("DL",0))+int(counts.get("DB",0))-3,0)
    return float(val)

def _single_authority_strategy(y,roster,slots,round_no,current_pick,next_pick):
    """All roster/market strategy enters here, after base player value."""
    z=_base_player_value_engine(y)
    counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    room=_room_position_pressure(z,current_pick,next_pick)

    z["marginal_slot_value"]=0.0
    z["wait_cost"]=0.0
    z["survival_probability"]=0.0
    z["room_pressure"]=room
    z["strategic_pick_value"]=-1e9
    _cross_slot=np.clip(_safe_num_series(z,"value_over_next_roster_slot",0.0),-8.0,8.0)
    z["cross_slot_value"]=_cross_slot
    _market_raw=_safe_num_series(z,"market_pick",float(current_pick)+12.0)
    _model_market=pd.to_numeric(z["model_rank"],errors="coerce").fillna(_market_raw) if "model_rank" in z.columns else _market_raw.copy()
    _offense=~z["position"].astype(str).isin(["DL","DB","K"])
    _market=_market_raw.copy()
    _market.loc[_offense]=0.90*_market_raw.loc[_offense]+0.10*_model_market.loc[_offense]
    _reach_ahead=np.maximum(_market-float(current_pick)-6.0,0.0)
    _reach_cost=np.minimum(_reach_ahead,45.0)*0.58
    z["strategic_reach_cost"]=_reach_cost
    _ropp=_safe_num_series(z,"roster_opportunity_adj",0.0)
    _late_factor=0.0 if int(round_no)<=10 else min(2.0,0.35*(int(round_no)-10))
    _late_negative_cost=np.maximum(-_ropp-1.0,0.0)*(1.2+_late_factor)
    z["late_roster_opp_cost"]=_late_negative_cost

    # Prospective Draft-Value economics: reward players available at/after market
    # and charge for reaches. This mirrors the benchmark's realized value economics
    # so the optimizer improves the metric rather than learning about it afterward.
    _market_delta=float(current_pick)-_market
    _market_value_component=pd.Series(
        np.where(
            _market_delta>=0.0,
            np.minimum(_market_delta,30.0)*0.28,
            np.maximum(_market_delta,-28.0)*0.68
        ),
        index=z.index,dtype=float
    )
    z["prospective_market_value"]=_market_value_component

    # Direct opportunity-loss estimate. Negative roster opportunity and being
    # inferior to another-position bench use are charged before rollout.
    _cross_loss=np.maximum(-_cross_slot,0.0)
    _opp_loss=np.maximum(-_ropp,0.0)
    _prospective_opp_cost=1.15*_opp_loss + 0.85*_cross_loss
    z["prospective_opportunity_cost"]=_prospective_opp_cost

    # Explicit player-quality anchor used by FINAL PICK.
    _qvorp=_safe_num_series(z,"vorp",0.0).rank(pct=True,method="average")
    _qproj=_safe_num_series(z,"projection",0.0).groupby(z["position"].astype(str)).rank(pct=True,method="average")
    _quality_anchor=10.0*(0.68*_qvorp.fillna(.5)+0.32*_qproj.fillna(.5)-0.50)
    z["final_quality_anchor"]=_quality_anchor

    # Preserve the roster-construction work produced by prepare_user_draft_candidates.
    _construction_context=np.clip(_safe_num_series(z,"_construction_bonus",0.0),-30.0,18.0)
    z["final_construction_context"]=_construction_context

    # V10.65 native ceiling/risk and actual lineup-delta authority. Early rounds
    # prioritize bankable quality, middle rounds complete starters/FLEX, and late
    # rounds increasingly reward asymmetric bench upside.
    _upside_component,_risk_component=_v1065_upside_risk(z,int(round_no),slots)
    _lineup_delta=np.clip(_safe_num_series(z,"roster_delta",0.0),-4.0,8.0)
    _phase=_v1065_draft_phase(int(round_no),slots)
    _lineup_w={"FOUNDATION":0.60,"STARTER/FLEX BUILD":1.15,"UPSIDE BENCH":0.55}[_phase]
    _upside_w={"FOUNDATION":0.75,"STARTER/FLEX BUILD":0.90,"UPSIDE BENCH":1.35}[_phase]
    z["draft_phase"]=_phase
    z["starter_lineup_delta_component"]=_lineup_delta*_lineup_w
    z["draft_upside_component"]=_upside_component*_upside_w
    z["draft_risk_cost"]=_risk_component
    z["te_scarcity_component"]=0.0

    # V6.8 adaptive portfolio regret. This is deliberately soft: it never blocks
    # a position. It simply makes the next redundant bench slot pay for the
    # opportunity it consumes, allowing a truly superior RB5/WR5/QB2/TE2 to win.
    def _portfolio_regret_for_pos(_p):
        _p=str(_p); _have=int(counts.get(_p,0))
        if _p in ("RB","WR"):
            _other="WR" if _p=="RB" else "RB"
            if _have < 4:
                return 0.0
            _pen=2.25 + 1.65*max(_have-4,0)
            if int(counts.get(_other,0)) <= 3:
                _pen += 1.25
            return float(_pen)
        if _p=="QB" and _have>=1:
            return 2.2 if int(round_no)<=11 else 1.0
        if _p=="TE" and _have>=1:
            return 2.0 if int(round_no)<=11 else 0.9
        if _p in ("DL","DB") and (int(counts.get("DL",0))+int(counts.get("DB",0)))>=2:
            return 1.0
        return 0.0
    z["portfolio_regret_cost"]=z["position"].map(_portfolio_regret_for_pos).astype(float)

    # Candidate pool: best overall plus best at every position.
    keep=set(z.nlargest(min(15,len(z)),"base_player_value").index)
    for p in z["position"].astype(str).unique():
        pm=z["position"].astype(str).eq(p)
        keep.update(z.loc[pm].nlargest(min(3,int(pm.sum())),"base_player_value").index)
    z["single_authority_shortlist"]=z.index.isin(keep)

    for idx in keep:
        p=str(z.at[idx,"position"])
        marginal=_marginal_slot_value(p,counts,slots)
        wait,survive=_survival_wait_cost(z,idx,current_pick,next_pick)

        # IDP extras receive no special bonus. Required DL/DB receive ordinary starter value.
        idp_total=int(counts.get("DL",0))+int(counts.get("DB",0))
        idp_pen=0.0
        if p in ("DL","DB") and idp_total>=3:
            idp_pen=100.0  # roster-size guard only

        z.at[idx,"marginal_slot_value"]=marginal
        z.at[idx,"wait_cost"]=wait
        z.at[idx,"survival_probability"]=survive
        _te_scarcity=_v1065_te_scarcity_component(z,idx,counts,slots,current_pick,next_pick)
        z.at[idx,"te_scarcity_component"]=_te_scarcity
        z.at[idx,"strategic_pick_value"]=(
            float(z.at[idx,"base_player_value"])+
            2.0*marginal+
            1.35*wait+
            float(room.loc[idx])+
            1.70*float(_cross_slot.loc[idx])+
            1.15*float(_quality_anchor.loc[idx])+
            0.45*float(_construction_context.loc[idx])+
            float(z.at[idx,"starter_lineup_delta_component"])+
            float(z.at[idx,"draft_upside_component"])+
            float(_te_scarcity)+
            float(_market_value_component.loc[idx])-
            float(_reach_cost.loc[idx])-
            float(_late_negative_cost.loc[idx])-
            float(_prospective_opp_cost.loc[idx])-
            float(z.at[idx,"draft_risk_cost"])-
            float(z.at[idx,"portfolio_regret_cost"])-
            idp_pen
        )
    _rs=_v1065_roster_state(roster,slots)
    z["draft_roster_state"]=_rs["label"]
    z["draft_flex_open"]=_rs["flex_open"]
    return z


def _branch_future_value(y,counts,slots,from_pick,to_pick,excluded,rng):
    """One lightweight stochastic future-board branch; vectorized for benchmark speed."""
    q=y.drop(index=list(excluded),errors="ignore")
    if q.empty:
        return 0.0,None

    market=_safe_num_series(q,"market_pick",float(to_pick)+20).to_numpy(dtype=float)
    if "market_pick" not in q.columns and "consensus_rank" in q.columns:
        market=_safe_num_series(q,"consensus_rank",float(to_pick)+20).to_numpy(dtype=float)
    base=_safe_num_series(q,"base_player_value",0.0).to_numpy(dtype=float)

    # Exact same logistic survival equation as _market_survival_probability, vectorized.
    margin=market-float(to_pick)
    probs=1.0/(1.0+np.exp(-margin/6.0))
    alive=rng.random(len(q)) < probs
    if not alive.any():
        alive[int(np.nanargmax(probs))]=True

    positions=q["position"].astype(str).to_numpy()
    unique_pos=np.unique(positions)
    marginal_map={p:2.0*_marginal_slot_value(p,counts,slots) for p in unique_pos}
    marginal=np.fromiter((marginal_map[p] for p in positions),dtype=float,count=len(positions))

    utility=base+marginal
    utility=np.where(alive,utility,-1e9)
    j=int(np.nanargmax(utility))
    return float(utility[j]),q.index[j]



def _multi_branch_rollout(y,idx,roster,slots,current_pick,next_pick,branches=18):
    """Monte Carlo continuation through the next three user turns.

    The simulation asks what the rest of the roster is likely to look like after
    taking each serious candidate now. It uses market survival, player value,
    marginal roster utility, and terminal roster construction rather than a fixed
    Zero-RB/Hero-RB/WR-heavy template.
    """
    counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    p=str(y.at[idx,"position"])
    counts=dict(counts); counts[p]=int(counts.get(p,0))+1
    gap=max(int(next_pick)-int(current_pick),1)
    turns=[int(next_pick),int(next_pick)+gap,int(next_pick)+2*gap]
    rng=np.random.default_rng(106500+int(current_pick)*17+int(idx)%997)
    vals=[]
    for _ in range(int(branches)):
        cc=dict(counts); excluded=[idx]; total=0.0
        prev=int(current_pick)
        for weight,tp in zip((0.31,0.18,0.10),turns):
            vv,jj=_branch_future_value(y,cc,slots,prev,tp,excluded,rng)
            total+=weight*vv
            if jj is not None:
                pp=str(y.at[jj,"position"]); cc[pp]=int(cc.get(pp,0))+1; excluded.append(jj)
            prev=tp
        total+=0.18*_v1065_counts_portfolio_utility(cc,slots)
        vals.append(total)
    return float(np.mean(vals)) if vals else 0.0


def _v610_take_now_wait_score(y, idx, current_pick, next_pick):
    """Expected advantage of taking a player now instead of waiting one turn.

    Positive = take-now urgency. Negative = value is likely replaceable/waitable.
    Uses market survival plus same-position replacement value, so this is a
    forward-looking decision term rather than a generic reach penalty.
    """
    if next_pick is None or int(next_pick) <= int(current_pick):
        return 0.0
    # V6.11 snake-turn correctness: when our next selection is immediately
    # adjacent, no opponent can take the player between our two picks. Do not
    # manufacture take-now urgency from stale market ADP in that zero-opponent gap.
    if int(next_pick)-int(current_pick) <= 1:
        return 0.0
    market=_safe_num_series(y,"market_pick",float(next_pick)+20.0)
    if "market_pick" not in y.columns and "consensus_rank" in y.columns:
        market=_safe_num_series(y,"consensus_rank",float(next_pick)+20.0)
    survive=_market_survival_probability(float(market.loc[idx]),current_pick,next_pick)
    mine=float(y.at[idx,"base_player_value"]) if "base_player_value" in y.columns else float(_safe_num_series(y,"unified_pick_score",0.0).loc[idx])
    pool=y[y["position"].astype(str).eq(str(y.at[idx,"position"]))].drop(index=idx,errors="ignore")
    if len(pool):
        pv=_safe_num_series(pool,"base_player_value",0.0)
        repl=float(pv.max())
    else:
        repl=max(mine-10.0,0.0)
    replacement_drop=max(mine-repl,0.0)
    # If likely gone, lock in the unique value. If likely to survive, waiting has value.
    urgency=(1.0-survive)*(1.6+0.85*replacement_drop)
    wait_credit=survive*min(max(float(market.loc[idx])-float(current_pick),0.0),30.0)*0.055
    # Onesie positions are especially costly to reach on when the market projects
    # survival to our next turn; preserve capital for RB/WR/FLEX value instead.
    p=str(y.at[idx,"position"])
    onesie_wait=0.0
    if p in ("QB","TE") and float(market.loc[idx]) >= float(next_pick)-2.0:
        onesie_wait=2.4*survive
    return float(np.clip(urgency-wait_credit-onesie_wait,-4.0,8.0))


def _v610_dynamic_bench_competition(y, idx, roster, slots):
    """Make every optional bench slot compete across positions on usable value."""
    counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    p=str(y.at[idx,"position"])
    have=int(counts.get(p,0)); need=int(slots.get(p,0))
    # Required starters are handled by construction/lineup logic, not bench competition.
    is_optional=have>=need
    if p in ("RB","WR","TE"):
        skill_have=sum(int(counts.get(q,0)) for q in ("RB","WR","TE"))
        skill_need=sum(int(slots.get(q,0)) for q in ("RB","WR","TE"))+int(slots.get("FLEX",0))
        if skill_have < skill_need:
            is_optional=False
    if not is_optional:
        return 0.0

    mrv=_safe_num_series(y,"marginal_roster_value",0.0)
    cross=_safe_num_series(y,"cross_position_bench_value",0.0)
    vorp=_safe_num_series(y,"vorp",0.0)
    mine=0.58*float(mrv.loc[idx])+0.27*float(cross.loc[idx])+0.15*float(vorp.loc[idx])
    optional=[]
    for j in y.index:
        q=str(y.at[j,"position"]); qhave=int(counts.get(q,0)); qneed=int(slots.get(q,0))
        qopt=qhave>=qneed
        if q in ("RB","WR","TE"):
            sh=sum(int(counts.get(k,0)) for k in ("RB","WR","TE"))
            sn=sum(int(slots.get(k,0)) for k in ("RB","WR","TE"))+int(slots.get("FLEX",0))
            if sh < sn: qopt=False
        if qopt:
            optional.append(0.58*float(mrv.loc[j])+0.27*float(cross.loc[j])+0.15*float(vorp.loc[j]))
    best=max(optional) if optional else mine
    gap=mine-best
    # Reward the best optional use; punish redundant depth that loses clearly.
    return float(np.clip(0.75*gap,-6.0,3.0))


def _v610_roster_regret_audit(roster, slots):
    """Post-draft harmful-decision audit used by certification/champion scoring."""
    if roster is None or len(roster)==0:
        return {"harmful_regret_count":99,"major_reach_count":99,"early_backup_count":99,"starter_vorp":0.0,"bench_upside":0.0}
    r=roster.copy()
    for c in ["vorp","projection","consensus_rank","mock_pick","marginal_roster_value"]:
        if c not in r.columns: r[c]=np.nan
        r[c]=pd.to_numeric(r[c],errors="coerce")
    reaches=(r["consensus_rank"]-r["mock_pick"]).fillna(0.0)
    raw_major=int((reaches>24).sum())
    if "avoidable_reach" in r.columns:
        avoid=r["avoidable_reach"].fillna(False).astype(bool)
    else:
        avoid=pd.Series(True,index=r.index,dtype=bool)
    major=int(((reaches>24) & avoid).sum())
    harmful=int(((reaches>18) & avoid & (r["vorp"].fillna(0)<2.0)).sum())
    early_backup=0
    for p in ("QB","TE"):
        q=r[r.position.astype(str).eq(p)].sort_values("mock_pick")
        if len(q)>=2 and float(q.iloc[1]["mock_pick"])<120:
            early_backup+=1; harmful+=1
    req={"QB":int(slots.get("QB",1)),"RB":int(slots.get("RB",2)),"WR":int(slots.get("WR",2)),"TE":int(slots.get("TE",1)),"K":int(slots.get("K",1)),"DL":int(slots.get("DL",1)),"DB":int(slots.get("DB",1))}
    used=set(); starter_vorp=0.0
    for p,n in req.items():
        if n<=0: continue
        idx=r[r.position.astype(str).eq(p)]["vorp"].fillna(0).nlargest(n).index
        used.update(idx.tolist()); starter_vorp+=float(r.loc[idx,"vorp"].fillna(0).sum())
    flex_pool=r.loc[~r.index.isin(used) & r.position.astype(str).isin(["RB","WR","TE"]),"vorp"].fillna(0)
    flex_n=int(slots.get("FLEX",0)); flex_idx=flex_pool.nlargest(flex_n).index
    used.update(flex_idx.tolist()); starter_vorp+=float(r.loc[flex_idx,"vorp"].fillna(0).sum())
    bench=r.loc[~r.index.isin(used)].copy()
    bench_upside=float(np.clip(bench["vorp"].fillna(0).clip(-2,10).sum(),-10,60))
    return {"harmful_regret_count":int(harmful),"major_reach_count":int(major),"raw_major_reach_count":int(raw_major),"early_backup_count":int(early_backup),"starter_vorp":float(starter_vorp),"bench_upside":bench_upside}


def _v610_champion_score(result):
    """Multi-objective promotion score. Legality/construction are non-negotiable."""
    if not bool(result.get("legal_roster",False)) or float(result.get("construction",0))<99.999:
        return -1000.0
    return float(
        0.28*float(result.get("model_edge",0))+
        0.25*float(result.get("draft_value",0))+
        0.20*float(result.get("positional_advantage",0))+
        0.12*float(result.get("grade",0))+
        0.08*min(float(result.get("starter_vorp",0)),70.0)+
        0.03*min(float(result.get("bench_upside",0)),30.0)-
        1.10*float(result.get("opportunity_penalty",0))-
        1.75*float(result.get("harmful_regret_count",0))-
        0.75*float(result.get("major_reach_count",0))
    )


def _single_authority_final(y,roster,slots,round_no,current_pick,next_pick,compute_stability=True,rollout_branches=18,rollout_contenders=5):
    """
    Single source of truth:
    Base Player Value -> Strategic Pick Value -> multi-branch rollout
    -> regret/challenger test -> FINAL PICK.
    """
    z=_single_authority_strategy(y,roster,slots,int(round_no),current_pick,next_pick)
    contenders=z[z["single_authority_shortlist"]].nlargest(min(max(int(rollout_contenders),1),int(z["single_authority_shortlist"].sum())),"strategic_pick_value").index

    z["rollout_value"]=0.0
    z["final_pick_value"]=z["strategic_pick_value"]
    for idx in contenders:
        rv=_multi_branch_rollout(z,idx,roster,slots,current_pick,next_pick,branches=max(int(rollout_branches),1))
        z.at[idx,"rollout_value"]=rv
        z.at[idx,"final_pick_value"]=float(z.at[idx,"strategic_pick_value"])+rv

    # V6.8 Tested Regret Winner: regret now changes FINAL PICK. For each serious
    # candidate, measure the value package sacrificed at another position when
    # that challenger is unlikely to survive the turn. This prevents rollout/timing
    # from selecting redundant depth unless the player advantage really clears it.
    z["challenger_regret_cost"]=0.0
    z["take_now_wait_component"]=0.0
    z["dynamic_bench_component"]=0.0
    _short=z["single_authority_shortlist"].fillna(False).astype(bool)
    _mrv=_safe_num_series(z,"marginal_roster_value",0.0)
    _vorp=_safe_num_series(z,"vorp",0.0)
    _ropp2=_safe_num_series(z,"roster_opportunity_adj",0.0)
    _market2=_safe_num_series(z,"market_pick",float(current_pick)+20.0)
    for _idx in list(z.index[_short]):
        _p=str(z.at[_idx,"position"])
        _alts=_short & (~z["position"].astype(str).eq(_p))
        if not bool(_alts.any()):
            continue
        _alt_idx=z.loc[_alts,"strategic_pick_value"].idxmax()
        _mrv_gap=max(float(_mrv.loc[_alt_idx]-_mrv.loc[_idx]),0.0)
        _vorp_gap=max(float(_vorp.loc[_alt_idx]-_vorp.loc[_idx]),0.0)
        _ropp_gap=max(float(_ropp2.loc[_alt_idx]-_ropp2.loc[_idx]),0.0)
        _alt_survive=_market_survival_probability(float(_market2.loc[_alt_idx]),current_pick,next_pick)
        _urgency=0.35+0.65*(1.0-float(_alt_survive))
        _depth_mult=1.0
        _have=int((roster.position.astype(str)==_p).sum()) if roster is not None and len(roster) else 0
        if _p in ("RB","WR") and _have>=4: _depth_mult=1.35
        elif _p in ("QB","TE") and _have>=1: _depth_mult=1.15
        _cost=_depth_mult*_urgency*(0.70*_mrv_gap+0.45*_vorp_gap+0.30*_ropp_gap)
        z.at[_idx,"challenger_regret_cost"]=float(np.clip(_cost,0.0,12.0))
        z.at[_idx,"take_now_wait_component"]=_v610_take_now_wait_score(z,_idx,current_pick,next_pick)
        z.at[_idx,"dynamic_bench_component"]=_v610_dynamic_bench_competition(z,_idx,roster,slots)
    z.loc[_short,"final_pick_value"]=(
        z.loc[_short,"final_pick_value"]
        - z.loc[_short,"challenger_regret_cost"]
        + 0.35*z.loc[_short,"take_now_wait_component"]
        + 0.30*z.loc[_short,"dynamic_bench_component"]
    )

    ranked=z.loc[_short,"final_pick_value"].sort_values(ascending=False)
    gap=float(ranked.iloc[0]-ranked.iloc[1]) if len(ranked)>=2 else 10.0
    z["expected_regret"]=0.0
    if len(ranked):
        best=float(ranked.iloc[0])
        z.loc[ranked.index,"expected_regret"]=best-z.loc[ranked.index,"final_pick_value"]

    # Stability uses the same final authority.
    finalists=list(contenders)
    if compute_stability:
        stability=_candidate_stability(z,finalists,trials=24)
        lead_stab=float(stability.loc[ranked.index[0]]) if len(ranked) else 0.0
    else:
        # Stability only changes displayed confidence; it never changes FINAL PICK.
        stability=pd.Series(0.0,index=z.index,dtype=float)
        lead_stab=0.0
    z["candidate_stability"]=stability
    z["challenger_gap"]=gap
    z["recommendation_confidence"]=float(np.clip(42.0+4.5*gap+35.0*lead_stab,45,99))
    return z


def v939_shared_candidate_rank(avail, roster, round_no, current_pick, next_pick, slots, randomness=6):
    """One authoritative scoring pipeline for Draft Mode and Mock Draft Lab."""
    # On the user's final draft turn there is no future snake pick. Normalize None
    # to the current pick so wait/survival urgency becomes effectively neutral.
    if next_pick is None:
        next_pick=int(current_pick)
    else:
        next_pick=int(next_pick)
    x=avail.copy()
    counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}

    # V6.32 QB draft-day role guard. The production board contains historical/depth
    # quarterbacks that are useful for data continuity but must never surface as
    # DRAFT NOW / VALUE FALLER candidates in a 1-QB live draft when they do not own
    # a viable 2026 starting role. Keep the block centralized here so Draft Mode and
    # Mock Draft Lab use identical eligibility.
    _qb_nonstarter_block = {
        "Carson Wentz", "Michael Pratt", "Derek Carr", "Diego Pavia"
    }
    if "player" in x.columns:
        _player_name = x["player"].astype(str)
    elif "Player" in x.columns:
        _player_name = x["Player"].astype(str)
    else:
        _player_name = pd.Series("", index=x.index, dtype=str)
    _qb_role_block = x["position"].astype(str).str.upper().eq("QB") & _player_name.isin(_qb_nonstarter_block)
    x["qb_role_blocked"] = _qb_role_block
    if _qb_role_block.any():
        x = x.loc[~_qb_role_block].copy()

    # Compute IDP evidence first so all downstream gates can use it.
    _idp_mask=x["position"].astype(str).str.upper().isin(["DL","DB"])
    _reuse_sim_idp=(
        "_sim_precomputed_idp" in x.columns and
        bool(x["_sim_precomputed_idp"].fillna(False).astype(bool).all()) and
        all(_c in x.columns for _c in ["idp_impact_score","idp_external_rank","idp_eligible","idp_quality_tier"])
    )
    if not _reuse_sim_idp:
        x["idp_impact_score"]=np.nan
        x["idp_external_rank"]=np.nan
        x["idp_eligible"]=pd.Series(pd.NA,index=x.index,dtype="boolean")
    else:
        x["idp_eligible"]=x["idp_eligible"].fillna(False).astype("boolean")
    x["roster_completion_blocked"]=False
    x["extra_idp_blocked"]=False
    x["deep_offense_blocked_for_idp"]=False
    x["bench_diversification_blocked"]=False
    x["extra_idp_opportunity_loss"]=False

    if _idp_mask.any() and not _reuse_sim_idp:
        _idp_rows=x.loc[_idp_mask]
        _idp_scores=_idp_rows.apply(_v935_idp_impact_score,axis=1)
        x.loc[_idp_mask,"idp_impact_score"]=[v[0] for v in _idp_scores]
        x.loc[_idp_mask,"idp_eligible"]=pd.Series(
            [bool(v[1]) for v in _idp_scores],
            index=_idp_rows.index,dtype="boolean"
        )
        x.loc[_idp_mask,"idp_external_rank"]=_idp_rows.apply(_v936_external_idp_rank,axis=1)
    _overlay=x.get("id",pd.Series("",index=x.index)).astype(str).str.match(r"^v9\d+:")
    _er=pd.to_numeric(x["idp_external_rank"],errors="coerce")
    _fb=((_overlay & x["position"].eq("DL") & _er.notna() & (_er<=15)) |
         (_overlay & x["position"].eq("DB") & _er.notna() & (_er<=20)))
    x.loc[_fb,"idp_eligible"]=pd.Series(True,index=x.index[_fb],dtype="boolean")
    _floor=np.where(x["position"].eq("DL"),np.maximum(5.5,16.0-_er*0.60),np.maximum(5.0,14.0-_er*0.42))
    _cur=pd.to_numeric(x["idp_impact_score"],errors="coerce").fillna(0)
    x.loc[_fb,"idp_impact_score"]=np.maximum(_cur[_fb],_floor[_fb])
    x["idp_consensus_fallback"]=_fb
    if not _reuse_sim_idp:
        x["idp_quality_tier"]=np.nan
        x["idp_quality_evidence"]=np.nan
        if _idp_mask.any():
            _q=x.loc[_idp_mask].apply(_v941_idp_quality,axis=1)
            x.loc[_idp_mask,"idp_quality_tier"]=[v[0] for v in _q]
            x.loc[_idp_mask,"idp_quality_evidence"]=[v[1] for v in _q]
    elif "idp_quality_evidence" not in x.columns:
        x["idp_quality_evidence"]=np.nan

    # IDP quality is computed above. Extra-IDP timing is decided only by the
    # two-stage opportunity/rollout optimizer below; no pre-score IDP bonus is applied here.
    x=v9_live_rank(x,int(round_no),int(current_pick),counts)
    x["evaluation_score"]=pd.to_numeric(x["v9_live_score"],errors="coerce").fillna(-1e9)
    x["evaluation_score"]-=_safe_num_series(x,"injury_penalty",0.0)

    # Stage-1 player evaluation stays roster-agnostic.
    # Roster construction, saturation and cross-position opportunity are handled
    # only by the final two-stage optimizer below.

    x=roster_opportunity_adjustment(x,roster,int(round_no),int(current_pick),slots)
    # Do not inject roster opportunity into Stage-1 player quality.
    x=apply_v931_idp_opportunity_gate(x,roster,int(round_no))
    x=apply_v932_exact_league_construction(x,roster,int(round_no),exact_roster_rounds(slots),slots)

    # Hard roster-completion authority. This is the final safety layer used by
    # both Live Draft and Mock Draft Lab.
    _rounds=exact_roster_rounds(slots)
    _counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    _min_now,_,_=_minimum_required_picks_remaining(_counts,slots)
    _picks_left=int(_rounds)-int(round_no)+1

    if _min_now>0:
        _after_min=[]
        for _p in x["position"].astype(str):
            _after=dict(_counts)
            _after[_p]=int(_after.get(_p,0))+1
            _m,_,_=_minimum_required_picks_remaining(_after,slots)
            _after_min.append(_m)
        x["minimum_required_after_pick"]=_after_min

        _remaining_after=max(int(_rounds)-int(round_no),0)
        _strands=pd.to_numeric(x["minimum_required_after_pick"],errors="coerce")>_remaining_after
        x.loc[_strands,"evaluation_score"]-=5000.0
        x.loc[_strands,"roster_completion_blocked"]=True

        if _picks_left<=_min_now:
            _does_not_reduce=pd.to_numeric(x["minimum_required_after_pick"],errors="coerce")>=_min_now
            x.loc[_does_not_reduce,"evaluation_score"]-=5000.0
            x.loc[_does_not_reduce,"roster_completion_blocked"]=True

    # Deep-offense vs impact-IDP competition is handled continuously by the
    # final opportunity optimizer; no non-legality hard block is applied here.

    # V6.9 cost-aware same-position Pareto dominance.
    # Quality authority must not hard-block a cheaper market option merely because
    # a slightly better player exists 15-25 picks later. A player is hard-dominated
    # only when the superior same-position alternative is also similarly priced.
    _proj_all=pd.to_numeric(x.get("projection",np.nan),errors="coerce")
    _vorp_all=pd.to_numeric(x.get("vorp",np.nan),errors="coerce")
    _market_all=_safe_num_series(x,"market_pick",999.0)
    if "market_pick" not in x.columns and "consensus_rank" in x.columns:
        _market_all=_safe_num_series(x,"consensus_rank",999.0)
    x["same_pos_dominated"]=False
    x["same_pos_soft_dominated"]=False
    x["same_pos_quality_gap"]=0.0

    for _p in ("QB","RB","WR","TE"):
        _idxp=list(x.index[x["position"].eq(_p)])
        if len(_idxp)<2:
            continue
        for _i in _idxp:
            _pi=float(_proj_all.loc[_i]) if pd.notna(_proj_all.loc[_i]) else -np.inf
            _vi=float(_vorp_all.loc[_i]) if pd.notna(_vorp_all.loc[_i]) else -np.inf
            _mi=float(_market_all.loc[_i]) if pd.notna(_market_all.loc[_i]) else 999.0
            _others=[j for j in _idxp if j!=_i]
            _dom=[]
            for _j in _others:
                _pj=float(_proj_all.loc[_j]) if pd.notna(_proj_all.loc[_j]) else -np.inf
                _vj=float(_vorp_all.loc[_j]) if pd.notna(_vorp_all.loc[_j]) else -np.inf
                if (_pj>=_pi and _vj>=_vi and ((_pj-_pi)>=0.20 or (_vj-_vi)>=0.20)):
                    _dom.append(_j)
            if not _dom:
                continue
            _best=max(_dom,key=lambda j:(float(_vorp_all.loc[j])+0.4*float(_proj_all.loc[j])))
            _gap=max(0.0,float(_proj_all.loc[_best])-_pi)*1.5 + max(0.0,float(_vorp_all.loc[_best])-_vi)*2.5
            x.at[_i,"same_pos_quality_gap"]=_gap
            _dm=float(_market_all.loc[_best]) if pd.notna(_market_all.loc[_best]) else 999.0
            if _dm <= _mi + 8.0:
                x.at[_i,"same_pos_dominated"]=True
                x.at[_i,"evaluation_score"]-=min(40.0,8.0+2.0*_gap)
            else:
                # Dominator is materially more expensive/later: keep the cheaper
                # player eligible and apply only a bounded quality tax.
                x.at[_i,"same_pos_soft_dominated"]=True
                x.at[_i,"evaluation_score"]-=min(6.0,1.25*_gap)

    # v9.50 RB quality authority: among available RBs, projection and VORP carry
    # more weight than ADP/faller noise. This is rank-relative and player-agnostic.
    _rb=x["position"].eq("RB")
    if _rb.any():
        _rp=pd.to_numeric(x.loc[_rb,"projection"],errors="coerce")
        _rv=pd.to_numeric(x.loc[_rb,"vorp"],errors="coerce")
        _proj_pct=_rp.rank(pct=True,method="average")
        _vorp_pct=_rv.rank(pct=True,method="average")
        _rb_quality=(0.42*_proj_pct + 0.58*_vorp_pct)
        x.loc[_rb,"rb_quality_score"]=_rb_quality*100.0
        x.loc[_rb,"evaluation_score"]+=(_rb_quality-0.50)*16.0

    # Negative roster opportunity is an authoritative cost.
    _ropp=_safe_num_series(x,"roster_opportunity_adj",0.0)
    _neg_ropp=_ropp < -3.0
    x.loc[_neg_ropp,"evaluation_score"]-=np.minimum(24.0,(-_ropp[_neg_ropp]-3.0)*1.35)

    # A strongly negative bench-IDP fit is never a FINAL PICK after required DL/DB are filled.
    _idp_counts2=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    _both_idp_filled=(
        int(_idp_counts2.get("DL",0))>=int(slots.get("DL",1)) and
        int(_idp_counts2.get("DB",0))>=int(slots.get("DB",1))
    )
    if _both_idp_filled:
        _bad_idp_fit=x["position"].isin(["DL","DB"]) & (_ropp<-5.0)
        x.loc[_bad_idp_fit,"evaluation_score"]-=5000.0

    # v9.45 quality authority: roster/market urgency decides WHEN, not WHO.
    _off=~x["position"].isin(["DL","DB","K"])
    _vorp=pd.to_numeric(x.get("vorp",np.nan),errors="coerce")
    _mr=pd.to_numeric(x.get("model_rank",np.nan),errors="coerce")
    _profile=x.get("profile",pd.Series("",index=x.index)).astype(str).str.lower()
    _bad_off=_off & ((_vorp < 0) | _profile.str.contains("decline",na=False))
    x.loc[_bad_off,"evaluation_score"]-=14.0 + np.minimum(10.0,(-_vorp[_bad_off]).clip(lower=0)*3.0)
    x.loc[_off & (_mr>1000),"evaluation_score"]-=8.0

    # IDP talent is independent of roster urgency: quality controls WHICH DL/DB.
    for _p in ("DL","DB"):
        _pm=x["position"].eq(_p) & x["idp_eligible"].fillna(False).astype(bool)
        if _pm.any():
            _impact=pd.to_numeric(x.loc[_pm,"idp_impact_score"],errors="coerce").fillna(-99)
            _ext=pd.to_numeric(x.loc[_pm,"idp_external_rank"],errors="coerce")
            _tier=pd.to_numeric(x.loc[_pm,"idp_quality_tier"],errors="coerce").fillna(5)
            _talent=(0.75*_impact) + (6-_tier)*2.5 + np.where(_ext.notna(),np.maximum(0,25-_ext)*0.18,0)
            x.loc[_pm,"evaluation_score"] += _talent
            x.loc[_pm,"idp_talent_score"] = _talent
            _ordered=x.loc[_pm].copy()
            _ordered["_talent_tmp"]=_talent
            _ordered=_ordered.sort_values(["idp_quality_tier","_talent_tmp"],ascending=[True,False])
            if len(_ordered):
                _best_idx=_ordered.index[0]
                _best_tier=float(pd.to_numeric(pd.Series([_ordered.iloc[0]["idp_quality_tier"]]),errors="coerce").fillna(5).iloc[0])
                _second_tier=float(pd.to_numeric(pd.Series([_ordered.iloc[1]["idp_quality_tier"]]),errors="coerce").fillna(5).iloc[0]) if len(_ordered)>1 else 5.0
                if _best_tier<=2 and _second_tier>_best_tier:
                    x.at[_best_idx,"evaluation_score"]+=5.0
                    x.at[_best_idx,"idp_dropoff_bonus"]=5.0

    # v9.47 strict IDP positional authority.
    # Roster urgency can decide WHEN to draft DL/DB, but cannot make a lower-quality
    # defender beat an available elite defender at the same position.
    x["idp_quality_blocked"]=False
    x["elite_idp_bonus"]=0.0
    x["elite_idp_quota_blocked"]=False
    for _p in ("DL","DB"):
        _pm=x["position"].eq(_p) & x["idp_eligible"].fillna(False).astype(bool)
        if not _pm.any():
            continue

        _tiers=pd.to_numeric(x.loc[_pm,"idp_quality_tier"],errors="coerce").fillna(5.0)
        _exts=pd.to_numeric(x.loc[_pm,"idp_external_rank"],errors="coerce")
        _talents=pd.to_numeric(x.loc[_pm,"idp_talent_score"],errors="coerce").fillna(-99.0)

        _best_tier=float(_tiers.min())
        _valid_ext=_exts.dropna()
        _best_ext=float(_valid_ext.min()) if len(_valid_ext) else np.nan
        _best_talent=float(_talents.max())

        # If Tier 1/2 exists, Tier 3+ becomes context only.
        if _best_tier<=2:
            _tier_all=pd.to_numeric(x["idp_quality_tier"],errors="coerce").fillna(5.0)
            _blocked=_pm & (_tier_all>=3)
            x.loc[_blocked,"evaluation_score"]-=1000.0
            x.loc[_blocked,"idp_quality_blocked"]=True

        # Strong elite-rank authority.
        _elite_cut=6 if _p=="DL" else 8
        _rank_gap=5 if _p=="DL" else 7
        if pd.notna(_best_ext) and _best_ext<=_elite_cut:
            _all_ext=pd.to_numeric(x["idp_external_rank"],errors="coerce")
            _all_talent=_safe_num_series(x,"idp_talent_score",-99.0)
            _lower=_pm & _all_ext.notna() & (_all_ext>=_best_ext+_rank_gap) & (_all_talent<_best_talent+6.0)
            x.loc[_lower,"evaluation_score"]-=1000.0
            x.loc[_lower,"idp_quality_blocked"]=True

    # v9.49 elite-IDP quota.
    # Goal: finish the draft with at least ONE elite defender, while still letting
    # value/timing decide whether that elite player is DL or DB.
    _roster_elite=False
    if roster is not None and len(roster):
        _r=roster.copy()
        if "idp_quality_tier" in _r.columns:
            _rt=pd.to_numeric(_r["idp_quality_tier"],errors="coerce")
            _rp=_r["position"].astype(str).str.upper().isin(["DL","DB"])
            _roster_elite=bool((_rp & (_rt<=2)).any())

    _elite_avail=(
        x["position"].isin(["DL","DB"]) &
        x["idp_eligible"].fillna(False).astype(bool) &
        (pd.to_numeric(x["idp_quality_tier"],errors="coerce")<=2)
    )

    if (not _roster_elite) and _elite_avail.any():
        # Escalating value pressure: pursue elite IDP before the final two rounds.
        _elite_bonus=0.0
        if int(round_no)>=10: _elite_bonus=4.0
        if int(round_no)>=12: _elite_bonus=9.0
        if int(round_no)>=14: _elite_bonus=18.0
        x.loc[_elite_avail,"evaluation_score"]+=_elite_bonus
        x.loc[_elite_avail,"elite_idp_bonus"]=_elite_bonus

        # By Round 15, if an elite defender still exists, do not spend the pick on
        # a non-required bench luxury. Required K/TE/DL/DB completion remains exempt.
        if int(round_no)>=15:
            _counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
            _required_open={
                "TE":int(_counts.get("TE",0))<int(slots.get("TE",0)),
                "K":int(_counts.get("K",0))<int(slots.get("K",0)),
                "DL":int(_counts.get("DL",0))<int(slots.get("DL",0)),
                "DB":int(_counts.get("DB",0))<int(slots.get("DB",0)),
            }
            _bench_luxury=~x["position"].isin(["DL","DB"])
            # Exempt any currently unfilled required position.
            for _p,_open in _required_open.items():
                if _open:
                    _bench_luxury &= ~x["position"].eq(_p)
            x.loc[_bench_luxury,"evaluation_score"]-=1000.0
            x.loc[_bench_luxury,"elite_idp_quota_blocked"]=True

    # Fantasy Edge deep-bench competition.
    # Once RB5 or WR6 territory is reached, compare directly against the best remaining
    # eligible impact defender. Deep offense must clearly beat that defender on marginal value.
    # Deep-offense vs extra-IDP competition is owned by the single-authority
    # marginal-slot / strategic-value engine below. The obsolete hard block that
    # depended on marginal_roster_value has been removed so Live/Mock/Simulation
    # do not require a legacy column that is not part of the final authority.

    # Fantasy Edge extra-IDP quality guard.
    # After both required IDP starters are filled, a bench DL/DB must be an actual
    # impact option. Strongly negative roster opportunity cannot be overridden by name/rank.
    _idp_counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    _required_idp_filled=(
        int(_idp_counts.get("DL",0))>=int(slots.get("DL",1)) and
        int(_idp_counts.get("DB",0))>=int(slots.get("DB",1))
    )
    if _required_idp_filled:
        _idp_mask_extra=x["position"].isin(["DL","DB"]) & x["idp_eligible"].fillna(False).astype(bool)
        _idp_ropp=_safe_num_series(x,"roster_opportunity_adj",0.0)
        _idp_tier=_safe_num_series(x,"idp_quality_tier",5.0)

        # Backup defender must be Tier 1-2 AND have acceptable roster opportunity.
        _elite_extra_ok=_idp_mask_extra & (_idp_tier<=2) & (_idp_ropp>=-18.0)
        _bad_extra=_idp_mask_extra & (~_elite_extra_ok)
        x.loc[_bad_extra,"evaluation_score"]-=5000.0
        x.loc[_bad_extra,"extra_idp_blocked"]=True

    # Fantasy Edge best-available IDP comparison.
    # Rank DL and DB *within the actually available pool* using the same inputs that drive
    # recommendations, so Brian Branch (or any other defender) must beat other available
    # same-position options rather than winning from a fixed name/rank prior.
    x["idp_available_rank"]=np.nan
    x["idp_available_score"]=np.nan
    x["idp_scarcity_cliff"]=0.0
    x["idp_scarcity_bonus"]=0.0

    for _p in ("DL","DB"):
        _pm=x["position"].eq(_p) & x["idp_eligible"].fillna(False).astype(bool)
        if not _pm.any():
            continue

        _impact=pd.to_numeric(x.loc[_pm,"idp_impact_score"],errors="coerce").fillna(0.0)
        _talent=pd.to_numeric(x.loc[_pm,"idp_talent_score"],errors="coerce").fillna(0.0)
        _tier=pd.to_numeric(x.loc[_pm,"idp_quality_tier"],errors="coerce").fillna(5.0)
        _ext=pd.to_numeric(x.loc[_pm,"idp_external_rank"],errors="coerce")
        _proj=pd.to_numeric(x.loc[_pm,"projection"],errors="coerce").fillna(0.0)
        _vorp=pd.to_numeric(x.loc[_pm,"vorp"],errors="coerce").fillna(0.0)

        # Available-player composite:
        # fantasy impact and talent dominate; tier/external rank stabilize sparse rows;
        # projection/VORP provide direct scoring support where present.
        _ext_support=np.where(_ext.notna(),np.maximum(0.0,30.0-_ext)*0.22,0.0)
        _avail_score=(
            0.36*_impact +
            0.30*_talent +
            (6.0-_tier)*1.9 +
            _ext_support +
            0.18*_proj +
            0.45*np.maximum(_vorp,0.0)
        )

        x.loc[_pm,"idp_available_score"]=_avail_score
        x.loc[_pm,"idp_available_rank"]=pd.Series(
            _avail_score,index=x.index[_pm]
        ).rank(method="min",ascending=False)

        # Dynamic same-position scarcity: quantify the cliff from IDP1 to IDP2/3.
        _ranked_scores=pd.Series(_avail_score,index=x.index[_pm]).sort_values(ascending=False)
        if len(_ranked_scores)>=2:
            _cliff=float(_ranked_scores.iloc[0]-_ranked_scores.iloc[1])
        else:
            _cliff=6.0
        _best_idx=_ranked_scores.index[0]
        x.at[_best_idx,"idp_scarcity_cliff"]=_cliff
        if _cliff>=2.5:
            x.at[_best_idx,"evaluation_score"]+=min(8.0,2.0+_cliff*1.25)
            x.at[_best_idx,"idp_scarcity_bonus"]=min(8.0,2.0+_cliff*1.25)

        # Same-position authority: if an available defender trails the best option
        # by a meaningful amount, roster need cannot make him FINAL PICK instead.
        _best=float(np.nanmax(_avail_score))
        _gap=_best-_avail_score
        _clearly_worse=_gap>=4.0
        if np.any(_clearly_worse):
            _bad_idx=x.index[_pm][_clearly_worse]
            x.loc[_bad_idx,"evaluation_score"]-=18.0

        # Top-3 available defenders get a modest positive nudge, preserving timing logic.
        _ranks=pd.to_numeric(x.loc[_pm,"idp_available_rank"],errors="coerce")
        x.loc[_pm & x.index.isin(_ranks.index[_ranks<=3]),"evaluation_score"]+=4.0

    # Evidence authority after all roster construction: ineligible IDPs cannot be FINAL PICK.
    bad=x["position"].isin(["DL","DB"]) & (~x["idp_eligible"].fillna(False).astype(bool))
    x.loc[bad,"evaluation_score"]-=1000.0
    # v9.41 positional-quality dominance.
    # This fixes "last required DL/DB => any positive depth player becomes #1".
    for _p in ("DL","DB"):
        pm=x["position"].eq(_p) & x["idp_eligible"].fillna(False).astype(bool)
        if pm.any():
            best_tier=pd.to_numeric(x.loc[pm,"idp_quality_tier"],errors="coerce").min()
            if pd.notna(best_tier):
                worse=pm & (pd.to_numeric(x["idp_quality_tier"],errors="coerce") >= best_tier+2)
                x.loc[worse,"evaluation_score"]-=45.0

    _ropp_final=_safe_num_series(x,"roster_opportunity_adj",0.0)
    _good_fit=x[_ropp_final>=0]
    if len(_good_fit):
        _best_good=float(pd.to_numeric(_good_fit["evaluation_score"],errors="coerce").max())
        _badfit=(_ropp_final<=-5) & (pd.to_numeric(x["evaluation_score"],errors="coerce")<=_best_good+12.0)
        x.loc[_badfit,"evaluation_score"]-=1000.0

    cr=_safe_num_series(x,"market_pick",float(current_pick))
    local,ready,survive=execution_choice(
        x.evaluation_score.to_numpy(float),cr.to_numpy(float),
        int(current_pick),next_pick,int(randomness)
    )
    x["survival_next"]=survive
    x["timing_ready"]=ready
    x["evaluation_rank"]=x.evaluation_score.rank(method="min",ascending=False)

    reach=np.maximum(cr-float(current_pick),0)  # player normally goes later = true reach
    fall=np.maximum(float(current_pick)-cr,0)   # player fell past market = value
    x["true_reach_picks"]=reach
    x["faller_value_picks"]=fall
    x["execution_score"]=x.evaluation_score.copy()

    # If a player is likely to survive, preserve the current pick for a scarcer option.
    x.loc[~x.timing_ready,"execution_score"]-=x.loc[~x.timing_ready,"survival_next"]*np.minimum(reach[~x.timing_ready],36)*.55

    # Hard reach protection: 24+ picks ahead of market needs a major evaluation edge.
    _best_eval=float(pd.to_numeric(x["evaluation_score"],errors="coerce").max()) if len(x) else -1e9
    _big_reach=(reach>=24)
    _insufficient_edge=pd.to_numeric(x["evaluation_score"],errors="coerce") < (_best_eval+4.0)
    x.loc[_big_reach & _insufficient_edge,"execution_score"]-=35.0

    # Falling past market is good, but only a modest timing bonus so late bench names
    # cannot overwhelm marginal roster value.
    x["execution_score"]+=.018*np.minimum(fall,48.0)
    # ------------------------------------------------------------------
    # Unified FINAL PICK layer shared by Live Draft and Interactive Mock.
    # Existing evaluation_score remains the mature player model. This final layer
    # adds transparent roster marginal value, snake-turn urgency and reach cost.
    # ------------------------------------------------------------------
    _uc=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    _upos=x["position"].astype(str)

    def _uc_num(name,default=0.0):
        if name in x.columns:
            return pd.to_numeric(x[name],errors="coerce").fillna(float(default))
        return pd.Series(float(default),index=x.index,dtype=float)

    _proj=_uc_num("projection",0.0)
    _vorp=_uc_num("vorp",0.0)
    _eval=_uc_num("evaluation_score",-999.0)
    _market=_uc_num("market_pick",999.0)
    if "market_pick" not in x.columns and "consensus_rank" in x.columns:
        _market=_uc_num("consensus_rank",999.0)

    # Preserve the mature engine as the majority of player value while making
    # projection and VORP explicit enough to prevent unexplained same-position leaps.
    _player_value=0.74*_eval + 0.16*_vorp + 0.10*_proj

    _roster_value=np.zeros(len(x),dtype=float)
    for _p,_default_need in [("QB",1),("RB",2),("WR",2),("TE",1),("K",1),("DL",1),("DB",1)]:
        _have=int(_uc.get(_p,0))
        if _have < int(slots.get(_p,_default_need)):
            _roster_value += np.where(_upos.eq(_p),7.0,0.0)

    _rb=int(_uc.get("RB",0)); _wr=int(_uc.get("WR",0))
    if _rb>=4: _roster_value += np.where(_upos.eq("RB"),-4.0,0.0)
    if _rb>=5: _roster_value += np.where(_upos.eq("RB"),-8.0,0.0)
    if _wr>=5: _roster_value += np.where(_upos.eq("WR"),-6.0,0.0)

    # Snake-turn urgency: candidates unlikely to survive to the user's next turn
    # receive a bounded bonus. This is never a legality override.
    _next_gap=max(int(next_pick)-int(current_pick),1)
    _survival_margin=_market-float(current_pick)
    _next_turn_risk=np.clip((_next_gap-_survival_margin)/max(_next_gap,1),0,1)*6.0

    # Continuous reach cost.
    _reach=np.maximum(_market-float(current_pick),0.0)
    _reach_cost=np.minimum(_reach,48.0)*0.14

    # Controlled IDP portfolio: 1 DL + 1 DB required; third IDP is purely merit-based.
    _idp=_upos.isin(["DL","DB"])
    _idp_total=int(_uc.get("DL",0))+int(_uc.get("DB",0))
    _tier=_uc_num("idp_quality_tier",5.0)
    _impact=_uc_num("idp_impact_score",0.0)
    _eligible=x["idp_eligible"].fillna(False).astype(bool) if "idp_eligible" in x.columns else pd.Series(False,index=x.index)
    _impact_idp=_idp & _eligible & (_tier<=2)
    _idp_marginal=np.zeros(len(x),dtype=float)

    if _idp_total<2:
        _idp_marginal += np.where(_impact_idp,3.5+np.minimum(_impact,15.0)*0.10,0.0)
    elif _idp_total==2 and int(round_no)>=11:
        # Third IDP receives no structural bonus. Quality, scarcity, opportunity cost
        # and rollout value must make it win naturally.
        _idp_marginal += 0.0
    elif _idp_total>=3:
        # Fourth IDP is effectively prohibited for this 17-player roster.
        _idp_marginal += np.where(_idp,-80.0,0.0)

    x["player_value_component"]=_player_value
    x["roster_value_component"]=_roster_value
    x["next_turn_risk_component"]=_next_turn_risk
    x["reach_cost_component"]=_reach_cost
    x["idp_marginal_component"]=_idp_marginal
    x["unified_pick_score"]=_player_value+_roster_value+_next_turn_risk+_idp_marginal-_reach_cost

    # Same-position projection/VORP sanity guard.
    x["same_position_value_guard"]=False
    for _p in x["position"].dropna().astype(str).unique():
        _m=_upos.eq(_p)
        if int(_m.sum())<2:
            continue
        _best_proj=float(_proj[_m].max())
        _best_vorp=float(_vorp[_m].max())
        _dominated=_m & (_proj < _best_proj-1.5) & (_vorp < _best_vorp-1.0)
        if _dominated.any() and (_m & ~_dominated).any():
            _best_good=float(x.loc[_m & ~_dominated,"unified_pick_score"].max())
            _weak=_dominated & (x["unified_pick_score"] < _best_good+4.0)
            x.loc[_weak,"unified_pick_score"]-=8.0
            x.loc[_weak,"same_position_value_guard"]=True

    # Absolute post-pick roster feasibility gate.
    _counts_now=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    _remaining_after=max(int(exact_roster_rounds(slots))-int(round_no),0)

    def _min_required_after(_after):
        fixed={p:max(int(slots.get(p,0))-int(_after.get(p,0)),0) for p in ["QB","RB","WR","TE","K","DL","DB"]}
        skill_need=int(slots.get("RB",0))+int(slots.get("WR",0))+int(slots.get("TE",0))+int(slots.get("FLEX",0))
        skill_have=int(_after.get("RB",0))+int(_after.get("WR",0))+int(_after.get("TE",0))
        flex_extra=max(skill_need-skill_have-(fixed["RB"]+fixed["WR"]+fixed["TE"]),0)
        return int(sum(fixed.values())+flex_extra)

    x["post_pick_feasible"]=True
    for _p in ["QB","RB","WR","TE","K","DL","DB"]:
        _pm=x["position"].astype(str).eq(_p)
        if _pm.any():
            _after=dict(_counts_now); _after[_p]=int(_after.get(_p,0))+1
            if _min_required_after(_after)>_remaining_after:
                x.loc[_pm,"post_pick_feasible"]=False

    if int(_counts_now.get("DL",0))+int(_counts_now.get("DB",0))>=3:
        x.loc[x["position"].isin(["DL","DB"]),"post_pick_feasible"]=False

    # Single authoritative Live/Mock decision engine.
    # V10.66 bulk simulation can lower Monte Carlo resolution while keeping the
    # exact same strategic score, legality gates, roster construction, wait-cost,
    # and rollout mechanism. Live/interactive draft remains full fidelity.
    _sim_rollout_branches=5
    _sim_rollout_contenders=5
    if _reuse_sim_idp:
        if "_sim_rollout_branches" in x.columns:
            _v=pd.to_numeric(x["_sim_rollout_branches"],errors="coerce").dropna()
            if len(_v): _sim_rollout_branches=max(int(_v.iloc[0]),1)
        if "_sim_rollout_contenders" in x.columns:
            _v=pd.to_numeric(x["_sim_rollout_contenders"],errors="coerce").dropna()
            if len(_v): _sim_rollout_contenders=max(int(_v.iloc[0]),1)
    x=_single_authority_final(
        x,roster,slots,int(round_no),int(current_pick),int(next_pick),
        compute_stability=not _reuse_sim_idp,
        rollout_branches=_sim_rollout_branches if _reuse_sim_idp else 18,
        rollout_contenders=_sim_rollout_contenders if _reuse_sim_idp else 5
    )

    # FINAL PICK has one authority plus non-negotiable quality/legality gates.
    x["execution_score"]=x["final_pick_value"]
    _hard_block=~x["post_pick_feasible"]
    for _flag in ["roster_completion_blocked","same_pos_dominated","idp_quality_blocked","extra_idp_blocked","deep_skill_hard_cap"]:
        if _flag in x.columns:
            _hard_block |= x[_flag].fillna(False).astype(bool)
    _idp_now=int(_counts_now.get("DL",0))+int(_counts_now.get("DB",0))
    if _idp_now>=3:
        _hard_block |= x["position"].isin(["DL","DB"])
    _mrv=_safe_num_series(x,"marginal_roster_value",0.0)
    _vorp=_safe_num_series(x,"vorp",0.0)
    _proj=_safe_num_series(x,"projection",0.0)
    _ropp=_safe_num_series(x,"roster_opportunity_adj",0.0)

    for _p in ["RB","WR"]:
        _have=int(_counts_now.get(_p,0))
        if _have>=5:
            _pm=x["position"].astype(str).eq(_p) & (~_hard_block)
            _alt=(~x["position"].astype(str).eq(_p)) & (~_hard_block)
            if _pm.any() and _alt.any():
                _best_alt_mrv=float(_mrv[_alt].max())
                _best_alt_vorp=float(_vorp[_alt].max())
                _best_alt_proj=float(_proj[_alt].max())
                _premium=(
                    (_mrv >= _best_alt_mrv+1.25) &
                    ((_vorp >= _best_alt_vorp+0.60) | (_proj >= _best_alt_proj+1.0)) &
                    (_ropp >= -1.5)
                )
                _hard_block |= _pm & (~_premium)

    _minimum_now,_,_=_minimum_required_picks_remaining(_counts_now,slots)
    x["cross_position_dominated"]=False
    if _minimum_now==0:
        _candidate_mask=~_hard_block
        _indices=list(x.index[_candidate_mask])
        for _idx in _indices:
            _others=_candidate_mask.copy()
            _others.loc[_idx]=False
            if not _others.any():
                continue
            _dom=(
                (_mrv[_others] >= float(_mrv.loc[_idx])+1.0) &
                (_vorp[_others] >= float(_vorp.loc[_idx])+0.40) &
                (_proj[_others] >= float(_proj.loc[_idx])+0.50) &
                (_ropp[_others] >= float(_ropp.loc[_idx]))
            )
            if bool(_dom.any()):
                x.at[_idx,"cross_position_dominated"]=True
        _hard_block |= x["cross_position_dominated"].fillna(False).astype(bool)

    if int(round_no)>=11:
        _nonnegative=(~_hard_block) & (_ropp>=0.0)
        if _nonnegative.any():
            _hard_block |= (~_hard_block) & (_ropp<-5.0)

        # V6.14 late optional quality floor: once a position's required starter
        # count is satisfied, do not spend a bench spot on negative VORP when a
        # legal nonnegative-VORP alternative exists. Required completion is exempt.
        _counts_late=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
        _required_pos=pd.Series(False,index=x.index,dtype=bool)
        for _p in ["QB","RB","WR","TE","K","DL","DB"]:
            if int(_counts_late.get(_p,0)) < int(slots.get(_p,0)):
                _required_pos |= x["position"].astype(str).eq(_p)
        _optional=(~_hard_block) & (~_required_pos)
        _good_optional=_optional & (_vorp>=0.0) & (_ropp>=-2.0)
        if _good_optional.any():
            _hard_block |= _optional & (_vorp<0.0)

    # Market-efficient reach guard. Avoid paying 18+ picks ahead of market when
    # another legal candidate has comparable VORP/marginal value and is priced
    # near the current pick. This directly attacks avoidable Draft Value loss.
    _market_final=_safe_num_series(x,"market_pick",float(current_pick)+20.0)
    _reach_gap=_market_final-float(current_pick)
    x["raw_reach_gap"]=_reach_gap
    x["avoidable_reach"]=False
    _legal_now=~_hard_block
    _near_market=_legal_now & (_reach_gap<=12.0)
    if _near_market.any():
        for _idx in list(x.index[_legal_now & (_reach_gap>=13.0)]):
            _similar=(
                _near_market &
                (_vorp >= float(_vorp.loc[_idx])-0.90) &
                (_mrv >= float(_mrv.loc[_idx])-1.75) &
                (_ropp >= float(_ropp.loc[_idx])-1.00)
            )
            if bool(_similar.any()):
                x.at[_idx,"avoidable_reach"]=True
                _hard_block.loc[_idx]=True

    # V6.18 draft-day status guard: DND/IR/NFI-level statuses must be true
    # hard exclusions, not merely a clipped score penalty.
    _injury_exec=_safe_num_series(x,"injury_penalty",0.0)
    _status_hard=_injury_exec>=900.0
    x["status_hard_blocked"]=_status_hard
    _hard_block |= _status_hard

    x["final_quality_blocked"]=_hard_block
    x.loc[_hard_block,"execution_score"]=-1e12

    # Final challenger test: a candidate cannot win on timing/rollout alone when
    # another legal player offers a clearly superior value package.
    _legal_value=~x["final_quality_blocked"]
    _mrv_final=_safe_num_series(x,"marginal_roster_value",0.0)
    _vorp_final=_safe_num_series(x,"vorp",0.0)
    _proj_final=_safe_num_series(x,"projection",0.0)
    _market_final2=_safe_num_series(x,"market_pick",float(current_pick)+20.0)
    _ropp_cmp=_safe_num_series(x,"roster_opportunity_adj",0.0)
    x["value_challenger_blocked"]=False

    _legal_indices=list(x.index[_legal_value])
    for _idx in _legal_indices:
        _others=_legal_value.copy()
        _others.loc[_idx]=False
        if not _others.any():
            continue
        _challenger=(
            _others &
            (_mrv_final >= float(_mrv_final.loc[_idx])+1.5) &
            (_vorp_final >= float(_vorp_final.loc[_idx])+0.5) &
            (_ropp_cmp >= float(_ropp_cmp.loc[_idx])-0.5) &
            (_market_final2 <= float(_market_final2.loc[_idx])+10.0)
        )
        if bool(_challenger.any()):
            x.at[_idx,"value_challenger_blocked"]=True
            x.at[_idx,"execution_score"]-=750.0

    _ropp_final=_safe_num_series(x,"roster_opportunity_adj",0.0)
    _feasible_now=~x["final_quality_blocked"]
    if (_feasible_now & (_ropp_final>=0)).any():
        _luxury_cut=-3.0 if int(round_no)>=11 else -6.0
        _bad_luxury=_feasible_now & (_ropp_final<_luxury_cut)
        x.loc[_bad_luxury,"execution_score"]-=325.0

    x=_v944_add_idp_display_metrics(x)

    return x.sort_values("execution_score",ascending=False), local




def _v633_active_roster_directory(players):
    """Build a clean active NFL roster directory from the Sleeper NFL player feed.
    This is an identity/status source only; it never manufactures fantasy value.
    """
    cols=["player_id","player","position","raw_position","team","active","injury_status","years_exp"]
    if not isinstance(players, dict) or not players:
        return pd.DataFrame(columns=cols)
    rows=[]
    allowed={"QB","RB","WR","TE","K","DL","DB"}
    for pid,pl in players.items():
        if not isinstance(pl,dict) or pl.get("active") is False:
            continue
        raw=str(pl.get("position") or "").upper().strip()
        pos=canonical_position(raw)
        team=str(pl.get("team") or "").upper().strip()
        # Active roster export = currently attached to an NFL team.
        if pos not in allowed or not team or team in {"FA","NONE","N/A"}:
            continue
        name=pl.get("full_name") or " ".join([pl.get("first_name") or "",pl.get("last_name") or ""]).strip()
        if not name:
            continue
        rows.append({
            "player_id":str(pid),"player":str(name),"position":pos,"raw_position":raw,
            "team":team,"active":True,"injury_status":pl.get("injury_status") or "",
            "years_exp":pl.get("years_exp")
        })
    if not rows:
        return pd.DataFrame(columns=cols)
    out=pd.DataFrame(rows)
    out["key"]=out["player"].map(norm)
    return out.sort_values(["position","team","player"]).drop_duplicates("key",keep="first").reset_index(drop=True)

@st.cache_data(ttl=21600, show_spinner=False)
def _v637_consensus_directory_ranks():
    """Fetch current 2026 FantasyPros PPR consensus ranks for display enrichment.
    This never changes the certified recommendation engine; it only gives roster
    directory players a real external rank when the player is actually ranked.
    """
    try:
        url="https://www.fantasypros.com/nfl/fantasy-football-rankings/ppr-overall.php"
        response=requests.get(url,timeout=(4,10),headers={"User-Agent":"FantasyEdge/8.06"})
        response.raise_for_status()
        tables=pd.read_html(io.StringIO(response.text))
        frames=[]
        for t in tables:
            cols=[str(c).strip().lower() for c in t.columns]
            if any(c in cols for c in ["rk","rank"]) and any("player" in c for c in cols):
                tt=t.copy(); tt.columns=cols; frames.append(tt)
        if not frames:
            return pd.DataFrame(columns=["key","external_ecr_rank"])
        raw=max(frames,key=len)
        rank_col="rk" if "rk" in raw.columns else "rank"
        player_col=next(c for c in raw.columns if "player" in c)
        out=pd.DataFrame({
            "player_raw":raw[player_col].astype(str),
            "external_ecr_rank":pd.to_numeric(raw[rank_col],errors="coerce")
        }).dropna(subset=["external_ecr_rank"])
        # FantasyPros table cells can include team/position text after the name.
        # Prefer matching by the clean name prefix generated from known roster names
        # later; retain normalized full cell as a secondary key.
        out["key_full"]=out.player_raw.map(norm)
        return out.drop_duplicates("external_ecr_rank").reset_index(drop=True)
    except Exception as e:
        pass  # V7.04: cached loaders must not mutate st.session_state
        return pd.DataFrame(columns=["player_raw","external_ecr_rank","key_full"])

def _v637_attach_directory_ranks(roster_dir):
    if roster_dir is None or roster_dir.empty:
        return roster_dir
    x=roster_dir.copy()
    x["external_ecr_rank"]=np.nan
    ranks=_v637_consensus_directory_ranks()
    if ranks is None or ranks.empty:
        return x
    # Match each active roster name against the beginning of the FantasyPros cell.
    cells=[(norm(r.player_raw),float(r.external_ecr_rank)) for _,r in ranks.iterrows()]
    def lookup(name):
        nk=norm(name)
        hits=[]
        for ck,rk in cells:
            if ck.startswith(nk): hits.append(rk)
        return min(hits) if hits else np.nan
    x["external_ecr_rank"]=x.player.astype(str).map(lookup)
    return x


def _v642_enrich_ranked_roster_players(board, roster_dir, max_ecr=260):
    """Add fantasy-relevant active roster players missing from the certified board.

    Only players with a real current external consensus rank are eligible.  Their
    projection / VORP / draft score are interpolated from Fantasy Edge's existing
    same-position ranked curve, so we never fall back to the old 999/-4 placeholder
    values.  These rows are explicitly tagged ECR_ENRICHED and use lower confidence.
    """
    if board is None or len(board)==0 or roster_dir is None or len(roster_dir)==0:
        return board
    x=board.copy()
    if "key" not in x.columns:
        x["key"]=x["player"].astype(str).map(norm)
    existing=set(x["key"].astype(str))
    rd=roster_dir.copy()
    rd["external_ecr_rank"]=pd.to_numeric(rd.get("external_ecr_rank"),errors="coerce")
    rd=rd[rd["external_ecr_rank"].notna() & (rd["external_ecr_rank"]<=float(max_ecr))].copy()
    rd=rd[~rd["key"].astype(str).isin(existing)]
    if rd.empty:
        return x

    repl={"QB":16.0,"RB":8.2,"WR":7.6,"TE":5.6,"DL":6.2,"DB":5.9,"K":8.1}
    rows=[]
    for _,r in rd.iterrows():
        pos=str(r.get("position") or "")
        ecr=float(r["external_ecr_rank"])
        peers=x[x["position"].astype(str).eq(pos)].copy()
        peers["market_pick"]=pd.to_numeric(peers.get("market_pick"),errors="coerce")
        peers["projection"]=pd.to_numeric(peers.get("projection"),errors="coerce")
        peers["draft_score"]=pd.to_numeric(peers.get("draft_score"),errors="coerce")
        peers=peers.dropna(subset=["market_pick","projection"]).sort_values("market_pick")
        if len(peers)<2:
            continue
        xp=peers["market_pick"].to_numpy(dtype=float)
        proj=float(np.interp(ecr,xp,peers["projection"].to_numpy(dtype=float),left=peers["projection"].iloc[0],right=peers["projection"].iloc[-1]))
        ds_peers=peers.dropna(subset=["draft_score"])
        if len(ds_peers)>=2:
            ds=float(np.interp(ecr,ds_peers["market_pick"].to_numpy(dtype=float),ds_peers["draft_score"].to_numpy(dtype=float),left=ds_peers["draft_score"].iloc[0],right=ds_peers["draft_score"].iloc[-1]))
        else:
            ds=float(100.0-ecr*0.45)
        replacement=float(repl.get(pos,0.0))
        vorp=float(proj-replacement)
        d={c:np.nan for c in x.columns}
        d.update({
            "player":str(r.get("player")),"position":pos,"raw_position":str(r.get("raw_position") or pos),
            "team":str(r.get("team") or "NFL"),"key":str(r.get("key")),
            "market_pick":ecr,"consensus_rank":ecr,"projection":proj,"replacement_ppg":replacement,
            "vorp":vorp,"draft_score":ds,"pure_model_score":ds,"last_ppg":proj,"prior_ppg":proj,
            "opp_pg":proj,"progression":0.0,"regression":0.0,"scarcity":0.0,
            "consensus_strength":max(0.0,100.0*(1.0-np.log(max(ecr,1.0))/np.log(300.0))),
            "confidence":0.60,"injury":str(r.get("injury_status") or ""),"injury_severity":0,
            "injury_penalty":0.0,"role_score":0.0,"profile":"Consensus-enriched active roster",
            "age":np.nan,"exp":pd.to_numeric(pd.Series([r.get("years_exp")]),errors="coerce").iloc[0],
            "breakout":0.0,"decline":0.0,"waiver_score":proj*4.0,
            "display_projection":proj,"display_vorp":vorp,"display_model_rank":np.nan,
            "model_rank":np.nan,"id":"roster-ecr:"+str(r.get("key")),
            "identity_key":"roster-ecr:"+str(r.get("key"))+"|"+pos,
            "pool_status":"ECR_ENRICHED","roster_sync_source":"Active roster + current ECR",
            "external_ecr_rank":ecr,
        })
        rows.append(d)
    if not rows:
        return x
    add=pd.DataFrame(rows)
    for c in x.columns:
        if c not in add.columns: add[c]=np.nan
    for c in add.columns:
        if c not in x.columns: x[c]=np.nan
    out=pd.concat([x,add[x.columns]],ignore_index=True)
    return out.drop_duplicates("key",keep="first").reset_index(drop=True)

def _v633_merge_active_roster_directory(board, roster_dir):
    """Guarantee every active NFL roster player is selectable in Draft/Mock.
    Missing directory players enter as DEPTH_ONLY with conservative placeholder
    values so identity completeness cannot create fake DRAFT NOW recommendations.
    Ranked players keep all certified Fantasy Edge values.
    """
    if board is None or len(board)==0 or roster_dir is None or len(roster_dir)==0:
        return board
    x=board.copy()
    if "key" not in x.columns:
        x["key"]=x["player"].astype(str).map(norm)
    if "pool_status" not in x.columns:
        x["pool_status"]="RANKED"
    if "roster_sync_source" not in x.columns:
        x["roster_sync_source"]="Fantasy Edge"
    existing=set(x["key"].astype(str))
    repl={"QB":16.0,"RB":8.2,"WR":7.6,"TE":7.8,"K":7.0,"DL":6.2,"DB":5.9}
    rows=[]
    for _,r in roster_dir.iterrows():
        key=str(r["key"]); pos=str(r["position"]); name=str(r["player"]); team=str(r["team"])
        if key in existing:
            m=x["key"].astype(str).eq(key)
            x.loc[m,"team"]=team
            x.loc[m,"roster_sync_source"]="Active NFL roster"
            continue
        base=float(repl.get(pos,7.0))
        d={c:np.nan for c in x.columns}
        d.update({
            "id":"roster:"+str(r["player_id"]),"player":name,"key":key,
            "position":pos,"raw_position":str(r.get("raw_position",pos)),"team":team,
            "projection":max(0.0,base-4.0),"vorp":-4.0,"replacement_ppg":base,
            "draft_score":-999.0,"model_rank":999.0,"consensus_rank":999.0,"market_pick":999.0,
            "confidence":0.10,"injury":str(r.get("injury_status","") or ""),"injury_penalty":0.0,
            "v9_market_pick":999.0,"v9_vorp":-4.0,"v9_draft_score":-999.0,
            "v9_model_rank":999.0,"v9_base_live_score":-999.0,
            "pool_status":"DEPTH_ONLY","roster_sync_source":"Active NFL roster"
        })
        rows.append(d)
        existing.add(key)
    if rows:
        x=pd.concat([x,pd.DataFrame(rows)],ignore_index=True,sort=False)
    return x.drop_duplicates("key",keep="first").reset_index(drop=True)

def make_board(players, hist, market, ppr, pass_td, idp, teams, slots):
    rows=[]
    for pid,p in players.items():
        rawpos=p.get("position")
        grp=canonical_position(rawpos)
        if grp not in ["QB","RB","WR","TE","K","DL","DB"] or p.get("active") is False: continue
        name=p.get("full_name") or " ".join([p.get("first_name") or "",p.get("last_name") or ""]).strip()
        if not name: continue
        rows.append({"id":str(pid),"player":name,"key":norm(name),"position":grp,"raw_position":rawpos,
                     "team":p.get("team") or "FA","age":p.get("age"),"exp":p.get("years_exp"),
                     "injury":p.get("injury_status")})
    b=pd.DataFrame(rows)
    if b.empty: return b

    if hist.empty:
        b["last_ppg"]=b.position.map({"QB":16,"RB":8.5,"WR":8,"TE":6,"K":8.5,"DL":6,"DB":5.5})
        b["prior_ppg"]=b.last_ppg*.9
        for c in ["opp_pg","td_rate_z","eff_z","growth_z","opp_z","idp_vol_z","bigplay_z"]:
            b[c]=0.
    else:
        h=hist.copy()
        if "position_group" not in h.columns:
            h["position_group"]=h["position"].map(position_group)
        yr=int(h.season.max())
        cur=h[h.season.eq(yr)].copy()
        prev=h[h.season.eq(yr-1)][["key","position_group","ppr_ppg"]].rename(columns={"ppr_ppg":"prior_off_ppg"})
        cur=cur.merge(prev,on=["key","position_group"],how="left")

        # Offensive features.
        cur["opp_pg"]=(cur.targets.fillna(0)+cur.carries.fillna(0))/cur.games
        touches=(cur.receptions.fillna(0)+cur.carries.fillna(0)).clip(lower=1)
        cur["td_rate"]=(cur.receiving_tds.fillna(0)+cur.rushing_tds.fillna(0))/touches
        cur["eff"]=(cur.receiving_yards.fillna(0)+cur.rushing_yards.fillna(0))/touches

        # IDP fantasy points using user scoring.
        cur["idp_points"]=(
            cur.def_tackles_solo.fillna(0)*idp["solo"]
            + cur.def_tackle_assists.fillna(0)*idp["assist"]
            + cur.def_sacks.fillna(0)*idp["sack"]
            + cur.def_tackles_for_loss.fillna(0)*idp["tfl"]
            + cur.def_qb_hits.fillna(0)*idp["qb_hit"]
            + cur.def_interceptions.fillna(0)*idp["int"]
            + cur.def_pass_defended.fillna(0)*idp["pd"]
            + cur.def_fumbles_forced.fillna(0)*idp["ff"]
            + cur.def_fumble_recovery_opp.fillna(0)*idp["fr"]
            + cur.def_tds.fillna(0)*idp["def_td"]
            + cur.def_safety.fillna(0)*idp["safety"]
        )
        cur["idp_ppg"]=cur.idp_points/cur.games
        cur["idp_volume"]=(cur.def_tackles_solo.fillna(0)+cur.def_tackle_assists.fillna(0)+
                           cur.def_sacks.fillna(0)*2+cur.def_pass_defended.fillna(0))/cur.games
        cur["bigplay_rate"]=(cur.def_sacks.fillna(0)+cur.def_interceptions.fillna(0)+
                             cur.def_fumbles_forced.fillna(0)+cur.def_tds.fillna(0))/cur.games

        # Prior IDP season from raw h.
        prv=h[h.season.eq(yr-1)].copy()
        prv["prior_idp_points"]=(
            prv.def_tackles_solo.fillna(0)*idp["solo"] + prv.def_tackle_assists.fillna(0)*idp["assist"]
            + prv.def_sacks.fillna(0)*idp["sack"] + prv.def_tackles_for_loss.fillna(0)*idp["tfl"]
            + prv.def_qb_hits.fillna(0)*idp["qb_hit"] + prv.def_interceptions.fillna(0)*idp["int"]
            + prv.def_pass_defended.fillna(0)*idp["pd"] + prv.def_fumbles_forced.fillna(0)*idp["ff"]
            + prv.def_fumble_recovery_opp.fillna(0)*idp["fr"] + prv.def_tds.fillna(0)*idp["def_td"]
            + prv.def_safety.fillna(0)*idp["safety"]
        )
        prv["prior_idp_ppg"]=prv.prior_idp_points/prv.games
        if "position_group" not in prv.columns:
            prv["position_group"]=prv["position"].map(position_group)
        cur=cur.merge(prv[["key","position_group","prior_idp_ppg"]],on=["key","position_group"],how="left")

        cur["last_ppg"]=np.where(cur.position.isin(["DL","DB"]),cur.idp_ppg,cur.ppr_ppg)
        cur["prior_ppg"]=np.where(cur.position.isin(["DL","DB"]),cur.prior_idp_ppg,cur.prior_off_ppg)
        cur["prior_ppg"]=pd.to_numeric(cur["prior_ppg"],errors="coerce")
        cur["prior_ppg"]=cur.prior_ppg.fillna(cur.last_ppg*.88)
        cur["growth"]=cur.last_ppg-cur.prior_ppg

        for c in ["td_rate","eff","growth","opp_pg","idp_volume","bigplay_rate"]:
            sd=cur[c].std()
            cur[c+"_z"]=(cur[c]-cur[c].median())/(sd if pd.notna(sd) and sd else 1)

        keep=["key","position_group","last_ppg","prior_ppg","opp_pg","td_rate_z","eff_z","growth_z","opp_pg_z",
              "idp_volume_z","bigplay_rate_z"]
        cur=cur[keep].rename(columns={"opp_pg_z":"opp_z","idp_volume_z":"idp_vol_z","bigplay_rate_z":"bigplay_z"})
        b=b.merge(cur,left_on=["key","position"],right_on=["key","position_group"],how="left")
        b.drop(columns=["position_group"],inplace=True,errors="ignore")

        base=b.position.map({"QB":16,"RB":8.5,"WR":8,"TE":6,"K":8.5,"DL":6,"DB":5.5})
        b["last_ppg"]=b.last_ppg.fillna(base)
        b["prior_ppg"]=b.prior_ppg.fillna(b.last_ppg*.9)
        for c in ["opp_pg","td_rate_z","eff_z","growth_z","opp_z","idp_vol_z","bigplay_z"]:
            b[c]=b[c].fillna(0)

    if market is not None and not market.empty:
        _market_cols=[c for c in ["key","consensus_pos","consensus_rank","consensus_rank_24h","consensus_rank_72h","consensus_page","consensus_updated_at"] if c in market.columns]
        b=b.merge(market[_market_cols],
                  left_on=["key","position"],right_on=["key","consensus_pos"],how="left")
        b.drop(columns=["consensus_pos"],inplace=True,errors="ignore")
    else:
        b["consensus_rank"]=np.nan
        b["consensus_page"]=""

    b["age"]=pd.to_numeric(b.age,errors="coerce")
    b["exp"]=pd.to_numeric(b.exp,errors="coerce").fillna(0)
    young=np.select([b.age<=22,b.age<=24,b.age<=26,b.age<=29],[16,12,7,2],default=-5)
    early=np.select([b.exp<=1,b.exp<=2,b.exp<=4],[10,7,3],default=0)

    is_idp=b.position.isin(["DL","DB"])
    # Offensive progression/regression.
    b["progression"]=50+b.growth_z*14+b.opp_z*11+young+early
    b["regression"]=50+b.td_rate_z*18+b.eff_z*10-b.opp_z*12
    # IDP: tackle/pressure volume is more repeatable; big-play spikes are more regression-prone.
    b.loc[is_idp,"progression"]=50+b.loc[is_idp,"growth_z"]*12+b.loc[is_idp,"idp_vol_z"]*15+young[is_idp]+early[is_idp]
    b.loc[is_idp,"regression"]=50+b.loc[is_idp,"bigplay_z"]*20-b.loc[is_idp,"idp_vol_z"]*12

    b["breakout"]=1/(1+np.exp(-(b.progression-55)/13))
    b["decline"]=1/(1+np.exp(-(b.regression-60)/12))

    # "Breakout" is reserved for genuinely ascending/early-career players.
    young_breakout=(b.age.fillna(99)<=26) & (b.exp<=4)
    b["profile"]="Stable / neutral"
    b.loc[b.decline>=.68,"profile"]="Decline risk"
    b.loc[(b.decline>=.50)&(b.decline<.68),"profile"]="High variance"
    b.loc[young_breakout & (b.breakout>=.67),"profile"]="Breakout target"
    b.loc[young_breakout & (b.breakout.between(.55,.67, inclusive="left")),"profile"]="Ascending"
    b.loc[(~young_breakout) & (b.breakout>=.65) & (b.decline<.50),"profile"]="Veteran upside"

    base=b.position.map({"QB":16,"RB":8.5,"WR":8,"TE":6,"K":8.5,"DL":6,"DB":5.5})
    b["projection"]=(b.last_ppg*.70+b.prior_ppg*.20+base*.10+b.growth_z*.50).clip(lower=1)

    # v9.50 kicker valuation: K has no nflverse fantasy-history feed in this build,
    # so do NOT leave every kicker at the same 8.5 projection.
    # Use the live market ordering already attached to the board as a conservative
    # relative projection proxy. This creates real separation without inventing a
    # player-name whitelist.
    _km=b.position.eq("K")
    if _km.any():
        # make_board has consensus_rank at this stage; market_pick is attached later.
        # Use consensus rank when available and fall back to deterministic row order.
        if "consensus_rank" in b.columns:
            _kmarket=pd.to_numeric(b.loc[_km,"consensus_rank"],errors="coerce")
        else:
            _kmarket=pd.Series(np.nan,index=b.index[_km],dtype=float)

        _fallback=pd.Series(
            np.arange(1,int(_km.sum())+1,dtype=float),
            index=b.index[_km]
        )
        # Missing K consensus values sort behind known market-ranked kickers.
        if _kmarket.notna().any():
            _max_known=float(_kmarket.max())
            _kmarket=_kmarket.fillna(_max_known + _fallback)
        else:
            _kmarket=_fallback

        _krank=_kmarket.rank(method="min",ascending=True,na_option="bottom")
        _kn=max(int(_km.sum()),1)
        _kpct=1.0-((_krank-1.0)/max(_kn-1,1))
        b.loc[_km,"projection"]=7.35 + 2.15*_kpct

    skill=b.position.isin(["RB","WR","TE"])
    b.loc[skill,"projection"] += (ppr-1.0)*np.clip(b.loc[skill,"opp_pg"]*.55,1,8)
    if pass_td!=4:
        qb=b.position.eq("QB"); b.loc[qb,"projection"] += (pass_td-4)*1.5

    b["draft_score"]=b.projection*5+b.progression*.18-b.regression*.12
    b["waiver_score"]=b.projection*4+b.progression*.23-b.regression*.10

    # Value Over Replacement Player (VORP): raw points above a realistic replacement starter.
    flex=float(slots.get("FLEX",0))
    # FLEX demand is distributed mostly to WR/RB in PPR, with a small TE share.
    replacement_slots={
        "QB":max(teams*int(slots.get("QB",1)),teams),
        "RB":max(int(round(teams*(float(slots.get("RB",2))+flex*.38))),teams),
        "WR":max(int(round(teams*(float(slots.get("WR",2))+flex*.55))),teams),
        "TE":max(int(round(teams*(float(slots.get("TE",1))+flex*.07))),teams),
        "K":max(teams*int(slots.get("K",1)),teams),
        "DL":max(teams*int(slots.get("DL",1)),teams),
        "DB":max(teams*int(slots.get("DB",1)),teams)
    }
    repl={}
    for pos,n in replacement_slots.items():
        vals=b.loc[b.position.eq(pos),"projection"].sort_values(ascending=False).reset_index(drop=True)
        idx=min(max(int(n)-1,0),len(vals)-1) if len(vals) else 0
        repl[pos]=float(vals.iloc[idx]) if len(vals) else 0.0
    b["replacement_ppg"]=b.position.map(repl).fillna(0)
    b["vorp"]=b.projection-b.replacement_ppg

    # v9.50: kicker VORP is position-relative, using the 12-team replacement line.
    # This prevents every K from displaying 0.0 VORP.
    _km=b.position.eq("K")
    if _km.any():
        _kvals=pd.to_numeric(b.loc[_km,"projection"],errors="coerce").sort_values(ascending=False)
        _krep_idx=min(max(int(teams)-1,0),len(_kvals)-1)
        _krep=float(_kvals.iloc[_krep_idx]) if len(_kvals) else 7.35
        b.loc[_km,"replacement_ppg"]=_krep
        b.loc[_km,"vorp"]=pd.to_numeric(b.loc[_km,"projection"],errors="coerce")-_krep

    # Pure model score before market consensus: this is where we intentionally disagree with consensus.
    scarcity=b.position.map({"QB":0.0,"RB":0.9,"WR":1.35,"TE":0.35,"K":-1.25,"DL":-0.35,"DB":-0.45}).fillna(0)
    b["pure_model_score"]=b.vorp*9+b.projection*1.6+b.progression*.12-b.regression*.10+scarcity
    b["model_rank"]=b.pure_model_score.rank(method="min",ascending=False)

    # Weekly-updated expert consensus acts as a reality check, not the engine.
    if b.consensus_rank.notna().any():
        maxrank=max(float(b.consensus_rank.max()),250.0)
        b["consensus_strength"]=(100*(1-np.log(b.consensus_rank.clip(lower=1))/np.log(maxrank))).clip(0,100)
    else:
        b["consensus_strength"]=50.0
    b["consensus_strength"]=b.consensus_strength.fillna(45.0)
    b["draft_score"]=b.pure_model_score+b.consensus_strength*.10
    b["consensus_edge"]=b.consensus_rank-b.model_rank

    # Confidence rises when we have history + consensus and falls with current injury flags.
    hist_conf=np.where(b.last_ppg.notna(),.20,0)
    market_conf=np.where(b.consensus_rank.notna(),.20,0)
    injury_pen=np.where(b.injury.fillna("").isin(["Out","IR","PUP"]),.25,0)
    agreement=np.where(b.consensus_rank.notna(), np.clip(1-np.abs(b.consensus_edge)/60,0,1)*.15, .05)
    b["confidence"]=(.40+hist_conf+market_conf+agreement-injury_pen).clip(.30,.95)
    # Stable identity guardrail: keep the canonical Sleeper position attached to each player ID.
    b["position"]=[validate_position(pl,pos) for pl,pos in zip(b.player,b.position)]
    b["identity_key"]=b["id"].astype(str)+"|"+b["position"].astype(str)
    return b.sort_values("draft_score",ascending=False).reset_index(drop=True)


def snake_pick(round_no, slot, teams):
    return (round_no-1)*teams + (slot if round_no % 2 else teams-slot+1)

def next_user_pick(current_overall, slot, teams, rounds):
    picks=[snake_pick(r,slot,teams) for r in range(1,rounds+1)]
    return next((p for p in picks if p>current_overall), None)

def survival_probability(consensus_rank, next_pick, randomness=12):
    if pd.isna(consensus_rank) or next_pick is None:
        return np.nan
    # Smooth probability that a player with consensus rank survives to a future pick.
    scale=max(float(randomness),4.0)
    z=(float(consensus_rank)-float(next_pick))/scale
    return float(1/(1+np.exp(-z)))


def survival_probability_array(market_pick, next_pick, randomness=12):
    """Probability a player remains available until our next snake-draft pick."""
    x=np.asarray(market_pick,dtype=float)
    if next_pick is None:
        return np.zeros_like(x,dtype=float)
    scale=max(float(randomness)*1.15,5.0)
    z=(x-float(next_pick))/scale
    return 1/(1+np.exp(-z))


def late_survival_probability_array_empirical(market_pick, next_pick, slot, round_no):
    """V7.54 challenger-only empirical R11+ survival lookup.

    Frozen from V7.53 calibration. Uses slot + round + market-minus-next-pick band,
    with clipping and simple backoff. This does NOT change the live V7.50 champion.
    """
    x=np.asarray(market_pick,dtype=float)
    if next_pick is None:
        return np.zeros_like(x,dtype=float)

    # Cell values are empirical rates from V7.53, clipped to avoid 0/1 certainty.
    # Keys: (slot, round, band), where band is deep (<-60), mid [-60,-40), other (>=-40).
    cell={
        (1,11,"deep"):.0761,(1,11,"mid"):.2500,
        (1,12,"deep"):.9500,(1,12,"mid"):.9500,
        (1,13,"deep"):.0700,
        (1,14,"mid"):.9500,(1,14,"other"):.9500,

        (3,11,"deep"):.1071,(3,11,"mid"):.2667,
        (3,12,"deep"):.6316,(3,12,"mid"):.7500,(3,12,"other"):.0500,
        (3,13,"deep"):.0800,
        (3,14,"mid"):.9500,

        (7,11,"deep"):.5000,(7,11,"mid"):.4167,
        (7,12,"deep"):.2041,(7,12,"other"):.0500,
        (7,13,"deep"):.2700,
        (7,14,"deep"):.9500,

        (12,11,"mid"):.9500,
        (12,12,"deep"):.0500,
        (12,13,"deep"):.9500,(12,13,"mid"):.9500,
        (12,14,"deep"):.9500,
    }

    # Slot-round backoff from V7.53.
    sr={
        (1,11):.0900,(1,12):.9500,(1,13):.0700,(1,14):.9500,
        (3,11):.1313,(3,12):.6300,(3,13):.0800,(3,14):.9500,
        (7,11):.4200,(7,12):.2020,(7,13):.2700,(7,14):.9500,
        (12,11):.9500,(12,12):.0500,(12,13):.9500,(12,14):.9500,
    }

    # Global distance-band backoff from V7.53.
    gb={"deep":.4191,"mid":.8560,"other":.2500}

    d=x-float(next_pick)
    out=np.zeros_like(x,dtype=float)
    for i,val in enumerate(d):
        if not np.isfinite(val):
            out[i]=.50
            continue
        band="deep" if val < -60 else "mid" if val < -40 else "other"
        key=(int(slot),int(round_no),band)
        if key in cell:
            p=cell[key]
        elif (int(slot),int(round_no)) in sr:
            # Blend slot-round backoff with global distance behavior.
            p=.70*sr[(int(slot),int(round_no))]+.30*gb[band]
        else:
            p=gb[band]
        out[i]=float(np.clip(p,.05,.95))
    return out


def execution_choice_with_survival(eval_score, market_pick, current_pick, next_pick, survival):
    """Same V7.50 execution architecture, but supplied a calibrated survival array."""
    ev=np.asarray(eval_score,dtype=float)
    mp=np.asarray(market_pick,dtype=float)
    surv=np.asarray(survival,dtype=float)
    reach=np.maximum(mp-float(current_pick),0)
    fall=np.maximum(float(current_pick)-mp,0)
    ready=(fall>=5) | (reach<6) | (surv<.50) | np.isnan(mp)

    n=min(24,len(ev))
    if n<=0:
        return None,ready,surv
    top=np.argpartition(-ev,n-1)[:n] if n<len(ev) else np.arange(len(ev))
    ready_top=top[ready[top]]
    if len(ready_top):
        j=int(ready_top[np.argmax(ev[ready_top]+.035*fall[ready_top])])
        return j,ready,surv

    timing_cost=surv[top]*np.minimum(reach[top],36.0)*.42
    j=int(top[np.argmax(ev[top]-timing_cost)])
    return j,ready,surv


def market_timing_state(market_pick,current_pick,next_pick,randomness=12):
    """Execution state. Player evaluation is handled separately from pick timing."""
    if pd.isna(market_pick):
        return "DRAFT NOW",np.nan
    mp=float(market_pick); cur=float(current_pick)
    surv=survival_probability(mp,next_pick,randomness)
    if cur-mp >= 5:
        return "VALUE FALLER",surv
    reach=mp-cur
    # If we are meaningfully ahead of market and the target is more likely than not
    # to make it back, preserve the target rather than spending this pick early.
    if next_pick is not None and reach>=6 and pd.notna(surv) and surv>=.50:
        return "WAIT / TARGET NEXT PICK",surv
    return "DRAFT NOW",surv


def execution_choice(eval_score, market_pick, current_pick, next_pick, randomness=12):
    """Choose who to draft NOW without changing the underlying player evaluation.

    The model's favorite players remain model targets. Pick execution selects the
    highest-evaluated target whose market window is open. If every good target is a
    WAIT, it chooses the least-cost early pick instead of blindly reaching for #1.
    """
    ev=np.asarray(eval_score,dtype=float)
    mp=np.asarray(market_pick,dtype=float)
    surv=survival_probability_array(mp,next_pick,randomness)
    reach=np.maximum(mp-float(current_pick),0)
    fall=np.maximum(float(current_pick)-mp,0)
    ready=(fall>=5) | (reach<6) | (surv<.50) | np.isnan(mp)
    # Only compare realistic model targets, not the full player universe.
    n=min(24,len(ev))
    if n<=0: return None,ready,surv
    top=np.argpartition(-ev,n-1)[:n] if n<len(ev) else np.arange(len(ev))
    ready_top=top[ready[top]]
    if len(ready_top):
        # Evaluation controls the selection among players whose timing window is open.
        j=int(ready_top[np.argmax(ev[ready_top]+.035*fall[ready_top])])
        return j,ready,surv
    # Emergency fallback: all top targets are early. Pay the smallest timing cost
    # while still respecting model evaluation.
    timing_cost=surv[top]*np.minimum(reach[top],36.0)*.42
    j=int(top[np.argmax(ev[top]-timing_cost)])
    return j,ready,surv


def dynamic_faller_threshold(current_pick, teams=12, rounds=15):
    """Round-aware minimum market fall required for a Faller Intercept.

    Early rounds protect elite model conviction.
    Middle rounds become progressively more willing to harvest market value.
    Late rounds aggressively capture model-compatible fallers.
    """
    teams=max(int(teams),1)
    round_no=max(1,int((int(current_pick)-1)//teams)+1)
    if round_no<=3:
        return 14.0, 12, 8.0   # frozen V7.15 early-round rule
    if round_no<=6:
        # V7.16 surgical mid-round discipline: modestly widen the model-compatible
        # band and lower the fall/improvement thresholds without becoming ADP-led.
        return 9.0, 18, 4.0
    if round_no<=10:
        return 8.0, 18, 4.0    # frozen V7.15 R7-10 rule
    # Frozen V7.15 late-round value harvest.
    return 4.0, 28, 2.0


def early_wr_scarcity_choice(eval_score, market_pick, position_code, current_pick, next_pick, normal_choice, teams=12, randomness=12, max_eval_deficit=10.0, max_wr_survival=.52):
    """R1-3 only: scarce market-priority WR intercept; underlying evaluation stays frozen."""
    ev=np.asarray(eval_score,dtype=float); mp=np.asarray(market_pick,dtype=float); pc=np.asarray(position_code,dtype=int)
    normal=int(normal_choice); rnd=max(1,int((int(current_pick)-1)//max(int(teams),1))+1)
    diag={"wr_scarcity":False,"wr_survival":np.nan,"eval_deficit":np.nan,"market_advantage":np.nan,"wr_index":None}
    if rnd>3 or next_pick is None or len(ev)==0 or pc[normal]==2: return normal,False,diag
    wr=np.flatnonzero(pc==2)
    if not len(wr): return normal,False,diag
    wi=int(wr[np.argmax(ev[wr])]); deficit=float(ev[normal]-ev[wi])
    wmp=float(mp[wi]) if np.isfinite(mp[wi]) else np.nan; nmp=float(mp[normal]) if np.isfinite(mp[normal]) else np.nan
    surv=survival_probability(wmp,next_pick,randomness) if np.isfinite(wmp) else np.nan
    adv=nmp-wmp if np.isfinite(nmp) and np.isfinite(wmp) else np.nan
    diag.update({"wr_survival":surv,"eval_deficit":deficit,"market_advantage":adv,"wr_index":wi})
    if pd.isna(surv) or surv>max_wr_survival or deficit>max_eval_deficit or pd.isna(adv) or adv<0: return normal,False,diag
    diag["wr_scarcity"]=True
    return wi,True,diag


def late_slot_wr_conflict_choice(eval_score, market_pick, position_code, draft_score, vorp,
                                current_pick, next_pick, normal_choice, draft_slot,
                                teams=12, randomness=12, enabled=False,
                                max_eval_deficit=8.0, max_wr_survival=.35,
                                min_draftscore_advantage=.5, require_vorp_driver=True,
                                eligible_slots=(7,12)):
    """R4-6, Picks 7/12 only: diagnostic WR conflict intercept.

    The live champion never calls this with enabled=True. A calibration variant may
    replace an RB/TE normal choice with the best evaluated WR only when:
    - draft slot is 7 or 12
    - round is 4-6
    - normal choice is RB or TE
    - WR is within a controlled FE evaluation deficit
    - WR has low survival probability to next pick
    - selected RB/TE's player/draft-score advantage is positive
    - VORP contribution to that player-score advantage is positive
    """
    ev=np.asarray(eval_score,dtype=float)
    mp=np.asarray(market_pick,dtype=float)
    pc=np.asarray(position_code,dtype=int)
    ds=np.asarray(draft_score,dtype=float)
    vp=np.asarray(vorp,dtype=float)
    normal=int(normal_choice)
    rnd=max(1,int((int(current_pick)-1)//max(int(teams),1))+1)

    diag={
        "ls_wr_intercept":False,"wr_index":None,"eval_deficit":np.nan,
        "wr_survival":np.nan,"draftscore_advantage":np.nan,
        "vorp_component_advantage":np.nan
    }
    if (not enabled) or int(draft_slot) not in list(eligible_slots) or rnd<4 or rnd>6:
        return normal,False,diag
    if normal<0 or normal>=len(ev) or pc[normal] not in [1,3]:
        return normal,False,diag

    wr=np.flatnonzero(pc==2)
    if not len(wr):
        return normal,False,diag

    wi=int(wr[np.argmax(ev[wr])])
    deficit=float(ev[normal]-ev[wi])
    wmp=float(mp[wi]) if np.isfinite(mp[wi]) else np.nan
    surv=survival_probability(wmp,next_pick,randomness) if np.isfinite(wmp) else np.nan

    # Exact FE-evaluation contribution from player/draft score.
    ds_adv=.38*float(ds[normal]-ds[wi])
    # VORP is weighted 9x in the frozen champion, then 0.38 in pick evaluation.
    vorp_adv=.38*9.0*float(vp[normal]-vp[wi])

    diag.update({
        "wr_index":wi,"eval_deficit":deficit,"wr_survival":surv,
        "draftscore_advantage":ds_adv,"vorp_component_advantage":vorp_adv
    })

    if pd.isna(surv) or surv>float(max_wr_survival):
        return normal,False,diag
    if deficit>float(max_eval_deficit):
        return normal,False,diag
    if ds_adv<float(min_draftscore_advantage):
        return normal,False,diag
    if require_vorp_driver and vorp_adv<=0:
        return normal,False,diag

    diag["ls_wr_intercept"]=True
    return wi,True,diag


def pick12_faller_activation_snapshot(eval_score, market_pick, position_code, current_pick, next_pick, normal_choice,
                                       randomness=12, min_fall=7.0, max_eval_deficit=8.0,
                                       min_normal_reach=4.0, max_normal_survival=.55):
    ev=np.asarray(eval_score,dtype=float); mp=np.asarray(market_pick,dtype=float); pos=np.asarray(position_code)
    normal=int(normal_choice)
    out={"rbte":False,"reach_pass":False,"faller_exists":False,"eval_pass":False,"survival_pass":False,
         "full_trigger":False,"trigger_no_survival":False,"trigger_no_reach":False,
         "normal_reach":np.nan,"normal_survival":np.nan,"best_faller_amount":np.nan,
         "best_faller_eval_deficit":np.nan,"best_faller_position":"","best_faller_market_pick":np.nan}
    if len(ev)==0 or normal_choice is None: return out
    if int(pos[normal]) not in [1,3]: return out
    out["rbte"]=True
    nr=max(float(mp[normal])-float(current_pick),0.0) if np.isfinite(mp[normal]) else 0.0
    ns=survival_probability(float(mp[normal]),next_pick,randomness) if np.isfinite(mp[normal]) else np.nan
    out["normal_reach"]=nr; out["normal_survival"]=ns
    out["reach_pass"]=bool(nr>=float(min_normal_reach))
    fall=np.maximum(float(current_pick)-mp,0.0)
    raw=np.flatnonzero(np.isfinite(mp) & (fall>=float(min_fall)))
    out["faller_exists"]=bool(len(raw))
    if len(raw):
        # best market faller first, then report whether it is model-compatible
        fi=int(raw[int(np.argmax(fall[raw]))])
        deficit=max(float(ev[normal]-ev[fi]),0.0)
        out["best_faller_amount"]=float(fall[fi])
        out["best_faller_eval_deficit"]=deficit
        out["best_faller_position"]={0:"QB",1:"RB",2:"WR",3:"TE"}.get(int(pos[fi]),str(int(pos[fi])))
        out["best_faller_market_pick"]=float(mp[fi])
        compatible=raw[(float(np.nanmax(ev))-ev[raw])<=float(max_eval_deficit)]
        out["eval_pass"]=bool(len(compatible))
    out["survival_pass"]=bool(pd.notna(ns) and float(ns)<=float(max_normal_survival))
    out["full_trigger"]=bool(out["rbte"] and out["reach_pass"] and out["faller_exists"] and out["eval_pass"] and out["survival_pass"])
    out["trigger_no_survival"]=bool(out["rbte"] and out["reach_pass"] and out["faller_exists"] and out["eval_pass"])
    out["trigger_no_reach"]=bool(out["rbte"] and out["faller_exists"] and out["eval_pass"] and out["survival_pass"])
    return out


def pick12_faller_need_choice(eval_score, market_pick, position_code, current_pick, next_pick, normal_choice,
                              teams=12, randomness=12, enabled=False, min_fall=7.0,
                              max_eval_deficit=8.0, min_normal_reach=4.0, max_normal_survival=.55):
    """Calibration-only Pick-12 R4-6 faller-vs-need execution rule.

    It does not prefer WR by position. It may take the best model-compatible market
    faller before a normal RB/TE reach when the RB/TE still has a reasonable chance
    to survive to the next Pick-12 turn.
    """
    ev=np.asarray(eval_score,dtype=float); mp=np.asarray(market_pick,dtype=float)
    pos=np.asarray(position_code)
    normal=int(normal_choice)
    diag={"trigger":False,"faller_index":None,"faller_amount":0.0,"eval_deficit":np.nan,
          "normal_reach":0.0,"normal_survival":np.nan}
    if not enabled or normal_choice is None or len(ev)==0:
        return normal,False,diag
    rnd=max(1,int((int(current_pick)-1)//max(int(teams),1))+1)
    if rnd<4 or rnd>6 or int(pos[normal]) not in [1,3]:
        return normal,False,diag

    normal_reach=max(float(mp[normal])-float(current_pick),0.0) if np.isfinite(mp[normal]) else 0.0
    normal_surv=survival_probability(float(mp[normal]),next_pick,randomness) if np.isfinite(mp[normal]) else np.nan
    diag["normal_reach"]=normal_reach; diag["normal_survival"]=normal_surv
    if normal_reach<float(min_normal_reach):
        return normal,False,diag
    if pd.isna(normal_surv) or float(normal_surv)>float(max_normal_survival):
        return normal,False,diag

    fall=np.maximum(float(current_pick)-mp,0.0)
    valid=np.isfinite(mp) & (fall>=float(min_fall))
    if not np.any(valid):
        return normal,False,diag

    # Keep the faller model-compatible; no positional forcing.
    best=float(np.nanmax(ev))
    valid &= (best-ev)<=float(max_eval_deficit)
    cand=np.flatnonzero(valid)
    if not len(cand):
        return normal,False,diag

    # Prioritize open draft-window value, then FE evaluation.
    score=.55*fall[cand] + .45*(ev[cand]-best)
    fi=int(cand[int(np.argmax(score))])
    deficit=max(float(ev[normal]-ev[fi]),0.0)
    diag.update({"faller_index":fi,"faller_amount":float(fall[fi]),"eval_deficit":deficit})
    if fi==normal or deficit>float(max_eval_deficit):
        return normal,False,diag

    diag["trigger"]=True
    return fi,True,diag


def faller_intercept_choice(eval_score, market_pick, current_pick, normal_choice,
                            teams=12, rounds=15, min_fall=None, model_band=None,
                            improvement_required=None):
    """Dynamic, model-compatible market faller override.

    The threshold changes by draft stage rather than using one fixed rule.
    A faller still must remain inside Fantasy Edge's model-compatible target band.
    """
    ev=np.asarray(eval_score,dtype=float)
    mp=np.asarray(market_pick,dtype=float)
    if len(ev)==0 or normal_choice is None:
        return normal_choice,False,0.0

    auto_min,auto_band,auto_improve=dynamic_faller_threshold(current_pick,teams,rounds)
    min_fall=float(auto_min if min_fall is None else min_fall)
    model_band=int(auto_band if model_band is None else model_band)
    improvement_required=float(auto_improve if improvement_required is None else improvement_required)

    fall=np.maximum(float(current_pick)-mp,0)
    valid=np.isfinite(mp) & (fall>=min_fall)
    normal=int(normal_choice)
    normal_fall=float(fall[normal]) if np.isfinite(fall[normal]) else 0.0

    if not np.any(valid):
        return normal,False,normal_fall

    n=min(model_band,len(ev))
    top=np.argpartition(-ev,n-1)[:n] if n<len(ev) else np.arange(len(ev))
    cand=top[valid[top]]
    if len(cand)==0:
        return normal,False,normal_fall

    # Model compatibility remains important, but larger fallers gain increasingly
    # more weight instead of all fallers above the minimum being treated similarly.
    ev_top=ev[top]
    spread=max(float(np.nanstd(ev_top)),1.0)
    best_eval=float(np.nanmax(ev_top))
    compatibility=(ev[cand]-best_eval)/spread

    excess=np.maximum(fall[cand]-min_fall,0)
    round_no=max(1,int((int(current_pick)-1)//max(int(teams),1))+1)
    if round_no>=11:
        # Frozen V7.15 late-round harvest scoring.
        fall_value=.46*fall[cand] + .055*(excess**1.40)
        intercept_score=fall_value + 1.45*compatibility
    elif 4<=round_no<=6:
        # V7.16: modest mid-round value boost, still keeping model compatibility
        # stronger than in late rounds.
        fall_value=.36*fall[cand] + .040*(excess**1.35)
        intercept_score=fall_value + 1.85*compatibility
    else:
        # Frozen V7.15 behavior for R1-3 and R7-10.
        fall_value=.32*fall[cand] + .035*(excess**1.35)
        intercept_score=fall_value + 2.0*compatibility
    best_cand=int(cand[int(np.argmax(intercept_score))])

    # Require the faller to improve market value enough over the normal execution
    # choice for the current draft stage.
    round_no=max(1,int((int(current_pick)-1)//max(int(teams),1))+1)
    if round_no>=11:
        normal_reach=max(float(mp[normal])-float(current_pick),0) if np.isfinite(mp[normal]) else 0.0
        required=max(min_fall,normal_fall+improvement_required)
        # Frozen V7.15 late-round anti-reach safeguard.
        if normal_reach>=4.0:
            required=min_fall
        if float(fall[best_cand]) >= required:
            return best_cand,True,float(fall[best_cand])
    elif 4<=round_no<=6:
        # V7.16 mid-round anti-reach safeguard: weaker than late rounds.
        # If the normal choice is a 6+ pick reach and a model-compatible 9+ pick
        # faller exists, the faller only needs to clear the normal R4-6 threshold.
        normal_reach=max(float(mp[normal])-float(current_pick),0) if np.isfinite(mp[normal]) else 0.0
        required=max(min_fall,normal_fall+improvement_required)
        if normal_reach>=6.0:
            required=min_fall
        if float(fall[best_cand]) >= required:
            return best_cand,True,float(fall[best_cand])
    else:
        # Frozen V7.15 behavior for R1-3 and R7-10.
        if float(fall[best_cand]) >= max(min_fall,normal_fall+improvement_required):
            return best_cand,True,float(fall[best_cand])
    return normal,False,normal_fall
def roster_need_for_mock(roster_df, pos, slots):
    """Marginal roster value: each additional player is worth less once usable depth is filled."""
    counts=roster_df.position.value_counts().to_dict() if len(roster_df) else {}
    have=int(counts.get(pos,0))
    direct=max(int(slots.get(pos,0))-have,0)
    flex_used=max(0,sum(counts.get(p,0) for p in ["RB","WR","TE"])-
                    sum(int(slots.get(p,0)) for p in ["RB","WR","TE"]))
    flex_need=max(int(slots.get("FLEX",0))-flex_used,0)

    if direct>0:
        base=11.0+min(direct,2)*2.0
        if pos=="WR": base+=2.0
        return base

    if pos=="WR":
        if flex_need>0: return 8.0
        if have==2: return 6.0
        if have==3: return 4.0
        if have==4: return 0.5
        return -5.0
    if pos=="RB":
        if flex_need>0 and have<3: return 5.0
        if have==2: return 3.0
        if have==3: return 0.5
        if have==4: return -3.5
        return -10.0
    if pos=="TE": return -10.0 if have>=1 else 0.0
    if pos=="QB": return -14.0 if have>=1 else 0.0
    if pos in ["DL","DB"]:
        return -12.0 if have>=int(slots.get(pos,1)) else -1.0
    return -3.0

def _small_roster_utility_df(roster, slots):
    """Expected final-roster utility for a small drafted roster DataFrame.

    Starters receive full value, FLEX receives near-starter value, and bench players
    receive diminishing insurance/upside value. This evaluates the players actually
    on the roster rather than prescribing a fixed QB/RB/WR/TE bench recipe.
    """
    if roster is None or len(roster)==0:
        return 0.0
    r=roster.copy()
    r["_base_value"]=r["projection"].fillna(0)+0.70*r["vorp"].fillna(0).clip(lower=-5)
    used=set(); total=0.0
    # Required position starters.
    for pos in ["QB","RB","WR","TE","DL","DB"]:
        n=max(int(slots.get(pos,0)),0)
        px=r[r.position.eq(pos)].sort_values("_base_value",ascending=False)
        for idx,row in px.head(n).iterrows():
            used.add(idx)
            total += float(row.projection)*1.00 + float(row.vorp)*0.90
    # FLEX from remaining RB/WR/TE.
    flex_n=max(int(slots.get("FLEX",0)),0)
    flex=r[(~r.index.isin(used)) & r.position.isin(["RB","WR","TE"])].sort_values("_base_value",ascending=False)
    for idx,row in flex.head(flex_n).iterrows():
        used.add(idx)
        total += float(row.projection)*0.92 + float(row.vorp)*0.75
    # Bench: value depends on actual player quality with diminishing depth utility.
    bench=r[~r.index.isin(used)].sort_values("_base_value",ascending=False)
    depth={"QB":0,"RB":0,"WR":0,"TE":0,"DL":0,"DB":0}
    bench_mult={"QB":[.14,.03],"RB":[.25,.15,.08,.03],"WR":[.40,.30,.20,.11,.06],
                "TE":[.16,.04],"DL":[.06],"DB":[.06]}
    for _,row in bench.iterrows():
        p=row.position; d=depth.get(p,0); arr=bench_mult.get(p,[.05])
        mult=arr[d] if d<len(arr) else .02
        total += mult*(float(row.projection)+0.55*max(float(row.vorp),0))
        depth[p]=d+1
    return float(total)


def _candidate_roster_delta_df(roster, candidates, slots, exact_cap=72):
    """Fast V7.3 marginal roster utility with bounded exact evaluation."""
    if candidates is None or len(candidates)==0:
        return np.array([],dtype=float)
    current=_small_roster_utility_df(roster,slots)
    c=candidates
    proj=pd.to_numeric(c["projection"],errors="coerce").fillna(0).to_numpy(float)
    vorp=pd.to_numeric(c["vorp"],errors="coerce").fillna(0).to_numpy(float)
    ds=pd.to_numeric(c["draft_score"],errors="coerce").fillna(-1e9).to_numpy(float)
    cr=pd.to_numeric(c["consensus_rank"],errors="coerce").fillna(999).to_numpy(float)
    approx=.10*proj+.08*np.maximum(vorp,0)
    out=approx.copy()
    n=min(int(exact_cap),len(c))
    k1=max(1,n//3); k2=max(1,n//3)
    a=np.argpartition(-ds,min(k1-1,len(ds)-1))[:k1]
    b=np.argpartition(cr,min(k2-1,len(cr)-1))[:k2]
    pi=[]; posarr=c["position"].astype(str).to_numpy()
    per=max(2,n//18)
    for pname in ["QB","RB","WR","TE","DL","DB"]:
        loc=np.flatnonzero(posarr==pname)
        if loc.size:
            take=min(per,loc.size)
            best=loc[np.argpartition(-ds[loc],min(take-1,loc.size-1))[:take]]
            pi.extend(best.tolist())
    short=np.unique(np.concatenate([a,b,np.asarray(pi,dtype=int)]))
    if len(short)>n:
        composite=(-ds[short])+0.05*cr[short]
        short=short[np.argsort(composite)[:n]]
    for j in short:
        row=c.iloc[int(j)]
        temp=pd.concat([roster,row.to_frame().T],ignore_index=True) if len(roster) else row.to_frame().T
        out[int(j)]=_small_roster_utility_df(temp,slots)-current
    return out
def _minimum_required_picks_remaining(counts, slots):
    """Minimum picks needed to complete fixed starters plus FLEX."""
    fixed_positions=["QB","RB","WR","TE","K","DL","DB"]
    fixed_def={p:max(int(slots.get(p,0))-int(counts.get(p,0)),0) for p in fixed_positions}

    required_skill=(
        int(slots.get("RB",0))+int(slots.get("WR",0))+int(slots.get("TE",0))+
        int(slots.get("FLEX",0))
    )
    have_skill=int(counts.get("RB",0))+int(counts.get("WR",0))+int(counts.get("TE",0))
    fixed_skill_def=fixed_def["RB"]+fixed_def["WR"]+fixed_def["TE"]
    flex_extra=max(required_skill-have_skill-fixed_skill_def,0)
    return int(sum(fixed_def.values())+flex_extra), fixed_def, int(flex_extra)


def _candidate_keeps_roster_feasible(roster, candidate_pos, round_no, rounds, slots):
    counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    after=dict(counts)
    after[candidate_pos]=int(after.get(candidate_pos,0))+1
    remaining_after=max(int(rounds)-int(round_no),0)
    minimum_after,_,_=_minimum_required_picks_remaining(after,slots)
    return minimum_after<=remaining_after


def draft_eligibility(avail, roster, round_no, rounds, slots):
    """Hard legality plus mathematical end-of-draft roster feasibility."""
    a=avail.copy()
    counts=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}

    qb=int(counts.get("QB",0)); te=int(counts.get("TE",0))
    dl=int(counts.get("DL",0)); db=int(counts.get("DB",0)); k=int(counts.get("K",0))
    total_idp=dl+db

    # Required-position depletion guard. If an unfilled required position is down
    # to two available players, take that requirement now rather than risk a
    # mathematically legal but practically impossible late roster.
    _required_open=[
        p for p in ["QB","RB","WR","TE","K","DL","DB"]
        if int(counts.get(p,0)) < int(slots.get(p,0))
    ]
    _critical=[]
    for _p in _required_open:
        _n=int((a["position"].astype(str)==_p).sum())
        if 0 < _n <= 2:
            _critical.append((_n,_p))
    if _critical:
        _critical.sort()
        _critical_pos=_critical[0][1]
        _critical_pool=a[a["position"].astype(str).eq(_critical_pos)]
        if len(_critical_pool):
            a=_critical_pool.copy()

    # Allow normal depth, including exactly one extra impact IDP.
    if int(slots.get("QB",1))<=1 and qb>=2:
        a=a[~a.position.eq("QB")]
    if int(slots.get("TE",1))<=1 and te>=2:
        a=a[~a.position.eq("TE")]
    if dl>=2:
        a=a[~a.position.eq("DL")]
    if db>=2:
        a=a[~a.position.eq("DB")]
    # Required starters are 1 DL + 1 DB. Allow at most ONE extra impact defender.
    if total_idp>=3:
        a=a[~a.position.isin(["DL","DB"])]
    if k>=max(int(slots.get("K",1)),1):
        a=a[~a.position.eq("K")]

    # V6.38: Never hard-hide required IDP positions from Live/Mock candidate pools.
    # Older builds removed every DL/DB through round 7 whenever enough offensive
    # players remained. That made the Position=DB/DL tables appear empty and
    # prevented the engine from considering an elite defender. Early-IDP timing
    # is already handled by the scoring/opportunity penalties downstream, so keep
    # defenders visible and let the model rank them rather than deleting them.

    # Candidate-level feasibility. A pick is illegal if it leaves too few future
    # picks to finish all required starters and both FLEX slots.
    if len(a):
        feasible=a["position"].map(
            lambda p:_candidate_keeps_roster_feasible(
                roster,str(p),int(round_no),int(rounds),slots
            )
        )
        a=a[feasible].copy()

    # Exact completion boundary: only a pick that reduces the minimum remaining
    # requirement may be selected.
    minimum_now,_,_=_minimum_required_picks_remaining(counts,slots)
    picks_left=int(rounds)-int(round_no)+1
    if len(a) and minimum_now>0 and picks_left<=minimum_now:
        reducers=[]
        for ix,row in a.iterrows():
            after=dict(counts)
            p=str(row.position)
            after[p]=int(after.get(p,0))+1
            after_min,_,_=_minimum_required_picks_remaining(after,slots)
            if after_min<minimum_now:
                reducers.append(ix)
        # Exact completion boundary: if no candidate reduces the remaining requirement,
        # there is no legal candidate.
        a=a.loc[reducers].copy()

    # Late-bench diversification authority.
    # Once the core offense is deep (5 RB + 5 WR) and required starters are covered,
    # reserve a remaining bench opportunity for a qualifying impact DL/DB.
    counts_now=roster.position.value_counts().to_dict() if roster is not None and len(roster) else {}
    core_filled=(
        int(counts_now.get("QB",0))>=int(slots.get("QB",1)) and
        int(counts_now.get("RB",0))>=int(slots.get("RB",2)) and
        int(counts_now.get("WR",0))>=int(slots.get("WR",2)) and
        int(counts_now.get("TE",0))>=int(slots.get("TE",1)) and
        int(counts_now.get("DL",0))>=int(slots.get("DL",1)) and
        int(counts_now.get("DB",0))>=int(slots.get("DB",1))
    )
    deep_offense=(int(counts_now.get("RB",0))>=5 and int(counts_now.get("WR",0))>=5)
    total_idp=int(counts_now.get("DL",0))+int(counts_now.get("DB",0))
    if core_filled and deep_offense and total_idp<3 and len(a):
        # Do not hard-force a defender here; scorer will require actual impact quality.
        # But prevent both RB6 and WR6 from consuming the final diversification window.
        picks_left=int(rounds)-int(round_no)+1
        if picks_left<=3:
            a=a[~((a.position.eq("RB")) | (a.position.eq("WR")))].copy() if a.position.isin(["DL","DB"]).any() else a

    # If all required starters/FLEX are already complete, soft depth/saturation
    # rules are not allowed to create an empty candidate set. Rebuild from the
    # original available pool using only true roster hard caps.
    if len(a)==0:
        minimum_now,_,_=_minimum_required_picks_remaining(counts,slots)
        if minimum_now==0:
            a=avail.copy()
            if int(slots.get("QB",1))<=1 and qb>=2:
                a=a[~a.position.eq("QB")]
            if int(slots.get("TE",1))<=1 and te>=2:
                a=a[~a.position.eq("TE")]
            if total_idp>=3:
                a=a[~a.position.isin(["DL","DB"])]
            if k>=max(int(slots.get("K",1)),1):
                a=a[~a.position.eq("K")]

    return a


def grade_mock(roster, teams, slots):
    def _gnum(name, default=0.0):
        if name in roster.columns:
            return pd.to_numeric(roster[name],errors="coerce").fillna(float(default))
        return pd.Series(float(default),index=roster.index,dtype=float)
    """Grade the mock on *realized* draft advantage, not a cosmetic score boost.

    v9.42 changes:
    - Honors the exact league: 1 TE is required; FLEX may also use RB/WR/TE.
    - Model Edge measures what the draft actually captured: market value at cost, model conviction
      at cost, VORP/projection quality, and roster construction.
    - DL/DB rows with obviously non-comparable global model ranks no longer poison Model Edge;
      shallow-IDP quality is judged by projection/market support and the shared IDP authority layer.
    - Reaches are penalized asymmetrically; falling past market is rewarded but capped so one late
      pick cannot inflate the entire grade.
    """
    if roster is None or len(roster)==0:
        return {"score":0,"grade":"F","starter":0,"value":0,"penalty":100,
                "draft_value":0,"construction":0,"positional_advantage":0,
                "model_edge_score":0,"opportunity_penalty":0}

    r=roster.copy()
    for c in ["projection","vorp","model_rank","consensus_rank","mock_pick"]:
        if c in r.columns: r[c]=pd.to_numeric(r[c],errors="coerce")
    counts=r.position.value_counts().to_dict()

    # Exact required starters: TE is required in this league.
    req={p:max(int(slots.get(p,d)),0) for p,d in
         {"QB":1,"RB":2,"WR":2,"TE":1,"K":1,"DL":1,"DB":1}.items()}
    flex_n=max(int(slots.get("FLEX",0)),0)

    # Realized market value: positive means we drafted the player AFTER consensus cost.
    # Reaches hurt faster than fallers help; both are capped for robustness.
    if "mock_pick" in r.columns:
        market_delta=r.mock_pick-r.consensus_rank
    else:
        market_delta=r.consensus_rank-r.model_rank
    market_delta=market_delta.where(r.consensus_rank.notna())
    market_points=np.where(market_delta.notna(),
        np.where(market_delta>=0, np.minimum(market_delta,36.0)*0.42,
                 np.maximum(market_delta,-30.0)*0.62), 0.0)

    # Model conviction realized at cost. Global offensive ranks are useful here, but the legacy
    # DL/DB global rank scale is not comparable (e.g. quality IDPs can be rank 500+ / 2000+).
    # For IDP, use market-supported positional quality rather than that broken cross-position rank.
    model_delta=(r.mock_pick-r.model_rank) if "mock_pick" in r.columns else (r.consensus_rank-r.model_rank)
    is_idp=r.position.isin(["DL","DB"])
    valid_model=(~is_idp) & r.model_rank.notna() & (r.model_rank<400)
    conviction=np.zeros(len(r),dtype=float)
    md=model_delta.to_numpy(dtype=float)
    vm=valid_model.to_numpy(dtype=bool)
    conviction[vm]=np.where(md[vm]>=0,np.minimum(md[vm],42.0)*0.24,np.maximum(md[vm],-35.0)*0.34)

    # Player-quality support: VORP is the primary cross-position signal. Projection adds a small
    # within-roster quality signal; IDP zero-VORP is neutral rather than an automatic failure.
    vorp=r.vorp.fillna(0).clip(-3,12)

    # Use roster-adjusted usable VORP when available so RB6/WR6/QB2 do not inflate Model Edge.
    if "usable_vorp" in r.columns:
        usable_vorp=pd.to_numeric(r["usable_vorp"],errors="coerce").fillna(vorp).clip(-3,12)
    else:
        usable_vorp=vorp
    vorp_points=(usable_vorp*0.72).to_numpy(dtype=float)
    proj=r.projection.fillna(0)
    quality=np.zeros(len(r),dtype=float)
    off=(~is_idp).to_numpy(dtype=bool)
    quality[off]=np.clip((proj.to_numpy(dtype=float)[off]-10.0)*0.12,-1.0,1.6)
    # Shallow IDP: reward credible market support + usable projection, without inventing VORP.
    idpm=is_idp.to_numpy(dtype=bool)
    cr=r.consensus_rank.to_numpy(dtype=float)
    pr=proj.to_numpy(dtype=float)
    quality[idpm]=np.where(np.isfinite(cr[idpm]),np.clip((130.0-cr[idpm])/55.0,-1.0,1.4),-0.5)
    quality[idpm]+=np.clip((pr[idpm]-5.0)*0.35,-0.5,1.0)

    pick_edge=market_points+conviction+vorp_points+quality
    avg_pick_edge=float(np.nanmean(pick_edge)) if len(pick_edge) else 0.0

    # Fantasy Edge calibration:
    # 100/100 is achievable, but only through repeated quality decisions rather than
    # a cosmetic score boost. Reward consistency across the whole roster.
    _clean_pick=((market_delta.fillna(-999)>=-5) & (vorp>=0)).astype(float)
    _clean_rate=float(_clean_pick.mean()) if len(_clean_pick) else 0.0
    _value_rate=float((market_delta.fillna(-999)>=0).mean()) if len(r) else 0.0

    # Base edge comes from realized per-pick advantage. Consistency adds at most 4 points:
    # 2.5 for avoiding bad-value/negative-VORP picks and 1.5 for repeatedly beating market.
    _consistency_bonus=2.5*_clean_rate + 1.5*_value_rate
    model_edge=float(np.clip(58.0+2.15*avg_pick_edge+_consistency_bonus,35,100))

    # Draft value is primarily realized market value + VORP, not model-vs-market disagreement.
    avg_market=float(np.nanmean(np.clip(market_delta.fillna(0),-30,36))) if len(r) else 0.0
    avg_vorp=float(usable_vorp.mean()) if len(r) else 0.0
    draft_value=float(np.clip(62+0.62*avg_market+2.0*avg_vorp,35,100))
    # Realized pick economics: Draft Value should respond to the actual roster,
    # not remain almost static across simulations.
    _rv=_gnum("vorp",0.0)
    _rp=_gnum("projection",0.0)
    if "roster_opportunity" in roster.columns:
        _ro=pd.to_numeric(roster["roster_opportunity"],errors="coerce").fillna(0.0)
    elif "roster_opportunity_adj" in roster.columns:
        _ro=pd.to_numeric(roster["roster_opportunity_adj"],errors="coerce").fillna(0.0)
    else:
        _ro=pd.Series(0.0,index=roster.index,dtype=float)
    realized_pick_economics=float(np.clip(
        0.55*np.nanmean(np.clip(_rv,-10,35))+
        0.035*np.nanmean(np.clip(_rp,0,400))+
        0.30*np.nanmean(np.clip(_ro,-10,15)),
        -5,12
    ))
    draft_value=float(np.clip(draft_value+realized_pick_economics,0,100))
    # V6.16: preserve the legacy market-timing-only value for transparency.
    raw_market_draft_value=float(draft_value)

    construction=100.0
    for p,v in req.items():
        construction-=16*max(v-counts.get(p,0),0)
    # FLEX is filled by the best remaining RB/WR/TE after nominal RB/WR/TE starters.
    skill=r[r.position.isin(["RB","WR","TE"])].copy()
    nominal=req["RB"]+req["WR"]+req["TE"]
    flex_available=max(len(skill)-nominal,0)
    construction-=14*max(flex_n-flex_available,0)
    # Healthy depth targets for this exact six-bench build with one required TE.
    rb,wr=counts.get("RB",0),counts.get("WR",0)
    if rb+wr+counts.get("TE",0)<6: construction-=5*(6-(rb+wr+counts.get("TE",0)))
    qb,te,dl,db=[counts.get(p,0) for p in ["QB","TE","DL","DB"]]
    construction-=12*max(qb-2,0)+10*max(te-2,0)
    # V6.11: one merit-earned backup IDP is legal bench construction. Penalize
    # only a fourth defender or excessive same-position defensive depth.
    _idp_total=dl+db
    construction-=7*max(_idp_total-3,0)
    construction-=4*max(dl-2,0)+4*max(db-2,0)
    construction=float(np.clip(construction,0,100))

    # Starter VORP: exact positional starters, then FLEX from remaining RB/WR/TE.
    starter=0.0; used=set()
    for p in ["QB","RB","WR","TE","K","DL","DB"]:
        n=req[p]
        if n<=0: continue
        idx=r[r.position.eq(p)].vorp.nlargest(n).index
        used.update(idx.tolist()); starter+=float(r.loc[idx,"vorp"].sum())
    flex_pool=r.loc[~r.index.isin(used) & r.position.isin(["RB","WR","TE"]),"vorp"]
    starter+=float(flex_pool.nlargest(flex_n).sum())
    positional=float(np.clip(50+starter*.78,35,100))

    # Opportunity cost: redundant depth, unnecessary early QB2/TE2, and
    # contextually avoidable reaches. Raw ADP reach cost is retained separately
    # so the dashboard remains transparent.
    opp=0.0; raw_opp=0.0; seen={"QB":0,"TE":0}
    ordered=r.sort_values("mock_pick") if "mock_pick" in r.columns else r
    for _idx,row in ordered.iterrows():
        p=row.position
        if p in seen:
            seen[p]+=1
            if seen[p]>=2 and float(row.get("mock_pick",999))<120:
                opp+=4; raw_opp+=4
        crv=row.get("consensus_rank",np.nan); pk=row.get("mock_pick",np.nan)
        if pd.notna(crv) and pd.notna(pk):
            reach=float(crv)-float(pk)  # positive = drafted ahead of market
            if reach>18:
                _reach_cost=min(8,(reach-18)*.12)
                raw_opp+=_reach_cost
                _avoidable=bool(row.get("avoidable_reach",True))
                if _avoidable:
                    opp+=_reach_cost

    # Portfolio/reach diagnostics. Contextual rate drives decision-quality
    # penalty; raw rate is reported separately.
    _reach_series=(r.consensus_rank-r.mock_pick) if "mock_pick" in r.columns else pd.Series(0,index=r.index)
    _raw_big_reach_rate=float((_reach_series>24).mean()) if len(r) else 0.0
    if "avoidable_reach" in r.columns:
        _avoid_flag=r["avoidable_reach"].fillna(False).astype(bool)
        _big_reach_rate=float(((_reach_series>24) & _avoid_flag).mean()) if len(r) else 0.0
    else:
        _big_reach_rate=_raw_big_reach_rate
    _redundant_depth=max(counts.get("RB",0)-5,0)+max(counts.get("WR",0)-5,0)+max(counts.get("QB",0)-2,0)+max(counts.get("TE",0)-2,0)
    _double_backup=int(counts.get("QB",0)>=2 and counts.get("TE",0)>=2)
    _portfolio_penalty=min(10.0,3.5*_redundant_depth + 2.5*_double_backup)
    _reach_penalty=min(8.0,12.0*_big_reach_rate)

    _idp_total=int(counts.get("DL",0))+int(counts.get("DB",0))
    _diversification_penalty=0.0
    if counts.get("RB",0)>=6 and counts.get("WR",0)>=6 and _idp_total<=2:
        _diversification_penalty=6.0

    opp+=_portfolio_penalty+_reach_penalty+_diversification_penalty
    raw_opp+=_portfolio_penalty+min(8.0,12.0*_raw_big_reach_rate)+_diversification_penalty

    # V6.16 calibrated Draft Value: draft capital is still the majority signal,
    # but a draft is also valuable when that capital converts into starter advantage,
    # usable bench upside, and low opportunity waste. Keep raw_market_draft_value
    # alongside this score so the dashboard cannot hide pure ADP efficiency.
    _bench_value_score=float(np.clip(70.0+2.0*float(np.clip(
        r.loc[~r.index.isin(used),"vorp"].fillna(0).clip(-2,10).sum(),-10,15
    )),35,100))
    _capital_efficiency=float(np.clip(100.0-5.0*float(opp),0,100))
    draft_value=float(np.clip(
        0.70*raw_market_draft_value +
        0.15*positional +
        0.10*_bench_value_score +
        0.05*_capital_efficiency,
        0,100
    ))

    # Interpretable quality composite.
    model_edge=float(np.clip(
        0.42*draft_value +
        0.30*construction +
        0.20*positional +
        8.0*_clean_rate -
        0.45*float(opp),
        0,100
    ))

    # Overall grade uses the same economics without double-counting opportunity loss.
    score=float(np.clip(.34*draft_value+.30*construction+.22*positional+.14*model_edge-0.35*opp,0,100))
    _construction_edge_penalty=0.0
    _draft_value_edge_penalty=0.0
    _positional_edge_penalty=0.0
    _opportunity_edge_penalty=0.0
    grade="A+" if score>=94 else "A" if score>=90 else "A-" if score>=86 else "B+" if score>=82 else "B" if score>=78 else "B-" if score>=74 else "C+" if score>=70 else "C" if score>=65 else "C-" if score>=60 else "D" if score>=55 else "F"
    return {"score":score,"grade":grade,"starter":starter,"value":avg_market,"penalty":max(0,100-construction),
            "draft_value":draft_value,"raw_market_draft_value":raw_market_draft_value,
            "construction":construction,"positional_advantage":positional,
            "model_edge_score":model_edge,"opportunity_penalty":opp,
            "raw_opportunity_penalty":raw_opp,"starter_vorp":starter,
            "clean_pick_rate":_clean_rate,"market_win_rate":_value_rate,
            "big_reach_rate":_big_reach_rate,"raw_big_reach_rate":_raw_big_reach_rate,"portfolio_penalty":_portfolio_penalty,"diversification_penalty":_diversification_penalty,"construction_edge_penalty":_construction_edge_penalty,"draft_value_edge_penalty":_draft_value_edge_penalty,"positional_edge_penalty":_positional_edge_penalty,"opportunity_edge_penalty":_opportunity_edge_penalty}

def _injury_severity(status):
    x=str(status or "").strip().lower()
    if x in ["ir","pup","nfi","reserve/ir","reserve/pup"]: return 3
    if x in ["out","suspended","susp"]: return 2
    if x in ["doubtful","questionable","q","d"]: return 1
    return 0



def _v677_normalize_injury_status(status):
    """One injury/status vocabulary used across every Fantasy Edge tab."""
    x=str(status or "").strip().upper()
    if x in ("", "NONE", "NAN", "HEALTHY", "ACTIVE", "FULL", "FULL PARTICIPATION"):
        return "ACTIVE"
    if x in ("Q", "QUESTIONABLE", "GTD", "GAME TIME DECISION", "GAME-TIME DECISION") or "GAME TIME DECISION" in x or "GAME-TIME DECISION" in x:
        return "QUESTIONABLE"
    if x in ("D", "DOUBTFUL"):
        return "DOUBTFUL"
    if x in ("O", "OUT"):
        return "OUT"
    if x in ("IR", "RESERVE/IR", "INJURED RESERVE"):
        return "IR"
    if x in ("PUP", "RESERVE/PUP", "PHYSICALLY UNABLE TO PERFORM"):
        return "PUP"
    if x in ("NFI", "RESERVE/NFI"):
        return "NFI"
    if x in ("SUSP", "SUSPENDED"):
        return "SUSPENDED"
    if x in ("DNR", "DO NOT DRAFT", "AVOID"):
        return "DO NOT DRAFT"
    # Keep unexpected official designations visible instead of silently discarding them.
    return x

def _v677_status_icon(status):
    s=_v677_normalize_injury_status(status)
    return {
        "ACTIVE":"🟢 ACTIVE",
        "QUESTIONABLE":"🟡 QUESTIONABLE",
        "DOUBTFUL":"🟠 DOUBTFUL",
        "OUT":"🔴 OUT",
        "IR":"⛔ IR",
        "PUP":"⛔ PUP",
        "NFI":"⛔ NFI",
        "SUSPENDED":"⛔ SUSPENDED",
        "DO NOT DRAFT":"⛔ DO NOT DRAFT",
    }.get(s, "⚪ "+s)




# ---------------- V6.81 direct Sleeper injury-field integration ----------------
@st.cache_data(ttl=900, show_spinner=False)
def _v681_sleeper_injury_watch():
    """
    Read Sleeper's actual injury-specific player fields directly.
    This fixes V6.80's main gap: the production board often had a blank/stale
    injury column, so QUESTIONABLE/LIMITED players were being normalized to ACTIVE.
    """
    out={}
    try:
        players=sleeper_players()
        if not isinstance(players,dict):
            return out

        for pid,pl in players.items():
            if not isinstance(pl,dict):
                continue
            name=str(
                pl.get("full_name")
                or " ".join([str(pl.get("first_name") or ""),str(pl.get("last_name") or "")]).strip()
                or ""
            ).strip()
            if not name:
                continue

            injury_status=str(pl.get("injury_status") or "").strip()
            generic_status=str(pl.get("status") or "").strip()
            practice=str(
                pl.get("practice_participation")
                or pl.get("practice_status")
                or ""
            ).strip()
            note=str(pl.get("injury_notes") or "").strip()
            body=str(
                pl.get("injury_body_part")
                or pl.get("body_part")
                or (note if len(note)<=80 else "")
                or ""
            ).strip()
            injury_start=str(pl.get("injury_start_date") or "").strip()

            # Game designation first.
            raw=(injury_status + " | " + generic_status).upper()
            designation="ACTIVE"
            if "PHYSICALLY UNABLE" in raw or re.search(r"\bPUP\b",raw):
                designation="PUP"
            elif "NON-FOOTBALL" in raw or re.search(r"\bNFI\b",raw):
                designation="NFI"
            elif "INJURED RESERVE" in raw or "RESERVE/INJURED" in raw or re.search(r"\bIR\b",raw):
                designation="IR"
            elif "SUSPEND" in raw:
                designation="SUSPENDED"
            elif "OUT" in raw:
                designation="OUT"
            elif "DOUBTFUL" in raw:
                designation="DOUBTFUL"
            elif "QUESTIONABLE" in raw or injury_status.upper()=="Q":
                designation="QUESTIONABLE"

            # Sleeper commonly has practice text even when no final game designation exists.
            p=practice.upper()
            practice_norm=""
            if "DID NOT PARTICIPATE" in p or p=="DNP":
                practice_norm="DNP"
            elif "LIMIT" in p:
                practice_norm="Limited"
            elif "FULL" in p:
                practice_norm="Full"
            elif practice:
                practice_norm=practice

            # Only store records with real injury/practice/reserve information.
            if designation!="ACTIVE" or practice_norm or body or note or injury_start:
                out[_owner_key(name)]={
                    "status":designation,
                    "practice":practice_norm,
                    "injury":body,
                    "note":note,
                    # injury_start_date is onset metadata, not a source update timestamp.
                    # Treating it as "updated" made an old status look newly authoritative.
                    "updated":"",
                    "injury_start":injury_start,
                    "team":str(pl.get("team") or "").upper(),
                    "source":"Fantasy Edge Injury Watch (Sleeper live fields)",
                    "raw_injury_status":injury_status,
                    "raw_player_status":generic_status,
                    "player_id":str(pid),
                    "player":name,
                    "practice_source":"Sleeper live fields" if practice_norm else "",
                    "fetched_at":datetime.now(timezone.utc).isoformat(),
                    "live_snapshot":True,
                }
    except Exception as e:
        pass  # cached loaders must not mutate session_state
    return out

# ---------------- V6.80 Fantasy Edge Injury Watch intelligence ----------------
# Adds richer weekly injury-report information (game designation, practice status,
# injury/body part, update date) across the entire player pool.
def _v805_espn_team_json(teams, endpoint):
    """Fetch independent team endpoints concurrently; keep parsing on the caller thread."""
    def fetch(tw):
        team=(tw.get("team") or {})
        team_id=str(team.get("id") or "").strip()
        slug=str(team.get("slug") or "").strip()
        identifiers=([team_id,slug] if endpoint=="injuries" else [slug])
        for ident in dict.fromkeys(x for x in identifiers if x):
            try:
                url=f"https://site.api.espn.com/apis/site/v2/sports/football/nfl/teams/{ident}/{endpoint}"
                response=requests.get(url,timeout=(3,5),headers={"User-Agent":"Mozilla/5.0"})
                if response.status_code==200:
                    data=response.json()
                    if isinstance(data,dict):
                        return team,data
            except Exception:
                continue
        return team,None

    if not teams:
        return []
    with concurrent.futures.ThreadPoolExecutor(max_workers=12) as pool:
        # map preserves league order, so duplicate player names resolve as before.
        return list(pool.map(fetch,teams))


@st.cache_data(ttl=900, show_spinner=False)
def _v680_espn_injury_watch_feed():
    """
    Returns canonical-name keyed injury intelligence for the full NFL player pool.
    ESPN team injury endpoints are used for current weekly designations/practice
    detail. Reserve-list authority remains a separate higher-priority layer.
    """
    out={}
    try:
        teams_url="https://site.api.espn.com/apis/site/v2/sports/football/nfl/teams?limit=40"
        tr=requests.get(teams_url,timeout=8,headers={"User-Agent":"Mozilla/5.0"})
        tr.raise_for_status()
        sports=tr.json().get("sports") or []
        leagues=(sports[0].get("leagues") or []) if sports else []
        teams=(leagues[0].get("teams") or []) if leagues else []

        for team,data in _v805_espn_team_json(teams,"injuries"):
            abbr=str(team.get("abbreviation") or "").upper().strip()
            if not isinstance(data,dict):
                continue

            # ESPN has used several shapes over time. Walk plausible collections.
            candidates=[]
            for key in ["injuries","items","athletes"]:
                val=data.get(key)
                if isinstance(val,list):
                    candidates.extend(val)

            # Some responses group entries.
            for grp in data.get("groups",[]) or []:
                if isinstance(grp,dict):
                    for key in ["injuries","items","athletes"]:
                        val=grp.get(key)
                        if isinstance(val,list):
                            candidates.extend(val)

            def _flatten_entry(entry):
                if not isinstance(entry,dict):
                    return []
                # group wrapper
                for key in ["items","athletes","injuries"]:
                    if isinstance(entry.get(key),list):
                        return entry.get(key)
                return [entry]

            flat=[]
            for entry in candidates:
                flat.extend(_flatten_entry(entry))

            for item in flat:
                if not isinstance(item,dict):
                    continue
                athlete=item.get("athlete") if isinstance(item.get("athlete"),dict) else item
                name=str(
                    athlete.get("fullName")
                    or athlete.get("displayName")
                    or item.get("fullName")
                    or item.get("displayName")
                    or ""
                ).strip()
                if not name:
                    continue

                # Gather status text from common ESPN fields.
                status_obj=item.get("status") or athlete.get("status") or {}
                status_texts=[]
                if isinstance(status_obj,dict):
                    status_texts.extend([
                        status_obj.get("name"), status_obj.get("type"),
                        status_obj.get("description"), status_obj.get("abbreviation"),
                        status_obj.get("detail"), status_obj.get("shortDetail")
                    ])
                elif status_obj:
                    status_texts.append(status_obj)

                status_texts.extend([
                    item.get("type"), item.get("status"),
                    item.get("designation"), item.get("gameStatus"),
                    item.get("shortComment"), item.get("longComment"),
                    item.get("details")
                ])
                status_raw=" | ".join(str(x) for x in status_texts if x).upper()
                # Preserve human-readable timeline/detail text for return-horizon parsing.
                # V10.97 keeps this separate from the body-part field so phrases like
                # "expected to miss four weeks" survive the injury reconciliation layer.
                _note_parts=[]
                if isinstance(status_obj,dict):
                    _note_parts.extend([status_obj.get("detail"),status_obj.get("shortDetail"),status_obj.get("description")])
                _note_parts.extend([item.get("shortComment"),item.get("longComment"),item.get("details"),item.get("description")])
                _seen_note=[]
                for _nv in _note_parts:
                    if _nv is None or isinstance(_nv,(dict,list)):
                        continue
                    _nt=str(_nv).strip()
                    if _nt and _nt not in _seen_note:
                        _seen_note.append(_nt)
                note_text=" | ".join(_seen_note)[:600]

                # Injury/body part.
                injury_text=""
                for key in ["injury","bodyPart","body_part","details","description","type"]:
                    v=item.get(key)
                    if isinstance(v,dict):
                        injury_text=str(
                            v.get("description") or v.get("name") or
                            v.get("displayName") or v.get("type") or ""
                        ).strip()
                    elif v:
                        injury_text=str(v).strip()
                    if injury_text:
                        break

                # Practice participation.
                practice=""
                practice_candidates=[
                    item.get("practiceStatus"), item.get("practice"),
                    item.get("participation"), item.get("practiceParticipation")
                ]
                for pv in practice_candidates:
                    if isinstance(pv,dict):
                        ptxt=str(
                            pv.get("description") or pv.get("name") or
                            pv.get("abbreviation") or pv.get("type") or ""
                        ).strip()
                    else:
                        ptxt=str(pv or "").strip()
                    if ptxt:
                        practice=ptxt
                        break

                # Infer practice from comments if needed.
                if not practice:
                    raw=status_raw
                    if "DID NOT PARTICIPATE" in raw or re.search(r"\bDNP\b",raw):
                        practice="DNP"
                    elif "LIMITED" in raw:
                        practice="Limited"
                    elif "FULL PARTICIPATION" in raw or re.search(r"\bFULL\b",raw):
                        practice="Full"

                # Normalize weekly game designation.
                designation="ACTIVE"
                if "OUT" in status_raw:
                    designation="OUT"
                elif "DOUBTFUL" in status_raw:
                    designation="DOUBTFUL"
                elif "QUESTIONABLE" in status_raw:
                    designation="QUESTIONABLE"
                elif "SUSPEND" in status_raw:
                    designation="SUSPENDED"
                elif "PHYSICALLY UNABLE" in status_raw or re.search(r"\bPUP\b",status_raw):
                    designation="PUP"
                elif "NON-FOOTBALL" in status_raw or re.search(r"\bNFI\b",status_raw):
                    designation="NFI"
                elif "INJURED RESERVE" in status_raw or "RESERVE/INJURED" in status_raw or re.search(r"\bIR\b",status_raw):
                    designation="IR"
                else:
                    # Practice status alone should not falsely label a player OUT.
                    # DNP/Limited become WATCH state while remaining officially active.
                    designation="ACTIVE"

                updated=str(
                    item.get("date")
                    or item.get("lastUpdated")
                    or item.get("updated")
                    or item.get("updateDate")
                    or ""
                ).strip()

                key=_owner_key(name)
                rec={
                    "status":designation,
                    "injury":injury_text,
                    "note":note_text,
                    "practice":practice,
                    "updated":updated,
                    "team":abbr,
                    "source":"Fantasy Edge Injury Watch",
                    "player":name,
                    "practice_source":"ESPN injury report" if practice else "",
                    "fetched_at":datetime.now(timezone.utc).isoformat(),
                }

                # Prefer the record with a stronger game designation / richer detail.
                priority={"IR":8,"PUP":8,"NFI":8,"SUSPENDED":8,"OUT":7,"DOUBTFUL":6,"QUESTIONABLE":5,"ACTIVE":1}
                prev=out.get(key)
                prev_score=priority.get(str((prev or {}).get("status","ACTIVE")),1) if prev else -1
                new_score=priority.get(designation,1)
                richness=sum(bool(rec.get(k)) for k in ["injury","note","practice","updated"])
                prev_rich=sum(bool((prev or {}).get(k)) for k in ["injury","note","practice","updated"]) if prev else -1
                if prev is None or new_score>prev_score or (new_score==prev_score and richness>prev_rich):
                    out[key]=rec

    except Exception as e:
        pass  # cached loaders must not mutate session_state
    return out


@st.cache_data(ttl=900, show_spinner=False)
def _v723_nflverse_practice_feed(season=None):
    """
    Official weekly NFL injury/practice report feed from nflverse.
    Uses practice_status, report_status, injury, team, week, and date_modified.
    """
    out={}
    try:
        if season is None:
            season=int(datetime.now().year)
        url=f"https://github.com/nflverse/nflverse-data/releases/download/injuries/injuries_{int(season)}.csv"
        rr=requests.get(url,timeout=12,headers={"User-Agent":"FantasyEdge/7.23"})
        if rr.status_code!=200 or not rr.content:
            return out
        df=pd.read_csv(io.BytesIO(rr.content),low_memory=False)
        if df.empty:
            return out
        df["_week"]=pd.to_numeric(df.get("week",-1),errors="coerce").fillna(-1)
        if "date_modified" in df.columns:
            df["_modified"]=pd.to_datetime(df["date_modified"],errors="coerce",utc=True)
        else:
            df["_modified"]=pd.NaT
        name_col=next((c for c in ["full_name","player_name","name"] if c in df.columns),None)
        if not name_col:
            return out
        df=df[df[name_col].fillna("").astype(str).str.strip().ne("")].copy()
        df=df.sort_values(["_week","_modified"],ascending=[True,True],na_position="first")

        def _practice(v):
            x=str(v or "").upper().strip()
            if not x or x in ("NAN","NONE"):
                return ""
            if "DID NOT PARTICIPATE" in x or x=="DNP" or "NOT PARTICIPATE" in x:
                return "DNP"
            if "LIMIT" in x:
                return "Limited"
            if "FULL" in x:
                return "Full"
            return str(v).strip()

        def _designation(v):
            x=str(v or "").upper().strip()
            if not x or x in ("NAN","NONE"):
                return "ACTIVE"
            if "OUT" in x: return "OUT"
            if "DOUBTFUL" in x: return "DOUBTFUL"
            if "QUESTIONABLE" in x: return "QUESTIONABLE"
            if x=="IR" or "INJURED RESERVE" in x: return "IR"
            if "PUP" in x: return "PUP"
            if "NFI" in x: return "NFI"
            if "SUSP" in x: return "SUSPENDED"
            return "ACTIVE"

        # Preserve the current report plus same-week practice history.  This lets
        # V7.25 estimate a transparent provisional ramp while today's
        # participation is still pending, without inventing a Full/Limited/DNP.
        histories={}
        for _,r in df.iterrows():
            name=str(r.get(name_col,"") or "").strip()
            key=_owner_key(name)
            if not key:
                continue
            practice=_practice(r.get("practice_status",""))
            # V7.69 runtime safety: pandas missing scalars (pd.NA) cannot be used in
            # Python boolean expressions (``value or ""`` raises "boolean value of NA
            # is ambiguous"). Normalize the source scalar explicitly before testing it.
            _report_val=r.get("report_status","")
            try:
                _report_missing=bool(pd.isna(_report_val))
            except Exception:
                _report_missing=False
            _report_raw="" if _report_missing else str(_report_val).strip()
            _report_raw_present=bool(_report_raw and _report_raw.upper() not in {"NAN","NONE","<NA>"})
            report=_designation(_report_raw)
            injury=str(r.get("practice_primary_injury","") or r.get("report_primary_injury","") or "").strip()
            team=str(r.get("team","") or "").upper().strip()
            modified=r.get("date_modified","")
            modified="" if pd.isna(modified) else str(modified)
            week=int(r.get("_week",-1)) if pd.notna(r.get("_week",-1)) else -1
            rec={"status":report,"injury":injury,"practice":practice,"updated":modified,"team":team,
                 "week":week,"source":"nflverse official injury report",
                 "player":name,
                 "report_raw":_report_raw,
                 "report_raw_present":_report_raw_present,
                 "practice_source":"nflverse official injury report" if practice else ""}
            histories.setdefault(key,[]).append({"week":week,"practice":practice,"updated":modified,"status":report,"injury":injury})
            prev=out.get(key)
            if prev is None:
                out[key]=rec
            else:
                pw=int(prev.get("week",-1) or -1); nw=int(rec.get("week",-1) or -1)
                # Newer week always wins.  Within a week, newer rows win even if
                # participation is blank, because that blank may represent a
                # newly matched report whose practice field has not published yet.
                prev_dt=pd.to_datetime(prev.get("updated",""),errors="coerce",utc=True)
                rec_dt=pd.to_datetime(rec.get("updated",""),errors="coerce",utc=True)
                newer=(pd.notna(rec_dt) and (pd.isna(prev_dt) or rec_dt>=prev_dt))
                if nw>pw:
                    out[key]=rec
                elif nw==pw and newer:
                    # V7.68: practice rows and game-status rows can be published separately.
                    # A later DNP row with a blank report_status must NOT erase an OUT
                    # designation that was already published for the same week. Merge the
                    # newest practice/detail fields while carrying the latest explicit game
                    # designation forward until a newer explicit designation replaces it.
                    merged_rec=dict(prev)
                    for _fld in ["practice","injury","updated","team","player","practice_source"]:
                        if str(rec.get(_fld,"") or "").strip() or _fld in {"updated","practice"}:
                            merged_rec[_fld]=rec.get(_fld)
                    if bool(rec.get("report_raw_present",False)):
                        merged_rec["status"]=rec.get("status","ACTIVE")
                        merged_rec["report_raw"]=rec.get("report_raw","")
                        merged_rec["report_raw_present"]=True
                    merged_rec["week"]=nw
                    merged_rec["source"]="nflverse official injury report"
                    out[key]=merged_rec

        for key,rec in list(out.items()):
            week=int(rec.get("week",-1) or -1)
            hist=[h for h in histories.get(key,[]) if int(h.get("week",-1) or -1)==week]
            hist=sorted(hist,key=lambda h: pd.to_datetime(h.get("updated",""),errors="coerce",utc=True) if h.get("updated") else pd.Timestamp.min.tz_localize("UTC"))
            published=[h for h in hist if str(h.get("practice","") or "").strip()]
            prior=published[-1] if published else None
            prior2=published[-2] if len(published)>=2 else None
            rec["prior_practice"] = str(prior.get("practice","") if prior else "")
            rec["prior_practice_updated"] = str(prior.get("updated","") if prior else "")
            if prior and prior2:
                rec["practice_trend"] = f"{prior2.get('practice','')} → {prior.get('practice','')}"
            elif prior:
                rec["practice_trend"] = str(prior.get("practice","") or "")
            else:
                rec["practice_trend"] = ""
        return out
    except Exception:
        return out


def _v762_expire_unverified_status(status, has_fresh, conflict=False, severe_undated=False):
    """V7.63 evidence-time lifecycle.

    Old unsupported injury evidence must not live forever in Monitoring.  Only fresh
    contradictory evidence or a fresh severe designation that lacks enough proof stays
    unresolved.  Everything else expires back to ACTIVE/clear.
    """
    st=_v677_normalize_injury_status(status)
    if conflict:
        return False
    if has_fresh and severe_undated:
        return False
    if not has_fresh and st in {"QUESTIONABLE","DOUBTFUL","OUT","IR","PUP","NFI","SUSPENDED"}:
        return True
    return False


@st.cache_data(ttl=900, show_spinner=False)
def _v680_injury_watch_feed():
    """V7.59 reconciled Injury Watch.

    Weekly designations are no longer selected by "most severe wins".  Each source is
    evaluated for recency and authority first.  A stale/undated OUT/PUP/IR record can
    never overrule a newer verified record simply because it is more severe.
    """
    # V9.15: these three providers are independent. Fetch them concurrently so a
    # cold injury cache costs roughly the slowest provider, not the sum of all three.
    sleeper={}; espn={}; official={}
    _v915_pool=concurrent.futures.ThreadPoolExecutor(max_workers=3)
    try:
        _v915_fs=_v915_pool.submit(_v681_sleeper_injury_watch)
        _v915_fe=_v915_pool.submit(_v680_espn_injury_watch_feed)
        _v915_fo=_v915_pool.submit(_v723_nflverse_practice_feed)
        _v915_fmap={_v915_fs:"sleeper",_v915_fe:"espn",_v915_fo:"official"}
        # One shared five-second budget. Do not accidentally spend 5-8 seconds per
        # provider by awaiting each future separately.
        _v915_done,_v915_pending=concurrent.futures.wait(set(_v915_fmap),timeout=5.0)
        for _v915_f in _v915_done:
            try: _v915_val=_v915_f.result() or {}
            except Exception: _v915_val={}
            if _v915_fmap[_v915_f]=="sleeper": sleeper=_v915_val
            elif _v915_fmap[_v915_f]=="espn": espn=_v915_val
            else: official=_v915_val
        for _v915_f in _v915_pending:
            _v915_f.cancel()
    finally:
        # Never let a lagging corroboration source hold the Streamlit rerun open.
        _v915_pool.shutdown(wait=False, cancel_futures=True)

    # Current official report week = newest week actually present in the downloaded feed.
    official_weeks=[]
    for r in official.values():
        try:
            w=int(r.get("week",-1) or -1)
            if w>=0: official_weeks.append(w)
        except Exception:
            pass
    current_official_week=max(official_weeks) if official_weeks else None
    now=pd.Timestamp.now(tz="UTC")

    def _dt(v):
        try:
            x=pd.to_datetime(v,errors="coerce",utc=True)
            return x if pd.notna(x) else None
        except Exception:
            return None

    def _source(rec):
        return str((rec or {}).get("source","") or "").lower()

    def _freshness(rec):
        """Return (fresh, reason, age_hours)."""
        if not isinstance(rec,dict): return False,"missing record",None
        src=_source(rec)
        week=rec.get("week",None)
        # nflverse carries explicit report week + modification time.
        if "nflverse" in src:
            try:
                iw=int(week)
            except Exception:
                iw=-1
            if current_official_week is not None and iw != current_official_week:
                return False,f"official report week {iw}; current {current_official_week}",None
            d=_dt(rec.get("updated",""))
            if d is None:
                return False,"official report missing timestamp",None
            age=max(0.0,(now-d).total_seconds()/3600.0)
            # Current-week official rows stay valid for the week; old-season rows do not.
            return age <= 24*10,("current official report" if age<=24*10 else f"official report {age/24:.1f}d old"),age

        # V7.63: evidence time and fetch time are different things. Downloading the
        # same old designation again must never make that designation "fresh" again.
        # Only a source-provided item/update timestamp can establish evidence freshness.
        d=_dt(rec.get("updated",""))
        f=_dt(rec.get("fetched_at",""))
        if d is not None:
            age=max(0.0,(now-d).total_seconds()/3600.0)
            if age <= 24*7:
                return True,f"source evidence updated {age:.1f}h ago",age
            return False,f"source evidence {age/24:.1f}d old",age
        if f is not None:
            fetch_age=max(0.0,(now-f).total_seconds()/3600.0)
            return False,f"current endpoint observation; source update time unavailable (fetched {fetch_age:.1f}h ago)",None
        return False,"source update time unavailable",None

    def _authority(rec):
        src=_source(rec)
        if "nflverse" in src: return 4
        if "espn injury" in src or src=="fantasy edge injury watch": return 3
        if "sleeper live fields" in src: return 2
        return 1

    keys=set(sleeper)|set(espn)|set(official)
    merged={}
    severe={"OUT","IR","PUP","NFI","SUSPENDED"}
    weekly={"OUT","DOUBTFUL","QUESTIONABLE"}
    reserve={"IR","PUP","NFI","SUSPENDED"}

    for key in keys:
        candidates=[]
        for label,srcmap in (("sleeper",sleeper),("espn",espn),("official",official)):
            rec=srcmap.get(key)
            if not isinstance(rec,dict): continue
            rr=dict(rec); rr["_label"]=label
            rr["status"]=_v677_normalize_injury_status(rr.get("status","ACTIVE"))
            fresh,reason,age=_freshness(rr)
            rr["_fresh"]=bool(fresh); rr["_fresh_reason"]=reason; rr["_age_hours"]=age
            rr["_authority"]=_authority(rr)
            candidates.append(rr)
        if not candidates: continue

        # Fresh records first, then source authority, then actual item recency.  Severity
        # is deliberately NOT part of ordering; this is the V7.59 bug fix.
        def _stamp(rec):
            # Ordering is based only on source evidence time. Fetch time is transport
            # metadata and cannot renew or outrank an older status.
            d=_dt(rec.get("updated",""))
            return d.value if d is not None else -1
        candidates.sort(key=lambda r:(1 if r["_fresh"] else 0,r["_authority"],_stamp(r)),reverse=True)

        # V7.68: a practice-report row with no game designation is NOT evidence that
        # the player is ACTIVE.  Previously nflverse DNP rows normalized blank
        # report_status to ACTIVE and, because nflverse has the highest authority,
        # erased a live OUT/PUP designation from another source.  Keep those rows for
        # practice detail, but remove neutral ACTIVE placeholders from status authority.
        def _status_bearing(rec):
            stx=str(rec.get("status","ACTIVE") or "ACTIVE").upper()
            if stx!="ACTIVE":
                return True
            if rec.get("_label")=="official" and not bool(rec.get("report_raw_present",False)):
                return False
            # ESPN/Sleeper ACTIVE rows in injury endpoints are usually absence of a
            # designation, not an explicit medical clearance. They may enrich practice
            # detail but cannot overrule a current non-active designation.
            return bool(rec.get("explicit_active",False))

        status_candidates=[r for r in candidates if _status_bearing(r)]
        fresh=[r for r in status_candidates if r["_fresh"]]
        chosen=(fresh[0] if fresh else (status_candidates[0] if status_candidates else dict(candidates[0],status="ACTIVE")))

        # V7.63 endpoint observations are tracked separately from timestamped evidence.
        # A live endpoint can still provide useful monitor-only QUESTIONABLE/DOUBTFUL
        # information, but its retrieval timestamp cannot create decision authority.
        observations=[]
        for r in candidates:
            f=_dt(r.get("fetched_at",""))
            if f is not None and (now-f).total_seconds() <= 6*3600:
                observations.append(r)

        # Agreement among independent sources is useful when severe live tags have no
        # per-item timestamp.  An uncorroborated severe tag from an undated live endpoint
        # is quarantined rather than promoted to authoritative OUT/IR/PUP.
        fresh_statuses=[r["status"] for r in fresh]

        # V7.68: reserve-list membership is a roster-eligibility state, not a weekly
        # injury opinion. A current live Sleeper PUP/IR/NFI/SUSPENDED observation must
        # outrank a generic ACTIVE record from an injury endpoint that simply omits
        # reserve players. This prevents Branch-on-PUP style players from re-entering
        # the Start/Sit candidate pool.
        _live_reserve=[r for r in observations if r.get("_label")=="sleeper" and r.get("status") in reserve]
        _reserve_override=bool(_live_reserve)
        if _reserve_override:
            chosen=_live_reserve[0]

        status=chosen["status"]
        corroboration=sum(1 for r in fresh if r["status"]==status)
        obs_corroboration=len({r.get("_label") for r in observations if r.get("status")==status})
        chosen_has_item_time=_dt(chosen.get("updated","")) is not None
        verified=True
        verify_reason=chosen.get("_fresh_reason","")

        if _reserve_override:
            verified=True
            verify_reason="current live roster/reserve designation"
        elif fresh:
            if status in severe and not chosen_has_item_time and corroboration < 2:
                verified=False
                verify_reason="severe designation lacks source update time or independent confirmation"
        else:
            # No source timestamp exists. Fetch time still does NOT make old evidence new,
            # but a CURRENT live endpoint can establish certain hard availability states.
            # Reserve-list states are roster states (not practice opinions), so a current
            # live PUP/IR/NFI/SUSPENDED observation is authoritative. Weekly OUT requires
            # either independent corroboration OR same-record DNP practice evidence.
            observed_nonactive=[r for r in observations if r.get("status") not in ("ACTIVE","")]
            _obs_same=[r for r in observations if r.get("status")==status]
            _same_has_dnp=any("DNP" in str(r.get("practice","") or "").upper() or "DID NOT PARTICIPATE" in str(r.get("practice","") or "").upper() for r in _obs_same)
            _sleeper_same=[r for r in _obs_same if r.get("_label")=="sleeper" and bool(r.get("live_snapshot",False))]
            if status in reserve and (_obs_same or _sleeper_same):
                verified=True
                verify_reason="current live roster/reserve designation"
            elif status=="OUT" and (obs_corroboration >= 2 or _same_has_dnp or bool(_sleeper_same)):
                verified=True
                verify_reason="current live OUT designation" if _sleeper_same else "current OUT designation corroborated by live status/practice evidence"
            elif status in ("QUESTIONABLE","DOUBTFUL") and _obs_same:
                verified=True
                verify_reason="current live endpoint observation; monitor-only authority"
                chosen=dict(chosen)
                chosen["monitor_only_status"]=True
            elif status in severe and obs_corroboration >= 2:
                verified=True
                verify_reason="current severe designation corroborated by independent live endpoints"
            else:
                verified=False
                verify_reason="no source-timestamped or independently corroborated current evidence"

        # If two fresh, high-authority sources actively disagree on a designation, do not
        # guess.  Preserve details but mark the status unverified for decision engines.
        material=[r for r in fresh if r["status"]!="ACTIVE"]
        distinct=set(r["status"] for r in material)
        conflict=(len(distinct)>1) and not _reserve_override
        if conflict:
            # A current-week official report outranks lower-authority feeds.
            off=[r for r in fresh if r["_authority"]>=4]
            if off:
                chosen=off[0]; status=chosen["status"]; conflict=False; verified=True
                verify_reason="current official report overrides conflicting lower-authority source"
            else:
                verified=False
                verify_reason="fresh sources disagree on player status"

        # V7.62: stale unsupported designations expire instead of becoming permanent
        # monitoring items. Fresh conflicts and fresh severe-but-undated evidence remain
        # unresolved because they can still matter for the current week.
        _severe_undated = bool(status in severe and not verified)
        # V7.63: monitor-only Q/D endpoint observations are intentionally retained;
        # unsupported severe/weekly designations expire rather than becoming permanent
        # verification items merely because the feed was fetched again.
        _has_live_snapshot_authority = bool(verified and any(r.get("_label")=="sleeper" and bool(r.get("live_snapshot",False)) and r.get("status")==status for r in observations))
        _has_authoritative_current = bool(fresh) or _has_live_snapshot_authority or bool(verified and (status in ("QUESTIONABLE","DOUBTFUL") or (status in severe and obs_corroboration>=2)))
        if _v762_expire_unverified_status(status, _has_authoritative_current, conflict=bool(conflict), severe_undated=_severe_undated):
            status="ACTIVE"
            verified=True
            conflict=False
            verify_reason="stale unsupported designation expired; no current injury evidence"
            chosen=dict(chosen)
            chosen["status"]="ACTIVE"
            chosen["_expired_unverified"]=True

        base=dict(chosen)
        # Enrich non-status detail from fresh sources only; stale rows cannot leak old
        # injury/practice text into the current display.
        _fresh_detail=[r for r in candidates if r.get("_fresh")]
        for rec in _fresh_detail:
            for fld in ["practice","injury","team","player","prior_practice","prior_practice_updated","practice_trend","practice_source"]:
                if not str(base.get(fld,"") or "").strip() and str(rec.get(fld,"") or "").strip():
                    base[fld]=rec.get(fld)
        base["status_raw_reconciled"]=status
        base["status_verified"]=bool(verified)
        base["status_conflict"]=bool(conflict)
        base["freshness_reason"]=verify_reason
        base["evidence_expired"]=bool(base.get("_expired_unverified",False))
        # Stable fingerprint excludes fetched_at so repeated downloads of the same
        # evidence remain the same evidence across refreshes.
        _fp_parts=[]
        for r in candidates:
            _fp_parts.append("|".join([str(r.get("_label","")),str(r.get("status","")),str(r.get("updated","") or ""),str(r.get("raw_injury_status","") or ""),str(r.get("raw_player_status","") or "")]))
        base["evidence_fingerprint"]="||".join(sorted(set(_fp_parts)))
        base["evidence_sources"]=" + ".join(dict.fromkeys(str(r.get("source","") or "") for r in (fresh or observations) if str(r.get("source","") or "")))
        # Unverified severe/weekly designations are quarantined as ACTIVE for scoring;
        # their raw label remains available for diagnostics and the Command Center.
        if status in weekly|reserve and not verified:
            base["status"]="ACTIVE"
            base["quarantined_status"]=status
        else:
            base["status"]=status
            base["quarantined_status"]=""
        merged[key]=base

    return merged


def _v724_name_parts(name):
    raw=str(name or "").strip()
    toks=[re.sub(r"[^A-Za-z0-9'-]","",x) for x in raw.split()]
    toks=[x for x in toks if x]
    if toks and toks[-1].lower().rstrip('.') in {"jr","sr","ii","iii","iv","v"}:
        toks=toks[:-1]
    first=toks[0].lower() if toks else ""
    last=toks[-1].lower() if toks else ""
    return first,last


def _v806_watch_index(watch):
    """Index injury records once, retaining original feed order and ambiguity rules."""
    display={}
    team_last={}
    seen=set()
    for r in watch.values():
        if not isinstance(r,dict):
            continue
        pname=str(r.get("player","") or "").strip()
        if not pname:
            continue
        key=_owner_key(pname)
        rteam=str(r.get("team","") or "").upper().strip()
        sig=(str(r.get("player_id","") or ""),key,rteam)
        if sig in seen:
            continue
        seen.add(sig)
        display.setdefault(key,r)
        first,last=_v724_name_parts(pname)
        if rteam and last:
            team_last.setdefault((rteam,last),[]).append((r,first))
    return display,team_last


def _v724_resolve_watch_record(name,team,watch,watch_index=None):
    """Resolve an injury/practice record without unsafe fuzzy player matching.

    Order: canonical identity -> exact normalized display name -> unique team+last
    name -> unique team+first-initial+last.  Team-aware fallbacks are deliberately
    conservative so similarly named NFL players cannot be cross-wired.
    Returns (record, match_method).
    """
    if not isinstance(watch,dict):
        return {},"none"
    key=_owner_key(name)
    rec=watch.get(key)
    if isinstance(rec,dict):
        return rec,"canonical"
    if watch_index is None:
        watch_index=_v806_watch_index(watch)
    display,team_last=watch_index
    rec=display.get(key)
    if isinstance(rec,dict):
        return rec,"display-name"
    target_team=str(team or "").upper().strip()
    tf,tl=_v724_name_parts(name)
    candidates=team_last.get((target_team,tl),[]) if target_team and tl else []
    if len(candidates)==1:
        return candidates[0][0],"team+last"
    if candidates and tf:
        init=[r for r,rf in candidates if rf and rf[:1]==tf[:1]]
        if len(init)==1:
            return init[0],"team+initial+last"
    return {},"none"

def _v680_practice_risk(practice):
    s=str(practice or "").upper().strip()
    if not s:
        return ""
    if "DNP" in s or "DID NOT PARTICIPATE" in s:
        return "🔴 DNP"
    if "LIMIT" in s:
        return "🟡 LIMITED"
    if "FULL" in s:
        return "🟢 FULL"
    return s

# ---------------- V6.79 authoritative NFL reserve-list status ----------------
# Sleeper's generic player record can say "Active" for players who are actually
# on Reserve/IR or Reserve/PUP. This feed uses current official roster-list
# designations from ESPN's athlete API as a second live source, and merges them
# conservatively: reserve/unavailable designations override generic ACTIVE.
@st.cache_data(ttl=1800, show_spinner=False)
def _v679_espn_roster_status():
    out={}
    try:
        # Pull all 32 current NFL team rosters from ESPN's public API.
        teams_url="https://site.api.espn.com/apis/site/v2/sports/football/nfl/teams?limit=40"
        tr=requests.get(teams_url,timeout=8,headers={"User-Agent":"Mozilla/5.0"})
        tr.raise_for_status()
        teams=((tr.json().get("sports") or [{}])[0].get("leagues") or [{}])[0].get("teams") or []
        for team,data in _v805_espn_team_json(teams,"roster"):
            abbr=str(team.get("abbreviation") or "").upper().strip()
            try:
                if not isinstance(data,dict):
                    continue
                for group in data.get("athletes",[]) or []:
                    group_name=str(group.get("position") or group.get("name") or "").upper()
                    for a in group.get("items",[]) or []:
                        name=str(a.get("fullName") or a.get("displayName") or "").strip()
                        if not name:
                            continue
                        # ESPN commonly exposes status in status.type/name/description;
                        # roster grouping can also carry reserve-list wording.
                        st=a.get("status") or {}
                        vals=[]
                        if isinstance(st,dict):
                            vals += [st.get("name"),st.get("type"),st.get("description"),st.get("abbreviation")]
                        elif st:
                            vals.append(st)
                        vals += [a.get("status"),group_name]
                        raw=" | ".join(str(x) for x in vals if x).upper()

                        designation="ACTIVE"
                        if "PHYSICALLY UNABLE" in raw or re.search(r"\bPUP\b",raw):
                            designation="PUP"
                        elif "NON-FOOTBALL" in raw or re.search(r"\bNFI\b",raw):
                            designation="NFI"
                        elif "SUSPEND" in raw:
                            designation="SUSPENDED"
                        elif "INJURED RESERVE" in raw or "RESERVE/INJURED" in raw or re.search(r"\bIR\b",raw):
                            designation="IR"
                        elif "OUT" in raw:
                            designation="OUT"
                        elif "DOUBTFUL" in raw:
                            designation="DOUBTFUL"
                        elif "QUESTIONABLE" in raw:
                            designation="QUESTIONABLE"

                        out[_owner_key(name)]={
                            "status":designation,
                            "team":abbr,
                            "source":"ESPN roster designation",
                            "fetched_at":datetime.now(timezone.utc).isoformat(),
                        }
            except Exception:
                continue
    except Exception as e:
        pass  # cached loaders must not mutate session_state
    return out

# Current official reserve-list corrections verified from team transaction/roster
# publications. These are a safety net for reserve designations that generic APIs
# may flatten to Active. Keep this small and only for verified reserve placements.
_V679_VERIFIED_RESERVE = {}  # V7.59: no timeless hard-coded injury/reserve statuses.


def _v679_authoritative_status(name, generic_status, roster_status=None, injury_watch=None):
    """V7.59 freshness-first status authority.

    Static historical designations are intentionally excluded. A live current roster
    reserve tag may establish IR/PUP/NFI/SUSPENDED. Weekly tags are accepted only when
    the reconciled Injury Watch marks them verified.
    """
    generic=_v677_normalize_injury_status(generic_status)
    key=_owner_key(name)

    live=(roster_status or {}).get(key)
    if isinstance(live,dict):
        live_status=_v677_normalize_injury_status(live.get("status","ACTIVE"))
        fetched=pd.to_datetime(live.get("fetched_at",""),errors="coerce",utc=True)
        fresh=bool(pd.notna(fetched) and (pd.Timestamp.now(tz="UTC")-fetched).total_seconds() <= 6*3600)
        if fresh and live_status in ("IR","PUP","NFI","SUSPENDED"):
            return live_status,live.get("source","ESPN roster designation")

    watch=(injury_watch or {}).get(key)
    if isinstance(watch,dict):
        watch_status=_v677_normalize_injury_status(watch.get("status","ACTIVE"))
        verified=bool(watch.get("status_verified",False))
        if verified and watch_status in ("OUT","DOUBTFUL","QUESTIONABLE","IR","PUP","NFI","SUSPENDED"):
            return watch_status,watch.get("evidence_sources") or watch.get("source","Fantasy Edge Injury Watch")
        # A verified ACTIVE current report can clear an older generic injury tag.
        if verified and watch_status=="ACTIVE":
            return "ACTIVE",watch.get("evidence_sources") or watch.get("source","Fantasy Edge Injury Watch")

    # Generic severe/weekly labels are not allowed to become authoritative without a
    # freshness-bearing source.  Keep only non-actionable ACTIVE fallback.
    if generic in ("OUT","DOUBTFUL","QUESTIONABLE","IR","PUP","NFI","SUSPENDED"):
        return "ACTIVE","Unverified generic injury tag quarantined"
    return generic,"Sleeper / injury feed"

# --- Fantasy Edge v9.2 live injury overlay ---
def _injury_overlay_penalty(status):
    x=_v677_normalize_injury_status(status).strip().lower()
    if x in ["do not draft","dnr","avoid"]: return 999.0
    if x in ["ir","reserve/ir","nfi","reserve/nfi"]: return 999.0
    if x in ["pup","reserve/pup"]: return 3.5
    if x in ["out","o","suspended","susp"]: return 2.5
    if x in ["doubtful","d"]: return 1.25
    if x in ["questionable","q"]: return 0.9
    return 0.0

def _injury_overlay_severity(status):
    p=_injury_overlay_penalty(status)
    if p>=900: return 3
    if p>=2.5: return 2
    if p>0: return 1
    return 0

def apply_v92_injury_overlay(board,state, injury_watch_prefetch=None, roster_status_prefetch=None):
    """Overlay Sleeper injury status with user-controlled manual overrides."""
    b=board.copy()
    overrides=state.get("injury_overrides",{}) or {}
    b["injury_auto"]=b.get("injury",pd.Series("",index=b.index)).fillna("").astype(str)
    effective=[]
    source=[]
    for _,r in b.iterrows():
        ov=overrides.get(norm(r["player"]))
        if ov and str(ov).upper()!="AUTO":
            effective.append("" if str(ov).upper()=="CLEAR" else str(ov))
            source.append("Manual")
        else:
            effective.append(str(r["injury_auto"] or ""))
            source.append("Sleeper")
    b["injury_effective"]=[_v677_normalize_injury_status(x) for x in effective]
    b["injury_source"]=source

    # V6.79 authority merge. Manual override remains king; otherwise reserve-list
    # status can override a stale/generic ACTIVE designation.
    _eff=[]
    _src=[]
    _body=[]
    _notes=[]
    _practice=[]
    _updated=[]
    _practice_source=[]
    _practice_match=[]
    _status_verified=[]
    _status_quarantined=[]
    _status_freshness=[]
    _status_conflict=[]
    _status_evidence_expired=[]
    _prior_practice=[]
    _practice_trend=[]
    _prior_practice_updated=[]
    # V9.20 FAST COMMIT: consume data already acquired by the shared startup budget.
    # Never pay a second 5-second injury wait inside the overlay. If a prefetch is
    # unavailable, use the provider cache with a tiny shared fallback budget.
    _v680_watch=injury_watch_prefetch if isinstance(injury_watch_prefetch,dict) else {}
    _v679_live_status=roster_status_prefetch if isinstance(roster_status_prefetch,dict) else {}
    if not _v680_watch or not _v679_live_status:
        _v920_pool=concurrent.futures.ThreadPoolExecutor(max_workers=2)
        try:
            _v920_map={}
            if not _v679_live_status: _v920_map[_v920_pool.submit(_v679_espn_roster_status)]="roster"
            if not _v680_watch: _v920_map[_v920_pool.submit(_v680_injury_watch_feed)]="watch"
            if _v920_map:
                _done,_pending=concurrent.futures.wait(set(_v920_map),timeout=1.25)
                for _f in _done:
                    try: _val=_f.result() or {}
                    except Exception: _val={}
                    if _v920_map[_f]=="roster": _v679_live_status=_val
                    else: _v680_watch=_val
                for _f in _pending: _f.cancel()
        finally:
            _v920_pool.shutdown(wait=False,cancel_futures=True)
    _v806_index=_v806_watch_index(_v680_watch)

    for i,row in b.iterrows():
        current=_v677_normalize_injury_status(row.get("injury_effective","ACTIVE"))
        current_source=str(row.get("injury_source","") or "")
        key=_owner_key(row.get("player",""))
        watch,watch_match=_v724_resolve_watch_record(
            row.get("player",""),row.get("team",""),_v680_watch,_v806_index
        )

        if current_source.lower().startswith("manual"):
            final,final_source=current,current_source
        else:
            final,final_source=_v679_authoritative_status(
                row.get("player",""),current,_v679_live_status,_v680_watch
            )
            if final==current and final_source=="Sleeper / injury feed":
                final_source=current_source or final_source

        _eff.append(final)
        _src.append(final_source)
        _body.append(str(watch.get("injury","") or ""))
        _notes.append(str(watch.get("note","") or ""))
        _practice.append(str(watch.get("practice","") or ""))
        _updated.append(str(watch.get("updated","") or ""))
        _practice_source.append(str(watch.get("practice_source","") or (watch.get("source","") if watch.get("practice") else "")))
        # V7.64 canonical-status authority: downstream decision engines must consume the
        # FINAL reconciled status, not raw/legacy evidence flags.  Previously a player
        # could be safely resolved to ACTIVE here while an older watch record still had
        # status_verified=False/quarantined_status set; Monitoring then resurrected that
        # raw flag and created an endless "Verify player" loop.
        _watch_verified=bool(watch.get("status_verified", final=="ACTIVE"))
        _watch_quarantined=str(watch.get("quarantined_status","") or "")
        _watch_conflict=bool(watch.get("status_conflict",False))
        _watch_expired=bool(watch.get("evidence_expired",False))
        _manual=current_source.lower().startswith("manual")
        _roster_reserve=(str(final_source).lower().startswith("espn roster designation") and final in ("IR","PUP","NFI","SUSPENDED"))

        # A raw unresolved record only remains decision-relevant when it still changes
        # the canonical result (or when genuinely current sources conflict). If the
        # authority merge has resolved the player to ACTIVE, stale/unverified raw tags
        # are diagnostic history only and cannot populate Certification/Monitoring.
        _canonical_conflict=bool(_watch_conflict)
        _canonical_unresolved=False
        if _manual or _roster_reserve:
            _canonical_verified=True
            _canonical_conflict=False
        elif _canonical_conflict:
            _canonical_verified=False
            _canonical_unresolved=True
        elif final != "ACTIVE":
            _canonical_verified=bool(_watch_verified)
            _canonical_unresolved=not _canonical_verified
        else:
            _canonical_verified=True
            _canonical_unresolved=False

        _status_verified.append(bool(_canonical_verified))
        _status_quarantined.append(_watch_quarantined if _canonical_unresolved else "")
        _status_freshness.append(str(watch.get("freshness_reason","") or ""))
        _status_conflict.append(bool(_canonical_conflict))
        _status_evidence_expired.append(bool(_watch_expired or (final=="ACTIVE" and not _canonical_unresolved and bool(_watch_quarantined))))
        _prior_practice.append(str(watch.get("prior_practice","") or ""))
        _practice_trend.append(str(watch.get("practice_trend","") or ""))
        _prior_practice_updated.append(str(watch.get("prior_practice_updated","") or ""))
        if watch_match!="none":
            _practice_match.append("practice found" if str(watch.get("practice","") or "").strip() else "report matched; participation not published")
        else:
            _practice_match.append("no practice report matched")

    b["injury_effective"]=_eff
    b["injury_source"]=_src
    b["injury_status_verified"]=_status_verified
    b["injury_status_quarantined"]=_status_quarantined
    b["injury_freshness_reason"]=_status_freshness
    b["injury_status_conflict"]=_status_conflict
    b["injury_status_evidence_expired"]=_status_evidence_expired
    # Single source of truth for decision/certification status uncertainty.
    b["injury_decision_unresolved"]=(~b["injury_status_verified"].astype(bool)) | b["injury_status_conflict"].astype(bool) | b["injury_status_quarantined"].fillna("").astype(str).str.len().gt(0)
    b["injury_detail"]=_body
    b["injury_note"]=_notes
    b["practice_status"]=_practice
    b["injury_updated"]=_updated
    b["practice_source"]=_practice_source
    b["practice_match_status"]=_practice_match
    b["prior_practice_status"]=_prior_practice
    b["practice_trend"]=_practice_trend
    b["prior_practice_updated"]=_prior_practice_updated
    b["practice_display"]=b["practice_status"].map(_v680_practice_risk)
    b["injury"]=b["injury_effective"]
    b["injury_designation"]=b["injury_effective"].map(_v677_status_icon)
    b["injury_penalty"]=b["injury_effective"].map(_injury_overlay_penalty).astype(float)
    b["injury_severity"]=b["injury_effective"].map(_injury_overlay_severity).astype(int)
    return b


# --- Fantasy Edge v9.24 dynamic roster opportunity cost ---

def _v934_num(row, *keys):
    for k in keys:
        if k in row.index:
            v = pd.to_numeric(pd.Series([row.get(k, np.nan)]), errors="coerce").iloc[0]
            if pd.notna(v):
                return float(v)
    return np.nan

_V937_IDP_DB_CONSENSUS = {'Brian Branch': 1, 'Nick Emmanwori': 2, 'Kyle Hamilton': 3, 'Derwin James': 4, 'Nick Cross': 5, 'Jessie Bates': 6, 'Antoine Winfield Jr.': 7, 'Tykee Smith': 8, 'Cooper DeJean': 9, 'Devon Witherspoon': 10, 'DeShon Elliott': 11, 'Xavier McKinney': 12, 'Budda Baker': 13, 'Julian Love': 14, 'Christian Gonzalez': 20, 'Sauce Gardner': 25, 'Pat Surtain II': 30, 'Denzel Ward': 35, 'Malaki Starks': 49, 'Nate Wiggins': 87}

