            if not focus_get_key and not focus_give_key and need_sc<12 and upgrade<0.75: continue
            starter_tax=7.0 if key in opp_starter_keys else 0.0
            score=need_sc*.45+max(-1.5,upgrade)*11.0+surplus*.28+min(12.0,_expected(r))*.45-starter_tax
            if focus_give_key:
                # Focused shopping needs a market-price lane as well as a need lane.
                # This prevents a useful lateral/starter swap from disappearing merely
                # because the return position was not one of the broad scan's top needs.
                score+=max(0.0,18.0-abs(_tval(r)-_focus_give_value)*1.8)
            reason=(f"{my_labels.get(pos,'Upgrade '+pos)} • {upgrade:+.2f} PPG vs current {pos} baseline"
                    f" • {team_name} surplus {surplus:.0f}/100")
            if not focus_get_key and not focus_give_key:
                _lab=str(my_labels.get(pos,"") or "").upper()
                # Weak/temporary needs stay on the target map but should not consume
