            _outs_keep=list(_outs_all[:4])
            _starter_lane=[]
            for _oi in _outs_all:
                _or=_oi[1]; _ok=_owner_key(_or.get("player","")); _oc=str(_or.get("_v1005_asset_class","") or "").upper()
                if _ok in _my_starter_keys or _oc in {"CORE","STARTER","RETURNING HOLD"}:
                    _starter_lane.append(_oi)
                if len(_starter_lane)>=2: break
            _seen_out=set(); outs=[]
            for _oi in _outs_keep+_starter_lane:
                _k=_owner_key(_oi[1].get("player",""))
                if _k in _seen_out: continue
                _seen_out.add(_k); outs.append(_oi)
                if len(outs)>=6: break
            if not outs: continue
            out_rows=[x[1] for x in outs]
            _focus_out_pos=""; _focus_out_need=0.0
            if focus_give_key and len(out_rows)==1:
                _focus_out_pos=str(out_rows[0].get("position","") or "").upper()
                _focus_out_need=_target_vacancy_need(my,out_rows[0],_my_starter_keys)

            # Secondary return candidates enable depth acquisition and balanced 2-for-2
            # structures. V12.05 also prices the vacancy created on *our* roster by the
