            sec=[]
            for _,r2 in opp.iterrows():
                k2=_owner_key(r2.get("player","")); p2=str(r2.get("position","") or "").upper()
                if k2==tkey or p2 not in {"QB","RB","WR","TE","DL","DB"}: continue
                if not bool(_v1096_trade_availability_profile(r2).get("auto_target_eligible",True)): continue
                sec_need=float(my_need.get(p2,0.0)); sec_up=_expected(r2)-_weak_position_baseline(my,p2)
                if focus_give_key and p2==_focus_out_pos:
                    sec_need=max(sec_need,float(_focus_out_need))
                if p2 not in my_positions and not (focus_give_key and p2==_focus_out_pos) and sec_up<0.50: continue
                sscore=sec_need*.45+sec_up*8.0+_position_surplus(opp,p2,opp_need.get(p2,0.0))*.15-_tval(r2)*.05
                sec.append((sscore,r2))
            _sec_sorted=sorted(sec,key=lambda x:x[0],reverse=True)
            sec=[x[1] for x in _sec_sorted[:2]]
            if focus_give_key and _focus_out_pos:
                for _,_sr2 in _sec_sorted:
                    if str(_sr2.get("position","") or "").upper()==_focus_out_pos:
                        if _owner_key(_sr2.get("player","")) not in {_owner_key(x.get("player","")) for x in sec}:
                            sec.append(_sr2)
                        break
            sec=sec[:3]

            packages=[]
            def _add_pkg(give_rows,get_rows,ptype):
                gdf=pd.DataFrame([dict(x) for x in give_rows]); rdf=pd.DataFrame([dict(x) for x in get_rows])
                if gdf.empty or rdf.empty: return
                if len({_owner_key(x) for x in gdf.get("player",pd.Series(dtype=str))})!=len(gdf): return
                if len({_owner_key(x) for x in rdf.get("player",pd.Series(dtype=str))})!=len(rdf): return
                gv=sum(_tval(x) for x in give_rows); rv=sum(_tval(x) for x in get_rows); gap=rv-gv
                # V12.04 replacement-adjusted construction: starters/core assets may be
