                # help for the selected player we are shopping. This is the natural
                # starter-for-starter / 2-for-2 structure that pre-trade need maps miss.
                _completion=None
                for _pi in _pkg_sorted:
                    _pg=_pi[2]; _pr=_pi[3]
                    _gpos=set(_pg.get("position",pd.Series(dtype=str)).astype(str).str.upper())
                    _rpos=set(_pr.get("position",pd.Series(dtype=str)).astype(str).str.upper())
                    if len(_pg)>=2 and tpos in _gpos and (not _focus_out_pos or _focus_out_pos in _rpos):
                        _completion=_pi; break
                if _completion is None:
                    for _pi in _pkg_sorted:
                        _pg=_pi[2]
