                _sig=(tuple(sorted(_pi[2].get("player",pd.Series(dtype=str)).astype(str))),tuple(sorted(_pi[3].get("player",pd.Series(dtype=str)).astype(str))))
                _existing={(tuple(sorted(x[2].get("player",pd.Series(dtype=str)).astype(str))),tuple(sorted(x[3].get("player",pd.Series(dtype=str)).astype(str)))) for x in package_list}
                if _sig not in _existing: package_list.append(_pi)
