                if not ev: continue
                nalign=_v1054_partner_need_alignment(opp_profile,give_df,ev.get("Partner Total Gain",0),ev.get("Partner ROS %",0))
                fit_parts=_v1054_trade_fit_components(
                    _num(ev.get("My Lineup Gain",0)),_num(ev.get("Your Total Gain",ev.get("Your Gain",0))),_num(ev.get("Your ROS %",0)),
                    _num(ev.get("Your Depth Change",0)),_num(ev.get("Asset Gap",0)),_num(ev.get("Partner Total Gain",0)),_num(ev.get("Partner ROS %",0)),
                    _num(nalign.get("score",0)),_num(ev.get("Fragility Reduction",0)),int(ev.get("Weak Starter Relief",0) or 0)+int(ev.get("Dead Bench Relief",0) or 0)
                )
                fit=_num(fit_parts.get("Trade Fit",0),0)
                tier,reason=_classify(ev,fit,_num(nalign.get("score",0)),give_df,get_df)

                # One bounded sweetener repair: if a 1-for-1 is close for the partner,
                # add the smallest useful asset that addresses a top partner need and
