# V8.22 stamp season/week ONLY onto rows with fresh weekly status evidence.
# V8.21 stamped the entire board after refresh, which could make an old snapshot OUT
# look like a brand-new current-week OUT.
if _refresh_live:
    try:
        _v821_ctx=globals().get("_v678_live_week",{}) or {}
        _v822_season=int(_v821_ctx.get("season",datetime.now().year) or datetime.now().year)
        _v822_week=int(_v821_ctx.get("week",1) or 1)
        if "injury_status_season" not in board.columns: board["injury_status_season"]=pd.NA
        if "injury_status_week" not in board.columns: board["injury_status_week"]=pd.NA
        _v920_stat_t=time.perf_counter()
        _src=board.get("injury_source",pd.Series("",index=board.index)).fillna("").astype(str).str.lower().str.strip()
        _upd=board.get("injury_updated",board.get("practice_updated",pd.Series("",index=board.index))).fillna("").astype(str).str.strip()
        _ver=board.get("injury_status_verified",board.get("status_verified",pd.Series(False,index=board.index))).fillna(False).astype(bool)
        _fallback=_src.isin(["","local","snapshot/local","snapshot","fallback","saved snapshot"]) | (_src.str.contains("snapshot",na=False) & _upd.eq(""))
        _fresh_tok=_src.str.contains("sleeper live roster status|sleeper injury|espn|injury watch|official|manual|live roster|current roster|weekly status|provider|practice report|transaction",regex=True,na=False)
        _timestamped=_upd.ne("") & ~_src.str.contains("local|snapshot",regex=True,na=False)
        _v822_fresh=_ver & ~_fallback & (_fresh_tok | _timestamped)
        board.loc[_v822_fresh,"injury_status_season"]=_v822_season
        board.loc[_v822_fresh,"injury_status_week"]=_v822_week
        # Weekly labels without current evidence must not inherit a current-week stamp.
        _raw_status=board.get("injury_effective",board.get("fe_status",pd.Series("ACTIVE",index=board.index))).fillna("ACTIVE").astype(str).str.upper().str.strip()
        _alias={"O":"OUT","Q":"QUESTIONABLE","D":"DOUBTFUL","SUSP":"SUSPENDED","RESERVE/IR":"IR","RESERVE/PUP":"PUP","RESERVE/NFI":"NFI"}
        _v822_status=_raw_status.replace(_alias)
        _v916_profiler_mark(_v916_profile,"weekly status stamping",_v920_stat_t,status="OK",detail=f"{int(_v822_fresh.sum())} fresh status rows")
        _v822_stale=(~_v822_fresh) & _v822_status.isin(["OUT","DOUBTFUL","QUESTIONABLE"])
        board.loc[_v822_stale,"injury_status_season"]=pd.NA
        board.loc[_v822_stale,"injury_status_week"]=pd.NA
    except Exception:
        pass

# V8.21 persist availability with correct lifecycle semantics.
# - IR/PUP/NFI/SUSPENDED persist until explicit authoritative clearance.
# - OUT/DOUBTFUL/QUESTIONABLE are stored with season/week and expire next week.
# - stale raw weekly labels never overwrite newer canonical evidence.
if _refresh_live:
    try:
        _reg=dict(state.get("_availability_registry",{}) or {})
        _reserve={"IR","PUP","NFI","SUSPENDED"}
        _weekly={"OUT","DOUBTFUL","QUESTIONABLE"}
        _now=datetime.now(timezone.utc).isoformat(timespec="seconds")
        _ctx=globals().get("_v678_live_week",{}) or {}
        _season=int(_ctx.get("season",datetime.now().year) or datetime.now().year)
        _week=int(_ctx.get("week",1) or 1)

        # First expire weekly records from prior weeks, including old legacy records
        # that never carried season/week metadata.
        for _key,_rec in list(_reg.items()):
            if not isinstance(_rec,dict):
                _reg.pop(_key,None); continue
            _rst=_v677_normalize_injury_status(_rec.get("status",""))
            if _rst in _weekly:
                try:
                    _same=(int(_rec.get("season",-1))==_season and int(_rec.get("week",-1))==_week)
                except Exception:
                    _same=False
                if not _same:
                    _reg.pop(_key,None)

        for _,_rr in board.iterrows():
            _name=str(_rr.get("player","") or ""); _key=_owner_key(_name)
            _resolved=_v677_normalize_injury_status(_rr.get("injury_effective",_rr.get("fe_status","ACTIVE")))
            _verified=bool(_rr.get("injury_status_verified",_rr.get("status_verified",False)))
            _source=str(_rr.get("injury_source","") or "").lower()
            _updated=str(_rr.get("injury_updated","") or "")

            if _verified and _resolved in _reserve:
                _reg[_key]={"status":_resolved,"updated":_now,"player":_name,"source":str(_rr.get("injury_source","") or "weekly authority"),"season":_season,"week":_week,"scope":"persistent_reserve",
                           "team":str(_rr.get("team","") or ""),"position":str(_rr.get("position","") or ""),
                           "projection_baseline":float(max([_v755_num(_rr,"projection",0),_v755_num(_rr,"fe_week",0),_v755_num(_rr,"fe_off_model_ppg",0),_v755_num(_rr,"_external_week_projection",0),_v755_num(_rr,"_recent_ppg3",0)])),
                           "opportunities":float(max(_v755_num(_rr,"_opps_last",0),_v755_num(_rr,"fe_off_recent_opportunities",0),_v755_num(_rr,"fe_off_projected_opportunities",0))),
                           "targets":float(max(_v755_num(_rr,"_targets_last",0),_v755_num(_rr,"fe_off_projected_targets",0))),
                           "carries":float(max(_v755_num(_rr,"_carries_last",0),_v755_num(_rr,"fe_off_projected_rush_att",0))),
                           "routes":float(_v755_num(_rr,"_routes_last",0)),"snap_pct":float(_v755_num(_rr,"_snap_pct_last",0))}
                continue
            if _verified and _resolved in _weekly and _v822_current_status_evidence(_rr,_season,_week):
                _reg[_key]={"status":_resolved,"updated":_now,"player":_name,"source":str(_rr.get("injury_source","") or "weekly authority"),"season":_season,"week":_week,"scope":"weekly",
                           "team":str(_rr.get("team","") or ""),"position":str(_rr.get("position","") or ""),
                           "projection_baseline":float(max([_v755_num(_rr,"projection",0),_v755_num(_rr,"fe_week",0),_v755_num(_rr,"fe_off_model_ppg",0),_v755_num(_rr,"_external_week_projection",0),_v755_num(_rr,"_recent_ppg3",0)])),
                           "opportunities":float(max(_v755_num(_rr,"_opps_last",0),_v755_num(_rr,"fe_off_recent_opportunities",0),_v755_num(_rr,"fe_off_projected_opportunities",0))),
                           "targets":float(max(_v755_num(_rr,"_targets_last",0),_v755_num(_rr,"fe_off_projected_targets",0))),
                           "carries":float(max(_v755_num(_rr,"_carries_last",0),_v755_num(_rr,"fe_off_projected_rush_att",0))),
                           "routes":float(_v755_num(_rr,"_routes_last",0)),"snap_pct":float(_v755_num(_rr,"_snap_pct_last",0))}
                continue
            # If this row only carries a stale weekly label, remove any same-player weekly
            # registry entry instead of re-persisting it under the new refresh.
            if _resolved in _weekly and _key in _reg and isinstance(_reg.get(_key),dict) and str(_reg[_key].get("scope",""))=="weekly":
                _reg.pop(_key,None)

            # Only explicit authoritative ACTIVE clears persistent reserve status.
            _explicit_active=bool(
                _resolved=="ACTIVE" and _verified and (
                    _source.startswith("manual") or
                    ("injury watch" in _source and bool(_updated)) or
                    ("official" in _source and bool(_updated)) or
                    ("roster" in _source and bool(_updated))
                )
            )
            if _explicit_active and _key in _reg:
                _reg.pop(_key,None)

        # Explicit weekly overrides remain week-scoped in the registry. Reserve
        # overrides may persist because they represent roster eligibility.
        for _key,_ov in (globals().get("_V785_WEEKLY_STATUS_OVERRIDES",{}) or {}).items():
            if not isinstance(_ov,dict): continue
            if int(_ov.get("season",-1))!=_season or int(_ov.get("week",-1))!=_week: continue
            _ost=_v677_normalize_injury_status(_ov.get("status",""))
            if _ost in _reserve|_weekly:
                _reg[_key]={"status":_ost,"updated":_now,"player":str(_ov.get("player",_key)),"source":str(_ov.get("source","confirmed weekly status")),"season":_season,"week":_week,"scope":"persistent_reserve" if _ost in _reserve else "weekly"}

        state["_availability_registry"]=_reg
        globals()["_V784_AVAILABILITY_REGISTRY"]=_reg
    except Exception:
        pass

# V11.14: recompute opportunity redistribution after canonical FE week values and the
# current availability registry have been finalized.  The early V11.13 pass remains a
