                            _dv=float(_d[_v1031_fb_value_col] if _v1031_fb_value_col in _d.index and pd.notna(_d.get(_v1031_fb_value_col)) else _v1005_shared_asset_value(_d,[] if _temp else _starter_names))
                            _ad=float(_av-_dv)
