            x["Conf"]=pd.to_numeric(x.get("fe_idp_model_confidence",0),errors="coerce").fillna(0).map(lambda v:f"{float(v)*100:.0f}%" if float(v)<=1 else f"{float(v):.0f}%")
            x["Snap"]=pd.to_numeric(x.get("fe_idp_snap_pct",0),errors="coerce").fillna(0).map(lambda v:f"{float(v)*100:.0f}%" if float(v)<=1 else f"{float(v):.0f}%")
            _compact=["player","position","Week PPG","Floor","Ceiling","VORP","Conf","Snap","injury"]
            _compact=[c for c in _compact if c in x.columns]
            st.dataframe(x.sort_values(["Week PPG","VORP"],ascending=False)[_compact].head(100).rename(columns={"player":"Player","position":"Pos","injury":"Status"}),use_container_width=True,hide_index=True)

