                if _history_col:
                    _bd_cols.insert(6,"last_ppg")
                    _bd_cols.insert(7,"ppg_change")
                _bd=_b[_bd_cols].copy()
                _rename={"player":"Player","position":"Pos","team":"Team",
                         "Signal Class":"Signal Type","Actionability Tier":"Actionability","Actionability Score":"Action Score","Momentum Score":"Momentum","ECR Momentum 24h":"ECR Δ24h","ECR Momentum 72h":"ECR Δ72h","Roster Momentum":"Roster/Market Δ","Roster Momentum Source":"Momentum Source","Usage Momentum":"Usage Δ","Status Multiplier":"Status Mult.","Injury Return Probability":"Return Prob.","Rank Alignment":"Rank Check","FantasyPros Pos Rank":"FantasyPros Pos Rank","FE Pos Rank":"FE Pos Rank","Position Rank Gap":"Pos Rank Gap","Ranking Penalty":"Rank Penalty","Evidence Penalty":"Evidence Penalty","Role Gate":"Role","Fantasy Relevance":"Rel.","breakout_score":"Breakout Signal","Waiver Opportunity":"Acquisition","Confidence":"Confidence",
                         "last_ppg":"2025 PPG","projection":"2026 PPG","vorp":"VORP","Breakout Action":"Action"}
                if _history_col:
                    _rename.update({"ppg_change":"PPG Δ"})
                _bd.rename(columns=_rename,inplace=True)
                if "2025 PPG" in _bd.columns:
                    _bd["2025 PPG"]=_bd["2025 PPG"].apply(lambda x: "N/A" if pd.isna(x) else round(float(x),2))
                if "PPG Δ" in _bd.columns:
                    _bd["PPG Δ"]=_bd["PPG Δ"].apply(lambda x: "N/A" if pd.isna(x) else round(float(x),2))
                # V8.92 cards-first mobile layout; raw board remains available on demand.
                for _,_rr in _b.iterrows():
                    _attr=_v891_signal_attribution(_rr,"breakout"); _primary=max(_attr,key=_attr.get) if _attr else "—"
                    _wf=_v892_contribution_waterfall(_rr,"breakout")
