            _wd_cols=["player","position","team","Role Gate","Fantasy Relevance","Evidence","Confidence","Actionability Tier","Actionability Score","Momentum Score","ECR Momentum 24h","ECR Momentum 72h","Roster Momentum","Usage Momentum","Status Multiplier","Injury Return Probability","Waiver Action","signal_score"]
