    # ---------------- V7.36 Early Injury News + Roster Contingency Hotfix ----------------
    _NEWS_INJURY_TERMS=("injury","injured","surgery","procedure","meniscus","sprain","strain","hamstring","knee","ankle","shoulder","concussion","miss","out","week-to-week","questionable","doubtful")
    _NEWS_HIGH_TERMS=("surgery","procedure","expected to miss","will miss","miss a game","miss 1","miss 2","meniscus","placed on ir","injured reserve","out indefinitely")

    @st.cache_data(ttl=900,show_spinner=False)
    def _v735_google_news_player(player):
        """Breaking-news layer only. It never overwrites the official NFL designation."""
        try:
            q=quote_plus(f'"{player}" (injury OR surgery OR miss OR questionable OR knee OR ankle OR hamstring OR concussion) when:2d')
            url=f"https://news.google.com/rss/search?q={q}&hl=en-US&gl=US&ceid=US:en"
            r=requests.get(url,timeout=5,headers={"User-Agent":"Mozilla/5.0 FantasyEdge/7.35"})
            r.raise_for_status(); root=ET.fromstring(r.content)
            rows=[]
            for item in root.findall('.//item')[:12]:
                title=(item.findtext('title') or '').strip(); desc=re.sub('<[^>]+>',' ',item.findtext('description') or '')
                text=(title+' '+desc).lower()
                if norm(player) not in norm(title+' '+desc): continue
                if not any(k in text for k in _NEWS_INJURY_TERMS): continue
                rows.append({"Player":player,"Headline":title,"Published":item.findtext('pubDate') or '',"URL":item.findtext('link') or '',"_text":text})
            return rows[:3]
        except Exception:
            return []

    def _v735_is_verified_reserve(row):
        """Safe reserve-list check using the existing V6.79 authority map/status fields."""
        key=_owner_key(row.get('player',row.get('Player','')))
        fixed=_V679_VERIFIED_RESERVE.get(key,{}) if isinstance(_V679_VERIFIED_RESERVE,dict) else {}
        fixed_status=_v677_normalize_injury_status(fixed.get('status','')) if fixed else 'ACTIVE'
        effective=_v677_normalize_injury_status(row.get('injury_effective',row.get('injury','')))
        return fixed_status in ('IR','PUP','NFI','SUSPENDED') or effective in ('IR','PUP','NFI','SUSPENDED')

    def _v735_has_injury_concern(row):
        """Normalize V6.82's emoji-labelled risk output into a real concern boolean."""
        risk=str(_v682_injury_risk(row) or '').upper()
        return not ('LOW' in risk and 'LOW-MOD' not in risk) and '🟢' not in risk

    def _v735_news_watch(board_df,state):
        return _v742_news_watch(board_df,state)

    def _v735_contingency(board_df,state,news_df):
        if news_df is None or news_df.empty: return pd.DataFrame()
        my=board_df[board_df['player'].map(lambda n:_player_owner(state,n)=='1')].copy()
        rows=[]
        for _,nw in news_df.iterrows():
            if int(nw.get('Depth',99))>1: continue
            pos=str(nw.get('Pos',''))
            if pos not in ('QB','TE','K','DL','DB'): continue
            # Reuse the exact ranked transaction already produced by Waiver Wire so the
            # Command Center can never name a different add/drop pair.
            shared=pd.DataFrame(st.session_state.get("_v742_waiver_transactions",[]))
            if len(shared):
                shared=shared[(shared.get('Pos',pd.Series('',index=shared.index)).astype(str)==pos) & shared.get('Emergency Coverage',pd.Series(False,index=shared.index)).fillna(False).astype(bool)]
            if len(shared):
                pick=shared.sort_values(['Transaction Score','Decision Score'],ascending=False).iloc[0]
                rows.append({"Player":nw['Player'],"Need":f"{pos} contingency","Best Available":str(pick.get('Add','')),"Proj PPG":round(float(pick.get('Effective Add PPG',0) or 0),2),"Action":"ADD CONTINGENCY" if nw.get('News Risk')=='HIGH' else 'WATCH / PREPARE',"Drop":str(pick.get('Drop','')),"Transaction Score":round(float(pick.get('Transaction Score',0) or 0),1)})
                continue
            fa=board_df[(board_df['position'].astype(str)==pos) & board_df['player'].map(lambda n:_is_free_agent(state,n))].copy()
            if fa.empty: continue
            fa['_v']=fa.apply(_v676_player_value,axis=1)
            add=fa.sort_values(['_v','projection'],ascending=False).iloc[0]
            # Suggest the replacement target now; existing V7.14 waiver guard remains the authority on any drop.
            rows.append({"Player":nw['Player'],"Need":f"{pos} contingency","Best Available":str(add.get('player','')),"Proj PPG":round(float(add.get('projection',0) or 0),2),"Action":"ADD CONTINGENCY" if nw.get('News Risk')=='HIGH' else 'WATCH / PREPARE',"Drop":"Use Waiver Wire protected-drop guard"})
        return pd.DataFrame(rows)

    # ---------------- V7.58 Fantasy Edge Command Center ----------------
    # V7.58 keeps the V7.57 unified action-safety architecture.  This surface is
    # presentation + actionability only: it never creates an independent waiver move.
    if _v777_page_idx==14:
        _v1099_action_page_t0=time.perf_counter()
        st.caption("⚡ Fast page mode: rendering from saved weekly snapshot. Full trade search is deferred to Trade Finder.")
        my=board[board["player"].map(lambda n:_player_owner(state,n)=="1")].copy()
        if my.empty:
            st.subheader("🏠 Fantasy Edge Command Center")
            st.info("Set your roster under League Setup to activate the Command Center.")
        else:
            starters,bench,lineup=_v676_optimize_lineup(my)
            # V7.80: Action Queue uses a snapshot-scoped decision cache.  Page switches
            # never rerun the arbiter/certifier when the weekly snapshot is unchanged.
            _v780_base_key=str((_v778_snapshot_meta or {}).get("updated", "local"))
            # V11.02: cache invalidation follows every field consumed by the weekly arbiter,
            # not status alone. Practice trajectory, current projection and role confidence can
            # change a START/SIT or contingency call without changing the saved snapshot timestamp.
            _v1102_decision_parts=[]
            for _,_r1102 in my.iterrows():
                _v1102_decision_parts.append(
                    f"{_owner_key(_r1102.get('player',''))}:{_v783_authoritative_week_status(_r1102)}:"
                    f"{str(_r1102.get('practice_status','') or '').upper()}:"
                    f"{str(_r1102.get('practice_trend',_r1102.get('practice_sequence','')) or '').upper()}:"
                    f"{float(pd.to_numeric(pd.Series([_r1102.get('fe_week',_r1102.get('projection',0))]),errors='coerce').fillna(0).iloc[0]):.3f}:"
                    f"{float(pd.to_numeric(pd.Series([_r1102.get('fe_role_confidence',0)]),errors='coerce').fillna(0).iloc[0]):.1f}"
                )
            _v1102_decision_sig=hashlib.sha256("|".join(sorted(_v1102_decision_parts)).encode("utf-8")).hexdigest()[:12]
            # V11.01+: the weekly snapshot alone is not a complete action-cache key.
            # Waiver and Trade Finder can change their certified handoffs without a new
            # weekly snapshot, so hash those dependencies to prevent stale cross-tab cards.
            try:
                _v1101_waiver_payload=st.session_state.get("_v742_waiver_transactions",[]) or []
                _v1101_waiver_sig=hashlib.sha256(json.dumps(_v1101_waiver_payload,sort_keys=True,default=str).encode("utf-8")).hexdigest()[:12]
            except Exception:
                _v1101_waiver_sig="none"
            try:
                _v1101_trade_payload=state.get("_v779_trade_ideas",[]) or []
                _v1101_trade_sig=hashlib.sha256(json.dumps(_v1101_trade_payload,sort_keys=True,default=str).encode("utf-8")).hexdigest()[:12]
            except Exception:
                _v1101_trade_sig="none"
            _v780_snap_key=f"{APP_VERSION}|{_v780_base_key}|d:{_v1102_decision_sig}|w:{_v1101_waiver_sig}|t:{_v1101_trade_sig}"
            _v780_cache=st.session_state.get("_v780_action_cache",{}) or {}
            if _v780_cache.get("snapshot_key")==_v780_snap_key:
                _v775_feed=pd.DataFrame(_v780_cache.get("feed",[]))
            else:
                _v775_feed=_v775_unified_decisions(board,state,12,include_trade_scan=False)
            _v775_feed=_v784_sanitize_unified_feed(_v775_feed,board)
            _actions=[]
            if isinstance(_v775_feed,pd.DataFrame) and len(_v775_feed):
                for _,_a in _v775_feed[_v775_feed["Tier"].eq("DO NOW")].iterrows():
                    _urg=95 if str(_a.get("Area",""))=="AVAILABILITY" else (88 if str(_a.get("Area","")) in ("START/SIT","WAIVER") else 76)
                    _actions.append((_urg,str(_a.get("Area","")),str(_a.get("Action","")),f"{float(_a.get('Week Impact',0) or 0):+.2f} wk • {_v933_confidence_semantics(_a.get('Confidence',50),_a.get('Week Impact',0),2.0,100.0,'PROBABILITY')['display']}"))
            if _v780_cache.get("snapshot_key")==_v780_snap_key:
                _monitors=_v780_cache.get("monitors",[]) or []
                _overall=str(_v780_cache.get("overall","READY"))
                _cert=pd.DataFrame(_v780_cache.get("cert",[]))
            else:
                _monitors=_v761_monitor_queue(board,state)
                _overall,_cert=_v756_certify(board,state)
                try:
                    _v780_new_cache={
                        "snapshot_key":_v780_snap_key,
                        "feed":_v775_feed.replace({np.nan:None}).to_dict("records") if isinstance(_v775_feed,pd.DataFrame) else [],
                        "monitors":_monitors,
                        "overall":_overall,
                        "cert":_cert.replace({np.nan:None}).to_dict("records") if isinstance(_cert,pd.DataFrame) else [],
                    }
                    st.session_state["_v780_action_cache"]=_v780_new_cache
                except Exception:
                    pass
            # V11.02 final cross-surface reconciliation. Never display an INJURY/ROLE
            # monitor for a player the same feed is telling the user to drop now.
            _monitors=_v1102_reconcile_monitor_queue(_monitors,_v775_feed)
            # A hard certification failure is a decision-quality veto. The UI previously
            # said NOT READY blocked confident recommendations while still rendering DO NOW
            # cards. Demote them to WATCH until the failed checks clear. Warnings alone do
            # not trigger this veto.
            if str(_overall).upper()=="NOT READY":
                if isinstance(_v775_feed,pd.DataFrame) and len(_v775_feed) and "Tier" in _v775_feed.columns:
                    _v1102_fail_mask=_v775_feed["Tier"].astype(str).eq("DO NOW")
                    if _v1102_fail_mask.any():
                        _v775_feed.loc[_v1102_fail_mask,"Tier"]="WATCH"
                        _v775_feed.loc[_v1102_fail_mask,"Why"]=_v775_feed.loc[_v1102_fail_mask,"Why"].fillna("").astype(str)+" • certification NOT READY"
                _actions=[]
            _season756=int(_v678_live_week.get("season",datetime.now().year)); _week756=int(_v678_live_week.get("week",1))
            _starter_names=set(starters.get("Player",pd.Series(dtype=str)).astype(str).tolist()) if isinstance(starters,pd.DataFrame) else set()

            # One-click weekly refresh.  Certification is always recalculated after the rerun.
            _h1,_h2=st.columns([4,1])
            with _h1:
                st.markdown("<div class='fecc-brand'>🏈 <b>Fantasy Edge</b><span>Command Center</span></div>",unsafe_allow_html=True)
            with _h2:
                if st.button("↻ Reload snapshot",key="v758_refresh_cert",use_container_width=True):
                    st.session_state["_v756_cert_after_refresh"]=True
                    st.session_state["_v765_last_refresh"]=datetime.now().strftime("%b %d, %I:%M %p")
                    st.rerun()
            if st.session_state.pop("_v756_cert_after_refresh",False):
                st.success("Saved snapshot reloaded and certification rerun. Use the sidebar refresh only when you want new live feeds.")

            # Meaningful injury-watch rows only.  Blank/UNKNOWN statuses are not counted as injuries.
            _watch_status={"QUESTIONABLE","DOUBTFUL","OUT","IR","PUP","NFI","SUSPENDED"}
            _inj_rows=[]
            for _,r in my.iterrows():
                _status=str(_v783_authoritative_week_status(r) or "ACTIVE").upper().strip()
                _verified=bool(r.get("injury_status_verified",True))
                if (not _verified) or _status not in _watch_status: continue
                _name=str(r.get("player","")); _pos=str(r.get("position","")); _is_starter=_name in _starter_names
                _tier=_v745_drop_tier(r,_starter_names)
                if _status in {"OUT","IR","PUP","NFI","SUSPENDED"}:
                    _impact="HIGH" if _is_starter or _tier in {"LOCKED","PROTECTED"} else "MEDIUM"
                    _rec="HOLD (IR)" if _status=="IR" and _tier in {"LOCKED","PROTECTED"} else ("HOLD" if _tier in {"LOCKED","PROTECTED"} else "REVIEW")
                elif _status=="DOUBTFUL":
                    _impact="HIGH" if _is_starter else "MEDIUM"; _rec="PLAN BACKUP" if _is_starter else "MONITOR"
                else:
                    _impact="MEDIUM" if _is_starter else "LOW"; _rec="MONITOR"
                _ret=str(r.get("estimated_return",r.get("return_week",r.get("injury_return","—"))) or "—")
                _inj_rows.append({"Player":_name,"Pos":_pos,"Status":_status,"Est. Return":_ret,"Impact":_impact,"Recommendation":_rec})
            _inj=len(_inj_rows)

            # Certification warning text drives the status explanation; no generic unexplained warning.
            _warn_rows=_cert[_cert["Status"].astype(str).eq("WARN")] if isinstance(_cert,pd.DataFrame) else pd.DataFrame()
            _fail_rows=_cert[_cert["Status"].astype(str).eq("FAIL")] if isinstance(_cert,pd.DataFrame) else pd.DataFrame()
            _status_class="ready" if _overall=="READY" else ("warn" if _overall=="READY WITH WARNINGS" else "fail")
            _status_icon="✅" if _overall=="READY" else ("⚠️" if _overall=="READY WITH WARNINGS" else "🛑")
            _status_sub=("All critical weekly checks passed." if _overall=="READY" else
                         ("Lineup decisions are usable; review the warnings below." if _overall=="READY WITH WARNINGS" else
                          "A failed certification check blocks confident recommendations."))
            _warning_detail=""
            _detail_rows=_fail_rows if len(_fail_rows) else _warn_rows
            if len(_detail_rows):
                _friendly=[]
                for _,_wr in _detail_rows.head(3).iterrows():
                    _ck=str(_wr.get("Check",""))
                    if _ck=="Source freshness": _friendly.append("A roster status needs verification")
                    elif _ck=="Decision data integrity": _friendly.append("A decision record needs review")
                    elif _ck=="Playable position floors": _friendly.append("Roster coverage needs attention")
                    elif _ck=="Schedule feed": _friendly.append("Schedule data needs verification")
                    elif _ck=="Player identity": _friendly.append("Player identity data needs repair")
                    elif _ck=="Projection integrity": _friendly.append("Projection data needs repair")
                    else: _friendly.append(_ck)
                _warning_detail=" • ".join(dict.fromkeys(_friendly[:2]))

            # Schedule confidence: playoff grades are only promoted when the schedule feed is actually loaded.
            try:
                if bool(globals().get("_v778_network_allowed",False)):
                    _sched=_v677_week_matchups(_season756,_week756)
                    _sched_ok=bool(_sched.get("__schedule_loaded__",False))
                else:
                    _sched_ok=bool(globals().get("_v778_snapshot_loaded",False))
            except Exception:
                _sched_ok=False

            # Six-week starter plan and trend are built from the same canonical player state.
            _plan=[]
            for _,sr in starters.iterrows():
                rr=my[my["player"].eq(str(sr.get("Player","")))]
                if rr.empty: continue
