# V7.81 TRUE INSTANT NAVIGATION ---------------------------------------------
# A widget inside st.fragment reruns only the fragment when changed. This is the
# key difference from V7.77-V7.80, where a page click still reran app.py from top.
_v781_fragment = getattr(st, "fragment", None)
if _v781_fragment is None:
    def _v781_fragment(func):
        return func

@_v781_fragment
def _v781_navigation_fragment():
    _current=int(st.session_state.get("_v781_page_idx",0) or 0)
    _current=max(0,min(_current,len(_V777_PAGES)-1))
    # V7.83 mobile-first navigation: a single dropdown removes the long horizontal
    # page strip that required repeated sideways scrolling on phones.  It remains
    # inside the fragment, so changing pages still reruns only the selected page.
    _choice=st.selectbox(
        "Go to page",
        _V777_PAGES,
        index=_current,
        key="_v783_page_select",
        label_visibility="collapsed",
    )
    _idx=_V777_PAGES.index(_choice)
    st.session_state["_v781_page_idx"]=_idx
    _t=time.perf_counter()
    # V7.87: one stable page host. Clearing it first prevents the previous
    # page's controls/tables from lingering underneath while the new page renders.
    _page_host=st.empty()
    _page_host.empty()
    try:
        with _page_host.container():
            _v781_render_page(_idx)
            st.caption(f"⚡ Page render: {time.perf_counter()-_t:.2f}s • isolated fragment page")
    except Exception as _page_exc:
        _page_host.empty()
        with _page_host.container():
            st.error(f"This page could not finish rendering: {type(_page_exc).__name__}")
            with st.expander("Technical details"):
                st.exception(_page_exc)

_v803_startup.empty()
_v781_navigation_fragment()
